# Colab-ready MVP for "Hair = Memory" idea
# -------------------------------------------------------
# Follicle i = one memory slot
# Root Summary r_i = coarse index / compressed key
# Shaft / Content c_i = detailed memory
# Scalp = global controller that searches roots first
#
# Simple math:
#   r_i = normalize(P @ k_i)
#   query search score: s_i = cos(P @ q, r_i)
#   retrieve top follicle: i* = argmax_i s_i
#   decode answer from its shaft
#
# Spiral vs Random test:
#   Each follicle has a 2D position p_i.
#   Writing memory i leaks a little into nearby follicles:
#       x_j <- normalize(x_j + leak * exp(-||p_i-p_j||^2 / (2*sigma^2)) * x_i)
#   Spiral should reduce close-neighbor collisions vs random placement.

import numpy as np
import matplotlib.pyplot as plt

# -----------------------------
# Utilities
# -----------------------------
def normalize(x, axis=-1, eps=1e-9):
    n = np.linalg.norm(x, axis=axis, keepdims=True)
    return x / (n + eps)

def cosine_matrix(A, b):
    # A: (n, d), b: (d,)
    return A @ b

# -----------------------------
# Placement functions
# -----------------------------
def fermat_spiral_positions(n, radius=1.0):
    """
    Deterministic spiral placement in a disk.
    """
    golden_angle = np.pi * (3.0 - np.sqrt(5.0))
    i = np.arange(n)
    r = radius * np.sqrt((i + 0.5) / n)
    theta = i * golden_angle
    x = r * np.cos(theta)
    y = r * np.sin(theta)
    return np.stack([x, y], axis=1)

def random_disk_positions(n, seed=0, radius=1.0):
    """
    Random placement in the same disk for fair comparison.
    """
    rng = np.random.default_rng(seed)
    r = radius * np.sqrt(rng.random(n))
    theta = 2.0 * np.pi * rng.random(n)
    x = r * np.cos(theta)
    y = r * np.sin(theta)
    return np.stack([x, y], axis=1)

def mean_nearest_neighbor_distance(pos):
    d = pos[:, None, :] - pos[None, :, :]
    dist = np.sqrt((d ** 2).sum(-1))
    np.fill_diagonal(dist, np.inf)
    return dist.min(axis=1).mean()

def mean_interference_kernel(pos, sigma):
    """
    Average leakage weight to nearby neighbors.
    Lower is better (less interference).
    """
    d = pos[:, None, :] - pos[None, :, :]
    dist2 = (d ** 2).sum(-1)
    W = np.exp(-dist2 / (2.0 * sigma ** 2))
    np.fill_diagonal(W, 0.0)
    return W.mean()

# -----------------------------
# Synthetic memory generation
# -----------------------------
def make_embeddings(n_items, key_dim, value_dim, seed=0):
    rng = np.random.default_rng(seed)
    keys = normalize(rng.normal(size=(n_items, key_dim)))
    values = normalize(rng.normal(size=(n_items, value_dim)))
    return keys, values

# -----------------------------
# Memory field
# -----------------------------
def build_memory_field(keys, values, positions, root_dim=16, leak=0.12, sigma=0.18, seed=0):
    """
    Build the memory field sequentially.

    root_i   = compressed key summary
    shaft_i  = full content / answer representation
    leak     = how much a write contaminates nearby follicles
    sigma    = locality of contamination
    """
    rng = np.random.default_rng(seed + 999)
    n, key_dim = keys.shape
    value_dim = values.shape[1]

    # Shared projection used for root summaries
    P = rng.normal(size=(root_dim, key_dim)) / np.sqrt(key_dim)

    roots = np.zeros((n, root_dim), dtype=np.float64)
    shafts = np.zeros((n, value_dim), dtype=np.float64)

    for i in range(n):
        root_i = normalize(P @ keys[i])          # compressed index
        shaft_i = values[i].copy()               # detailed content

        # Write the focal follicle
        roots[i] = root_i
        shafts[i] = shaft_i

        # Local interference / leakage to neighbors
        d2 = np.sum((positions - positions[i]) ** 2, axis=1)
        w = leak * np.exp(-d2 / (2.0 * sigma ** 2))
        w[i] = 0.0

        # Add the leakage globally
        if np.any(w > 0):
            roots += w[:, None] * root_i
            shafts += w[:, None] * shaft_i

            # Re-normalize the whole field lightly
            roots = normalize(roots)
            shafts = normalize(shafts)

            # Restore the exact written follicle after normalization
            roots[i] = root_i
            shafts[i] = shaft_i

    return P, roots, shafts

# -----------------------------
# Retrieval
# -----------------------------
def retrieve(query_key, P, roots, shafts, values):
    """
    1) Convert query to root space
    2) Match against all root summaries
    3) Pick top follicle
    4) Decode its shaft into a value id
    """
    q_root = normalize(P @ query_key)
    scores = cosine_matrix(roots, q_root)
    top_idx = int(np.argmax(scores))

    # Decode shaft by nearest value embedding
    ans_scores = shafts[top_idx] @ values.T
    pred_value_idx = int(np.argmax(ans_scores))
    return top_idx, pred_value_idx, float(scores[top_idx])

# -----------------------------
# Experiment
# -----------------------------
def run_experiment(
    placement="spiral",
    seed=0,
    n_items=256,
    key_dim=64,
    value_dim=64,
    root_dim=16,
    query_noise=0.25,
    leak=0.12,
    sigma=0.18,
    trials_per_item=3,
):
    # Facts: key_i -> value_i
    keys, values = make_embeddings(n_items, key_dim, value_dim, seed=seed)

    # Positions: spiral or random
    if placement == "spiral":
        positions = fermat_spiral_positions(n_items, radius=1.0)
    elif placement == "random":
        positions = random_disk_positions(n_items, seed=seed + 12345, radius=1.0)
    else:
        raise ValueError("placement must be 'spiral' or 'random'")

    # Build the memory field
    P, roots, shafts = build_memory_field(
        keys=keys,
        values=values,
        positions=positions,
        root_dim=root_dim,
        leak=leak,
        sigma=sigma,
        seed=seed,
    )

    # Evaluate retrieval
    rng = np.random.default_rng(seed + 4242)
    root_hits = 0
    answer_hits = 0
    total = 0
    margins = []

    for i in range(n_items):
        for _ in range(trials_per_item):
            query = normalize(keys[i] + query_noise * rng.normal(size=key_dim))
            top_idx, pred_value_idx, top_score = retrieve(query, P, roots, shafts, values)

            root_hits += int(top_idx == i)
            answer_hits += int(pred_value_idx == i)
            total += 1

            # Simple confidence proxy: top score minus 2nd-best score
            q_root = normalize(P @ query)
            scores = roots @ q_root
            best2 = np.partition(scores, -2)[-2:]
            margins.append(float(best2[1] - best2[0]))  # second-best minus best (negative if clear)

    root_acc = root_hits / total
    answer_acc = answer_hits / total
    avg_margin = float(np.mean(margins))

    nn_dist = mean_nearest_neighbor_distance(positions)
    interference = mean_interference_kernel(positions, sigma=sigma)

    return {
        "placement": placement,
        "seed": seed,
        "root_acc": root_acc,
        "answer_acc": answer_acc,
        "avg_margin": avg_margin,
        "nn_dist": nn_dist,
        "interference": interference,
    }

# -----------------------------
# Sweep leak strength
# -----------------------------
leak_values = np.linspace(0.0, 0.35, 8)
seeds = [0, 1, 2, 3, 4]

spiral_answer = []
random_answer = []
spiral_root = []
random_root = []

for leak in leak_values:
    s_ans, r_ans = [], []
    s_root, r_root = [], []
    for seed in seeds:
        out_s = run_experiment(placement="spiral", seed=seed, leak=leak)
        out_r = run_experiment(placement="random", seed=seed, leak=leak)

        s_ans.append(out_s["answer_acc"])
        r_ans.append(out_r["answer_acc"])
        s_root.append(out_s["root_acc"])
        r_root.append(out_r["root_acc"])

    spiral_answer.append(np.mean(s_ans))
    random_answer.append(np.mean(r_ans))
    spiral_root.append(np.mean(s_root))
    random_root.append(np.mean(r_root))

# -----------------------------
# Report
# -----------------------------
print("=== Memory Hair MVP ===")
print("Definition:")
print("  Follicle = one memory slot")
print("  Root Summary = compressed coarse index")
print("  Shaft / Content = detailed memory")
print("  Scalp = global retriever that searches roots first")
print()

# Show one representative run
