demo_leak = 0.18
out_spiral = run_experiment(placement="spiral", seed=demo_seed, leak=demo_leak)
out_random = run_experiment(placement="random", seed=demo_seed, leak=demo_leak)

print(f"Example run with leak={demo_leak:.2f}, seed={demo_seed}:")
print(f"  Spiral  -> root_acc={out_spiral['root_acc']:.3f}, answer_acc={out_spiral['answer_acc']:.3f}, "
      f"nn_dist={out_spiral['nn_dist']:.3f}, interference={out_spiral['interference']:.3f}")
print(f"  Random  -> root_acc={out_random['root_acc']:.3f}, answer_acc={out_random['answer_acc']:.3f}, "
      f"nn_dist={out_random['nn_dist']:.3f}, interference={out_random['interference']:.3f}")
print()

