# Hair = Memory MVP, v2
# ------------------------------------------------------------
# What this tests:
# 1) Baseline with leak = 0.0
# 2) Sweep root_dim (compressed root size)
# 3) Sweep top-k retrieval
# 4) Multiple seeds for reliability
#
# Follicle = one memory slot
# Root Summary = compressed coarse index
# Shaft / Content = detailed memory
# Scalp = global retriever that searches roots first
#
# Spiral here is ONLY a placement geometry for follicles,
# not your earlier spiral-sparsity weight-masking paper.

import numpy as np
import matplotlib.pyplot as plt
import pandas as pd

# -----------------------------
# Global defaults
# -----------------------------
N_ITEMS = 256
KEY_DIM = 64
VALUE_DIM = 64
QUERY_NOISE = 0.25
SIGMA = 0.18
TRIALS_PER_ITEM = 3
SEEDS = [0, 1, 2, 3, 4]

# Sweeps
LEAK_SWEEP = np.linspace(0.0, 0.35, 8)
ROOT_DIMS = [8, 16, 32, 64]
TOPKS = [1, 3, 5]

# Fixed settings for isolated tests
FIXED_ROOT_DIM = 16
FIXED_TOPK = 1
FIXED_LEAK_FOR_TOPK_SWEEP = 0.10

# -----------------------------
# Utilities
# -----------------------------
def normalize(x, axis=-1, eps=1e-9):
    n = np.linalg.norm(x, axis=axis, keepdims=True)
    return x / (n + eps)

def softmax(x, axis=-1):
    x = x - np.max(x, axis=axis, keepdims=True)
    ex = np.exp(x)
    return ex / (np.sum(ex, axis=axis, keepdims=True) + 1e-9)

# -----------------------------
# Placement functions
# -----------------------------
def fermat_spiral_positions(n, radius=1.0):
    golden_angle = np.pi * (3.0 - np.sqrt(5.0))
    i = np.arange(n)
    r = radius * np.sqrt((i + 0.5) / n)
    theta = i * golden_angle
    x = r * np.cos(theta)
    y = r * np.sin(theta)
    return np.stack([x, y], axis=1)

def random_disk_positions(n, seed=0, radius=1.0):
    rng = np.random.default_rng(seed)
    r = radius * np.sqrt(rng.random(n))
    theta = 2.0 * np.pi * rng.random(n)
    x = r * np.cos(theta)
    y = r * np.sin(theta)
    return np.stack([x, y], axis=1)

def mean_nearest_neighbor_distance(pos):
    d = pos[:, None, :] - pos[None, :, :]
    dist = np.sqrt((d ** 2).sum(-1))
    np.fill_diagonal(dist, np.inf)
    return dist.min(axis=1).mean()

def mean_interference_kernel(pos, sigma):
    d = pos[:, None, :] - pos[None, :, :]
    dist2 = (d ** 2).sum(-1)
    W = np.exp(-dist2 / (2.0 * sigma ** 2))
    np.fill_diagonal(W, 0.0)
    return W.mean()

# -----------------------------
# Synthetic memory generation
# -----------------------------
def make_embeddings(n_items, key_dim, value_dim, seed=0):
    rng = np.random.default_rng(seed)
    keys = normalize(rng.normal(size=(n_items, key_dim)))
    values = normalize(rng.normal(size=(n_items, value_dim)))
    return keys, values

# -----------------------------
# Memory field construction
# -----------------------------
def build_memory_field(keys, values, positions, root_dim=16, leak=0.0, sigma=0.18, seed=0):
    """
    Sequentially write memories into a field.

    root_i  = compressed index of key_i
    shaft_i = detailed content/value_i

    Optional leakage:
      writing item i slightly contaminates nearby follicles
      according to their 2D placement distance.
    """
    rng = np.random.default_rng(seed + 999)
    n, key_dim = keys.shape
    value_dim = values.shape[1]

    P = rng.normal(size=(root_dim, key_dim)) / np.sqrt(key_dim)

    roots = np.zeros((n, root_dim), dtype=np.float64)
    shafts = np.zeros((n, value_dim), dtype=np.float64)

    for i in range(n):
        root_i = normalize(P @ keys[i])
        shaft_i = values[i].copy()

        roots[i] = root_i
        shafts[i] = shaft_i

        if leak > 0:
            d2 = np.sum((positions - positions[i]) ** 2, axis=1)
            w = leak * np.exp(-d2 / (2.0 * sigma ** 2))
            w[i] = 0.0

            if np.any(w > 0):
                roots += w[:, None] * root_i
                shafts += w[:, None] * shaft_i
                roots = normalize(roots)
                shafts = normalize(shafts)

                # keep the focal follicle exact
                roots[i] = root_i
                shafts[i] = shaft_i

    return P, roots, shafts

# -----------------------------
# Vectorized evaluation
# -----------------------------
def evaluate_memory_field(
    keys,
    values,
    P,
    roots,
    shafts,
    query_noise=0.25,
    topk=1,
    trials_per_item=3,
    seed=0,
):
    """
    Returns:
      root1_acc   = top-1 root retrieval accuracy
      rootk_acc   = true index included in top-k root candidates
      answer_acc  = final decoded answer accuracy
    """
    rng = np.random.default_rng(seed + 4242)

    n_items, key_dim = keys.shape
    value_dim = values.shape[1]
    num_q = n_items * trials_per_item

    # Build noisy queries in one shot
    labels = np.repeat(np.arange(n_items), trials_per_item)
    base = np.repeat(keys, trials_per_item, axis=0)
    noise = query_noise * rng.normal(size=(num_q, key_dim))
    queries = normalize(base + noise)

    # Query -> root space
    q_roots = normalize(queries @ P.T)   # (num_q, root_dim)

    # Root search
    scores = q_roots @ roots.T           # (num_q, n_items)
    top1 = np.argmax(scores, axis=1)
    root1_acc = float(np.mean(top1 == labels))

    topk_eff = min(topk, n_items)
    topk_idx = np.argpartition(scores, -topk_eff, axis=1)[:, -topk_eff:]
    rootk_acc = float(np.mean(np.any(topk_idx == labels[:, None], axis=1)))

    # Sort top-k candidates by score so the weighting is stable
    row_idx = np.arange(num_q)[:, None]
    topk_scores = scores[row_idx, topk_idx]
    order = np.argsort(topk_scores, axis=1)[:, ::-1]
    topk_idx = topk_idx[row_idx, order]
    topk_scores = topk_scores[row_idx, order]

    # Soft vote among retrieved follicles
    weights = softmax(topk_scores / 0.2, axis=1)  # temperature = 0.2
    agg_shafts = np.sum(weights[:, :, None] * shafts[topk_idx], axis=1)  # (num_q, value_dim)

    # Decode by nearest value embedding
    ans_scores = agg_shafts @ values.T
    pred = np.argmax(ans_scores, axis=1)
    answer_acc = float(np.mean(pred == labels))

    return {
        "root1_acc": root1_acc,
        "rootk_acc": rootk_acc,
        "answer_acc": answer_acc,
    }

# -----------------------------
# One experiment
# -----------------------------
def run_experiment(
    placement="spiral",
    seed=0,
    n_items=N_ITEMS,
    key_dim=KEY_DIM,
    value_dim=VALUE_DIM,
    root_dim=FIXED_ROOT_DIM,
    query_noise=QUERY_NOISE,
    leak=0.0,
    sigma=SIGMA,
    topk=1,
    trials_per_item=TRIALS_PER_ITEM,
):
    keys, values = make_embeddings(n_items, key_dim, value_dim, seed=seed)

    if placement == "spiral":
        positions = fermat_spiral_positions(n_items, radius=1.0)
    elif placement == "random":
        positions = random_disk_positions(n_items, seed=seed + 12345, radius=1.0)
    else:
        raise ValueError("placement must be 'spiral' or 'random'")

    P, roots, shafts = build_memory_field(
        keys=keys,
        values=values,
        positions=positions,
        root_dim=root_dim,
        leak=leak,
        sigma=sigma,
        seed=seed,
    )

    metrics = evaluate_memory_field(
        keys=keys,
        values=values,
        P=P,
        roots=roots,
        shafts=shafts,
        query_noise=query_noise,
        topk=topk,
        trials_per_item=trials_per_item,
        seed=seed,
    )

    nn_dist = mean_nearest_neighbor_distance(positions)
    interference = mean_interference_kernel(positions, sigma=sigma)

    metrics.update({
        "placement": placement,
        "seed": seed,
        "root_dim": root_dim,
        "leak": leak,
        "topk": topk,
        "nn_dist": nn_dist,
        "interference": interference,
    })
    return metrics

# -----------------------------
# Sweep helper
# -----------------------------
def aggregate_sweep(rows, group_cols):
    df = pd.DataFrame(rows)
    agg = (
        df.groupby(group_cols, as_index=False)
          .agg(
              root1_mean=("root1_acc", "mean"),
              root1_std=("root1_acc", "std"),
              rootk_mean=("rootk_acc", "mean"),
              rootk_std=("rootk_acc", "std"),
              answer_mean=("answer_acc", "mean"),
              answer_std=("answer_acc", "std"),
              nn_dist_mean=("nn_dist", "mean"),
              interference_mean=("interference", "mean"),
          )
    )
    return df, agg

# -----------------------------
# 1) Leak sweep, fixed root_dim/topk
# -----------------------------
rows = []
for leak in LEAK_SWEEP:
    for placement in ["spiral", "random"]:
        for seed in SEEDS:
            out = run_experiment(
                placement=placement,
                seed=seed,
                root_dim=FIXED_ROOT_DIM,
                leak=float(leak),
                topk=FIXED_TOPK,
            )
            rows.append(out)

df_leak, agg_leak = aggregate_sweep(rows, ["placement", "leak"])

print("\n=== Leak sweep (fixed root_dim=16, topk=1) ===")
print(agg_leak[["placement", "leak", "root1_mean", "root1_std", "answer_mean", "answer_std", "nn_dist_mean", "interference_mean"]].to_string(index=False))

# -----------------------------
# 2) Root_dim sweep at leak=0.0, topk=1
# -----------------------------
rows = []
for root_dim in ROOT_DIMS:
    for placement in ["spiral", "random"]:
        for seed in SEEDS:
            out = run_experiment(
                placement=placement,
                seed=seed,
                root_dim=root_dim,
                leak=0.0,
                topk=1,
            )
            rows.append(out)

df_root, agg_root = aggregate_sweep(rows, ["placement", "root_dim"])

print("\n=== Root_dim sweep (leak=0.0, topk=1) ===")
print(agg_root[["placement", "root_dim", "root1_mean", "root1_std", "answer_mean", "answer_std"]].to_string(index=False))

# -----------------------------
# 3) Top-k sweep at leak=0.10, root_dim=16
# -----------------------------
rows = []
for topk in TOPKS:
    for placement in ["spiral", "random"]:
        for seed in SEEDS:
            out = run_experiment(
                placement=placement,
                seed=seed,
                root_dim=FIXED_ROOT_DIM,
                leak=FIXED_LEAK_FOR_TOPK_SWEEP,
                topk=topk,
            )
            rows.append(out)

df_topk, agg_topk = aggregate_sweep(rows, ["placement", "topk"])

print(f"\n=== Top-k sweep (leak={FIXED_LEAK_FOR_TOPK_SWEEP}, root_dim=16) ===")
print(agg_topk[["placement", "topk", "root1_mean", "root1_std", "rootk_mean", "rootk_std", "answer_mean", "answer_std"]].to_string(index=False))

# -----------------------------
# Pretty baseline comparison
# -----------------------------
def pairwise_table(df, group_key, value_key):
    pivot = df.pivot(index=group_key, columns="placement", values=value_key)
    return pivot

print("\n=== Leak sweep: answer accuracy by placement ===")
print(pairwise_table(agg_leak, "leak", "answer_mean").to_string())

print("\n=== Root_dim sweep: answer accuracy by placement ===")
print(pairwise_table(agg_root, "root_dim", "answer_mean").to_string())

print("\n=== Top-k sweep: answer accuracy by placement ===")
print(pairwise_table(agg_topk, "topk", "answer_mean").to_string())

# -----------------------------
# Plots
# -----------------------------
# 1) Leak sweep plot
fig = plt.figure(figsize=(10, 5))
for placement in ["spiral", "random"]:
    sub = agg_leak[agg_leak["placement"] == placement].sort_values("leak")
    plt.errorbar(
        sub["leak"],
        sub["answer_mean"],
        yerr=sub["answer_std"].fillna(0.0),
        marker="o",
        capsize=3,
        label=f"{placement} answer"
    )
    plt.errorbar(
        sub["leak"],
        sub["root1_mean"],
        yerr=sub["root1_std"].fillna(0.0),
        marker="s",
        linestyle="--",
        capsize=3,
        label=f"{placement} root@1"
    )
plt.xlabel("Leak strength")
plt.ylabel("Accuracy")
plt.title("Leak sweep: Spiral vs Random")
plt.grid(True, alpha=0.3)
plt.legend()
plt.show()

# 2) Root_dim sweep plot
