# Memory Hair MVP v3
# ------------------------------------------------------------
# Goal:
# Make spiral placement matter directly in retrieval.
#
# Idea:
# 1) We create clustered memories: related facts are written near each other in write order.
# 2) Spiral placement preserves that locality in 2D space.
# 3) Random placement destroys it.
# 4) Retrieval is two-stage:
#       Stage A: global coarse search over Root Summaries
#       Stage B: local neighborhood rerank using geometric neighbors
#
# This is still a toy MVP.
# It does NOT use your earlier Spiral Sparsity weight-mask paper.
# Here, spiral is only a placement geometry for memory follicles.

import numpy as np
import matplotlib.pyplot as plt
import pandas as pd

# -----------------------------
# Global settings
# -----------------------------
N_GROUPS = 64
GROUP_SIZE = 4
N_ITEMS = N_GROUPS * GROUP_SIZE

KEY_DIM = 64
VALUE_DIM = 64
ROOT_DIM = 32

QUERY_NOISE = 0.25
KEY_JITTER = 0.12
VALUE_JITTER = 0.12

TOPK_GLOBAL = 5      # stage-1 coarse candidates
LOCAL_K = 9          # local neighborhood size around each candidate
ALPHA_ROOT = 0.60    # weight for candidate's own root score
SEEDS = [0, 1, 2, 3, 4]

# Neighborhood weighting temperature
LOCAL_TAU = 0.18

# -----------------------------
# Utilities
# -----------------------------
def normalize(x, axis=-1, eps=1e-9):
    n = np.linalg.norm(x, axis=axis, keepdims=True)
    return x / (n + eps)

def softmax(x, axis=-1):
    x = x - np.max(x, axis=axis, keepdims=True)
    ex = np.exp(x)
    return ex / (np.sum(ex, axis=axis, keepdims=True) + 1e-9)

# -----------------------------
# Geometry / placement
# -----------------------------
def fermat_spiral_positions(n, radius=1.0):
    golden_angle = np.pi * (3.0 - np.sqrt(5.0))
    i = np.arange(n)
    r = radius * np.sqrt((i + 0.5) / n)
    theta = i * golden_angle
    x = r * np.cos(theta)
    y = r * np.sin(theta)
    return np.stack([x, y], axis=1)

def random_disk_positions(n, seed=0, radius=1.0):
    rng = np.random.default_rng(seed)
    r = radius * np.sqrt(rng.random(n))
    theta = 2.0 * np.pi * rng.random(n)
    x = r * np.cos(theta)
    y = r * np.sin(theta)
    return np.stack([x, y], axis=1)

def nearest_neighbors_by_position(positions, idx, k):
    d2 = np.sum((positions - positions[idx]) ** 2, axis=1)
    nn = np.argpartition(d2, k)[:k]
    return nn, d2[nn]

def mean_nearest_neighbor_distance(pos):
    d = pos[:, None, :] - pos[None, :, :]
    dist = np.sqrt((d ** 2).sum(-1))
    np.fill_diagonal(dist, np.inf)
    return dist.min(axis=1).mean()

def mean_interference_kernel(pos, sigma=0.18):
    d = pos[:, None, :] - pos[None, :, :]
    dist2 = (d ** 2).sum(-1)
    W = np.exp(-dist2 / (2.0 * sigma ** 2))
    np.fill_diagonal(W, 0.0)
    return W.mean()

# -----------------------------
# Synthetic clustered memory
# -----------------------------
def make_clustered_memory(
    n_groups,
    group_size,
    key_dim,
    value_dim,
    seed=0,
    key_jitter=0.12,
    value_jitter=0.12,
):
    """
    Creates semantically related items in clusters.

    Each group has its own latent center.
    Items in the same group are similar in key/value space.
    This makes local neighborhood retrieval meaningful.
    """
    rng = np.random.default_rng(seed)
    keys = []
    values = []
    group_ids = []

    key_centers = normalize(rng.normal(size=(n_groups, key_dim)))
    value_centers = normalize(rng.normal(size=(n_groups, value_dim)))

    for g in range(n_groups):
        for _ in range(group_size):
            k = normalize(key_centers[g] + key_jitter * rng.normal(size=key_dim))
            v = normalize(value_centers[g] + value_jitter * rng.normal(size=value_dim))
            keys.append(k)
            values.append(v)
            group_ids.append(g)

    keys = np.stack(keys, axis=0)
    values = np.stack(values, axis=0)
    group_ids = np.array(group_ids, dtype=int)
    return keys, values, group_ids

# -----------------------------
# Memory field construction
# -----------------------------
def build_memory_field(keys, values, positions, root_dim=32, seed=0):
    """
    Root Summary = compressed coarse index of the key
    Shaft = detailed content/value
    """
    rng = np.random.default_rng(seed + 999)
    n, key_dim = keys.shape
    value_dim = values.shape[1]

    P = rng.normal(size=(root_dim, key_dim)) / np.sqrt(key_dim)

    roots = normalize(keys @ P.T)   # (n, root_dim)
    shafts = values.copy()          # (n, value_dim)

    return P, roots, shafts

# -----------------------------
# Retrieval
# -----------------------------
def stage1_global_search(query_key, P, roots):
    q_root = normalize(query_key @ P.T)
    scores = roots @ q_root
    return q_root, scores

def stage2_local_rerank(scores, positions, top_candidates, local_k=9, alpha_root=0.6, local_tau=0.18):
    """
    For each coarse candidate:
      - look at its geometric neighborhood in 2D
      - compute local support from neighboring follicles
      - rerank using root score + neighborhood support

    This makes the placement geometry matter directly.
    """
    final_scores = []
    for c in top_candidates:
        nn, d2 = nearest_neighbors_by_position(positions, c, k=min(local_k, len(positions)))
        local_w = np.exp(-d2 / (2.0 * local_tau ** 2))
        local_w = local_w / (local_w.sum() + 1e-9)

        local_support = np.sum(local_w * scores[nn])
        final_score = alpha_root * scores[c] + (1.0 - alpha_root) * local_support
        final_scores.append(final_score)

    final_scores = np.array(final_scores)
    best_idx_in_top = int(np.argmax(final_scores))
    return int(top_candidates[best_idx_in_top]), final_scores

def evaluate_system(
    keys,
    values,
    group_ids,
    P,
    roots,
    shafts,
    positions,
    query_noise=0.25,
    topk_global=5,
    local_k=9,
    alpha_root=0.6,
    local_tau=0.18,
    trials_per_item=3,
    seed=0,
):
    rng = np.random.default_rng(seed + 4242)
    n_items, key_dim = keys.shape

    total = 0
    global_top1_hits = 0
    global_topk_hits = 0
    local_hits = 0
    group_hits = 0

    for i in range(n_items):
        for _ in range(trials_per_item):
            query = normalize(keys[i] + query_noise * rng.normal(size=key_dim))
            q_root, scores = stage1_global_search(query, P, roots)

            # Stage 1
            top1 = int(np.argmax(scores))
            global_top1_hits += int(top1 == i)

            top_candidates = np.argpartition(scores, -min(topk_global, n_items))[-min(topk_global, n_items):]
            global_topk_hits += int(i in top_candidates)

            # Stage 2
            best_idx, rerank_scores = stage2_local_rerank(
                scores=scores,
                positions=positions,
                top_candidates=top_candidates,
                local_k=local_k,
                alpha_root=alpha_root,
                local_tau=local_tau,
            )
            local_hits += int(best_idx == i)
            group_hits += int(group_ids[best_idx] == group_ids[i])

            total += 1

    return {
        "global_top1_acc": global_top1_hits / total,
        "global_topk_acc": global_topk_hits / total,
        "local_rerank_acc": local_hits / total,
        "group_acc": group_hits / total,
    }

# -----------------------------
# One full experiment
# -----------------------------
def run_experiment(
    placement="spiral",
    seed=0,
    root_dim=32,
    topk_global=5,
    local_k=9,
    alpha_root=0.6,
    query_noise=0.25,
    trials_per_item=3,
):
    keys, values, group_ids = make_clustered_memory(
        n_groups=N_GROUPS,
        group_size=GROUP_SIZE,
        key_dim=KEY_DIM,
        value_dim=VALUE_DIM,
        seed=seed,
        key_jitter=KEY_JITTER,
        value_jitter=VALUE_JITTER,
    )

    if placement == "spiral":
        positions = fermat_spiral_positions(N_ITEMS, radius=1.0)
    elif placement == "random":
        positions = random_disk_positions(N_ITEMS, seed=seed + 12345, radius=1.0)
    else:
        raise ValueError("placement must be 'spiral' or 'random'")

    P, roots, shafts = build_memory_field(
        keys=keys,
        values=values,
        positions=positions,
        root_dim=root_dim,
        seed=seed,
    )

    metrics = evaluate_system(
        keys=keys,
        values=values,
        group_ids=group_ids,
        P=P,
        roots=roots,
        shafts=shafts,
        positions=positions,
        query_noise=query_noise,
        topk_global=topk_global,
        local_k=local_k,
        alpha_root=alpha_root,
        local_tau=LOCAL_TAU,
        trials_per_item=trials_per_item,
        seed=seed,
    )

    metrics.update({
        "placement": placement,
        "seed": seed,
        "root_dim": root_dim,
        "topk_global": topk_global,
        "local_k": local_k,
        "alpha_root": alpha_root,
        "query_noise": query_noise,
        "nn_dist": mean_nearest_neighbor_distance(positions),
        "interference": mean_interference_kernel(positions),
    })
    return metrics

# -----------------------------
# Sweeps
# -----------------------------
def aggregate(rows, group_cols):
    df = pd.DataFrame(rows)
    agg = (
        df.groupby(group_cols, as_index=False)
          .agg(
              global_top1_mean=("global_top1_acc", "mean"),
              global_top1_std=("global_top1_acc", "std"),
              global_topk_mean=("global_topk_acc", "mean"),
              global_topk_std=("global_topk_acc", "std"),
              local_rerank_mean=("local_rerank_acc", "mean"),
              local_rerank_std=("local_rerank_acc", "std"),
              group_acc_mean=("group_acc", "mean"),
              group_acc_std=("group_acc", "std"),
              nn_dist_mean=("nn_dist", "mean"),
              interference_mean=("interference", "mean"),
          )
    )
    return df, agg

# 1) Sweep local neighborhood size
LOCAL_K_VALUES = [3, 5, 9, 15, 25]
rows = []
for local_k in LOCAL_K_VALUES:
    for placement in ["spiral", "random"]:
        for seed in SEEDS:
            out = run_experiment(
                placement=placement,
                seed=seed,
                root_dim=ROOT_DIM,
                topk_global=TOPK_GLOBAL,
                local_k=local_k,
                alpha_root=ALPHA_ROOT,
                query_noise=QUERY_NOISE,
                trials_per_item=3,
            )
            rows.append(out)

df_local, agg_local = aggregate(rows, ["placement", "local_k"])

print("\n=== Local neighborhood sweep ===")
print(agg_local[[
    "placement", "local_k",
    "global_top1_mean", "global_top1_std",
    "global_topk_mean", "global_topk_std",
    "local_rerank_mean", "local_rerank_std",
    "group_acc_mean", "group_acc_std",
    "nn_dist_mean", "interference_mean"
]].to_string(index=False))

# 2) Sweep root dimension to see if compression bottlenecks the system
ROOT_DIMS = [8, 16, 32, 64]
rows = []
for root_dim in ROOT_DIMS:
    for placement in ["spiral", "random"]:
        for seed in SEEDS:
            out = run_experiment(
                placement=placement,
                seed=seed,
                root_dim=root_dim,
                topk_global=TOPK_GLOBAL,
                local_k=LOCAL_K,
                alpha_root=ALPHA_ROOT,
                query_noise=QUERY_NOISE,
                trials_per_item=3,
            )
            rows.append(out)

df_root, agg_root = aggregate(rows, ["placement", "root_dim"])

print("\n=== Root dimension sweep ===")
print(agg_root[[
    "placement", "root_dim",
    "global_top1_mean", "global_topk_mean",
    "local_rerank_mean", "group_acc_mean"
]].to_string(index=False))

# 3) Sweep query noise to test robustness
NOISE_VALUES = [0.10, 0.20, 0.30, 0.40]
rows = []
for query_noise in NOISE_VALUES:
    for placement in ["spiral", "random"]:
        for seed in SEEDS:
            out = run_experiment(
                placement=placement,
                seed=seed,
                root_dim=ROOT_DIM,
                topk_global=TOPK_GLOBAL,
                local_k=LOCAL_K,
                alpha_root=ALPHA_ROOT,
                query_noise=query_noise,
                trials_per_item=3,
            )
            rows.append(out)

df_noise, agg_noise = aggregate(rows, ["placement", "query_noise"])

print("\n=== Query noise sweep ===")
print(agg_noise[[
    "placement", "query_noise",
    "global_top1_mean", "global_topk_mean",
    "local_rerank_mean", "group_acc_mean"
]].to_string(index=False))

# -----------------------------
# Plotting
# -----------------------------
