# Memory Hair MVP v4
# ------------------------------------------------------------
# New change:
# Spatial-window retrieval.
#
# Retrieval now works like this:
#   1) Global coarse search over root summaries
#   2) Pick the best candidate
#   3) Open only a local spatial window around that candidate
#   4) Use the local neighborhood to refine the answer
#
# Why this matters:
# Spiral placement should help if locality is important,
# because nearby follicles in spiral space are more evenly structured.
# Random placement should be noisier.
#
# This is still a toy MVP. It is a test of the hair idea,
# not your earlier spiral-sparsity paper.

import numpy as np
import matplotlib.pyplot as plt
import pandas as pd

# -----------------------------
# Global settings
# -----------------------------
N_GROUPS = 64
GROUP_SIZE = 4
N_ITEMS = N_GROUPS * GROUP_SIZE

KEY_DIM = 64
VALUE_DIM = 64
ROOT_DIM = 32

QUERY_NOISE = 0.25
KEY_JITTER = 0.12
VALUE_JITTER = 0.12

SEEDS = [0, 1, 2, 3, 4]

# Retrieval settings
TOPK_GLOBAL = 5
WINDOW_RADIUS_VALUES = [0.06, 0.10, 0.14, 0.18, 0.24]
ALPHA_ROOT = 0.55
ALPHA_LOCAL = 0.45

# -----------------------------
# Utilities
# -----------------------------
def normalize(x, axis=-1, eps=1e-9):
    n = np.linalg.norm(x, axis=axis, keepdims=True)
    return x / (n + eps)

def softmax(x, axis=-1):
    x = x - np.max(x, axis=axis, keepdims=True)
    ex = np.exp(x)
    return ex / (np.sum(ex, axis=axis, keepdims=True) + 1e-9)

# -----------------------------
# Geometry / placement
# -----------------------------
def fermat_spiral_positions(n, radius=1.0):
    golden_angle = np.pi * (3.0 - np.sqrt(5.0))
    i = np.arange(n)
    r = radius * np.sqrt((i + 0.5) / n)
    theta = i * golden_angle
    x = r * np.cos(theta)
    y = r * np.sin(theta)
    return np.stack([x, y], axis=1)

def random_disk_positions(n, seed=0, radius=1.0):
    rng = np.random.default_rng(seed)
    r = radius * np.sqrt(rng.random(n))
    theta = 2.0 * np.pi * rng.random(n)
    x = r * np.cos(theta)
    y = r * np.sin(theta)
    return np.stack([x, y], axis=1)

def mean_nearest_neighbor_distance(pos):
    d = pos[:, None, :] - pos[None, :, :]
    dist = np.sqrt((d ** 2).sum(-1))
    np.fill_diagonal(dist, np.inf)
    return dist.min(axis=1).mean()

def mean_interference_kernel(pos, sigma=0.18):
    d = pos[:, None, :] - pos[None, :, :]
    dist2 = (d ** 2).sum(-1)
    W = np.exp(-dist2 / (2.0 * sigma ** 2))
    np.fill_diagonal(W, 0.0)
    return W.mean()

def within_radius(pos, center_idx, radius):
    d2 = np.sum((pos - pos[center_idx]) ** 2, axis=1)
    return np.where(d2 <= radius ** 2)[0]

# -----------------------------
# Synthetic clustered memory
# -----------------------------
def make_clustered_memory(n_groups, group_size, key_dim, value_dim, seed=0, key_jitter=0.12, value_jitter=0.12):
    rng = np.random.default_rng(seed)
    keys = []
    values = []
    group_ids = []

    key_centers = normalize(rng.normal(size=(n_groups, key_dim)))
    value_centers = normalize(rng.normal(size=(n_groups, value_dim)))

    for g in range(n_groups):
        for _ in range(group_size):
            k = normalize(key_centers[g] + key_jitter * rng.normal(size=key_dim))
            v = normalize(value_centers[g] + value_jitter * rng.normal(size=value_dim))
            keys.append(k)
            values.append(v)
            group_ids.append(g)

    return np.stack(keys), np.stack(values), np.array(group_ids, dtype=int)

# -----------------------------
# Memory field
# -----------------------------
def build_memory_field(keys, values, root_dim=32, seed=0):
    rng = np.random.default_rng(seed + 999)
    n, key_dim = keys.shape
    P = rng.normal(size=(root_dim, key_dim)) / np.sqrt(key_dim)
    roots = normalize(keys @ P.T)
    shafts = values.copy()
    return P, roots, shafts

# -----------------------------
# Retrieval
# -----------------------------
def stage1_global_search(query_key, P, roots):
    q_root = normalize(query_key @ P.T)
    scores = roots @ q_root
    return q_root, scores

def stage2_spatial_window_rerank(
    scores,
    query_key,
    values,
    positions,
    top_candidates,
    P,
    roots,
    window_radius=0.12,
    alpha_root=0.55,
    alpha_local=0.45,
):
    """
    For each global candidate:
      - open a local spatial window around that candidate
      - pool scores from neighbors inside the window
      - mix candidate root score + local window support
      - decode the answer from the locally pooled content

    This makes placement directly matter.
    """
    q_root = normalize(query_key @ P.T)

    final_scores = []
    final_value_vectors = []

    for c in top_candidates:
        local_idx = within_radius(positions, c, window_radius)

        # Ensure the candidate itself is always included
        if c not in local_idx:
            local_idx = np.unique(np.append(local_idx, c))

        # Local support from root scores
        local_root_support = scores[local_idx]

        # Local content support: neighbors that look like the query in value-space
        # We use a soft query-to-value similarity proxy
        qv = query_key
        local_content_scores = values[local_idx] @ qv

        # Normalize local weights
        w_root = softmax(local_root_support / 0.15)
        w_cont = softmax(local_content_scores / 0.15)

        local_value = np.sum((0.5 * w_root[:, None] + 0.5 * w_cont[:, None]) * values[local_idx], axis=0)

        candidate_score = alpha_root * scores[c] + alpha_local * np.max(local_root_support)
        final_scores.append(candidate_score)
        final_value_vectors.append(local_value)

    final_scores = np.array(final_scores)
    final_value_vectors = np.stack(final_value_vectors, axis=0)

    best_in_top = int(np.argmax(final_scores))
    return int(top_candidates[best_in_top]), final_value_vectors[best_in_top]

def evaluate_system(
    keys,
    values,
    group_ids,
    P,
    roots,
    shafts,
    positions,
    window_radius=0.12,
    query_noise=0.25,
    topk_global=5,
    trials_per_item=3,
    seed=0,
):
    rng = np.random.default_rng(seed + 4242)
    n_items, key_dim = keys.shape

    total = 0
    global_top1_hits = 0
    global_topk_hits = 0
    spatial_hits = 0
    group_hits = 0

    for i in range(n_items):
        for _ in range(trials_per_item):
            query = normalize(keys[i] + query_noise * rng.normal(size=key_dim))

            q_root, scores = stage1_global_search(query, P, roots)

            top1 = int(np.argmax(scores))
            global_top1_hits += int(top1 == i)

            k = min(topk_global, n_items)
            top_candidates = np.argpartition(scores, -k)[-k:]
            global_topk_hits += int(i in top_candidates)

            best_idx, pooled_value = stage2_spatial_window_rerank(
                scores=scores,
                query_key=query,
                values=values,
                positions=positions,
                top_candidates=top_candidates,
                P=P,
                roots=roots,
                window_radius=window_radius,
                alpha_root=ALPHA_ROOT,
                alpha_local=ALPHA_LOCAL,
            )

            spatial_hits += int(best_idx == i)

            # Final decode from pooled local value vector
            pred = int(np.argmax(pooled_value @ values.T))
            group_hits += int(group_ids[pred] == group_ids[i])

            total += 1

    return {
        "global_top1_acc": global_top1_hits / total,
        "global_topk_acc": global_topk_hits / total,
        "spatial_rerank_acc": spatial_hits / total,
        "group_acc": group_hits / total,
    }

# -----------------------------
# Full experiment
# -----------------------------
def run_experiment(
    placement="spiral",
    seed=0,
    root_dim=32,
    window_radius=0.12,
    query_noise=0.25,
    topk_global=5,
    trials_per_item=3,
):
    keys, values, group_ids = make_clustered_memory(
        n_groups=N_GROUPS,
        group_size=GROUP_SIZE,
        key_dim=KEY_DIM,
        value_dim=VALUE_DIM,
        seed=seed,
        key_jitter=KEY_JITTER,
        value_jitter=VALUE_JITTER,
    )

    if placement == "spiral":
        positions = fermat_spiral_positions(N_ITEMS, radius=1.0)
    elif placement == "random":
        positions = random_disk_positions(N_ITEMS, seed=seed + 12345, radius=1.0)
    else:
        raise ValueError("placement must be 'spiral' or 'random'")

    P, roots, shafts = build_memory_field(keys, values, root_dim=root_dim, seed=seed)

    metrics = evaluate_system(
        keys=keys,
        values=values,
        group_ids=group_ids,
        P=P,
        roots=roots,
        shafts=shafts,
        positions=positions,
        window_radius=window_radius,
        query_noise=query_noise,
        topk_global=topk_global,
        trials_per_item=trials_per_item,
        seed=seed,
    )

    metrics.update({
        "placement": placement,
        "seed": seed,
        "root_dim": root_dim,
        "window_radius": window_radius,
        "query_noise": query_noise,
        "topk_global": topk_global,
        "nn_dist": mean_nearest_neighbor_distance(positions),
        "interference": mean_interference_kernel(positions),
    })
    return metrics

# -----------------------------
# Sweeps
# -----------------------------
def aggregate(rows, group_cols):
    df = pd.DataFrame(rows)
    agg = (
        df.groupby(group_cols, as_index=False)
          .agg(
              global_top1_mean=("global_top1_acc", "mean"),
              global_top1_std=("global_top1_acc", "std"),
              global_topk_mean=("global_topk_acc", "mean"),
              global_topk_std=("global_topk_acc", "std"),
              spatial_rerank_mean=("spatial_rerank_acc", "mean"),
              spatial_rerank_std=("spatial_rerank_acc", "std"),
              group_acc_mean=("group_acc", "mean"),
              group_acc_std=("group_acc", "std"),
              nn_dist_mean=("nn_dist", "mean"),
              interference_mean=("interference", "mean"),
          )
    )
    return df, agg

# 1) Window radius sweep
