# QDMN-Follicle MVP v7 — Group-first active follicle
# ------------------------------------------------------------
# What changed vs v6:
# - The active follicle is trained with CrossEntropy on GROUP labels
# - Passive baselines stay for exact-item retrieval
# - Active inference first predicts the group, then retrieves the exact item
# - Spiral vs random is still only the memory-field geometry prior
#
# This is the cleanest next test after the v6 failure:
#   "Can the QDMN follicle learn coarse group structure first?"
#
# After that, exact-item retrieval can be revisited with a stronger loss.
#
# Output:
# - main comparison table
# - root_dim sweep
# - local_radius sweep
# - query_noise sweep
# - combined subfigures
#
# Requirements:
# - numpy
# - pandas
# - matplotlib
# - torch
# - scikit-learn

import os
import math
import random
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt

import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.data import DataLoader, TensorDataset

# ============================================================
# Config
# ============================================================
SEEDS = [0, 1, 2]
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")

N_GROUPS = 64
GROUP_SIZE = 4
N_ITEMS = N_GROUPS * GROUP_SIZE

KEY_DIM = 64
VALUE_DIM = 64

ROOT_DIMS = [16, 32, 64]
QUERY_NOISES = [0.10, 0.20, 0.30, 0.40]
LOCAL_RADII = [0.06, 0.10, 0.12, 0.16, 0.20]

TOPK_GLOBAL = 5
TRAIN_QUERY_NOISE = 0.25
TRAIN_LOCAL_RADIUS = 0.12
TRAIN_SAMPLES_PER_ITEM = 4

BATCH = 64
EPOCHS_FOLLICLE = 25
LR = 1e-3
B_LOOPS = 2

KEY_JITTER = 0.12
VALUE_JITTER = 0.12

OUTDIR = "qdmn_follicle_group_artifacts"
os.makedirs(OUTDIR, exist_ok=True)

print("Device:", DEVICE)
print("Artifacts:", OUTDIR)

# ============================================================
# Utilities
# ============================================================
def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if DEVICE.type == "cuda":
        torch.cuda.manual_seed_all(seed)

def normalize_np(x, axis=-1, eps=1e-9):
    n = np.linalg.norm(x, axis=axis, keepdims=True)
    return x / (n + eps)

def softmax_np(x, axis=-1, temperature=1.0):
    x = x / max(temperature, 1e-9)
    x = x - np.max(x, axis=axis, keepdims=True)
    ex = np.exp(x)
    return ex / (np.sum(ex, axis=axis, keepdims=True) + 1e-9)

# ============================================================
# Geometry / placement
# ============================================================
def fermat_spiral_positions(n, radius=1.0):
    golden_angle = np.pi * (3.0 - np.sqrt(5.0))
    i = np.arange(n)
    r = radius * np.sqrt((i + 0.5) / n)
    theta = i * golden_angle
    x = r * np.cos(theta)
    y = r * np.sin(theta)
    return np.stack([x, y], axis=1)

def random_disk_positions(n, seed=0, radius=1.0):
    rng = np.random.default_rng(seed)
    r = radius * np.sqrt(rng.random(n))
    theta = 2.0 * np.pi * rng.random(n)
    x = r * np.cos(theta)
    y = r * np.sin(theta)
    return np.stack([x, y], axis=1)

def mean_nearest_neighbor_distance(pos):
    d = pos[:, None, :] - pos[None, :, :]
    dist = np.sqrt((d ** 2).sum(-1))
    np.fill_diagonal(dist, np.inf)
    return dist.min(axis=1).mean()

def mean_interference_kernel(pos, sigma=0.18):
    d = pos[:, None, :] - pos[None, :, :]
    dist2 = (d ** 2).sum(-1)
    W = np.exp(-dist2 / (2.0 * sigma ** 2))
    np.fill_diagonal(W, 0.0)
    return W.mean()

def within_radius(pos, center_idx, radius):
    d2 = np.sum((pos - pos[center_idx]) ** 2, axis=1)
    return np.where(d2 <= radius ** 2)[0]

# ============================================================
# Synthetic clustered memory
# ============================================================
def make_clustered_memory(n_groups, group_size, key_dim, value_dim, seed=0, key_jitter=0.12, value_jitter=0.12):
    rng = np.random.default_rng(seed)
    keys = []
    values = []
    group_ids = []

    key_centers = normalize_np(rng.normal(size=(n_groups, key_dim)))
    value_centers = normalize_np(rng.normal(size=(n_groups, value_dim)))

    for g in range(n_groups):
        for _ in range(group_size):
            k = normalize_np(key_centers[g] + key_jitter * rng.normal(size=key_dim))
            v = normalize_np(value_centers[g] + value_jitter * rng.normal(size=value_dim))
            keys.append(k)
            values.append(v)
            group_ids.append(g)

    return np.stack(keys), np.stack(values), np.array(group_ids, dtype=int)

def split_by_group(group_ids, test_per_group=1, seed=0):
    """
    Guaranteed split:
    - one test item per group
    - rest train
    """
    rng = np.random.default_rng(seed)
    train_ids = []
    test_ids = []

    for g in np.unique(group_ids):
        idx = np.where(group_ids == g)[0]
        if len(idx) <= test_per_group:
            raise ValueError(f"Group {g} has too few items for split.")
        test_sel = rng.choice(idx, size=test_per_group, replace=False)
        train_sel = np.array([i for i in idx if i not in set(test_sel.tolist())], dtype=int)
        test_ids.extend(test_sel.tolist())
        train_ids.extend(train_sel.tolist())

    return np.array(train_ids, dtype=int), np.array(test_ids, dtype=int)

# ============================================================
# Memory field
# ============================================================
def build_memory_field(keys, values, root_dim=32, seed=0):
    rng = np.random.default_rng(seed + 999)
    n, key_dim = keys.shape
    P = rng.normal(size=(root_dim, key_dim)) / np.sqrt(key_dim)
    roots = normalize_np(keys @ P.T)
    shafts = values.copy()
    return P, roots, shafts

def global_search(query_key, P, roots):
    q_root = normalize_np(query_key @ P.T)
    scores = roots @ q_root
    return q_root, scores

def build_local_context(q_root, scores, positions, candidate_idx, roots, shafts, local_radius):
    local_idx = within_radius(positions, candidate_idx, local_radius)
    if len(local_idx) == 0:
        local_idx = np.array([candidate_idx], dtype=int)

    d2 = np.sum((positions[local_idx] - positions[candidate_idx]) ** 2, axis=1)
    spatial_w = np.exp(-d2 / (2.0 * max(local_radius, 1e-6) ** 2))
    root_w = softmax_np(scores[local_idx], temperature=0.15)
    qroot_w = softmax_np(roots[local_idx] @ q_root, temperature=0.15)

    w = 0.4 * spatial_w + 0.3 * root_w + 0.3 * qroot_w
    w = w / (w.sum() + 1e-9)

    context = np.sum(w[:, None] * shafts[local_idx], axis=0)
    return context

# ============================================================
# QDMN-style follicle processor
# ============================================================
class ContractiveRefiner(nn.Module):
    def __init__(self, dim):
        super().__init__()
        self.linear = nn.utils.parametrizations.spectral_norm(nn.Linear(dim, dim))
        self.gate = nn.Linear(dim, 1)
        self.alpha = 0.08

    def forward(self, x):
        g = torch.sigmoid(self.gate(x))
        delta = torch.tanh(self.linear(x))
        return x + self.alpha * g * delta

class MiniFollicleQDMN(nn.Module):
    """
    Tiny directional processor inside one follicle.

    Route:
      F -> U -> B -> B -> D -> H
    """
    def __init__(self, input_dim, hidden=128, bottleneck=64, out_dim=64):
        super().__init__()
        self.F = nn.Linear(input_dim, hidden)
        self.U = nn.Linear(hidden, bottleneck)
        self.B = ContractiveRefiner(bottleneck)
        self.D = nn.Linear(bottleneck, hidden)
        self.H = nn.Linear(hidden, out_dim)

    def route(self, x, b_loops=2):
        s = torch.relu(self.F(x))
        s = torch.relu(self.U(s))
        for _ in range(b_loops):
            s = self.B(s)
        s = torch.relu(self.D(s))
        out = self.H(s)
        return out

    def forward(self, x, b_loops=2):
        return self.route(x, b_loops=b_loops)

# ============================================================
# Baselines
# ============================================================
def decode_to_item(vec, values):
    sims = vec @ values.T
    return int(np.argmax(sims))

def passive_top1(query_key, P, roots, shafts, values):
    _, scores = global_search(query_key, P, roots)
    best = int(np.argmax(scores))
    pred = decode_to_item(shafts[best], values)
    return best, pred, scores

def passive_topk(query_key, P, roots, shafts, values, topk=5):
    _, scores = global_search(query_key, P, roots)
    k = min(topk, len(scores))
    top_idx = np.argpartition(scores, -k)[-k:]
    top_scores = scores[top_idx]
    w = softmax_np(top_scores, temperature=0.20)
    pooled = np.sum(w[:, None] * shafts[top_idx], axis=0)
    pred = decode_to_item(pooled, values)
    best = int(top_idx[np.argmax(top_scores)])
    return best, pred, scores

# ============================================================
# Dataset for training the follicle processor
# ============================================================
def make_follicle_training_set(
    train_ids,
    keys,
    values,
    roots,
    shafts,
    positions,
    P,
    group_ids,
    query_noise=0.25,
    local_radius=0.12,
    samples_per_item=4,
    seed=0,
):
    """
    Active target = group label, not exact item label.
    This matches what the previous experiments suggested the active model could learn.
    """
    rng = np.random.default_rng(seed + 4242)
    xs = []
    ys = []

    for i in train_ids:
        for _ in range(samples_per_item):
            q = normalize_np(keys[i] + query_noise * rng.normal(size=KEY_DIM))
            q_root, scores = global_search(q, P, roots)

            # Use the top-k candidates to build training examples
            topk = min(TOPK_GLOBAL, len(scores))
            top_idx = np.argpartition(scores, -topk)[-topk:]

            for c in top_idx:
                context = build_local_context(q_root, scores, positions, c, roots, shafts, local_radius)
                x = np.concatenate([q_root, roots[c], context], axis=0).astype(np.float32)
                y = int(group_ids[i])  # group label
                xs.append(x)
                ys.append(y)

    X = torch.tensor(np.stack(xs), dtype=torch.float32)
    Y = torch.tensor(np.array(ys), dtype=torch.long)
    return X, Y

def train_group_follicle(model, train_loader, epochs=25, lr=1e-3):
    model.to(DEVICE)
    opt = torch.optim.Adam(model.parameters(), lr=lr)
    loss_fn = nn.CrossEntropyLoss()

    model.train()
    for _ in range(epochs):
        for xb, yb in train_loader:
            xb = xb.to(DEVICE)
            yb = yb.to(DEVICE)
            opt.zero_grad()
            logits = model(xb, b_loops=B_LOOPS)
            loss = loss_fn(logits, yb)
            loss.backward()
            opt.step()

def eval_group_follicle(
    model,
    test_ids,
    keys,
    values,
    roots,
    shafts,
    positions,
    P,
    group_ids,
    query_noise=0.25,
    topk=5,
    local_radius=0.12,
    trials_per_item=3,
    seed=0,
):
    """
    Active inference:
    1) search top-k candidates globally
    2) run QDMN follicle on each candidate
    3) aggregate group logits
    4) predict group
    5) retrieve exact item by restricting to the predicted group
    """
    rng = np.random.default_rng(seed + 9999)
    model.eval()

    total = 0
    group_hits = 0
    item_hits = 0

    with torch.no_grad():
        for i in test_ids:
            true_group = int(group_ids[i])

            for _ in range(trials_per_item):
                q = normalize_np(keys[i] + query_noise * rng.normal(size=KEY_DIM))
                q_root, scores = global_search(q, P, roots)

                k = min(topk, len(scores))
                top_idx = np.argpartition(scores, -k)[-k:]
                top_scores = scores[top_idx]
                cand_w = softmax_np(top_scores, temperature=0.20)

                group_logits_agg = None

                for j, c in enumerate(top_idx):
                    context = build_local_context(q_root, scores, positions, c, roots, shafts, local_radius)
                    x = np.concatenate([q_root, roots[c], context], axis=0).astype(np.float32)
                    xb = torch.tensor(x[None, :], dtype=torch.float32, device=DEVICE)

                    logits = model(xb, b_loops=B_LOOPS)[0]  # (N_GROUPS,)
                    weighted_logits = cand_w[j] * logits

                    if group_logits_agg is None:
                        group_logits_agg = weighted_logits
                    else:
                        group_logits_agg = group_logits_agg + weighted_logits

                pred_group = int(torch.argmax(group_logits_agg).item())
                group_hits += int(pred_group == true_group)

                # Exact item retrieval from the predicted group:
                group_mask = np.where(group_ids == pred_group)[0]
                if len(group_mask) == 0:
                    pred_item = int(np.argmax(scores))
                else:
                    pred_item = int(group_mask[np.argmax(scores[group_mask])])

                item_hits += int(pred_item == i)
                total += 1

    return {
        "group_acc": group_hits / total,
        "item_acc": item_hits / total,
    }

def eval_passive(
    test_ids,
    keys,
    values,
    roots,
    shafts,
    positions,
    P,
    group_ids,
    query_noise=0.25,
    topk=5,
    local_radius=0.12,
    trials_per_item=3,
    seed=0,
):
    rng = np.random.default_rng(seed + 9999)
    total = 0
    top1_hits = 0
    top1_group_hits = 0
    topk_hits = 0
    topk_pool_hits = 0
    topk_pool_group_hits = 0

    for i in test_ids:
        true_group = int(group_ids[i])

        for _ in range(trials_per_item):
            q = normalize_np(keys[i] + query_noise * rng.normal(size=KEY_DIM))
            _, scores = global_search(q, P, roots)

            top1 = int(np.argmax(scores))
            top1_hits += int(top1 == i)
            top1_group_hits += int(group_ids[top1] == true_group)

            k = min(topk, len(scores))
            top_idx = np.argpartition(scores, -k)[-k:]
            topk_hits += int(i in top_idx)

            top_scores = scores[top_idx]
            w = softmax_np(top_scores, temperature=0.20)
            pooled = np.sum(w[:, None] * shafts[top_idx], axis=0)
            pred_pool = decode_to_item(pooled, values)
            topk_pool_hits += int(pred_pool == i)
            topk_pool_group_hits += int(group_ids[pred_pool] == true_group)

            total += 1

    return {
        "passive_top1_item": top1_hits / total,
        "passive_top1_group": top1_group_hits / total,
        "passive_topk_set": topk_hits / total,
        "passive_topk_pool_item": topk_pool_hits / total,
        "passive_topk_pool_group": topk_pool_group_hits / total,
    }

# ============================================================
# Main run helper
# ============================================================
def run_once(placement="spiral", seed=0, root_dim=32, local_radius=0.12, query_noise=0.25):
    set_seed(seed)

    keys, values, group_ids = make_clustered_memory(
        N_GROUPS, GROUP_SIZE, KEY_DIM, VALUE_DIM,
        seed=seed,
        key_jitter=KEY_JITTER,
        value_jitter=VALUE_JITTER,
    )

    if placement == "spiral":
        positions = fermat_spiral_positions(N_ITEMS, radius=1.0)
    elif placement == "random":
        positions = random_disk_positions(N_ITEMS, seed=seed + 12345, radius=1.0)
    else:
        raise ValueError("placement must be 'spiral' or 'random'")

    P, roots, shafts = build_memory_field(keys, values, root_dim=root_dim, seed=seed)

    # Guaranteed split by group
    train_ids, test_ids = split_by_group(group_ids, test_per_group=1, seed=seed)

    # Train the QDMN follicle on the training subset
    Xtr, Ytr = make_follicle_training_set(
        train_ids=train_ids,
        keys=keys,
        values=values,
        roots=roots,
        shafts=shafts,
        positions=positions,
        P=P,
        group_ids=group_ids,
        query_noise=TRAIN_QUERY_NOISE,
        local_radius=TRAIN_LOCAL_RADIUS,
        samples_per_item=TRAIN_SAMPLES_PER_ITEM,
        seed=seed,
    )

    train_loader = DataLoader(
        TensorDataset(Xtr, Ytr),
        batch_size=BATCH,
        shuffle=True,
        drop_last=False
    )

    follicle = MiniFollicleQDMN(
        input_dim=2 * root_dim + VALUE_DIM,
        hidden=128,
        bottleneck=64,
        out_dim=N_GROUPS
    )
    train_group_follicle(follicle, train_loader, epochs=EPOCHS_FOLLICLE, lr=LR)

    passive = eval_passive(
        test_ids=test_ids,
        keys=keys,
        values=values,
        roots=roots,
        shafts=shafts,
        positions=positions,
        P=P,
        group_ids=group_ids,
        query_noise=query_noise,
        topk=TOPK_GLOBAL,
        local_radius=local_radius,
        trials_per_item=3,
        seed=seed,
    )

    active = eval_group_follicle(
        model=follicle,
        test_ids=test_ids,
        keys=keys,
        values=values,
        roots=roots,
        shafts=shafts,
        positions=positions,
        P=P,
        group_ids=group_ids,
        query_noise=query_noise,
        topk=TOPK_GLOBAL,
        local_radius=local_radius,
        trials_per_item=3,
        seed=seed,
    )

    # Sweeps reusing the same structure but retraining per setting
    root_rows = []
    for rd in ROOT_DIMS:
        P2, roots2, shafts2 = build_memory_field(keys, values, root_dim=rd, seed=seed)
        follicle2 = MiniFollicleQDMN(
            input_dim=2 * rd + VALUE_DIM,
            hidden=128,
            bottleneck=64,
            out_dim=N_GROUPS
        )
        Xtr2, Ytr2 = make_follicle_training_set(
            train_ids=train_ids,
            keys=keys,
            values=values,
            roots=roots2,
            shafts=shafts2,
            positions=positions,
            P=P2,
            group_ids=group_ids,
            query_noise=TRAIN_QUERY_NOISE,
            local_radius=TRAIN_LOCAL_RADIUS,
            samples_per_item=TRAIN_SAMPLES_PER_ITEM,
            seed=seed,
        )
        train_loader2 = DataLoader(TensorDataset(Xtr2, Ytr2), batch_size=BATCH, shuffle=True, drop_last=False)
        train_group_follicle(follicle2, train_loader2, epochs=max(12, EPOCHS_FOLLICLE // 2), lr=LR)

        passive2 = eval_passive(
            test_ids=test_ids,
            keys=keys,
            values=values,
            roots=roots2,
            shafts=shafts2,
            positions=positions,
            P=P2,
            group_ids=group_ids,
            query_noise=query_noise,
            topk=TOPK_GLOBAL,
            local_radius=local_radius,
            trials_per_item=3,
            seed=seed,
        )
        active2 = eval_group_follicle(
            model=follicle2,
            test_ids=test_ids,
            keys=keys,
            values=values,
            roots=roots2,
            shafts=shafts2,
            positions=positions,
            P=P2,
            group_ids=group_ids,
            query_noise=query_noise,
            topk=TOPK_GLOBAL,
            local_radius=local_radius,
            trials_per_item=3,
            seed=seed,
        )
        root_rows.append({
            "placement": placement,
            "seed": seed,
            "root_dim": rd,
            "passive_top1_item": passive2["passive_top1_item"],
            "passive_top1_group": passive2["passive_top1_group"],
            "passive_topk_pool_item": passive2["passive_topk_pool_item"],
            "passive_topk_pool_group": passive2["passive_topk_pool_group"],
            "active_item": active2["item_acc"],
            "active_group": active2["group_acc"],
            "nn_dist": mean_nearest_neighbor_distance(positions),
            "interference": mean_interference_kernel(positions),
        })

    radius_rows = []
    for r in LOCAL_RADII:
        active_r = eval_group_follicle(
            model=follicle,
            test_ids=test_ids,
            keys=keys,
            values=values,
            roots=roots,
            shafts=shafts,
            positions=positions,
            P=P,
            group_ids=group_ids,
            query_noise=query_noise,
            topk=TOPK_GLOBAL,
            local_radius=r,
            trials_per_item=3,
            seed=seed,
        )
        radius_rows.append({
            "placement": placement,
            "seed": seed,
            "local_radius": r,
            "active_item": active_r["item_acc"],
            "active_group": active_r["group_acc"],
        })

    noise_rows = []
    for qn in QUERY_NOISES:
        active_n = eval_group_follicle(
            model=follicle,
            test_ids=test_ids,
            keys=keys,
            values=values,
            roots=roots,
            shafts=shafts,
            positions=positions,
            P=P,
            group_ids=group_ids,
            query_noise=qn,
            topk=TOPK_GLOBAL,
            local_radius=local_radius,
            trials_per_item=3,
            seed=seed,
        )
        passive_n = eval_passive(
            test_ids=test_ids,
            keys=keys,
            values=values,
            roots=roots,
            shafts=shafts,
            positions=positions,
            P=P,
            group_ids=group_ids,
            query_noise=qn,
            topk=TOPK_GLOBAL,
            local_radius=local_radius,
            trials_per_item=3,
            seed=seed,
        )
        noise_rows.append({
            "placement": placement,
            "seed": seed,
            "query_noise": qn,
            "passive_top1_item": passive_n["passive_top1_item"],
            "passive_top1_group": passive_n["passive_top1_group"],
            "active_item": active_n["item_acc"],
            "active_group": active_n["group_acc"],
        })

    return passive, active, root_rows, radius_rows, noise_rows, positions

# ============================================================
# Run experiments
# ============================================================
main_rows = []
root_rows_all = []
radius_rows_all = []
noise_rows_all = []
geom_cache = {}

for placement in ["spiral", "random"]:
    for seed in SEEDS:
        passive, active, root_rows, radius_rows, noise_rows, positions = run_once(
            placement=placement,
            seed=seed,
            root_dim=32,
            local_radius=TRAIN_LOCAL_RADIUS,
            query_noise=TRAIN_QUERY_NOISE,
        )

        geom_cache[(placement, seed)] = positions

        main_rows.append({
            "placement": placement,
            "seed": seed,
            "variant": "passive_top1",
            "item_acc": passive["passive_top1_item"],
            "group_acc": passive["passive_top1_group"],
        })
        main_rows.append({
            "placement": placement,
            "seed": seed,
            "variant": "passive_topk_pool",
            "item_acc": passive["passive_topk_pool_item"],
            "group_acc": passive["passive_topk_pool_group"],
        })
        main_rows.append({
            "placement": placement,
            "seed": seed,
            "variant": "qdmn_group_follicle",
            "item_acc": active["item_acc"],
            "group_acc": active["group_acc"],
        })

        root_rows_all.extend(root_rows)
        radius_rows_all.extend(radius_rows)
        noise_rows_all.extend(noise_rows)

main_df = pd.DataFrame(main_rows)
root_df = pd.DataFrame(root_rows_all)
radius_df = pd.DataFrame(radius_rows_all)
noise_df = pd.DataFrame(noise_rows_all)

# ============================================================
# Aggregates
# ============================================================
main_agg = main_df.groupby(["placement", "variant"], as_index=False).agg(
    item_acc_mean=("item_acc", "mean"),
    item_acc_std=("item_acc", "std"),
    group_acc_mean=("group_acc", "mean"),
    group_acc_std=("group_acc", "std"),
)

root_agg = root_df.groupby(["placement", "root_dim"], as_index=False).agg(
    passive_top1_item_mean=("passive_top1_item", "mean"),
    passive_top1_group_mean=("passive_top1_group", "mean"),
    passive_topk_pool_item_mean=("passive_topk_pool_item", "mean"),
    passive_topk_pool_group_mean=("passive_topk_pool_group", "mean"),
    active_item_mean=("active_item", "mean"),
    active_group_mean=("active_group", "mean"),
    nn_dist_mean=("nn_dist", "mean"),
    interference_mean=("interference", "mean"),
)

radius_agg = radius_df.groupby(["placement", "local_radius"], as_index=False).agg(
    active_item_mean=("active_item", "mean"),
    active_group_mean=("active_group", "mean"),
)

noise_agg = noise_df.groupby(["placement", "query_noise"], as_index=False).agg(
    passive_top1_item_mean=("passive_top1_item", "mean"),
    passive_top1_group_mean=("passive_top1_group", "mean"),
    active_item_mean=("active_item", "mean"),
    active_group_mean=("active_group", "mean"),
)

# ============================================================
# Print tables
# ============================================================
print("\n=== Main comparison (root_dim=32, query_noise=0.25) ===")
print(main_agg[[
    "placement", "variant",
    "item_acc_mean", "item_acc_std",
    "group_acc_mean", "group_acc_std"
]].to_string(index=False))

print("\n=== Root dimension sweep (group-first active follicle) ===")
print(root_agg[[
    "placement", "root_dim",
    "passive_top1_item_mean", "passive_top1_group_mean",
    "passive_topk_pool_item_mean", "passive_topk_pool_group_mean",
    "active_item_mean", "active_group_mean"
]].to_string(index=False))

print("\n=== Local radius sweep (active follicle) ===")
print(radius_agg[[
    "placement", "local_radius",
    "active_item_mean", "active_group_mean"
]].to_string(index=False))

print("\n=== Query noise sweep ===")
print(noise_agg[[
    "placement", "query_noise",
    "passive_top1_item_mean", "passive_top1_group_mean",
    "active_item_mean", "active_group_mean"
]].to_string(index=False))

# ============================================================
# Combined plots
# ============================================================
fig, axes = plt.subplots(2, 2, figsize=(15, 10))

# Panel 1: Main comparison
ax = axes[0, 0]
order = ["passive_top1", "passive_topk_pool", "qdmn_group_follicle"]
x = np.arange(len(order))
width = 0.35

for idx, placement in enumerate(["spiral", "random"]):
    sub = main_agg[main_agg["placement"] == placement]
    y = [float(sub[sub["variant"] == v]["group_acc_mean"].values[0]) for v in order]
    ax.bar(x + (idx - 0.5) * width, y, width=width, label=placement)

