# Optional separate noise figure
plt.figure(figsize=(10, 5))
for placement in ["spiral", "random"]:
    sub = noise_agg[noise_agg["placement"] == placement].sort_values("query_noise")
    plt.plot(sub["query_noise"], sub["active_group_mean"], marker="o", label=f"{placement}: active")
    plt.plot(sub["query_noise"], sub["passive_top1_group_mean"], marker="s", linestyle="--", label=f"{placement}: passive")

plt.xlabel("Query noise")
plt.ylabel("Group accuracy")
plt.title("Query noise sweep")
plt.grid(True, alpha=0.25)
plt.legend()
plt.show()

