# ============================================================
# MEMORY HAIR CAUSE PINPOINT LAB — PART 3
# Root compression vs neighbor aggregation
# ------------------------------------------------------------
# Goal:
#   Pinpoint, with multi-seed sweeps and paired comparisons,
#   whether the main failure comes from:
#     (A) root/sticker compression loss
#     (B) neighbor/jury aggregation noise
#     (C) spatial contamination / write leakage
#
# What this script compares:
#   1) passive_top1
#   2) passive_topk_pool
#   3) clean_jury_best1   (single best neighbor; "clean the jury")
#   4) context_soup_pool  (radius pooling; noisy neighborhood soup)
#   5) selective_route    (gate between candidate and best neighbor)
#
# What it sweeps:
#   - root_dim
#   - query_noise
#   - write_leak
#   - local_radius
#   - layout: spiral vs random
#
# What it measures:
#   - item accuracy
#   - group accuracy
#   - root top-1 / top-k hit rates
#   - local coverage of the true item
#   - neighborhood size / gate / support
#   - geometry metrics (nearest-neighbor distance / interference)
#   - paired seed deltas vs passive_top1
#
# Notes:
#   - This is intentionally a diagnostic, not a new architecture.
#   - It is designed to isolate cause, not maximize performance.
#   - Keep the script single-block so it is easy to paste into Colab.
# ============================================================

import os
import math
import random
from pathlib import Path

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import torch

try:
    from scipy import stats
    SCIPY_OK = True
except Exception:
    SCIPY_OK = False

# ============================================================
# Config
# ============================================================
SEEDS = [0, 1, 2]
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")

N_GROUPS = 64
GROUP_SIZE = 4
N_ITEMS = N_GROUPS * GROUP_SIZE

KEY_DIM = 64
VALUE_DIM = 64

ROOT_DIMS = [8, 16, 32, 64]
QUERY_NOISES = [0.10, 0.20, 0.30, 0.40]
WRITE_LEAKS = [0.00, 0.05, 0.10, 0.20]
LOCAL_RADII = [0.06, 0.10, 0.12, 0.16, 0.20]

TOPK_GLOBAL = 5
TRIALS_PER_ITEM = 2

KEY_JITTER = 0.12
VALUE_JITTER = 0.12

LOCAL_TEMP = 0.15
SELECTIVE_GATE_TEMP = 0.08

OUTDIR = Path("memory_hair_part3_cause_pinpoint")
OUTDIR.mkdir(parents=True, exist_ok=True)

pd.set_option("display.max_columns", 200)
pd.set_option("display.width", 240)
pd.set_option("display.max_rows", 300)

print("Device:", DEVICE)
print("Artifacts:", OUTDIR)

# ============================================================
# Reproducibility
# ============================================================
def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

# ============================================================
# Math helpers
# ============================================================
def normalize(x, axis=-1, eps=1e-9):
    x = np.asarray(x, dtype=np.float64)
    n = np.linalg.norm(x, axis=axis, keepdims=True)
    return x / (n + eps)

def softmax_np(x, axis=-1, temperature=1.0):
    x = np.asarray(x, dtype=np.float64)
    x = x / max(float(temperature), 1e-9)
    x = x - np.max(x, axis=axis, keepdims=True)
    ex = np.exp(x)
    return ex / (np.sum(ex, axis=axis, keepdims=True) + 1e-9)

def sigmoid_np(x):
    x = np.asarray(x, dtype=np.float64)
    return 1.0 / (1.0 + np.exp(-x))

def cosine_np(a, b, eps=1e-9):
    a = np.asarray(a, dtype=np.float64).reshape(-1)
    b = np.asarray(b, dtype=np.float64).reshape(-1)
    return float(np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b) + eps))

def paired_ttest(a, b):
    a = np.asarray(a, dtype=np.float64)
    b = np.asarray(b, dtype=np.float64)
    if a.size < 2 or b.size < 2:
        return float("nan"), float("nan")
    if SCIPY_OK:
        t, p = stats.ttest_rel(a, b)
        return float(t), float(p)
    d = a - b
    sd = float(d.std(ddof=1))
    if sd < 1e-12:
        return float("inf"), float("nan")
    t = float(d.mean() / (sd / np.sqrt(len(d))))
    return t, float("nan")

# ============================================================
# Geometry / placement
# ============================================================
def fermat_spiral_positions(n, radius=1.0):
    golden_angle = np.pi * (3.0 - np.sqrt(5.0))
    i = np.arange(n)
    r = radius * np.sqrt((i + 0.5) / n)
    theta = i * golden_angle
    x = r * np.cos(theta)
    y = r * np.sin(theta)
    return np.stack([x, y], axis=1)

def random_disk_positions(n, seed=0, radius=1.0):
    rng = np.random.default_rng(seed)
    r = radius * np.sqrt(rng.random(n))
    theta = 2.0 * np.pi * rng.random(n)
    x = r * np.cos(theta)
    y = r * np.sin(theta)
    return np.stack([x, y], axis=1)

def mean_nearest_neighbor_distance(pos):
    d = pos[:, None, :] - pos[None, :, :]
    dist = np.sqrt((d ** 2).sum(-1))
    np.fill_diagonal(dist, np.inf)
    return float(dist.min(axis=1).mean())

def mean_interference_kernel(pos, sigma=0.18):
    d = pos[:, None, :] - pos[None, :, :]
    dist2 = (d ** 2).sum(-1)
    w = np.exp(-dist2 / (2.0 * sigma ** 2))
    np.fill_diagonal(w, 0.0)
    return float(w.mean())

def within_radius(pos, center_idx, radius):
    d2 = np.sum((pos - pos[center_idx]) ** 2, axis=1)
    return np.where(d2 <= radius ** 2)[0]

# ============================================================
# Synthetic clustered memory
# ============================================================
def make_clustered_memory(
    n_groups,
    group_size,
    key_dim,
    value_dim,
    seed=0,
    key_jitter=0.12,
    value_jitter=0.12,
):
    rng = np.random.default_rng(seed)
    keys = []
    values = []
    group_ids = []

    key_centers = normalize(rng.normal(size=(n_groups, key_dim)))
    value_centers = normalize(rng.normal(size=(n_groups, value_dim)))

    for g in range(n_groups):
        for _ in range(group_size):
            k = normalize(key_centers[g] + key_jitter * rng.normal(size=key_dim))
            v = normalize(value_centers[g] + value_jitter * rng.normal(size=value_dim))
            keys.append(k)
            values.append(v)
            group_ids.append(g)

    return np.stack(keys), np.stack(values), np.array(group_ids, dtype=int)

def split_by_group(group_ids, test_per_group=1, seed=0):
    """
    Guaranteed split:
      - one test item per group
      - the rest train
    """
    rng = np.random.default_rng(seed)
    train_ids = []
    test_ids = []

    for g in np.unique(group_ids):
        idx = np.where(group_ids == g)[0]
        if len(idx) <= test_per_group:
            raise ValueError(f"Group {g} has too few items for split.")
        test_sel = rng.choice(idx, size=test_per_group, replace=False)
        test_sel_set = set(test_sel.tolist())
        train_sel = np.array([i for i in idx if i not in test_sel_set], dtype=int)
        test_ids.extend(test_sel.tolist())
        train_ids.extend(train_sel.tolist())

    return np.array(train_ids, dtype=int), np.array(test_ids, dtype=int)

# ============================================================
# Memory field with write-time contamination
# ============================================================
def build_memory_field(keys, values, positions, root_dim=32, write_leak=0.10, leak_sigma=0.18, seed=0):
    """
    Base memory:
      roots = projected keys
      shafts = values

    Write leak contaminates each item by a weighted average of its spatial neighbors.
    Spiral vs random only matters through this geometry-sensitive contamination.
    """
    rng = np.random.default_rng(seed + 999)
    n, key_dim = keys.shape

    P = rng.normal(size=(root_dim, key_dim)) / np.sqrt(key_dim)
    base_roots = normalize(keys @ P.T)
    base_shafts = normalize(values)

    if write_leak <= 0:
        return P, base_roots, base_shafts

    d = positions[:, None, :] - positions[None, :, :]
    dist2 = (d ** 2).sum(-1)
    W = np.exp(-dist2 / (2.0 * leak_sigma ** 2))
    np.fill_diagonal(W, 0.0)

    row_sum = W.sum(axis=1, keepdims=True) + 1e-9
    W = W / row_sum

    roots = normalize(base_roots + write_leak * (W @ base_roots))
    shafts = normalize(base_shafts + write_leak * (W @ base_shafts))
    return P, roots, shafts

def global_search(query_key, P, roots):
    q_root = normalize(query_key @ P.T)
    scores = roots @ q_root
    order = np.argsort(scores)[::-1]
    margin = float(scores[order[0]] - scores[order[1]]) if len(scores) > 1 else float(scores[order[0]])
    probs = softmax_np(scores, temperature=0.20)
    entropy = float(-np.sum(probs * np.log(probs + 1e-9)))
    return q_root, scores, order, margin, entropy

def decode_to_item(vec, values):
    vec = np.asarray(vec, dtype=np.float64).reshape(-1)
    sims = vec @ values.T
    return int(np.argmax(sims))

# ============================================================
# Retrieval modes
# ============================================================
MODE_ORDER = [
    "passive_top1",
    "passive_topk_pool",
    "clean_jury_best1",
    "context_soup_pool",
    "selective_route",
]

def passive_top1(query_key, P, roots, shafts, values):
    q_root, scores, order, margin, entropy = global_search(query_key, P, roots)
    best = int(order[0])
    pred = decode_to_item(shafts[best], values)
    meta = {
        "local_size": 0.0,
        "gate": 0.0,
        "coherence": 0.0,
        "support": float(scores[best]),
        "margin": margin,
        "entropy": entropy,
    }
    return best, pred, scores, order, meta, q_root

def passive_topk_pool(query_key, P, roots, shafts, values, topk=5):
    q_root, scores, order, margin, entropy = global_search(query_key, P, roots)
    k = min(topk, len(scores))
    top_idx = order[:k]
    top_scores = scores[top_idx]
    w = softmax_np(top_scores, temperature=0.20)
    pooled = normalize(np.sum(w[:, None] * shafts[top_idx], axis=0))
    pred = decode_to_item(pooled, values)
    best = int(top_idx[np.argmax(top_scores)])
    meta = {
        "local_size": 0.0,
        "gate": 0.0,
        "coherence": 0.0,
        "support": float(top_scores.max()),
        "margin": margin,
        "entropy": entropy,
    }
    return best, pred, scores, order, meta, q_root

def local_jury_modes(query_key, P, roots, shafts, values, positions, topk=5, local_radius=0.12):
    """
    Clean the jury vs context soup vs selective routing.

    For each global top-k candidate:
      - gather a local spatial neighborhood
      - compute a clean single-neighbor choice
      - compute a pooled neighborhood choice
      - compute a selective gate between candidate and best local neighbor

    The mode then selects the candidate with the highest support under each rule.
    """
    q_root, scores, order, margin, entropy = global_search(query_key, P, roots)
    k = min(topk, len(scores))
    top_idx = order[:k]

    union_local = set()
    candidates = []

    for c in top_idx:
        local_idx = within_radius(positions, c, local_radius)
        if len(local_idx) == 0:
            local_idx = np.array([c], dtype=int)

        union_local.update(local_idx.tolist())

        local_scores = scores[local_idx]
        local_best_idx = int(local_idx[np.argmax(local_scores)])

        d2 = np.sum((positions[local_idx] - positions[c]) ** 2, axis=1)
        spatial_w = np.exp(-d2 / (2.0 * max(local_radius, 1e-6) ** 2))
        spatial_w = spatial_w / (spatial_w.sum() + 1e-9)

        score_w = softmax_np(local_scores, temperature=LOCAL_TEMP)
        jury_w = 0.5 * spatial_w + 0.5 * score_w
        jury_w = jury_w / (jury_w.sum() + 1e-9)

        pooled_vec = normalize(np.sum(jury_w[:, None] * shafts[local_idx], axis=0))
        gate = float(sigmoid_np((scores[c] - float(local_scores.mean())) / max(SELECTIVE_GATE_TEMP, 1e-9)))

        pred_clean = decode_to_item(shafts[local_best_idx], values)
        pred_pool = decode_to_item(pooled_vec, values)
        pred_selective = decode_to_item(shafts[c] if gate >= 0.5 else shafts[local_best_idx], values)

        support_clean = 0.70 * float(scores[c]) + 0.30 * float(scores[local_best_idx])
        support_pool = 0.50 * float(scores[c]) + 0.50 * cosine_np(pooled_vec, shafts[c])
        support_selective = gate * float(scores[c]) + (1.0 - gate) * float(scores[local_best_idx])

        candidates.append({
            "candidate": int(c),
            "local_size": float(len(local_idx)),
            "gate": gate,
            "coherence": float(cosine_np(pooled_vec, shafts[c])),
            "support_clean": support_clean,
            "support_pool": support_pool,
            "support_selective": support_selective,
            "pred_clean": pred_clean,
            "pred_pool": pred_pool,
            "pred_selective": pred_selective,
        })

    local_coverage = None  # filled by caller when true item is known

    def pick_best(key):
        best_i = int(np.argmax([c[key] for c in candidates]))
        return best_i, candidates[best_i]

    idx_clean, cand_clean = pick_best("support_clean")
    idx_pool, cand_pool = pick_best("support_pool")
    idx_sel, cand_sel = pick_best("support_selective")

    return {
        "q_root": q_root,
        "scores": scores,
        "order": order,
        "margin": margin,
        "entropy": entropy,
        "top_idx": top_idx,
        "union_local": union_local,
        "candidates": candidates,
        "clean": cand_clean,
        "pool": cand_pool,
        "selective": cand_sel,
    }

# ============================================================
# Evaluation
# ============================================================
def evaluate_once(
    placement="spiral",
    seed=0,
    root_dim=32,
    query_noise=0.25,
    write_leak=0.10,
    local_radius=0.12,
    topk=TOPK_GLOBAL,
    trials_per_item=TRIALS_PER_ITEM,
):
    set_seed(seed)

    keys, values, group_ids = make_clustered_memory(
        N_GROUPS,
        GROUP_SIZE,
        KEY_DIM,
        VALUE_DIM,
        seed=seed,
        key_jitter=KEY_JITTER,
        value_jitter=VALUE_JITTER,
    )

    if placement == "spiral":
        positions = fermat_spiral_positions(N_ITEMS, radius=1.0)
    elif placement == "random":
        positions = random_disk_positions(N_ITEMS, seed=seed + 12345, radius=1.0)
    else:
        raise ValueError("placement must be 'spiral' or 'random'")

    P, roots, shafts = build_memory_field(
        keys=keys,
        values=values,
        positions=positions,
        root_dim=root_dim,
        write_leak=write_leak,
        leak_sigma=0.18,
        seed=seed,
    )

    rng = np.random.default_rng(seed + 4242)

    stats = {
        mode: {
            "item_hits": 0,
            "group_hits": 0,
            "root_hits": 0,
            "root_topk_hits": 0,
            "local_coverage_hits": 0,
            "local_size_sum": 0.0,
            "gate_sum": 0.0,
            "coherence_sum": 0.0,
            "support_sum": 0.0,
            "margin_sum": 0.0,
            "entropy_sum": 0.0,
        }
        for mode in MODE_ORDER
    }

    total = 0

    for i in range(N_ITEMS):
        true_group = int(group_ids[i])
        for _ in range(trials_per_item):
            query = normalize(keys[i] + query_noise * rng.normal(size=KEY_DIM))
            q_root, scores, order, margin, entropy = global_search(query, P, roots)

            root_best = int(order[0])
            root_topk_idx = order[: min(topk, len(scores))]

            # Common local jury diagnostics
            jury = local_jury_modes(
                query_key=query,
                P=P,
                roots=roots,
                shafts=shafts,
                values=values,
                positions=positions,
                topk=topk,
                local_radius=local_radius,
            )

            local_union = set(jury["union_local"])
            local_coverage = int(i in local_union)

            # Mode 1: passive top-1
            _, pred1, _, _, meta1, _ = passive_top1(query, P, roots, shafts, values)

            # Mode 2: passive top-k pool
            _, predk, _, _, metak, _ = passive_topk_pool(query, P, roots, shafts, values, topk=topk)

            # Mode 3: clean jury, single best neighbor
            pred_clean = int(jury["clean"]["pred_clean"])
            clean_root_pick = int(jury["clean"]["candidate"])
            meta_clean = {
                "local_size": float(jury["clean"]["local_size"]),
                "gate": 0.0,
                "coherence": float(jury["clean"]["coherence"]),
                "support": float(jury["clean"]["support_clean"]),
            }

            # Mode 4: context soup pooling
            pred_pool = int(jury["pool"]["pred_pool"])
            pool_root_pick = int(jury["pool"]["candidate"])
            meta_pool = {
                "local_size": float(jury["pool"]["local_size"]),
                "gate": 0.0,
                "coherence": float(jury["pool"]["coherence"]),
                "support": float(jury["pool"]["support_pool"]),
            }

            # Mode 5: selective route between candidate and best local neighbor
            pred_sel = int(jury["selective"]["pred_selective"])
            sel_root_pick = int(jury["selective"]["candidate"])
            meta_sel = {
                "local_size": float(jury["selective"]["local_size"]),
                "gate": float(jury["selective"]["gate"]),
                "coherence": float(jury["selective"]["coherence"]),
                "support": float(jury["selective"]["support_selective"]),
            }

            mode_rows = {
                "passive_top1": (root_best, pred1, meta1),
                "passive_topk_pool": (int(np.argmax(scores[root_topk_idx])), predk, metak),
                "clean_jury_best1": (clean_root_pick, pred_clean, meta_clean),
                "context_soup_pool": (pool_root_pick, pred_pool, meta_pool),
                "selective_route": (sel_root_pick, pred_sel, meta_sel),
            }

            for mode, (root_pick, pred, meta) in mode_rows.items():
                stats[mode]["item_hits"] += int(pred == i)
                stats[mode]["group_hits"] += int(group_ids[pred] == true_group)
                stats[mode]["root_hits"] += int(root_pick == i)
                stats[mode]["root_topk_hits"] += int(i in root_topk_idx)
                stats[mode]["local_coverage_hits"] += local_coverage
                stats[mode]["local_size_sum"] += float(meta.get("local_size", 0.0))
                stats[mode]["gate_sum"] += float(meta.get("gate", 0.0))
                stats[mode]["coherence_sum"] += float(meta.get("coherence", 0.0))
                stats[mode]["support_sum"] += float(meta.get("support", 0.0))
                stats[mode]["margin_sum"] += float(margin)
                stats[mode]["entropy_sum"] += float(entropy)

            total += 1

    rows = []
    for mode in MODE_ORDER:
        rows.append({
            "placement": placement,
            "seed": seed,
            "mode": mode,
            "root_dim": root_dim,
            "query_noise": query_noise,
            "write_leak": write_leak,
            "local_radius": local_radius,
            "topk": topk,
            "item_acc": stats[mode]["item_hits"] / total,
            "group_acc": stats[mode]["group_hits"] / total,
            "root_hit_top1": stats[mode]["root_hits"] / total,
            "root_hit_topk": stats[mode]["root_topk_hits"] / total,
            "local_coverage": stats[mode]["local_coverage_hits"] / total,
            "avg_local_size": stats[mode]["local_size_sum"] / total,
            "avg_gate": stats[mode]["gate_sum"] / total,
            "avg_coherence": stats[mode]["coherence_sum"] / total,
            "avg_support": stats[mode]["support_sum"] / total,
            "root_margin": stats[mode]["margin_sum"] / total,
            "root_entropy": stats[mode]["entropy_sum"] / total,
            "nn_dist": mean_nearest_neighbor_distance(positions),
            "interference": mean_interference_kernel(positions),
        })

    return rows, positions

# ============================================================
# Aggregation helpers
# ============================================================
METRICS = [
    "item_acc",
    "group_acc",
    "root_hit_top1",
    "root_hit_topk",
    "local_coverage",
    "avg_local_size",
    "avg_gate",
    "avg_coherence",
    "avg_support",
    "root_margin",
    "root_entropy",
    "nn_dist",
    "interference",
]

def aggregate(df, group_cols):
    agg_spec = {}
    for m in METRICS:
        agg_spec[f"{m}_mean"] = (m, "mean")
        agg_spec[f"{m}_std"] = (m, "std")
    return df.groupby(group_cols, as_index=False).agg(**agg_spec)

def paired_delta_table(df, group_cols, metric="item_acc", baseline="passive_top1", compare_modes=None):
    if compare_modes is None:
        compare_modes = [m for m in MODE_ORDER if m != baseline]

    idx_cols = list(group_cols) + ["seed"]
    piv = df.pivot_table(index=idx_cols, columns="mode", values=metric, aggfunc="mean").reset_index()

    rows = []
    for gvals, grp in piv.groupby(group_cols, dropna=False):
        if not isinstance(gvals, tuple):
            gvals = (gvals,)
        gdict = {col: val for col, val in zip(group_cols, gvals)}

        if baseline not in grp.columns:
            continue
        base = grp[baseline].to_numpy()

        for mode in compare_modes:
            if mode not in grp.columns:
                continue
            arr = grp[mode].to_numpy()
            delta = arr - base
            t, p = paired_ttest(arr, base)
            rows.append({
                **gdict,
                "mode": mode,
                "delta_mean": float(delta.mean()),
                "delta_std": float(delta.std(ddof=1)) if len(delta) > 1 else 0.0,
                "paired_t": t,
                "paired_p": p,
                "baseline_mean": float(base.mean()),
                "mode_mean": float(arr.mean()),
            })

    return pd.DataFrame(rows)

def print_mode_pivot(summary_df, value_col):
    print(summary_df.pivot(index="mode", columns="placement", values=value_col).to_string())

# ============================================================
# Run experiments
# ============================================================
main_rows = []
root_rows_all = []
leak_rows_all = []
radius_rows_all = []
noise_rows_all = []
geom_cache = {}

print("\nRunning root / neighbor cause pinpoint lab...\n")

# Main comparison
for placement in ["spiral", "random"]:
    for seed in SEEDS:
        rows, positions = evaluate_once(
            placement=placement,
            seed=seed,
            root_dim=32,
            query_noise=0.25,
            write_leak=0.10,
            local_radius=0.12,
            topk=TOPK_GLOBAL,
            trials_per_item=TRIALS_PER_ITEM,
        )
        geom_cache[(placement, seed)] = positions
        main_rows.extend(rows)

# Root-dimension sweep
for placement in ["spiral", "random"]:
    for seed in SEEDS:
        for rd in ROOT_DIMS:
            rows, _ = evaluate_once(
                placement=placement,
                seed=seed,
                root_dim=rd,
                query_noise=0.25,
                write_leak=0.10,
                local_radius=0.12,
                topk=TOPK_GLOBAL,
                trials_per_item=TRIALS_PER_ITEM,
            )
            for r in rows:
                root_rows_all.append(r)

# Leak sweep
for placement in ["spiral", "random"]:
    for seed in SEEDS:
        for wl in WRITE_LEAKS:
            rows, _ = evaluate_once(
                placement=placement,
                seed=seed,
                root_dim=32,
                query_noise=0.25,
                write_leak=wl,
                local_radius=0.12,
                topk=TOPK_GLOBAL,
                trials_per_item=TRIALS_PER_ITEM,
            )
            for r in rows:
                leak_rows_all.append(r)

# Local radius sweep
for placement in ["spiral", "random"]:
    for seed in SEEDS:
        for radius in LOCAL_RADII:
            rows, _ = evaluate_once(
                placement=placement,
                seed=seed,
                root_dim=32,
                query_noise=0.25,
                write_leak=0.10,
                local_radius=radius,
                topk=TOPK_GLOBAL,
                trials_per_item=TRIALS_PER_ITEM,
            )
            for r in rows:
                radius_rows_all.append(r)

# Query-noise sweep
for placement in ["spiral", "random"]:
    for seed in SEEDS:
        for qn in QUERY_NOISES:
            rows, _ = evaluate_once(
                placement=placement,
                seed=seed,
                root_dim=32,
                query_noise=qn,
                write_leak=0.10,
                local_radius=0.12,
                topk=TOPK_GLOBAL,
                trials_per_item=TRIALS_PER_ITEM,
            )
            for r in rows:
                noise_rows_all.append(r)

main_df = pd.DataFrame(main_rows)
root_df = pd.DataFrame(root_rows_all)
leak_df = pd.DataFrame(leak_rows_all)
radius_df = pd.DataFrame(radius_rows_all)
noise_df = pd.DataFrame(noise_rows_all)

# ============================================================
# Aggregates
# ============================================================
main_agg = aggregate(main_df, ["placement", "mode"])
root_agg = aggregate(root_df, ["placement", "root_dim", "mode"])
leak_agg = aggregate(leak_df, ["placement", "write_leak", "mode"])
radius_agg = aggregate(radius_df, ["placement", "local_radius", "mode"])
noise_agg = aggregate(noise_df, ["placement", "query_noise", "mode"])

# Paired deltas vs passive_top1
main_delta = paired_delta_table(main_df, ["placement"], metric="item_acc", baseline="passive_top1")
root_delta = paired_delta_table(root_df, ["placement", "root_dim"], metric="item_acc", baseline="passive_top1")
leak_delta = paired_delta_table(leak_df, ["placement", "write_leak"], metric="item_acc", baseline="passive_top1")
radius_delta = paired_delta_table(radius_df, ["placement", "local_radius"], metric="item_acc", baseline="passive_top1")
noise_delta = paired_delta_table(noise_df, ["placement", "query_noise"], metric="item_acc", baseline="passive_top1")

