# ============================================================
# MEMORY HAIR STRESS TEST — PART 5
# Neighbor Aggregation Comparison
# ------------------------------------------------------------
# Goal:
#   Keep the same memory field and test which local neighbor
#   aggregation works best:
#     1) local_avg_pool
#     2) local_top1_pick
#     3) local_softmax_pool
#
# Also compares:
#   - passive_top1
#   - passive_topk_pool
#
# Sweeps:
#   - root_dim
#   - query_noise
#   - local_radius
#   - write_leak
#   - softmax_temperature
#   - placement: spiral vs random
#
# Metrics:
#   - item accuracy
#   - group accuracy
#   - root top-1 / top-k hit rates
#   - local coverage
#   - average local neighborhood size
#   - geometry sanity
# ============================================================

import os
import math
import random
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt

# ============================================================
# Config
# ============================================================
SEEDS = [0, 1, 2]
N_GROUPS = 64
GROUP_SIZE = 4
N_ITEMS = N_GROUPS * GROUP_SIZE

KEY_DIM = 64
VALUE_DIM = 64

ROOT_DIMS = [8, 16, 32, 64]
QUERY_NOISES = [0.10, 0.20, 0.30, 0.40]
LOCAL_RADII = [0.06, 0.10, 0.12, 0.16, 0.20]
WRITE_LEAKS = [0.00, 0.05, 0.10, 0.20]
SOFTMAX_TEMPS = [0.05, 0.10, 0.15, 0.20, 0.40]

TOPK_GLOBAL = 5

KEY_JITTER = 0.12
VALUE_JITTER = 0.12
LEAK_SIGMA = 0.18

MAIN_ROOT_DIM = 32
MAIN_QUERY_NOISE = 0.25
MAIN_LOCAL_RADIUS = 0.12
MAIN_WRITE_LEAK = 0.10
MAIN_SOFTMAX_TEMP = 0.15

OUTDIR = "memory_hair_part5_neighbor_aggregation"
os.makedirs(OUTDIR, exist_ok=True)

pd.set_option("display.max_columns", 200)
pd.set_option("display.width", 240)

print("Device: cpu")
print("Artifacts:", OUTDIR)

# ============================================================
# Reproducibility
# ============================================================
def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)

# ============================================================
# Utilities
# ============================================================
def normalize_np(x, axis=-1, eps=1e-9):
    n = np.linalg.norm(x, axis=axis, keepdims=True)
    return x / (n + eps)

def softmax_np(x, axis=-1, temperature=1.0):
    x = np.asarray(x, dtype=np.float64)
    x = x / max(float(temperature), 1e-9)
    x = x - np.max(x, axis=axis, keepdims=True)
    ex = np.exp(x)
    return ex / (np.sum(ex, axis=axis, keepdims=True) + 1e-9)

def noise_tag(x: float) -> str:
    return str(x).replace(".", "p")

def mean_nearest_neighbor_distance(pos):
    d = pos[:, None, :] - pos[None, :, :]
    dist = np.sqrt((d ** 2).sum(-1))
    np.fill_diagonal(dist, np.inf)
    return float(dist.min(axis=1).mean())

def mean_interference_kernel(pos, sigma=0.18):
    d = pos[:, None, :] - pos[None, :, :]
    dist2 = (d ** 2).sum(-1)
    w = np.exp(-dist2 / (2.0 * sigma ** 2))
    np.fill_diagonal(w, 0.0)
    return float(w.mean())

def within_radius(pos, center_idx, radius):
    d2 = np.sum((pos - pos[center_idx]) ** 2, axis=1)
    return np.where(d2 <= radius ** 2)[0]

# ============================================================
# Geometry / placement
# ============================================================
def fermat_spiral_positions(n, radius=1.0):
    golden_angle = np.pi * (3.0 - np.sqrt(5.0))
    i = np.arange(n)
    r = radius * np.sqrt((i + 0.5) / n)
    theta = i * golden_angle
    x = r * np.cos(theta)
    y = r * np.sin(theta)
    return np.stack([x, y], axis=1)

def random_disk_positions(n, seed=0, radius=1.0):
    rng = np.random.default_rng(seed)
    r = radius * np.sqrt(rng.random(n))
    theta = 2.0 * np.pi * rng.random(n)
    x = r * np.cos(theta)
    y = r * np.sin(theta)
    return np.stack([x, y], axis=1)

# ============================================================
# Synthetic clustered memory
# ============================================================
def make_clustered_memory(n_groups, group_size, key_dim, value_dim, seed=0,
                          key_jitter=0.12, value_jitter=0.12):
    rng = np.random.default_rng(seed)
    keys = []
    values = []
    group_ids = []

    key_centers = normalize_np(rng.normal(size=(n_groups, key_dim)))
    value_centers = normalize_np(rng.normal(size=(n_groups, value_dim)))

    for g in range(n_groups):
        for _ in range(group_size):
            k = normalize_np(key_centers[g] + key_jitter * rng.normal(size=key_dim))
            v = normalize_np(value_centers[g] + value_jitter * rng.normal(size=value_dim))
            keys.append(k)
            values.append(v)
            group_ids.append(g)

    return np.stack(keys), np.stack(values), np.array(group_ids, dtype=int)

def split_by_group(group_ids, test_per_group=1, seed=0):
    rng = np.random.default_rng(seed)
    train_ids = []
    test_ids = []

    for g in np.unique(group_ids):
        idx = np.where(group_ids == g)[0]
        if len(idx) <= test_per_group:
            raise ValueError(f"Group {g} has too few items for split.")
        test_sel = rng.choice(idx, size=test_per_group, replace=False)
        test_sel_set = set(test_sel.tolist())
        train_sel = np.array([i for i in idx if i not in test_sel_set], dtype=int)
        test_ids.extend(test_sel.tolist())
        train_ids.extend(train_sel.tolist())

    return np.array(train_ids, dtype=int), np.array(test_ids, dtype=int)

# ============================================================
# Memory field
# ============================================================
def build_memory_field(keys, values, positions, root_dim=32, write_leak=0.10, leak_sigma=0.18, seed=0):
    rng = np.random.default_rng(seed + 999)
    _, key_dim = keys.shape

    P = rng.normal(size=(root_dim, key_dim)) / np.sqrt(key_dim)

    base_roots = normalize_np(keys @ P.T)
    base_shafts = normalize_np(values)

    if write_leak > 0:
        d = positions[:, None, :] - positions[None, :, :]
        dist2 = (d ** 2).sum(-1)
        K = np.exp(-dist2 / (2.0 * leak_sigma ** 2))
        np.fill_diagonal(K, 0.0)

        roots = base_roots + write_leak * (K @ base_roots)
        shafts = base_shafts + write_leak * (K @ base_shafts)
    else:
        roots = base_roots.copy()
        shafts = base_shafts.copy()

    roots = normalize_np(roots)
    shafts = normalize_np(shafts)
    return P, roots, shafts

def global_search(query_key, P, roots):
    q_root = normalize_np(query_key @ P.T)
    scores = roots @ q_root
    return q_root, scores

def decode_to_item(vec, values):
    vec = np.asarray(vec, dtype=np.float64).reshape(-1)
    sims = vec @ values.T
    return int(np.argmax(sims))

# ============================================================
# Retrieval strategies
# ============================================================
def passive_top1(query_key, P, roots, shafts, values):
    q_root, scores = global_search(query_key, P, roots)
    best = int(np.argmax(scores))
    pred = decode_to_item(shafts[best], values)
    return best, pred, scores, q_root, {"local_size": 0.0, "local_coverage": 0.0, "score_margin": float(np.sort(scores)[-1] - np.sort(scores)[-2])}

def passive_topk_pool(query_key, P, roots, shafts, values, topk=5):
    q_root, scores = global_search(query_key, P, roots)
    k = min(topk, len(scores))
    top_idx = np.argpartition(scores, -k)[-k:]
    top_scores = scores[top_idx]
    w = softmax_np(top_scores, temperature=0.20)
    pooled = np.sum(w[:, None] * shafts[top_idx], axis=0)
    pred = decode_to_item(pooled, values)
    best = int(top_idx[np.argmax(top_scores)])
    return best, pred, scores, q_root, {"local_size": 0.0, "local_coverage": 0.0, "score_margin": float(np.sort(scores)[-1] - np.sort(scores)[-2])}

def local_aggregate(query_key, P, roots, shafts, values, positions,
                    local_radius=0.12, mode="avg", temperature=0.15):
    """
    local modes use the best global candidate as anchor, then inspect
    the spatial neighborhood around that anchor.
      mode = "avg"   -> uniform average
      mode = "top1"  -> pick local item with highest score
      mode = "softmax" -> temperature softmax over local scores
    """
    q_root, scores = global_search(query_key, P, roots)
    anchor = int(np.argmax(scores))

    local_idx = within_radius(positions, anchor, local_radius)
    if len(local_idx) == 0:
        local_idx = np.array([anchor], dtype=int)

    local_scores = scores[local_idx]
    local_coverage = 1.0 if False else 0.0  # filled by evaluator
    if mode == "avg":
        vec = np.mean(shafts[local_idx], axis=0)
    elif mode == "top1":
        pick = int(local_idx[np.argmax(local_scores)])
        vec = shafts[pick]
    elif mode == "softmax":
        w = softmax_np(local_scores, temperature=temperature)
        vec = np.sum(w[:, None] * shafts[local_idx], axis=0)
    else:
        raise ValueError(f"Unknown mode: {mode}")

    pred = decode_to_item(vec, values)
    meta = {
        "anchor": anchor,
        "local_size": float(len(local_idx)),
        "local_coverage": local_coverage,
        "avg_local_score": float(np.mean(local_scores)),
        "max_local_score": float(np.max(local_scores)),
    }
    return anchor, pred, scores, q_root, local_idx, meta

# ============================================================
# Evaluation core
# ============================================================
MODES = [
    "passive_top1",
    "passive_topk_pool",
    "local_avg_pool",
    "local_top1_pick",
    "local_softmax_pool",
]

def evaluate_once(
    placement="spiral",
    seed=0,
    root_dim=32,
    query_noise=0.25,
    write_leak=0.10,
    local_radius=0.12,
    topk=5,
    softmax_temp=0.15,
    trials_per_item=3,
):
    set_seed(seed)

    keys, values, group_ids = make_clustered_memory(
        N_GROUPS, GROUP_SIZE, KEY_DIM, VALUE_DIM,
        seed=seed,
        key_jitter=KEY_JITTER,
        value_jitter=VALUE_JITTER,
    )

    if placement == "spiral":
        positions = fermat_spiral_positions(N_ITEMS, radius=1.0)
    elif placement == "random":
        positions = random_disk_positions(N_ITEMS, seed=seed + 12345, radius=1.0)
    else:
        raise ValueError("placement must be 'spiral' or 'random'")

    P, roots, shafts = build_memory_field(
        keys=keys,
        values=values,
        positions=positions,
        root_dim=root_dim,
        write_leak=write_leak,
        leak_sigma=LEAK_SIGMA,
        seed=seed,
    )

    rng = np.random.default_rng(seed + 4242)

    stats = {
        mode: {
            "item_hits": 0,
            "group_hits": 0,
            "root_hits": 0,
            "root_topk_hits": 0,
            "local_coverage_hits": 0,
            "local_size_sum": 0.0,
            "score_margin_sum": 0.0,
        }
        for mode in MODES
    }

    total = 0

    for i in range(N_ITEMS):
        true_group = int(group_ids[i])

        for _ in range(trials_per_item):
            query = normalize_np(keys[i] + query_noise * rng.normal(size=KEY_DIM))
            q_root, scores = global_search(query, P, roots)

            root_best = int(np.argmax(scores))
            k = min(topk, len(scores))
            topk_idx = np.argpartition(scores, -k)[-k:]

            local_idx = within_radius(positions, root_best, local_radius)
            if len(local_idx) == 0:
                local_idx = np.array([root_best], dtype=int)

            local_coverage = int(i in local_idx)

            # Passive top-1
            b1, pred1, _, _, meta1 = passive_top1(query, P, roots, shafts, values)

            # Passive top-k pool
            bk, predk, _, _, metak = passive_topk_pool(query, P, roots, shafts, values, topk=topk)

            # Local average
            ba, preda, _, _, local_idx_a, meta_a = local_aggregate(
                query, P, roots, shafts, values,
                positions=positions,
                local_radius=local_radius,
                mode="avg",
                temperature=softmax_temp,
            )

            # Local top-1 pick
            bt, predt, _, _, local_idx_t, meta_t = local_aggregate(
                query, P, roots, shafts, values,
                positions=positions,
                local_radius=local_radius,
                mode="top1",
                temperature=softmax_temp,
            )

            # Local softmax pool
            bs, preds, _, _, local_idx_s, meta_s = local_aggregate(
                query, P, roots, shafts, values,
                positions=positions,
                local_radius=local_radius,
                mode="softmax",
                temperature=softmax_temp,
            )

            mode_pack = {
                "passive_top1": (b1, pred1, meta1),
                "passive_topk_pool": (bk, predk, metak),
                "local_avg_pool": (ba, preda, meta_a),
                "local_top1_pick": (bt, predt, meta_t),
                "local_softmax_pool": (bs, preds, meta_s),
            }

            for mode, (root_pick, pred, meta) in mode_pack.items():
                stats[mode]["item_hits"] += int(pred == i)
                stats[mode]["group_hits"] += int(group_ids[pred] == true_group)
                stats[mode]["root_hits"] += int(root_pick == i)
                stats[mode]["root_topk_hits"] += int(i in topk_idx)
                stats[mode]["local_coverage_hits"] += local_coverage
                stats[mode]["local_size_sum"] += float(len(local_idx))
                stats[mode]["score_margin_sum"] += float(np.sort(scores)[-1] - np.sort(scores)[-2])

            total += 1

    rows = []
    for mode in MODES:
        rows.append({
            "placement": placement,
            "seed": seed,
            "mode": mode,
            "root_dim": root_dim,
            "query_noise": query_noise,
            "write_leak": write_leak,
            "local_radius": local_radius,
            "topk": topk,
            "softmax_temp": softmax_temp,
            "item_acc": stats[mode]["item_hits"] / total,
            "group_acc": stats[mode]["group_hits"] / total,
            "root_hit_top1": stats[mode]["root_hits"] / total,
            "root_hit_topk": stats[mode]["root_topk_hits"] / total,
            "local_coverage": stats[mode]["local_coverage_hits"] / total,
            "avg_local_size": stats[mode]["local_size_sum"] / total,
            "avg_score_margin": stats[mode]["score_margin_sum"] / total,
            "nn_dist": mean_nearest_neighbor_distance(positions),
            "interference": mean_interference_kernel(positions),
        })

    return rows, positions

def aggregate(df, group_cols):
    return (
        df.groupby(group_cols, as_index=False)
          .agg(
              item_acc_mean=("item_acc", "mean"),
              item_acc_std=("item_acc", "std"),
              group_acc_mean=("group_acc", "mean"),
              group_acc_std=("group_acc", "std"),
              root_hit_top1_mean=("root_hit_top1", "mean"),
              root_hit_topk_mean=("root_hit_topk", "mean"),
              local_coverage_mean=("local_coverage", "mean"),
              avg_local_size_mean=("avg_local_size", "mean"),
              avg_score_margin_mean=("avg_score_margin", "mean"),
              nn_dist_mean=("nn_dist", "mean"),
              interference_mean=("interference", "mean"),
          )
    )

def paired_delta_summary(df, baseline_mode="passive_top1", target_col="item_acc", group_cols=None):
    if group_cols is None:
        group_cols = ["placement", "root_dim", "query_noise", "write_leak", "local_radius", "softmax_temp"]
    rows = []

    for keys, grp in df.groupby(group_cols, dropna=False):
        if not isinstance(keys, tuple):
            keys = (keys,)
        pivot = grp.pivot_table(index="seed", columns="mode", values=target_col, aggfunc="mean")
        if baseline_mode not in pivot.columns:
            continue

        baseline = pivot[baseline_mode].dropna()
        for mode in pivot.columns:
            if mode == baseline_mode:
                continue
            pair = pd.concat([baseline, pivot[mode]], axis=1, join="inner").dropna()
            if len(pair) < 2:
                continue
            delta = pair.iloc[:, 1] - pair.iloc[:, 0]
            mean = float(delta.mean())
            std = float(delta.std(ddof=1)) if len(delta) > 1 else 0.0
            t_stat = float(mean / (std / math.sqrt(len(delta)))) if std > 1e-12 and len(delta) > 1 else float("nan")
            row = {col: key for col, key in zip(group_cols, keys)}
            row.update({
                "mode": mode,
                "baseline_mode": baseline_mode,
                "delta_mean": mean,
                "delta_std": std,
                "paired_t": t_stat,
                "baseline_mean": float(pair.iloc[:, 0].mean()),
                "mode_mean": float(pair.iloc[:, 1].mean()),
            })
            rows.append(row)
    return pd.DataFrame(rows)

