# ============================================================
# MEMORY HAIR — PART 6
# Root fixes + local rerank + multi-root union
# ------------------------------------------------------------
# Goal:
#   Test the three solution families side by side:
#     1) stronger root search
#     2) query-based local reranking
#     3) multi-root union + refinement + hard gate
#
# What it compares:
#   - passive_top1
#   - passive_topk_pool
#   - single_root_rerank
#   - single_root_refine_rerank
#   - multi_root_rerank
#   - multi_root_refine_gate
#   - oracle_union
#
# What it sweeps:
#   - root_dim
#   - num_projections
#   - topk_root
#   - query_noise
#   - placement: spiral vs random
#
# What it measures:
#   - item accuracy
#   - group accuracy
#   - root top-1 / top-k hit rates
#   - candidate coverage
#   - candidate set size
#   - geometry sanity: nearest-neighbor distance / interference
#
# Notes:
#   - No training.
#   - No QDMN.
#   - No averaging neighbors.
#   - The final decision for rerank modes is query-key similarity
#     over a candidate union, with optional refinement and gating.
# ============================================================

import os
import math
import random
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt

try:
    from scipy.stats import ttest_rel
except Exception:
    ttest_rel = None

# ============================================================
# Config
# ============================================================
SEEDS = [11, 22, 33]
DEVICE = "cpu"

N_GROUPS = 64
GROUP_SIZE = 4
N_ITEMS = N_GROUPS * GROUP_SIZE

KEY_DIM = 64
VALUE_DIM = 64

ROOT_DIMS = [8, 16, 32, 64]
QUERY_NOISES = [0.10, 0.20, 0.30, 0.40]
NUM_PROJECTIONS_SWEEP = [1, 2, 4, 8]
TOPK_ROOT_SWEEP = [1, 3, 5, 10]

ROOT_DIM_MAIN = 32
QUERY_NOISE_MAIN = 0.25
WRITE_LEAK_MAIN = 0.10
LOCAL_RADIUS_MAIN = 0.12
TOPK_ROOT_MAIN = 5
NUM_PROJECTIONS_MAIN = 4

# Solution knobs
REFINE_BETA = 0.25
GATE_MARGIN = 0.01
RERANK_MIX = 0.05

KEY_JITTER = 0.12
VALUE_JITTER = 0.12

TRIALS_PER_ITEM = 2

OUTDIR = "memory_hair_part6_solution_hunt"
os.makedirs(OUTDIR, exist_ok=True)

pd.set_option("display.max_columns", 200)
pd.set_option("display.width", 240)
pd.set_option("display.max_rows", 300)

print("Device:", DEVICE)
print("Artifacts:", OUTDIR)

# ============================================================
# Reproducibility
# ============================================================
def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)

# ============================================================
# Utilities
# ============================================================
def normalize_np(x, axis=-1, eps=1e-9):
    x = np.asarray(x, dtype=np.float64)
    n = np.linalg.norm(x, axis=axis, keepdims=True)
    return x / (n + eps)

def softmax_np(x, axis=-1, temperature=1.0):
    x = np.asarray(x, dtype=np.float64)
    x = x / max(temperature, 1e-9)
    x = x - np.max(x, axis=axis, keepdims=True)
    ex = np.exp(x)
    return ex / (np.sum(ex, axis=axis, keepdims=True) + 1e-9)

def unique_preserve_order(seq):
    seen = set()
    out = []
    for v in seq:
        v = int(v)
        if v not in seen:
            seen.add(v)
            out.append(v)
    return np.array(out, dtype=int)

def topk_indices(scores, k):
    k = min(int(k), len(scores))
    if k <= 0:
        return np.array([], dtype=int)
    return np.argpartition(scores, -k)[-k:]

def mean_std(values):
    arr = np.asarray(values, dtype=np.float64)
    if arr.size == 0:
        return float("nan"), float("nan")
    if arr.size == 1:
        return float(arr.item()), 0.0
    return float(arr.mean()), float(arr.std(ddof=1))

def safe_ttest_rel(a, b):
    a = np.asarray(a, dtype=np.float64)
    b = np.asarray(b, dtype=np.float64)
    if a.size < 2 or b.size < 2:
        return float("nan"), float("nan")
    if np.allclose(a - b, 0.0):
        return float("nan"), float("nan")
    if ttest_rel is None:
        return float("nan"), float("nan")
    try:
        res = ttest_rel(a, b)
        return float(res.statistic), float(res.pvalue)
    except Exception:
        return float("nan"), float("nan")

# ============================================================
# Geometry / placement
# ============================================================
def fermat_spiral_positions(n, radius=1.0):
    golden_angle = np.pi * (3.0 - np.sqrt(5.0))
    i = np.arange(n)
    r = radius * np.sqrt((i + 0.5) / n)
    theta = i * golden_angle
    x = r * np.cos(theta)
    y = r * np.sin(theta)
    return np.stack([x, y], axis=1)

def random_disk_positions(n, seed=0, radius=1.0):
    rng = np.random.default_rng(seed)
    r = radius * np.sqrt(rng.random(n))
    theta = 2.0 * np.pi * rng.random(n)
    x = r * np.cos(theta)
    y = r * np.sin(theta)
    return np.stack([x, y], axis=1)

def mean_nearest_neighbor_distance(pos):
    d = pos[:, None, :] - pos[None, :, :]
    dist = np.sqrt((d ** 2).sum(-1))
    np.fill_diagonal(dist, np.inf)
    return float(dist.min(axis=1).mean())

def mean_interference_kernel(pos, sigma=0.18):
    d = pos[:, None, :] - pos[None, :, :]
    dist2 = (d ** 2).sum(-1)
    W = np.exp(-dist2 / (2.0 * sigma ** 2))
    np.fill_diagonal(W, 0.0)
    return float(W.mean())

def within_radius(pos, center_idx, radius):
    d2 = np.sum((pos - pos[center_idx]) ** 2, axis=1)
    return np.where(d2 <= radius ** 2)[0]

# ============================================================
# Synthetic clustered memory
# ============================================================
def make_clustered_memory(
    n_groups,
    group_size,
    key_dim,
    value_dim,
    seed=0,
    key_jitter=0.12,
    value_jitter=0.12,
):
    rng = np.random.default_rng(seed)
    keys = []
    values = []
    group_ids = []

    key_centers = normalize_np(rng.normal(size=(n_groups, key_dim)))
    value_centers = normalize_np(rng.normal(size=(n_groups, value_dim)))

    for g in range(n_groups):
        for _ in range(group_size):
            k = normalize_np(key_centers[g] + key_jitter * rng.normal(size=key_dim))
            v = normalize_np(value_centers[g] + value_jitter * rng.normal(size=value_dim))
            keys.append(k)
            values.append(v)
            group_ids.append(g)

    return np.stack(keys), np.stack(values), np.array(group_ids, dtype=int)

def split_by_group(group_ids, test_per_group=1, seed=0):
    rng = np.random.default_rng(seed)
    train_ids = []
    test_ids = []

    for g in np.unique(group_ids):
        idx = np.where(group_ids == g)[0]
        if len(idx) <= test_per_group:
            raise ValueError(f"Group {g} has too few items for split.")
        test_sel = rng.choice(idx, size=test_per_group, replace=False)
        test_set = set(test_sel.tolist())
        train_sel = np.array([i for i in idx if i not in test_set], dtype=int)
        test_ids.extend(test_sel.tolist())
        train_ids.extend(train_sel.tolist())

    return np.array(train_ids, dtype=int), np.array(test_ids, dtype=int)

# ============================================================
# Memory field
# ============================================================
def build_projection_stack(num_projections, root_dim, key_dim, seed):
    Ps = []
    for j in range(num_projections):
        rng = np.random.default_rng(seed + 1000 + 17 * j)
        P = rng.normal(size=(root_dim, key_dim)) / np.sqrt(key_dim)
        Ps.append(P.astype(np.float64))
    return Ps

def build_memory_field(keys, values, positions, root_dim=32, write_leak=0.10, leak_sigma=0.18, seed=0):
    rng = np.random.default_rng(seed + 999)
    n, key_dim = keys.shape
    P = rng.normal(size=(root_dim, key_dim)) / np.sqrt(key_dim)

    base_roots = normalize_np(keys @ P.T)
    base_shafts = normalize_np(values)

    roots = base_roots.copy()
    shafts = base_shafts.copy()

    if write_leak > 0:
        for i in range(n):
            d2 = np.sum((positions - positions[i]) ** 2, axis=1)
            w = write_leak * np.exp(-d2 / (2.0 * leak_sigma ** 2))
            w[i] = 0.0
            if np.any(w > 0):
                roots += w[:, None] * base_roots[i]
                shafts += w[:, None] * base_shafts[i]

    roots = normalize_np(roots)
    shafts = normalize_np(shafts)
    return P, roots, shafts

def global_search(query_key, P, roots):
    q_root = normalize_np(query_key @ P.T)
    scores = roots @ q_root
    return q_root, scores

def decode_to_item(vec, values):
    sims = vec @ values.T
    return int(np.argmax(sims))

# ============================================================
# Candidate building and reranking
# ============================================================
def expand_candidates(anchor_ids, positions, local_radius):
    cand = set(int(a) for a in anchor_ids)
    for a in anchor_ids:
        local_idx = within_radius(positions, int(a), local_radius)
        cand.update(int(i) for i in local_idx)
    return np.array(sorted(cand), dtype=int)

def rerank_candidates(query_vec, keys, candidate_idx, support=None, support_weight=0.0):
    if len(candidate_idx) == 0:
        return None, float("-inf"), np.array([], dtype=np.float64)

    q = normalize_np(query_vec)
    cand_keys = keys[candidate_idx]
    sims = cand_keys @ q

    if support is not None and support_weight != 0.0:
        supp = np.array([support.get(int(i), 0.0) for i in candidate_idx], dtype=np.float64)
        sims = sims + support_weight * supp

    best_local = int(np.argmax(sims))
    return int(candidate_idx[best_local]), float(sims[best_local]), sims

def refine_query(query_vec, anchor_key, beta=0.25):
    return normalize_np((1.0 - beta) * query_vec + beta * anchor_key)

def softmax_pool_predict(top_idx, scores, shafts, values, temp=0.20):
    top_scores = scores[top_idx]
    w = softmax_np(top_scores, temperature=temp)
    pooled = np.sum(w[:, None] * shafts[top_idx], axis=0)
    return decode_to_item(pooled, values)

# ============================================================
# One-query decision set
# ============================================================
def predict_modes_for_query(
    query_vec,
    true_item_idx,
    keys,
    values,
    group_ids,
    positions,
    projections,
    roots_list,
    topk_root=5,
    local_radius=0.12,
    refine_beta=0.25,
    gate_margin=0.01,
    support_weight=0.0,
):
    """
    Returns:
      - predictions for all modes
      - coverage / candidate statistics
      - root scores for the first projection and multi-root union
    """
    # First projection = the baseline root
    q0, scores0 = global_search(query_vec, projections[0], roots_list[0])
    root1 = int(np.argmax(scores0))
    root_topk = topk_indices(scores0, topk_root)

    # Multi-root anchors across all projections
    all_anchor_ids = []
    best_anchor_idx = root1
    best_anchor_score = float(scores0[root1])

    # Optional support map from anchors only
    support_map = {}

    for P, roots in zip(projections, roots_list):
        _, scores = global_search(query_vec, P, roots)
        top_idx = topk_indices(scores, topk_root)
        for idx in top_idx:
            idx = int(idx)
            all_anchor_ids.append(idx)
            s = float(scores[idx])
            if idx not in support_map or s > support_map[idx]:
                support_map[idx] = s
            if s > best_anchor_score:
                best_anchor_score = s
                best_anchor_idx = idx

    all_anchor_ids = unique_preserve_order(all_anchor_ids)

    # Candidate unions
    cand_single = expand_candidates(root_topk, positions, local_radius)
    cand_multi = expand_candidates(all_anchor_ids, positions, local_radius)

    # Query refinement
    q_ref_single = refine_query(query_vec, keys[root1], beta=refine_beta)
    q_ref_multi = refine_query(query_vec, keys[best_anchor_idx], beta=refine_beta)

    # Baselines
    passive_top1_pred = root1
    passive_topk_pool_pred = softmax_pool_predict(root_topk, scores0, values, values, temp=0.20)

    # Root-only shortlist rerank
    single_rerank_pred, single_rerank_score, _ = rerank_candidates(
        query_vec, keys, cand_single, support=None, support_weight=0.0
    )
    single_refine_pred, single_refine_score, _ = rerank_candidates(
        q_ref_single, keys, cand_single, support=None, support_weight=0.0
    )

    # Multi-root union rerank
    multi_rerank_pred, multi_rerank_score, _ = rerank_candidates(
        query_vec, keys, cand_multi, support=None, support_weight=0.0
    )
    multi_refine_pred, multi_refine_score, _ = rerank_candidates(
        q_ref_multi, keys, cand_multi, support=None, support_weight=0.0
    )

    # Hybrid gate:
    # keep the best anchor unless rerank improves enough
    anchor_query_score = float(np.dot(normalize_np(query_vec), normalize_np(keys[best_anchor_idx])))
    hybrid_pred = multi_refine_pred
    hybrid_score = multi_refine_score
    if hybrid_pred is None:
        hybrid_pred = best_anchor_idx
        hybrid_score = anchor_query_score
    elif hybrid_score < anchor_query_score + gate_margin:
        hybrid_pred = best_anchor_idx
        hybrid_score = anchor_query_score

    # Candidate oracle:
    # if truth is in the multi-candidate union, pick it; else fall back to passive_top1
    oracle_pred = true_item_idx if true_item_idx in set(cand_multi.tolist()) else passive_top1_pred

    # Coverage metrics
    true_in_root_topk = int(true_item_idx in set(root_topk.tolist()))
    true_in_cand_single = int(true_item_idx in set(cand_single.tolist()))
    true_in_cand_multi = int(true_item_idx in set(cand_multi.tolist()))

    out = {
        "passive_top1": passive_top1_pred,
        "passive_topk_pool": passive_topk_pool_pred,
        "single_root_rerank": single_rerank_pred,
        "single_root_refine_rerank": single_refine_pred,
        "multi_root_rerank": multi_rerank_pred,
        "multi_root_refine_gate": hybrid_pred,
        "oracle_union": oracle_pred,
        "root_top1": root1,
        "root_topk_hit": true_in_root_topk,
        "single_candidate_coverage": true_in_cand_single,
        "multi_candidate_coverage": true_in_cand_multi,
        "single_candidate_size": int(len(cand_single)),
        "multi_candidate_size": int(len(cand_multi)),
        "best_anchor_idx": int(best_anchor_idx),
        "best_anchor_score": float(best_anchor_score),
        "anchor_query_score": float(anchor_query_score),
        "single_rerank_score": float(single_rerank_score),
        "single_refine_score": float(single_refine_score),
        "multi_rerank_score": float(multi_rerank_score),
        "multi_refine_score": float(multi_refine_score),
        "q0": q0,
        "scores0": scores0,
    }
    return out

# ============================================================
# Evaluation
# ============================================================
MODES = [
    "passive_top1",
    "passive_topk_pool",
    "single_root_rerank",
    "single_root_refine_rerank",
    "multi_root_rerank",
    "multi_root_refine_gate",
    "oracle_union",
]

def evaluate_once(
    placement="spiral",
    seed=0,
    root_dim=32,
    query_noise=0.25,
    write_leak=0.10,
    local_radius=0.12,
    topk_root=5,
    num_projections=4,
    refine_beta=0.25,
    gate_margin=0.01,
    support_weight=0.0,
    trials_per_item=2,
):
    set_seed(seed)

    keys, values, group_ids = make_clustered_memory(
        N_GROUPS,
        GROUP_SIZE,
        KEY_DIM,
        VALUE_DIM,
        seed=seed,
        key_jitter=KEY_JITTER,
        value_jitter=VALUE_JITTER,
    )

    if placement == "spiral":
        positions = fermat_spiral_positions(N_ITEMS, radius=1.0)
    elif placement == "random":
        positions = random_disk_positions(N_ITEMS, seed=seed + 12345, radius=1.0)
    else:
        raise ValueError("placement must be 'spiral' or 'random'")

    # One baseline memory field, plus a stack of projections for the multi-root variants
    P0, roots0, shafts0 = build_memory_field(
        keys, values, positions=positions,
        root_dim=root_dim,
        write_leak=write_leak,
        leak_sigma=0.18,
        seed=seed,
    )

    projections = build_projection_stack(num_projections, root_dim, KEY_DIM, seed)
    roots_list = []
    for P in projections:
        roots = normalize_np(keys @ P.T)
        roots_list.append(roots)

    rng = np.random.default_rng(seed + 4242)

    stats = {
        mode: {
            "item_hits": 0,
            "group_hits": 0,
            "root_hits": 0,
            "root_topk_hits": 0,
            "cand_cov_hits": 0,
            "cand_size_sum": 0.0,
        }
        for mode in MODES
    }

    # extra metrics for interpretation
    sum_candidate_size_single = 0.0
    sum_candidate_size_multi = 0.0
    sum_root_topk_hit = 0.0
    total = 0

    for i in range(N_ITEMS):
        true_group = int(group_ids[i])

        for _ in range(trials_per_item):
            query = normalize_np(keys[i] + query_noise * rng.normal(size=KEY_DIM))

            out = predict_modes_for_query(
                query_vec=query,
                true_item_idx=i,
                keys=keys,
                values=values,
                group_ids=group_ids,
                positions=positions,
                projections=projections,
                roots_list=roots_list,
                topk_root=topk_root,
                local_radius=local_radius,
                refine_beta=refine_beta,
                gate_margin=gate_margin,
                support_weight=support_weight,
            )

            for mode in MODES:
                pred = int(out[mode])
                stats[mode]["item_hits"] += int(pred == i)
                stats[mode]["group_hits"] += int(group_ids[pred] == true_group)

            # root and coverage diagnostics
            sum_root_topk_hit += out["root_topk_hit"]
            sum_candidate_size_single += out["single_candidate_size"]
            sum_candidate_size_multi += out["multi_candidate_size"]

            # mode-specific coverage fields
            # baselines use the first-projection root structure
            stats["passive_top1"]["root_hits"] += int(out["root_top1"] == i)
            stats["passive_top1"]["root_topk_hits"] += int(out["root_topk_hit"] == 1)
            stats["passive_top1"]["cand_cov_hits"] += int(out["single_candidate_coverage"] == 1)
            stats["passive_top1"]["cand_size_sum"] += 0.0

            stats["passive_topk_pool"]["root_hits"] += int(out["root_top1"] == i)
            stats["passive_topk_pool"]["root_topk_hits"] += int(out["root_topk_hit"] == 1)
            stats["passive_topk_pool"]["cand_cov_hits"] += int(out["single_candidate_coverage"] == 1)
            stats["passive_topk_pool"]["cand_size_sum"] += 0.0

            stats["single_root_rerank"]["root_hits"] += int(out["root_top1"] == i)
            stats["single_root_rerank"]["root_topk_hits"] += int(out["root_topk_hit"] == 1)
            stats["single_root_rerank"]["cand_cov_hits"] += int(out["single_candidate_coverage"] == 1)
            stats["single_root_rerank"]["cand_size_sum"] += out["single_candidate_size"]

            stats["single_root_refine_rerank"]["root_hits"] += int(out["root_top1"] == i)
            stats["single_root_refine_rerank"]["root_topk_hits"] += int(out["root_topk_hit"] == 1)
            stats["single_root_refine_rerank"]["cand_cov_hits"] += int(out["single_candidate_coverage"] == 1)
            stats["single_root_refine_rerank"]["cand_size_sum"] += out["single_candidate_size"]

            stats["multi_root_rerank"]["root_hits"] += int(out["root_top1"] == i)
            stats["multi_root_rerank"]["root_topk_hits"] += int(out["root_topk_hit"] == 1)
            stats["multi_root_rerank"]["cand_cov_hits"] += int(out["multi_candidate_coverage"] == 1)
            stats["multi_root_rerank"]["cand_size_sum"] += out["multi_candidate_size"]

            stats["multi_root_refine_gate"]["root_hits"] += int(out["root_top1"] == i)
            stats["multi_root_refine_gate"]["root_topk_hits"] += int(out["root_topk_hit"] == 1)
            stats["multi_root_refine_gate"]["cand_cov_hits"] += int(out["multi_candidate_coverage"] == 1)
            stats["multi_root_refine_gate"]["cand_size_sum"] += out["multi_candidate_size"]

            stats["oracle_union"]["root_hits"] += int(out["root_top1"] == i)
            stats["oracle_union"]["root_topk_hits"] += int(out["root_topk_hit"] == 1)
            stats["oracle_union"]["cand_cov_hits"] += int(out["multi_candidate_coverage"] == 1)
            stats["oracle_union"]["cand_size_sum"] += out["multi_candidate_size"]

            total += 1

    rows = []
    for mode in MODES:
        rows.append({
            "placement": placement,
            "seed": seed,
            "mode": mode,
            "root_dim": root_dim,
            "query_noise": query_noise,
            "write_leak": write_leak,
            "local_radius": local_radius,
            "topk_root": topk_root,
            "num_projections": num_projections,
            "item_acc": stats[mode]["item_hits"] / total,
            "group_acc": stats[mode]["group_hits"] / total,
            "root_hit_top1": stats[mode]["root_hits"] / total,
            "root_hit_topk": stats[mode]["root_topk_hits"] / total,
            "candidate_coverage": stats[mode]["cand_cov_hits"] / total,
            "avg_candidate_size": stats[mode]["cand_size_sum"] / total,
            "nn_dist": mean_nearest_neighbor_distance(positions),
            "interference": mean_interference_kernel(positions),
        })

    diagnostics = {
        "single_candidate_size_mean": sum_candidate_size_single / total,
        "multi_candidate_size_mean": sum_candidate_size_multi / total,
        "root_topk_hit_mean": sum_root_topk_hit / total,
        "nn_dist": mean_nearest_neighbor_distance(positions),
        "interference": mean_interference_kernel(positions),
    }

    return rows, diagnostics, positions

def aggregate(df, group_cols):
    return (
        df.groupby(group_cols, as_index=False)
          .agg(
              item_acc_mean=("item_acc", "mean"),
              item_acc_std=("item_acc", "std"),
              group_acc_mean=("group_acc", "mean"),
              group_acc_std=("group_acc", "std"),
              root_hit_top1_mean=("root_hit_top1", "mean"),
              root_hit_topk_mean=("root_hit_topk", "mean"),
              candidate_coverage_mean=("candidate_coverage", "mean"),
              avg_candidate_size_mean=("avg_candidate_size", "mean"),
              nn_dist_mean=("nn_dist", "mean"),
              interference_mean=("interference", "mean"),
          )
    )

def paired_delta_table(df, baseline_mode="passive_top1", metric="item_acc", group_cols=None):
    if group_cols is None:
        group_cols = ["placement", "root_dim", "query_noise", "write_leak", "local_radius", "topk_root", "num_projections"]

    base = df[df["mode"] == baseline_mode].copy()
    other = df[df["mode"] != baseline_mode].copy()
    merged = other.merge(
        base[group_cols + ["seed", metric]],
        on=group_cols + ["seed"],
        suffixes=("", "_baseline"),
        how="left",
    )
    merged["delta"] = merged[metric] - merged[f"{metric}_baseline"]

    rows = []
    for keys, grp in merged.groupby(group_cols + ["mode"], dropna=False):
        if not isinstance(keys, tuple):
            keys = (keys,)
        row = {col: val for col, val in zip(group_cols + ["mode"], keys)}
        row["delta_mean"] = float(grp["delta"].mean())
        row["delta_std"] = float(grp["delta"].std(ddof=1)) if len(grp) > 1 else 0.0
        t, p = safe_ttest_rel(grp[metric].values, grp[f"{metric}_baseline"].values)
        row["paired_t"] = t
        row["paired_p"] = p
        row["baseline_mean"] = float(grp[f"{metric}_baseline"].mean())
        row["mode_mean"] = float(grp[metric].mean())
        rows.append(row)
    return pd.DataFrame(rows)

