# ============================================================
# Optional plots
# ============================================================
def plot_main_beta(df, placement):
    sub = df[df["placement"] == placement]
    order = ["flat_key_nn", "passive_root_top1", "single_root_rerank", "multi_root_rerank", "oracle_union"]
    vals = [float(sub[sub["mode"] == m]["item_acc_mean"].iloc[0]) for m in order]
    plt.figure(figsize=(9, 4))
    plt.bar(order, vals)
    plt.xticks(rotation=20)
    plt.ylabel("Item accuracy")
    plt.title(f"Main operating point — {placement}")
    plt.grid(True, alpha=0.25)
    plt.tight_layout()
    plt.show()

plot_main_beta(main_agg, "spiral")
plot_main_beta(main_agg, "random")

# ============================================================
# MEMORY HAIR — PART 8
# Gap Closer: candidate discovery vs candidate judgment
# ------------------------------------------------------------
# Goal:
#   Use the strongest candidate pool we have found so far,
#   then compare several judges to see what closes the gap:
#     - flat key NN over all items
#     - passive_root_top1
#     - single_root_rerank
#     - multi_root_rerank
#     - multi_root_mix_rerank (flat + root + local signals)
#     - learned_linear_judge (trained on held-out split)
#     - oracle_union (upper bound from the candidate pool)
#
# What this script answers:
#   1) Is the remaining gap mostly the judge, not discovery?
#   2) Does a slightly richer non-learned score help?
#   3) Can a simple learned judge close more of the gap?
#   4) Does spiral still help once the judge improves?
#
# Design choices:
#   - Keeps the same synthetic clustered memory as earlier parts.
#   - Uses multi-root candidate discovery.
#   - Adds a fair train/test split by group for the learned judge.
#   - Runs at least 3 seeds.
#   - Prints only the important summary tables.
#
# Notes:
#   - This is meant to be a diagnostic, not a final architecture.
#   - If the learned judge still cannot beat flat key NN, the paper
#     story should stay focused on candidate coverage / ranking limits.
# ============================================================

import os
import random
from dataclasses import dataclass
from collections import defaultdict

import numpy as np
