# Config
# ============================================================
SEEDS = [11, 22, 33]
PLACEMENTS = ["spiral", "random"]
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")

# Memory size
N_GROUPS = 64
GROUP_SIZE = 4
KEY_DIM = 64
VALUE_DIM = 64

# Candidate discovery
ROOT_DIM = 32
TOPK_ROOT = 5
NUM_PROJECTIONS = 4
LOCAL_RADIUS = 0.12

# Query conditions
QUERY_NOISE = 0.25
KEY_JITTER = 0.12
VALUE_JITTER = 0.12

# Learnable judge
TRAIN_PER_GROUP = 3   # with group size 4, this leaves 1 test item/group
BATCH_SIZE = 256
EPOCHS = 18
LR = 1e-3
NEG_PER_POS = 6

# Sweeps
ROOT_DIMS = [8, 16, 32, 64]
TOPK_ROOTS = [1, 3, 5, 10]
NUM_PROJECTIONS_LIST = [1, 2, 4, 8]
QUERY_NOISES = [0.10, 0.20, 0.30, 0.40]
SCALE_GROUPS = [32, 64, 128]

