# ============================================================
# Repro
# ============================================================
def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

# ============================================================
# Math helpers
# ============================================================
def normalize(x, axis=-1, eps=1e-9):
    x = np.asarray(x, dtype=np.float64)
    n = np.linalg.norm(x, axis=axis, keepdims=True)
    return x / (n + eps)


def softmax_np(x, axis=-1, temperature=1.0):
    x = np.asarray(x, dtype=np.float64)
    x = x / max(float(temperature), 1e-9)
    x = x - np.max(x, axis=axis, keepdims=True)
    ex = np.exp(x)
    return ex / (np.sum(ex, axis=axis, keepdims=True) + 1e-9)


def topk_idx(scores, k):
    k = min(int(k), len(scores))
    if k <= 0:
        return np.array([], dtype=int)
    idx = np.argpartition(scores, -k)[-k:]
    return idx[np.argsort(scores[idx])[::-1]]


def cosine(a, b, eps=1e-9):
    a = np.asarray(a, dtype=np.float64)
    b = np.asarray(b, dtype=np.float64)
    return float(np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b) + eps))

# ============================================================
# Geometry
# ============================================================
def fermat_spiral_positions(n, radius=1.0):
    golden_angle = np.pi * (3.0 - np.sqrt(5.0))
    i = np.arange(n)
    r = radius * np.sqrt((i + 0.5) / n)
    theta = i * golden_angle
    x = r * np.cos(theta)
    y = r * np.sin(theta)
    return np.stack([x, y], axis=1)


def random_disk_positions(n, seed=0, radius=1.0):
    rng = np.random.default_rng(seed)
    r = radius * np.sqrt(rng.random(n))
    theta = 2.0 * np.pi * rng.random(n)
    x = r * np.cos(theta)
    y = r * np.sin(theta)
    return np.stack([x, y], axis=1)


def mean_nearest_neighbor_distance(pos):
    d = pos[:, None, :] - pos[None, :, :]
    dist = np.sqrt((d ** 2).sum(-1))
    np.fill_diagonal(dist, np.inf)
    return float(dist.min(axis=1).mean())


def mean_interference_kernel(pos, sigma=0.18):
    d = pos[:, None, :] - pos[None, :, :]
    dist2 = (d ** 2).sum(-1)
    W = np.exp(-dist2 / (2.0 * sigma ** 2))
    np.fill_diagonal(W, 0.0)
    return float(W.mean())


def union_radius_neighbors(positions, centers, radius):
    centers = np.asarray(centers, dtype=int)
    if len(centers) == 0:
        return np.array([], dtype=int)
    diff = positions[:, None, :] - positions[centers][None, :, :]
    d2 = np.sum(diff ** 2, axis=2)
    mask = np.any(d2 <= radius ** 2, axis=1)
    idx = np.where(mask)[0]
    if len(idx) == 0:
        idx = np.array([int(centers[0])], dtype=int)
    return idx

# ============================================================
# Synthetic clustered memory
# ============================================================
def make_clustered_memory(n_groups, group_size, key_dim, value_dim, seed=0, key_jitter=0.12, value_jitter=0.12):
    rng = np.random.default_rng(seed)
    keys = []
    values = []
    group_ids = []

    key_centers = normalize(rng.normal(size=(n_groups, key_dim)))
    value_centers = normalize(rng.normal(size=(n_groups, value_dim)))

    for g in range(n_groups):
        for _ in range(group_size):
            k = normalize(key_centers[g] + key_jitter * rng.normal(size=key_dim))
            v = normalize(value_centers[g] + value_jitter * rng.normal(size=value_dim))
            keys.append(k)
            values.append(v)
            group_ids.append(g)

    return np.stack(keys), np.stack(values), np.array(group_ids, dtype=int)


def split_by_group(group_ids, test_per_group=1, seed=0):
    rng = np.random.default_rng(seed)
    train_ids = []
    test_ids = []
    for g in np.unique(group_ids):
        idx = np.where(group_ids == g)[0]
        test_sel = rng.choice(idx, size=test_per_group, replace=False)
        test_set = set(test_sel.tolist())
        train_sel = np.array([i for i in idx if i not in test_set], dtype=int)
        train_ids.extend(train_sel.tolist())
        test_ids.extend(test_sel.tolist())
    return np.array(train_ids, dtype=int), np.array(test_ids, dtype=int)

# ============================================================
# Projections / roots
# ============================================================
def build_projections(key_dim, root_dim, num_projections, seed=0):
    rng = np.random.default_rng(seed + 999)
    Ps = []
    for _ in range(num_projections):
        P = rng.normal(size=(root_dim, key_dim)) / np.sqrt(key_dim)
        Ps.append(P)
    return Ps


def build_roots(keys, Ps):
    roots = []
    for P in Ps:
        roots.append(normalize(keys @ P.T))
    return roots


def root_scores_for_query(query, Ps, roots_bank):
    qroots = []
    scores_bank = []
    for P, roots in zip(Ps, roots_bank):
        qroot = normalize(query @ P.T)
        scores = roots @ qroot
        qroots.append(qroot)
        scores_bank.append(scores)
    return qroots, scores_bank

# ============================================================
# Candidate pools
# ============================================================
def candidate_pool_from_anchors(positions, anchor_idx, radius):
    return union_radius_neighbors(positions, anchor_idx, radius)


def union_of_candidates(positions, anchor_sets, radius):
    all_anchors = np.unique(np.concatenate(anchor_sets)) if len(anchor_sets) else np.array([], dtype=int)
    return candidate_pool_from_anchors(positions, all_anchors, radius), all_anchors

# ============================================================
# Reranking features
# ============================================================
def candidate_features(query, keys, candidate_idx, scores_bank, positions=None, candidate_center_idx=None, local_radius=0.12):
    """
    Features used by the learned judge and some heuristics.
    The candidate is the item being scored.
    """
    q = normalize(query)
    cand = keys[candidate_idx]
    flat = cand @ q

    # Aggregate root support across projections
    root_supports = np.stack([sb[candidate_idx] for sb in scores_bank], axis=0)  # (P,)
    root_mean = float(root_supports.mean())
    root_max = float(root_supports.max())
    root_std = float(root_supports.std())

    # Candidate local density around its own position (static, not query dependent)
    if positions is not None and candidate_center_idx is not None:
        d2 = np.sum((positions - positions[candidate_center_idx]) ** 2, axis=1)
        local_density = float(np.mean(d2 <= local_radius ** 2))
        nn_dist = float(np.sqrt(np.sort(d2)[1])) if len(d2) > 1 else 0.0
    else:
        local_density = 0.0
        nn_dist = 0.0

    # A simple support-gap proxy
    support_gap = root_max - root_mean

    return np.array([flat, root_mean, root_max, root_std, support_gap, local_density, nn_dist], dtype=np.float32)


class LinearJudge(nn.Module):
    def __init__(self, in_dim):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, 32),
            nn.ReLU(),
            nn.Linear(32, 1),
        )

    def forward(self, x):
        return self.net(x).squeeze(-1)


# ============================================================
# One evaluation case
# ============================================================
def evaluate_case(
    n_groups=64,
    group_size=4,
    placement="spiral",
    seed=0,
    root_dim=32,
    topk_root=5,
    num_projections=4,
    query_noise=0.25,
    local_radius=0.12,
    trials_per_item=3,
    train_per_group=3,
    use_learned_judge=True,
):
    set_seed(seed)
    n_items = n_groups * group_size

    keys, values, group_ids = make_clustered_memory(
        n_groups=n_groups,
        group_size=group_size,
        key_dim=KEY_DIM,
        value_dim=VALUE_DIM,
        seed=seed,
        key_jitter=KEY_JITTER,
        value_jitter=VALUE_JITTER,
    )

    if placement == "spiral":
        positions = fermat_spiral_positions(n_items, radius=1.0)
    elif placement == "random":
        positions = random_disk_positions(n_items, seed=seed + 12345, radius=1.0)
    else:
        raise ValueError("placement must be 'spiral' or 'random'")

    Ps = build_projections(KEY_DIM, root_dim, num_projections, seed=seed)
    roots_bank = build_roots(keys, Ps)
    keys_norm = normalize(keys)
    rng = np.random.default_rng(seed + 4242)

    # Split for learned judge
    train_ids, test_ids = split_by_group(group_ids, test_per_group=1, seed=seed)

    # Build training data for learned judge from candidate pools around training items
    X_train = []
    y_train = []
    # We train the judge on candidate ranking among the discovered pool.
    # Positive is the true item. Negatives are other candidates from the same pool.
    for i in train_ids:
        for _ in range(train_per_group):
            q = normalize(keys[i] + query_noise * rng.normal(size=KEY_DIM))
            qroots, scores_bank = root_scores_for_query(q, Ps, roots_bank)
            anchor_sets = [topk_idx(scores_bank[p], topk_root) for p in range(num_projections)]
            cand_multi, _ = union_of_candidates(positions, anchor_sets, local_radius)
            if len(cand_multi) == 0:
                continue
            # Limit negatives to keep training fast
            cand_list = cand_multi.tolist()
            if i not in cand_list:
                cand_list = cand_list + [i]
            cand_list = list(dict.fromkeys(cand_list))
            pos_feat = candidate_features(q, keys, i, scores_bank, positions=positions, candidate_center_idx=i, local_radius=local_radius)
            X_train.append(pos_feat)
            y_train.append(1.0)
            negs = [c for c in cand_list if c != i]
            if len(negs) > 0:
                neg_pick = rng.choice(negs, size=min(NEG_PER_POS, len(negs)), replace=False)
                for c in neg_pick:
                    feat = candidate_features(q, keys, c, scores_bank, positions=positions, candidate_center_idx=c, local_radius=local_radius)
                    X_train.append(feat)
                    y_train.append(0.0)

    X_train = np.asarray(X_train, dtype=np.float32)
    y_train = np.asarray(y_train, dtype=np.float32)

    learned_judge = None
    if use_learned_judge and len(X_train) > 0:
        learned_judge = LinearJudge(X_train.shape[1]).to(DEVICE)
        opt = torch.optim.Adam(learned_judge.parameters(), lr=LR)
        loss_fn = nn.BCEWithLogitsLoss()
        ds = TensorDataset(torch.tensor(X_train), torch.tensor(y_train))
        dl = DataLoader(ds, batch_size=BATCH_SIZE, shuffle=True, drop_last=False)
        learned_judge.train()
        for _ in range(EPOCHS):
            for xb, yb in dl:
                xb = xb.to(DEVICE)
                yb = yb.to(DEVICE)
                opt.zero_grad()
                logits = learned_judge(xb)
                loss = loss_fn(logits, yb)
                loss.backward()
                opt.step()

    modes = [
        "flat_key_nn",
        "passive_root_top1",
        "single_root_rerank",
        "multi_root_rerank",
        "multi_root_mix_rerank",
        "learned_linear_judge",
        "oracle_union",
    ]

    stats = {m: defaultdict(float) for m in modes}
    total = 0

    learned_judge.eval() if learned_judge is not None else None

    with torch.no_grad():
        for i in test_ids:
            true_group = int(group_ids[i])
            for _ in range(trials_per_item):
                q = normalize(keys[i] + query_noise * rng.normal(size=KEY_DIM))
                qroots, scores_bank = root_scores_for_query(q, Ps, roots_bank)

                flat_scores = keys_norm @ q
                flat_pred = int(np.argmax(flat_scores))

                anchor_sets = [topk_idx(scores_bank[p], topk_root) for p in range(num_projections)]
                single_anchors = anchor_sets[0]
                multi_anchors = np.unique(np.concatenate(anchor_sets))

                cand_single = candidate_pool_from_anchors(positions, single_anchors, local_radius)
                cand_multi, _ = union_of_candidates(positions, anchor_sets, local_radius)

                # Root coverage / discovery diagnostics
                root_top1 = int(np.argmax(scores_bank[0]))
                root_hit_top1 = int(root_top1 == i)
                root_hit_topk = int(i in set(np.unique(np.concatenate(anchor_sets)).tolist()))

                # Heuristic 1: passive root top1 (local pick using the first projection's anchor pool)
                if len(cand_single) > 0:
                    pred_passive = int(cand_single[np.argmax(flat_scores[cand_single])])
                else:
                    pred_passive = flat_pred

                # Heuristic 2: single-root rerank (flat + root mean from the single projection)
                if len(cand_single) > 0:
                    feats = []
                    for c in cand_single:
                        f = candidate_features(q, keys, c, scores_bank[:1], positions=positions, candidate_center_idx=c, local_radius=local_radius)
                        feats.append(f)
                    feats = np.stack(feats, axis=0)
                    flat = feats[:, 0]
                    root_mean = feats[:, 1]
                    root_std = (root_mean - root_mean.mean()) / (root_mean.std() + 1e-9)
                    score = flat + 0.00 * root_std  # keep this as a clean single-root rerank
                    pred_single = int(cand_single[int(np.argmax(score))])
                else:
                    pred_single = flat_pred

                # Heuristic 3: multi-root rerank (flat + root support)
                if len(cand_multi) > 0:
                    feats = []
                    for c in cand_multi:
                        f = candidate_features(q, keys, c, scores_bank, positions=positions, candidate_center_idx=c, local_radius=local_radius)
                        feats.append(f)
                    feats = np.stack(feats, axis=0)
                    flat = feats[:, 0]
                    root_mean = feats[:, 1]
                    root_max = feats[:, 2]
                    root_std = feats[:, 3]
                    # This is the baseline heuristic judge.
                    score = flat + 0.25 * root_mean + 0.10 * root_max - 0.05 * root_std
                    pred_multi = int(cand_multi[int(np.argmax(score))])
                else:
                    pred_multi = flat_pred

                # Heuristic 4: slightly richer mix (flat + root + local density)
                if len(cand_multi) > 0:
                    feats = []
                    for c in cand_multi:
                        f = candidate_features(q, keys, c, scores_bank, positions=positions, candidate_center_idx=c, local_radius=local_radius)
                        feats.append(f)
                    feats = np.stack(feats, axis=0)
                    flat = feats[:, 0]
                    root_mean = feats[:, 1]
                    root_max = feats[:, 2]
                    root_std = feats[:, 3]
                    support_gap = feats[:, 4]
                    local_density = feats[:, 5]
                    # Very light extra structure: prefer candidates supported by roots and not too isolated.
                    score = flat + 0.18 * root_mean + 0.12 * root_max - 0.05 * root_std + 0.03 * support_gap + 0.02 * local_density
                    pred_mix = int(cand_multi[int(np.argmax(score))])
                else:
                    pred_mix = flat_pred

                # Learned judge on the same candidate pool
                if learned_judge is not None and len(cand_multi) > 0:
                    feats = []
                    for c in cand_multi:
                        f = candidate_features(q, keys, c, scores_bank, positions=positions, candidate_center_idx=c, local_radius=local_radius)
                        feats.append(f)
                    feats_t = torch.tensor(np.stack(feats, axis=0), dtype=torch.float32, device=DEVICE)
                    logits = learned_judge(feats_t).cpu().numpy()
                    pred_learned = int(cand_multi[int(np.argmax(logits))])
                else:
                    pred_learned = pred_multi

                # Oracle ceiling for the candidate pool
                pred_oracle = i if i in set(cand_multi.tolist()) else pred_multi

                for mode, pred, cand in [
                    ("flat_key_nn", flat_pred, np.arange(n_items)),
                    ("passive_root_top1", pred_passive, cand_single),
                    ("single_root_rerank", pred_single, cand_single),
                    ("multi_root_rerank", pred_multi, cand_multi),
                    ("multi_root_mix_rerank", pred_mix, cand_multi),
                    ("learned_linear_judge", pred_learned, cand_multi),
                    ("oracle_union", pred_oracle, cand_multi),
                ]:
                    stats[mode]["item_hits"] += int(pred == i)
                    stats[mode]["group_hits"] += int(group_ids[pred] == true_group)
                    stats[mode]["root_hit_top1"] += root_hit_top1
                    stats[mode]["root_hit_topk"] += root_hit_topk
                    stats[mode]["candidate_coverage"] += int(i in set(cand.tolist()))
                    stats[mode]["candidate_size"] += len(cand)
                total += 1

    rows = []
    for mode in modes:
        rows.append({
            "placement": placement,
            "seed": seed,
            "n_groups": n_groups,
            "group_size": group_size,
            "root_dim": root_dim,
            "topk_root": topk_root,
            "num_projections": num_projections,
            "query_noise": query_noise,
            "local_radius": local_radius,
            "mode": mode,
            "item_acc": stats[mode]["item_hits"] / total,
            "group_acc": stats[mode]["group_hits"] / total,
            "root_hit_top1": stats[mode]["root_hit_top1"] / total,
            "root_hit_topk": stats[mode]["root_hit_topk"] / total,
            "candidate_coverage": stats[mode]["candidate_coverage"] / total,
            "avg_candidate_size": stats[mode]["candidate_size"] / total,
            "nn_dist": mean_nearest_neighbor_distance(positions),
            "interference": mean_interference_kernel(positions),
            "trained_judge": int(learned_judge is not None),
        })
    return rows

# ============================================================
# Summary helpers
# ============================================================
def summarize(df, group_cols, value_cols):
    agg = {}
    for c in value_cols:
        agg[f"{c}_mean"] = (c, "mean")
        agg[f"{c}_std"] = (c, "std")
    return df.groupby(group_cols, as_index=False).agg(**agg)


def gap_table(summary_df, group_cols):
    # summary_df must already contain item_acc_mean
    base = summary_df[summary_df["mode"] == "flat_key_nn"][group_cols + ["item_acc_mean"]].rename(columns={"item_acc_mean": "baseline"})
    hair = summary_df[summary_df["mode"] == "multi_root_rerank"][group_cols + ["item_acc_mean"]].rename(columns={"item_acc_mean": "hair"})
    oracle = summary_df[summary_df["mode"] == "oracle_union"][group_cols + ["item_acc_mean"]].rename(columns={"item_acc_mean": "oracle"})
    out = base.merge(hair, on=group_cols).merge(oracle, on=group_cols)
    out["hair_minus_baseline"] = out["hair"] - out["baseline"]
    out["oracle_minus_hair"] = out["oracle"] - out["hair"]
    out["oracle_minus_baseline"] = out["oracle"] - out["baseline"]
    return out

# ============================================================
# Runs
# ============================================================
all_rows = []
root_rows = []
topk_rows = []
proj_rows = []
noise_rows = []
scale_rows = []

print("\nRunning main gap-closer benchmark...\n")
for placement in PLACEMENTS:
    for seed in SEEDS:
        all_rows.extend(evaluate_case(
            placement=placement,
            seed=seed,
            root_dim=ROOT_DIM,
            topk_root=TOPK_ROOT,
            num_projections=NUM_PROJECTIONS,
            query_noise=QUERY_NOISE,
            local_radius=LOCAL_RADIUS,
            trials_per_item=3,
            train_per_group=TRAIN_PER_GROUP,
            use_learned_judge=True,
        ))

print("Running root_dim sweep...")
for placement in PLACEMENTS:
    for seed in SEEDS:
        for rd in ROOT_DIMS:
            root_rows.extend(evaluate_case(
                placement=placement,
                seed=seed,
                root_dim=rd,
                topk_root=TOPK_ROOT,
                num_projections=NUM_PROJECTIONS,
                query_noise=QUERY_NOISE,
                local_radius=LOCAL_RADIUS,
                trials_per_item=3,
                train_per_group=TRAIN_PER_GROUP,
                use_learned_judge=True,
            ))

print("Running topk_root sweep...")
for placement in PLACEMENTS:
    for seed in SEEDS:
        for tk in TOPK_ROOTS:
            topk_rows.extend(evaluate_case(
                placement=placement,
                seed=seed,
                root_dim=ROOT_DIM,
                topk_root=tk,
                num_projections=NUM_PROJECTIONS,
                query_noise=QUERY_NOISE,
                local_radius=LOCAL_RADIUS,
                trials_per_item=3,
                train_per_group=TRAIN_PER_GROUP,
                use_learned_judge=True,
            ))

print("Running num_projections sweep...")
for placement in PLACEMENTS:
    for seed in SEEDS:
        for npj in NUM_PROJECTIONS_LIST:
            proj_rows.extend(evaluate_case(
                placement=placement,
                seed=seed,
                root_dim=ROOT_DIM,
                topk_root=TOPK_ROOT,
                num_projections=npj,
                query_noise=QUERY_NOISE,
                local_radius=LOCAL_RADIUS,
                trials_per_item=3,
                train_per_group=TRAIN_PER_GROUP,
                use_learned_judge=True,
            ))

print("Running query_noise sweep...")
for placement in PLACEMENTS:
    for seed in SEEDS:
        for qn in QUERY_NOISES:
            noise_rows.extend(evaluate_case(
                placement=placement,
                seed=seed,
                root_dim=ROOT_DIM,
                topk_root=TOPK_ROOT,
                num_projections=NUM_PROJECTIONS,
                query_noise=qn,
                local_radius=LOCAL_RADIUS,
                trials_per_item=3,
                train_per_group=TRAIN_PER_GROUP,
                use_learned_judge=True,
            ))

print("Running scale sweep...")
for placement in PLACEMENTS:
    for seed in SEEDS:
        for ng in SCALE_GROUPS:
            scale_rows.extend(evaluate_case(
                n_groups=ng,
                placement=placement,
                seed=seed,
                root_dim=ROOT_DIM,
                topk_root=TOPK_ROOT,
                num_projections=NUM_PROJECTIONS,
                query_noise=QUERY_NOISE,
                local_radius=LOCAL_RADIUS,
                trials_per_item=3,
                train_per_group=TRAIN_PER_GROUP,
                use_learned_judge=True,
            ))

# ============================================================
# DataFrames and summaries
# ============================================================
main_df = pd.DataFrame(all_rows)
root_df = pd.DataFrame(root_rows)
topk_df = pd.DataFrame(topk_rows)
proj_df = pd.DataFrame(proj_rows)
noise_df = pd.DataFrame(noise_rows)
