# ============================================================
# MEMORY HAIR — PART 9
# Loose-Screw + Selective Guard on a Fixed Multi-Root Pool
# ------------------------------------------------------------
# What this script answers:
#   1) Is the candidate pool already strong?
#   2) Can a better judge close more of the remaining gap?
#   3) Does a Loose-Screw style judge help?
#   4) Does a Selective Guard fallback help?
#   5) Does spiral still help after the judge improves?
#
# Main idea:
#   Freeze candidate discovery, then compare judges on the same pool:
#     - flat_key_nn
#     - passive_root_top1
#     - single_root_rerank
#     - multi_root_rerank
#     - multi_root_mix_rerank
#     - learned_linear_judge
#     - loose_screw_judge
#     - guarded_linear_judge
#     - guarded_loose_screw
#     - oracle_union
#
# Notes:
#   - This is a diagnostic script, not a final architecture.
#   - It uses 3 seeds.
#   - It prints only the important summaries.
# ============================================================

import os
import random
from collections import defaultdict

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import torch
import torch.nn as nn
from torch.utils.data import DataLoader, TensorDataset

# ============================================================
# Config
# ============================================================
SEEDS = [11, 22, 33]
PLACEMENTS = ["spiral", "random"]
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")

# Memory size
N_GROUPS = 64
GROUP_SIZE = 4
KEY_DIM = 64
VALUE_DIM = 64

# Candidate discovery
ROOT_DIM = 32
TOPK_ROOT = 5
NUM_PROJECTIONS = 4
LOCAL_RADIUS = 0.12

# Query conditions
QUERY_NOISE = 0.25
KEY_JITTER = 0.12
VALUE_JITTER = 0.12

# Learned judges
TRAIN_PER_GROUP = 3
NEG_PER_POS = 6
BATCH_SIZE = 256
EPOCHS = 14
LR = 1e-3

# Guard
GUARD_MARGIN = 0.08

# Sweeps
ROOT_DIMS = [8, 16, 32, 64]
TOPK_ROOTS = [1, 3, 5, 10]
NUM_PROJECTIONS_LIST = [1, 2, 4, 8]
QUERY_NOISES = [0.10, 0.20, 0.30, 0.40]
SCALE_GROUPS = [32, 64, 128]

OUTDIR = "memory_hair_part9_ls_guard"
os.makedirs(OUTDIR, exist_ok=True)

pd.set_option("display.max_columns", 300)
pd.set_option("display.width", 240)

print("Device:", DEVICE)
print("Artifacts:", OUTDIR)

# ============================================================
# Repro
# ============================================================
def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

# ============================================================
# Math helpers
# ============================================================
def normalize(x, axis=-1, eps=1e-9):
    x = np.asarray(x, dtype=np.float64)
    n = np.linalg.norm(x, axis=axis, keepdims=True)
    return x / (n + eps)

def softmax_np(x, axis=-1, temperature=1.0):
    x = np.asarray(x, dtype=np.float64)
    x = x / max(float(temperature), 1e-9)
    x = x - np.max(x, axis=axis, keepdims=True)
    ex = np.exp(x)
    return ex / (np.sum(ex, axis=axis, keepdims=True) + 1e-9)

def topk_idx(scores, k):
    k = min(int(k), len(scores))
    if k <= 0:
        return np.array([], dtype=int)
    idx = np.argpartition(scores, -k)[-k:]
    return idx[np.argsort(scores[idx])[::-1]]

# ============================================================
# Geometry
# ============================================================
def fermat_spiral_positions(n, radius=1.0):
    golden_angle = np.pi * (3.0 - np.sqrt(5.0))
    i = np.arange(n)
    r = radius * np.sqrt((i + 0.5) / n)
    theta = i * golden_angle
    x = r * np.cos(theta)
    y = r * np.sin(theta)
    return np.stack([x, y], axis=1)

def random_disk_positions(n, seed=0, radius=1.0):
    rng = np.random.default_rng(seed)
    r = radius * np.sqrt(rng.random(n))
    theta = 2.0 * np.pi * rng.random(n)
    x = r * np.cos(theta)
    y = r * np.sin(theta)
    return np.stack([x, y], axis=1)

def mean_nearest_neighbor_distance(pos):
    d = pos[:, None, :] - pos[None, :, :]
    dist = np.sqrt((d ** 2).sum(-1))
    np.fill_diagonal(dist, np.inf)
    return float(dist.min(axis=1).mean())

def mean_interference_kernel(pos, sigma=0.18):
    d = pos[:, None, :] - pos[None, :, :]
    dist2 = (d ** 2).sum(-1)
    W = np.exp(-dist2 / (2.0 * sigma ** 2))
    np.fill_diagonal(W, 0.0)
    return float(W.mean())

def union_radius_neighbors(positions, centers, radius):
    centers = np.asarray(centers, dtype=int)
    if len(centers) == 0:
        return np.array([], dtype=int)
    diff = positions[:, None, :] - positions[centers][None, :, :]
    d2 = np.sum(diff ** 2, axis=2)
    mask = np.any(d2 <= radius ** 2, axis=1)
    idx = np.where(mask)[0]
    if len(idx) == 0:
        idx = np.array([int(centers[0])], dtype=int)
    return idx

# ============================================================
# Synthetic clustered memory
# ============================================================
def make_clustered_memory(
    n_groups,
    group_size,
    key_dim,
    value_dim,
    seed=0,
    key_jitter=0.12,
    value_jitter=0.12,
):
    rng = np.random.default_rng(seed)
    keys = []
    values = []
    group_ids = []

    key_centers = normalize(rng.normal(size=(n_groups, key_dim)))
    value_centers = normalize(rng.normal(size=(n_groups, value_dim)))

    for g in range(n_groups):
        for _ in range(group_size):
            k = normalize(key_centers[g] + key_jitter * rng.normal(size=key_dim))
            v = normalize(value_centers[g] + value_jitter * rng.normal(size=value_dim))
            keys.append(k)
            values.append(v)
            group_ids.append(g)

    return np.stack(keys), np.stack(values), np.array(group_ids, dtype=int)

def split_by_group(group_ids, test_per_group=1, seed=0):
    rng = np.random.default_rng(seed)
    train_ids = []
    test_ids = []

    for g in np.unique(group_ids):
        idx = np.where(group_ids == g)[0]
        if len(idx) <= test_per_group:
            raise ValueError(f"Group {g} too small for split.")
        test_sel = rng.choice(idx, size=test_per_group, replace=False)
        test_set = set(test_sel.tolist())
        train_sel = np.array([i for i in idx if i not in test_set], dtype=int)
        train_ids.extend(train_sel.tolist())
        test_ids.extend(test_sel.tolist())

    return np.array(train_ids, dtype=int), np.array(test_ids, dtype=int)

# ============================================================
# Projections / roots
# ============================================================
def build_projections(key_dim, root_dim, num_projections, seed=0):
    rng = np.random.default_rng(seed + 999)
    Ps = []
    for _ in range(num_projections):
        P = rng.normal(size=(root_dim, key_dim)) / np.sqrt(key_dim)
        Ps.append(P)
    return Ps

def build_roots(keys, Ps):
    roots = []
    for P in Ps:
        roots.append(normalize(keys @ P.T))
    return roots

def root_scores_for_query(query, Ps, roots_bank):
    qroots = []
    scores_bank = []
    for P, roots in zip(Ps, roots_bank):
        qroot = normalize(query @ P.T)
        scores = roots @ qroot
        qroots.append(qroot)
        scores_bank.append(scores)
    return qroots, scores_bank

# ============================================================
# Candidate pools
# ============================================================
def candidate_pool_from_anchors(positions, anchor_idx, radius):
    return union_radius_neighbors(positions, anchor_idx, radius)

def union_of_candidates(positions, anchor_sets, radius):
    if len(anchor_sets) == 0:
        return np.array([], dtype=int), np.array([], dtype=int)
    all_anchors = np.unique(np.concatenate(anchor_sets))
    cand = candidate_pool_from_anchors(positions, all_anchors, radius)
    return cand, all_anchors

# ============================================================
# Candidate features
# ============================================================
def candidate_features(
    query,
    keys,
    candidate_idx,
    scores_bank,
    positions=None,
    candidate_center_idx=None,
    local_radius=0.12,
):
    """
    Features for a candidate item under a specific query.
    """
    q = normalize(query)
    cand = keys[candidate_idx]
    flat = float(cand @ q)

    root_supports = np.array([sb[candidate_idx] for sb in scores_bank], dtype=np.float64)
    root_mean = float(root_supports.mean())
    root_max = float(root_supports.max())
    root_std = float(root_supports.std())
    support_gap = float(root_max - root_mean)

    if positions is not None and candidate_center_idx is not None:
        d2 = np.sum((positions - positions[candidate_center_idx]) ** 2, axis=1)
        d2_sorted = np.sort(d2)
        nn_dist = float(np.sqrt(d2_sorted[1])) if len(d2_sorted) > 1 else 0.0
        local_density = float(np.mean(d2 <= local_radius ** 2))
    else:
        nn_dist = 0.0
        local_density = 0.0

    return np.array(
        [flat, root_mean, root_max, root_std, support_gap, local_density, nn_dist],
        dtype=np.float32,
    )

# ============================================================
# Judges
# ============================================================
class LinearJudge(nn.Module):
    def __init__(self, in_dim):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, 32),
            nn.ReLU(),
            nn.Linear(32, 1),
        )

    def forward(self, x):
        return self.net(x).squeeze(-1)

class ContractiveRefiner(nn.Module):
    def __init__(self, dim):
        super().__init__()
        self.linear = nn.utils.spectral_norm(nn.Linear(dim, dim))
        self.gate = nn.Linear(dim, dim)
        self.alpha = 0.08

    def forward(self, x):
        g = torch.sigmoid(self.gate(x))
        delta = torch.tanh(self.linear(x))
        return x + self.alpha * g * delta

class LooseScrewJudge(nn.Module):
    """
    A small residual judge with a contractive refinement block.
    """
    def __init__(self, in_dim, hidden=64):
        super().__init__()
        self.inp = nn.Linear(in_dim, hidden)
        self.refine = ContractiveRefiner(hidden)
        self.mid = nn.Linear(hidden, hidden)
        self.out = nn.Linear(hidden, 1)

    def forward(self, x):
        h = torch.relu(self.inp(x))
        h = self.refine(h)
        h = torch.relu(self.mid(h))
        return self.out(h).squeeze(-1)

def train_binary_judge(model, X, y, epochs=14, lr=1e-3, batch_size=256):
    model = model.to(DEVICE)
    opt = torch.optim.Adam(model.parameters(), lr=lr)
    loss_fn = nn.BCEWithLogitsLoss()

    ds = TensorDataset(torch.tensor(X, dtype=torch.float32), torch.tensor(y, dtype=torch.float32))
    dl = DataLoader(ds, batch_size=batch_size, shuffle=True, drop_last=False)

    model.train()
    for _ in range(epochs):
        for xb, yb in dl:
            xb = xb.to(DEVICE)
            yb = yb.to(DEVICE)
            opt.zero_grad()
            logits = model(xb)
            loss = loss_fn(logits, yb)
            loss.backward()
            opt.step()
    model.eval()
    return model

def score_judge(model, feats):
    if model is None or len(feats) == 0:
        return None
    with torch.no_grad():
        xb = torch.tensor(feats, dtype=torch.float32, device=DEVICE)
        logits = model(xb)
        probs = torch.sigmoid(logits).detach().cpu().numpy()
    return probs

def selective_guard_decision(scores, margin_threshold=0.08):
    """
    scores: higher is better
    trust the judge only if top1 - top2 >= threshold
    """
    if len(scores) <= 1:
        return True
    sorted_scores = np.sort(scores)[::-1]
    margin = float(sorted_scores[0] - sorted_scores[1])
    return margin >= margin_threshold

# ============================================================
# Training data for judges
# ============================================================
def build_judge_training_data(
    train_ids,
    keys,
    roots_bank,
    Ps,
    positions,
    group_ids,
    query_noise,
    local_radius,
    topk_root,
    num_projections,
    samples_per_item,
    seed,
):
    rng = np.random.default_rng(seed + 4242)
    X = []
    y = []

    for i in train_ids:
        for _ in range(samples_per_item):
            q = normalize(keys[i] + query_noise * rng.normal(size=KEY_DIM))
            _, scores_bank = root_scores_for_query(q, Ps, roots_bank)

            anchor_sets = [topk_idx(scores_bank[p], topk_root) for p in range(num_projections)]
            cand_multi, _ = union_of_candidates(positions, anchor_sets, local_radius)

            if len(cand_multi) == 0:
                continue

            cand_list = cand_multi.tolist()
            if i not in cand_list:
                cand_list.append(int(i))
            cand_list = list(dict.fromkeys(cand_list))

            pos_feat = candidate_features(
                q, keys, i, scores_bank,
                positions=positions,
                candidate_center_idx=i,
                local_radius=local_radius,
            )
            X.append(pos_feat)
            y.append(1.0)

            negatives = [c for c in cand_list if c != i]
            if len(negatives) > 0:
                pick_n = min(NEG_PER_POS, len(negatives))
                neg_pick = rng.choice(negatives, size=pick_n, replace=False)
                for c in neg_pick:
                    feat = candidate_features(
                        q, keys, c, scores_bank,
                        positions=positions,
                        candidate_center_idx=c,
                        local_radius=local_radius,
                    )
                    X.append(feat)
                    y.append(0.0)

    if len(X) == 0:
        return np.zeros((0, 7), dtype=np.float32), np.zeros((0,), dtype=np.float32)

    return np.asarray(X, dtype=np.float32), np.asarray(y, dtype=np.float32)

# ============================================================
# Heuristic scores
# ============================================================
def score_single_root_rerank(feats):
    # simple, clean single-root rerank
    flat = feats[:, 0]
    root_mean = feats[:, 1]
    root_max = feats[:, 2]
    root_std = feats[:, 3]
    return flat + 0.25 * root_mean + 0.10 * root_max - 0.05 * root_std

def score_multi_root_rerank(feats):
    flat = feats[:, 0]
    root_mean = feats[:, 1]
    root_max = feats[:, 2]
    root_std = feats[:, 3]
    return flat + 0.25 * root_mean + 0.10 * root_max - 0.05 * root_std

def score_multi_root_mix(feats):
    flat = feats[:, 0]
    root_mean = feats[:, 1]
    root_max = feats[:, 2]
    root_std = feats[:, 3]
    support_gap = feats[:, 4]
    local_density = feats[:, 5]
    return flat + 0.18 * root_mean + 0.12 * root_max - 0.05 * root_std + 0.03 * support_gap + 0.02 * local_density

# ============================================================
# Evaluation case
# ============================================================
def evaluate_case(
    n_groups=64,
    group_size=4,
    placement="spiral",
    seed=0,
    root_dim=32,
    topk_root=5,
    num_projections=4,
    query_noise=0.25,
    local_radius=0.12,
    trials_per_item=3,
    train_per_group=3,
    train_judges=True,
):
    set_seed(seed)
    n_items = n_groups * group_size

    keys, values, group_ids = make_clustered_memory(
        n_groups=n_groups,
        group_size=group_size,
        key_dim=KEY_DIM,
        value_dim=VALUE_DIM,
        seed=seed,
        key_jitter=KEY_JITTER,
        value_jitter=VALUE_JITTER,
    )

    if placement == "spiral":
        positions = fermat_spiral_positions(n_items, radius=1.0)
    elif placement == "random":
        positions = random_disk_positions(n_items, seed=seed + 12345, radius=1.0)
    else:
        raise ValueError("placement must be 'spiral' or 'random'")

    Ps = build_projections(KEY_DIM, root_dim, num_projections, seed=seed)
    roots_bank = build_roots(keys, Ps)
    keys_norm = normalize(keys)

    train_ids, test_ids = split_by_group(group_ids, test_per_group=1, seed=seed)
    rng = np.random.default_rng(seed + 4242)

    X_train, y_train = build_judge_training_data(
        train_ids=train_ids,
        keys=keys,
        roots_bank=roots_bank,
        Ps=Ps,
        positions=positions,
        group_ids=group_ids,
        query_noise=query_noise,
        local_radius=local_radius,
        topk_root=topk_root,
        num_projections=num_projections,
        samples_per_item=train_per_group,
        seed=seed,
    )

    linear_judge = None
    loose_screw_judge = None

    if train_judges and len(X_train) > 0:
        linear_judge = LinearJudge(in_dim=X_train.shape[1]).to(DEVICE)
        loose_screw_judge = LooseScrewJudge(in_dim=X_train.shape[1]).to(DEVICE)

        linear_judge = train_binary_judge(
            linear_judge, X_train, y_train,
            epochs=EPOCHS, lr=LR, batch_size=BATCH_SIZE,
        )
        loose_screw_judge = train_binary_judge(
            loose_screw_judge, X_train, y_train,
            epochs=EPOCHS, lr=LR, batch_size=BATCH_SIZE,
        )

    modes = [
        "flat_key_nn",
        "passive_root_top1",
        "single_root_rerank",
        "multi_root_rerank",
        "multi_root_mix_rerank",
        "learned_linear_judge",
        "loose_screw_judge",
        "guarded_linear_judge",
        "guarded_loose_screw",
        "oracle_union",
    ]

    stats = {m: defaultdict(float) for m in modes}
    total = 0

    with torch.no_grad():
        for i in test_ids:
            true_group = int(group_ids[i])

            for _ in range(trials_per_item):
                q = normalize(keys[i] + query_noise * rng.normal(size=KEY_DIM))

                # Flat baseline over all items
                flat_scores = keys_norm @ q
                flat_pred = int(np.argmax(flat_scores))

                # Multi-root discovery
                _, scores_bank = root_scores_for_query(q, Ps, roots_bank)
                anchor_sets = [topk_idx(scores_bank[p], topk_root) for p in range(num_projections)]

                single_anchors = anchor_sets[0]
                multi_anchors = np.unique(np.concatenate(anchor_sets))
                cand_single = candidate_pool_from_anchors(positions, single_anchors, local_radius)
                cand_multi, _ = union_of_candidates(positions, anchor_sets, local_radius)

                # Root diagnostics
                root_top1 = int(np.argmax(scores_bank[0]))
                root_hit_top1 = int(root_top1 == i)
                root_hit_topk = int(i in set(multi_anchors.tolist()))

                # Passive root top1
                if len(cand_single) > 0:
                    pred_passive = int(cand_single[np.argmax(flat_scores[cand_single])])
                else:
                    pred_passive = flat_pred

                # Single-root rerank
                if len(cand_single) > 0:
                    feats_single = np.stack(
                        [
                            candidate_features(
                                q, keys, c, scores_bank[:1],
                                positions=positions,
                                candidate_center_idx=c,
                                local_radius=local_radius,
                            )
                            for c in cand_single
                        ],
                        axis=0,
                    )
                    s_single = score_single_root_rerank(feats_single)
                    pred_single = int(cand_single[int(np.argmax(s_single))])
                else:
                    pred_single = flat_pred

                # Multi-root rerank
                if len(cand_multi) > 0:
                    feats_multi = np.stack(
                        [
                            candidate_features(
                                q, keys, c, scores_bank,
                                positions=positions,
                                candidate_center_idx=c,
                                local_radius=local_radius,
                            )
                            for c in cand_multi
                        ],
                        axis=0,
                    )
                    s_multi = score_multi_root_rerank(feats_multi)
                    pred_multi = int(cand_multi[int(np.argmax(s_multi))])
                    s_mix = score_multi_root_mix(feats_multi)
                    pred_mix = int(cand_multi[int(np.argmax(s_mix))])
                else:
                    pred_multi = flat_pred
                    pred_mix = flat_pred

                # Learned linear judge
                if linear_judge is not None and len(cand_multi) > 0:
                    logits = score_judge(
                        linear_judge,
                        np.stack(
                            [
                                candidate_features(
                                    q, keys, c, scores_bank,
                                    positions=positions,
                                    candidate_center_idx=c,
                                    local_radius=local_radius,
                                )
                                for c in cand_multi
                            ],
                            axis=0,
                        ),
                    )
                    pred_linear = int(cand_multi[int(np.argmax(logits))])
                    linear_margin = float(np.sort(logits)[::-1][0] - np.sort(logits)[::-1][1]) if len(logits) > 1 else 1.0
                else:
                    pred_linear = pred_mix
                    linear_margin = 1.0

                # Loose-screw judge
                if loose_screw_judge is not None and len(cand_multi) > 0:
                    ls_logits = score_judge(
                        loose_screw_judge,
                        np.stack(
                            [
                                candidate_features(
                                    q, keys, c, scores_bank,
                                    positions=positions,
                                    candidate_center_idx=c,
                                    local_radius=local_radius,
                                )
                                for c in cand_multi
                            ],
                            axis=0,
                        ),
                    )
                    pred_ls = int(cand_multi[int(np.argmax(ls_logits))])
                    ls_margin = float(np.sort(ls_logits)[::-1][0] - np.sort(ls_logits)[::-1][1]) if len(ls_logits) > 1 else 1.0
                else:
                    pred_ls = pred_mix
                    ls_margin = 1.0

                # Selective guard:
                # trust the judge only when its own margin is high enough;
                # otherwise fall back to the best heuristic baseline.
                pred_guard_linear = pred_linear if selective_guard_decision(np.array([linear_margin, 0.0]), GUARD_MARGIN) else pred_mix
                pred_guard_ls = pred_ls if selective_guard_decision(np.array([ls_margin, 0.0]), GUARD_MARGIN) else pred_mix

                # Oracle ceiling for the candidate pool
                pred_oracle = i if i in set(cand_multi.tolist()) else pred_mix

                # Candidate coverage per mode
                coverage_single = int(i in set(cand_single.tolist())) if len(cand_single) > 0 else 0
                coverage_multi = int(i in set(cand_multi.tolist())) if len(cand_multi) > 0 else 0

                for mode, pred, cand, cov in [
                    ("flat_key_nn", flat_pred, np.arange(n_items), 1),
                    ("passive_root_top1", pred_passive, cand_single, coverage_single),
                    ("single_root_rerank", pred_single, cand_single, coverage_single),
                    ("multi_root_rerank", pred_multi, cand_multi, coverage_multi),
                    ("multi_root_mix_rerank", pred_mix, cand_multi, coverage_multi),
                    ("learned_linear_judge", pred_linear, cand_multi, coverage_multi),
                    ("loose_screw_judge", pred_ls, cand_multi, coverage_multi),
                    ("guarded_linear_judge", pred_guard_linear, cand_multi, coverage_multi),
                    ("guarded_loose_screw", pred_guard_ls, cand_multi, coverage_multi),
                    ("oracle_union", pred_oracle, cand_multi, coverage_multi),
                ]:
                    stats[mode]["item_hits"] += int(pred == i)
                    stats[mode]["group_hits"] += int(group_ids[pred] == true_group)
                    stats[mode]["root_hit_top1"] += root_hit_top1
                    stats[mode]["root_hit_topk"] += root_hit_topk
                    stats[mode]["candidate_coverage"] += cov
                    stats[mode]["candidate_size"] += len(cand)

                total += 1

    rows = []
    for mode in modes:
        rows.append({
            "placement": placement,
            "seed": seed,
            "n_groups": n_groups,
            "group_size": group_size,
            "root_dim": root_dim,
            "topk_root": topk_root,
            "num_projections": num_projections,
            "query_noise": query_noise,
            "local_radius": local_radius,
            "mode": mode,
            "item_acc": stats[mode]["item_hits"] / total,
            "group_acc": stats[mode]["group_hits"] / total,
            "root_hit_top1": stats[mode]["root_hit_top1"] / total,
            "root_hit_topk": stats[mode]["root_hit_topk"] / total,
            "candidate_coverage": stats[mode]["candidate_coverage"] / total,
            "avg_candidate_size": stats[mode]["candidate_size"] / total,
            "nn_dist": mean_nearest_neighbor_distance(positions),
            "interference": mean_interference_kernel(positions),
            "trained_judge": int(linear_judge is not None and loose_screw_judge is not None),
        })
    return rows

# ============================================================
# Summary helpers
# ============================================================
def summarize(df, group_cols, value_cols):
    agg = {}
    for c in value_cols:
        agg[f"{c}_mean"] = (c, "mean")
        agg[f"{c}_std"] = (c, "std")
    return df.groupby(group_cols, as_index=False).agg(**agg)

def gap_table(summary_df, group_cols, baseline_mode="flat_key_nn", hair_mode="multi_root_rerank", oracle_mode="oracle_union"):
    base = summary_df[summary_df["mode"] == baseline_mode][group_cols + ["item_acc_mean"]].rename(columns={"item_acc_mean": "baseline"})
    hair = summary_df[summary_df["mode"] == hair_mode][group_cols + ["item_acc_mean"]].rename(columns={"item_acc_mean": "hair"})
    oracle = summary_df[summary_df["mode"] == oracle_mode][group_cols + ["item_acc_mean"]].rename(columns={"item_acc_mean": "oracle"})
    out = base.merge(hair, on=group_cols).merge(oracle, on=group_cols)
    out["hair_minus_baseline"] = out["hair"] - out["baseline"]
    out["oracle_minus_hair"] = out["oracle"] - out["hair"]
    out["oracle_minus_baseline"] = out["oracle"] - out["baseline"]
    return out

