# ============================================================
# MEMORY HAIR — PART 10
# Adaptive Shortlist Order Experiment
# ------------------------------------------------------------
# What this script answers:
#   1) Does adaptive shortlist ordering help close the gap?
#   2) Is fixed multi-root rerank still better than adaptive?
#   3) Does spiral still help once shortlist order is adaptive?
#   4) How much of the remaining gap is still oracle gap?
#
# Core idea:
#   Freeze the candidate generator, but let shortlist size change
#   based on root confidence (margin). Then compare:
#     - flat_key_nn
#     - passive_root_top1
#     - fixed_multi_root_rerank
#     - adaptive_shortlist_rerank
#     - adaptive_shortlist_mix
#     - oracle_fixed_union
#     - oracle_adaptive_union
#
# Adaptive policy:
#   root_margin >= t1 -> topk=1
#   root_margin >= t2 -> topk=3
#   root_margin >= t3 -> topk=5
#   else              -> topk=10
# ============================================================

import os
import random
from collections import defaultdict

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt

# ============================================================
# Config
# ============================================================
SEEDS = [11, 22, 33]
PLACEMENTS = ["spiral", "random"]

N_GROUPS = 64
GROUP_SIZE = 4
KEY_DIM = 64
VALUE_DIM = 64

ROOT_DIM = 32
NUM_PROJECTIONS = 4
BASE_TOPK = 5
LOCAL_RADIUS = 0.12

QUERY_NOISE = 0.25
KEY_JITTER = 0.12
VALUE_JITTER = 0.12

ROOT_DIMS = [8, 16, 32, 64]
TOPK_ROOTS = [1, 3, 5, 10]
NUM_PROJECTIONS_LIST = [1, 2, 4, 8]
QUERY_NOISES = [0.10, 0.20, 0.30, 0.40]
SCALE_GROUPS = [32, 64, 128]

ADAPTIVE_SCHEDULES = {
    "conservative": (0.12, 0.08, 0.04),
    "balanced": (0.10, 0.06, 0.03),
    "aggressive": (0.07, 0.04, 0.02),
}

OUTDIR = "memory_hair_part10_adaptive_shortlist"
os.makedirs(OUTDIR, exist_ok=True)

pd.set_option("display.max_columns", 300)
pd.set_option("display.width", 240)

print("Artifacts:", OUTDIR)

# ============================================================
# Repro / math
# ============================================================
def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)

def normalize(x, axis=-1, eps=1e-9):
    x = np.asarray(x, dtype=np.float64)
    n = np.linalg.norm(x, axis=axis, keepdims=True)
    return x / (n + eps)

def topk_idx(scores, k):
    k = min(int(k), len(scores))
    if k <= 0:
        return np.array([], dtype=int)
    idx = np.argpartition(scores, -k)[-k:]
    return idx[np.argsort(scores[idx])[::-1]]

def summarize(df, group_cols, value_cols):
    agg = {}
    for c in value_cols:
        agg[f"{c}_mean"] = (c, "mean")
        agg[f"{c}_std"] = (c, "std")
    return df.groupby(group_cols, as_index=False).agg(**agg)

# ============================================================
# Geometry
# ============================================================
def fermat_spiral_positions(n, radius=1.0):
    golden_angle = np.pi * (3.0 - np.sqrt(5.0))
    i = np.arange(n)
    r = radius * np.sqrt((i + 0.5) / n)
    theta = i * golden_angle
    x = r * np.cos(theta)
    y = r * np.sin(theta)
    return np.stack([x, y], axis=1)

def random_disk_positions(n, seed=0, radius=1.0):
    rng = np.random.default_rng(seed)
    r = radius * np.sqrt(rng.random(n))
    theta = 2.0 * np.pi * rng.random(n)
    x = r * np.cos(theta)
    y = r * np.sin(theta)
    return np.stack([x, y], axis=1)

def mean_nearest_neighbor_distance(pos):
    d = pos[:, None, :] - pos[None, :, :]
    dist = np.sqrt((d ** 2).sum(-1))
    np.fill_diagonal(dist, np.inf)
    return float(dist.min(axis=1).mean())

def mean_interference_kernel(pos, sigma=0.18):
    d = pos[:, None, :] - pos[None, :, :]
    dist2 = (d ** 2).sum(-1)
    W = np.exp(-dist2 / (2.0 * sigma ** 2))
    np.fill_diagonal(W, 0.0)
    return float(W.mean())

def union_radius_neighbors(positions, centers, radius):
    centers = np.asarray(centers, dtype=int)
    if len(centers) == 0:
        return np.array([], dtype=int)
    diff = positions[:, None, :] - positions[centers][None, :, :]
    d2 = np.sum(diff ** 2, axis=2)
    mask = np.any(d2 <= radius ** 2, axis=1)
    idx = np.where(mask)[0]
    if len(idx) == 0:
        idx = np.array([int(centers[0])], dtype=int)
    return idx

# ============================================================
# Synthetic memory
# ============================================================
def make_clustered_memory(
    n_groups,
    group_size,
    key_dim,
    value_dim,
    seed=0,
    key_jitter=0.12,
    value_jitter=0.12,
):
    rng = np.random.default_rng(seed)
    keys = []
    values = []
    group_ids = []

    key_centers = normalize(rng.normal(size=(n_groups, key_dim)))
    value_centers = normalize(rng.normal(size=(n_groups, value_dim)))

    for g in range(n_groups):
        for _ in range(group_size):
            k = normalize(key_centers[g] + key_jitter * rng.normal(size=key_dim))
            v = normalize(value_centers[g] + value_jitter * rng.normal(size=value_dim))
            keys.append(k)
            values.append(v)
            group_ids.append(g)

    return np.stack(keys), np.stack(values), np.array(group_ids, dtype=int)

# ============================================================
# Projections / roots
# ============================================================
def build_projections(key_dim, root_dim, num_projections, seed=0):
    rng = np.random.default_rng(seed + 999)
    Ps = []
    for _ in range(num_projections):
        P = rng.normal(size=(root_dim, key_dim)) / np.sqrt(key_dim)
        Ps.append(P)
    return Ps

def build_roots(keys, Ps):
    roots = []
    for P in Ps:
        roots.append(normalize(keys @ P.T))
    return roots

def root_scores_for_query(query, Ps, roots_bank):
    qroots = []
    scores_bank = []
    for P, roots in zip(Ps, roots_bank):
        qroot = normalize(query @ P.T)
        scores = roots @ qroot
        qroots.append(qroot)
        scores_bank.append(scores)
    return qroots, scores_bank

def root_margin_confidence(scores_bank):
    margins = []
    for scores in scores_bank:
        if len(scores) < 2:
            margins.append(0.0)
            continue
        s = np.sort(scores)[::-1]
        margins.append(float(s[0] - s[1]))
    return float(np.mean(margins))

def choose_shortlist_k(root_margin, thresholds):
    t1, t2, t3 = thresholds
    if root_margin >= t1:
        return 1
    if root_margin >= t2:
        return 3
    if root_margin >= t3:
        return 5
    return 10

# ============================================================
# Candidate scoring
# ============================================================
def candidate_features(query, keys, candidate_idx, scores_bank, positions=None, candidate_center_idx=None, local_radius=0.12):
    q = normalize(query)
    cand = keys[candidate_idx]
    flat = float(cand @ q)

    root_supports = np.array([sb[candidate_idx] for sb in scores_bank], dtype=np.float64)
    root_mean = float(root_supports.mean())
    root_max = float(root_supports.max())
    root_std = float(root_supports.std())
    support_gap = float(root_max - root_mean)

    if positions is not None and candidate_center_idx is not None:
        d2 = np.sum((positions - positions[candidate_center_idx]) ** 2, axis=1)
        d2_sorted = np.sort(d2)
        nn_dist = float(np.sqrt(d2_sorted[1])) if len(d2_sorted) > 1 else 0.0
        local_density = float(np.mean(d2 <= local_radius ** 2))
    else:
        nn_dist = 0.0
        local_density = 0.0

    return np.array(
        [flat, root_mean, root_max, root_std, support_gap, local_density, nn_dist],
        dtype=np.float32,
    )

def score_rerank(feats):
    flat = feats[:, 0]
    root_mean = feats[:, 1]
    root_max = feats[:, 2]
    root_std = feats[:, 3]
    return flat + 0.25 * root_mean + 0.10 * root_max - 0.05 * root_std

def score_mix(feats):
    flat = feats[:, 0]
    root_mean = feats[:, 1]
    root_max = feats[:, 2]
    root_std = feats[:, 3]
    support_gap = feats[:, 4]
    local_density = feats[:, 5]
    return flat + 0.18 * root_mean + 0.12 * root_max - 0.05 * root_std + 0.03 * support_gap + 0.02 * local_density

# ============================================================
# Candidate pools
# ============================================================
def candidate_pool_from_anchors(positions, anchor_idx, radius):
    return union_radius_neighbors(positions, anchor_idx, radius)

def union_of_candidates(positions, anchor_sets, radius):
    if len(anchor_sets) == 0:
        return np.array([], dtype=int), np.array([], dtype=int)
    all_anchors = np.unique(np.concatenate(anchor_sets))
    cand = candidate_pool_from_anchors(positions, all_anchors, radius)
    return cand, all_anchors

# ============================================================
# Main evaluator
# ============================================================
def evaluate_case(
    n_groups=64,
    group_size=4,
    placement="spiral",
    seed=0,
    root_dim=32,
    base_topk=5,
    num_projections=4,
    query_noise=0.25,
    local_radius=0.12,
    shortlist_schedule_name="balanced",
    trials_per_item=3,
):
    set_seed(seed)
    n_items = n_groups * group_size

    keys, values, group_ids = make_clustered_memory(
        n_groups=n_groups,
        group_size=group_size,
        key_dim=KEY_DIM,
        value_dim=VALUE_DIM,
        seed=seed,
        key_jitter=KEY_JITTER,
        value_jitter=VALUE_JITTER,
    )

    if placement == "spiral":
        positions = fermat_spiral_positions(n_items, radius=1.0)
    elif placement == "random":
        positions = random_disk_positions(n_items, seed=seed + 12345, radius=1.0)
    else:
        raise ValueError("placement must be 'spiral' or 'random'")

    Ps = build_projections(KEY_DIM, root_dim, num_projections, seed=seed)
    roots_bank = build_roots(keys, Ps)
    keys_norm = normalize(keys)
    rng = np.random.default_rng(seed + 4242)

    thresholds = ADAPTIVE_SCHEDULES[shortlist_schedule_name]

    modes = [
        "flat_key_nn",
        "passive_root_top1",
        "fixed_multi_root_rerank",
        "adaptive_shortlist_rerank",
        "adaptive_shortlist_mix",
        "oracle_fixed_union",
        "oracle_adaptive_union",
    ]

    stats = {m: defaultdict(float) for m in modes}

    for i in range(n_items):
        true_group = int(group_ids[i])

        for _ in range(trials_per_item):
            q = normalize(keys[i] + query_noise * rng.normal(size=KEY_DIM))
            flat_scores = keys_norm @ q
            flat_pred = int(np.argmax(flat_scores))

            _, scores_bank = root_scores_for_query(q, Ps, roots_bank)
            root_margin = root_margin_confidence(scores_bank)
            adapt_k = choose_shortlist_k(root_margin, thresholds)

            fixed_anchor_sets = [topk_idx(scores_bank[p], base_topk) for p in range(num_projections)]
            adapt_anchor_sets = [topk_idx(scores_bank[p], adapt_k) for p in range(num_projections)]

            single_anchors = fixed_anchor_sets[0]
            fixed_cand, fixed_all_anchors = union_of_candidates(positions, fixed_anchor_sets, local_radius)
            adapt_cand, adapt_all_anchors = union_of_candidates(positions, adapt_anchor_sets, local_radius)
            single_cand = candidate_pool_from_anchors(positions, single_anchors, local_radius)

            root_top1 = int(np.argmax(scores_bank[0]))
            root_hit_top1 = int(root_top1 == i)
            root_hit_topk_fixed = int(i in set(fixed_all_anchors.tolist()))
            root_hit_topk_adapt = int(i in set(adapt_all_anchors.tolist()))

            # Baseline: flat key NN
            pred_flat = flat_pred

            # Passive root top1: local pick around the first projection's top anchor
            if len(single_cand) > 0:
                pred_passive = int(single_cand[np.argmax(flat_scores[single_cand])])
            else:
                pred_passive = flat_pred

            # Fixed multi-root rerank
            if len(fixed_cand) > 0:
                feats_fixed = np.stack(
                    [
                        candidate_features(
                            q, keys, c, scores_bank,
                            positions=positions,
                            candidate_center_idx=c,
                            local_radius=local_radius,
                        )
                        for c in fixed_cand
                    ],
                    axis=0,
                )
                s_fixed = score_rerank(feats_fixed)
                pred_fixed = int(fixed_cand[int(np.argmax(s_fixed))])
                pred_fixed_oracle = i if i in set(fixed_cand.tolist()) else pred_fixed
            else:
                pred_fixed = flat_pred
                pred_fixed_oracle = flat_pred

            # Adaptive shortlist rerank
            if len(adapt_cand) > 0:
                feats_adapt = np.stack(
                    [
                        candidate_features(
                            q, keys, c, scores_bank,
                            positions=positions,
                            candidate_center_idx=c,
                            local_radius=local_radius,
                        )
                        for c in adapt_cand
                    ],
                    axis=0,
                )
                s_adapt = score_rerank(feats_adapt)
                pred_adapt = int(adapt_cand[int(np.argmax(s_adapt))])

                s_mix = score_mix(feats_adapt)
                pred_mix = int(adapt_cand[int(np.argmax(s_mix))])

                pred_adapt_oracle = i if i in set(adapt_cand.tolist()) else pred_adapt
            else:
                pred_adapt = flat_pred
                pred_mix = flat_pred
                pred_adapt_oracle = flat_pred

            # Metrics
            rows = [
                ("flat_key_nn", pred_flat, np.arange(n_items), 1, 0),
                ("passive_root_top1", pred_passive, single_cand, int(i in set(single_cand.tolist())) if len(single_cand) > 0 else 0, 1),
                ("fixed_multi_root_rerank", pred_fixed, fixed_cand, int(i in set(fixed_cand.tolist())) if len(fixed_cand) > 0 else 0, base_topk),
                ("adaptive_shortlist_rerank", pred_adapt, adapt_cand, int(i in set(adapt_cand.tolist())) if len(adapt_cand) > 0 else 0, adapt_k),
                ("adaptive_shortlist_mix", pred_mix, adapt_cand, int(i in set(adapt_cand.tolist())) if len(adapt_cand) > 0 else 0, adapt_k),
                ("oracle_fixed_union", pred_fixed_oracle, fixed_cand, int(i in set(fixed_cand.tolist())) if len(fixed_cand) > 0 else 0, base_topk),
                ("oracle_adaptive_union", pred_adapt_oracle, adapt_cand, int(i in set(adapt_cand.tolist())) if len(adapt_cand) > 0 else 0, adapt_k),
            ]

            for mode, pred, cand, cov, chosen_k in rows:
                stats[mode]["item_hits"] += int(pred == i)
                stats[mode]["group_hits"] += int(group_ids[pred] == true_group)
                stats[mode]["root_hit_top1"] += root_hit_top1
                stats[mode]["root_hit_topk_fixed"] += root_hit_topk_fixed
                stats[mode]["root_hit_topk_adapt"] += root_hit_topk_adapt
                stats[mode]["candidate_coverage"] += cov
                stats[mode]["candidate_size"] += len(cand)
                stats[mode]["shortlist_k"] += chosen_k
                stats[mode]["root_margin"] += root_margin

    total = n_items * trials_per_item
    rows = []
    for mode in modes:
        rows.append({
            "placement": placement,
            "seed": seed,
            "n_groups": n_groups,
            "group_size": group_size,
            "root_dim": root_dim,
            "base_topk": base_topk,
            "num_projections": num_projections,
            "query_noise": query_noise,
            "local_radius": local_radius,
            "shortlist_schedule": shortlist_schedule_name,
            "mode": mode,
            "item_acc": stats[mode]["item_hits"] / total,
            "group_acc": stats[mode]["group_hits"] / total,
            "root_hit_top1": stats[mode]["root_hit_top1"] / total,
            "root_hit_topk_fixed": stats[mode]["root_hit_topk_fixed"] / total,
            "root_hit_topk_adapt": stats[mode]["root_hit_topk_adapt"] / total,
            "candidate_coverage": stats[mode]["candidate_coverage"] / total,
            "avg_candidate_size": stats[mode]["candidate_size"] / total,
            "avg_shortlist_k": stats[mode]["shortlist_k"] / total,
            "avg_root_margin": stats[mode]["root_margin"] / total,
            "nn_dist": mean_nearest_neighbor_distance(positions),
            "interference": mean_interference_kernel(positions),
        })

    return rows

# ============================================================
# Gap helper
# ============================================================
def gap_table(summary_df, group_cols, baseline_mode="flat_key_nn", hair_mode="fixed_multi_root_rerank", oracle_mode="oracle_adaptive_union"):
    base = summary_df[summary_df["mode"] == baseline_mode][group_cols + ["item_acc_mean"]].rename(columns={"item_acc_mean": "baseline"})
    hair = summary_df[summary_df["mode"] == hair_mode][group_cols + ["item_acc_mean"]].rename(columns={"item_acc_mean": "hair"})
    oracle = summary_df[summary_df["mode"] == oracle_mode][group_cols + ["item_acc_mean"]].rename(columns={"item_acc_mean": "oracle"})
    out = base.merge(hair, on=group_cols).merge(oracle, on=group_cols)
    out["hair_minus_baseline"] = out["hair"] - out["baseline"]
    out["oracle_minus_hair"] = out["oracle"] - out["hair"]
    out["oracle_minus_baseline"] = out["oracle"] - out["baseline"]
    return out

# ============================================================
# Run main benchmark across schedules
# ============================================================
MAIN_OP = dict(
    n_groups=N_GROUPS,
    group_size=GROUP_SIZE,
    root_dim=ROOT_DIM,
    base_topk=BASE_TOPK,
    num_projections=NUM_PROJECTIONS,
    query_noise=QUERY_NOISE,
    local_radius=LOCAL_RADIUS,
)

print("\nRunning main benchmark across shortlist schedules...\n")
main_rows = []
for placement in PLACEMENTS:
    for seed in SEEDS:
        for schedule_name in ADAPTIVE_SCHEDULES.keys():
            main_rows.extend(
                evaluate_case(
                    placement=placement,
                    seed=seed,
                    shortlist_schedule_name=schedule_name,
                    trials_per_item=3,
                    **MAIN_OP,
                )
            )

main_df = pd.DataFrame(main_rows)

value_cols = [
    "item_acc",
    "group_acc",
    "candidate_coverage",
    "avg_candidate_size",
    "avg_shortlist_k",
    "root_hit_top1",
    "root_hit_topk_fixed",
    "root_hit_topk_adapt",
    "avg_root_margin",
    "nn_dist",
    "interference",
]

main_agg = summarize(main_df, ["placement", "shortlist_schedule", "mode"], value_cols)

# Pick best schedule per placement from adaptive shortlist rerank
best_schedule_by_placement = {}
for placement in PLACEMENTS:
    sub = main_agg[
        (main_agg["placement"] == placement) &
        (main_agg["mode"] == "adaptive_shortlist_rerank")
    ].copy()
    best = sub.sort_values("item_acc_mean", ascending=False).iloc[0]
    best_schedule_by_placement[placement] = best["shortlist_schedule"]

print("\n=== Main comparison ===")
print(
    main_agg[main_agg["shortlist_schedule"].isin(ADAPTIVE_SCHEDULES.keys())][[
        "placement", "shortlist_schedule", "mode",
        "item_acc_mean", "group_acc_mean",
        "candidate_coverage_mean", "avg_candidate_size_mean",
        "avg_shortlist_k_mean", "avg_root_margin_mean",
    ]]
    .sort_values(["placement", "shortlist_schedule", "item_acc_mean"], ascending=[True, True, False])
    .to_string(index=False)
)

print("\n=== Best adaptive schedule per placement ===")
for placement, sch in best_schedule_by_placement.items():
    best_row = main_agg[
        (main_agg["placement"] == placement) &
        (main_agg["shortlist_schedule"] == sch) &
        (main_agg["mode"] == "adaptive_shortlist_rerank")
    ].iloc[0]
    print(
        f"{placement}: {sch} | item_acc={best_row['item_acc_mean']:.4f} | "
        f"coverage={best_row['candidate_coverage_mean']:.4f} | "
        f"avg_k={best_row['avg_shortlist_k_mean']:.2f}"
    )

main_gap_fixed = gap_table(
    main_agg[main_agg["shortlist_schedule"] == "balanced"].copy(),
    ["placement", "shortlist_schedule"],
    baseline_mode="flat_key_nn",
    hair_mode="fixed_multi_root_rerank",
    oracle_mode="oracle_fixed_union",
)

main_gap_adapt = gap_table(
    main_agg[main_agg["shortlist_schedule"] == "balanced"].copy(),
    ["placement", "shortlist_schedule"],
    baseline_mode="flat_key_nn",
    hair_mode="adaptive_shortlist_rerank",
    oracle_mode="oracle_adaptive_union",
)

print("\n=== Gap vs flat_key_nn and oracle (fixed pool, balanced schedule only) ===")
print(
    main_gap_fixed[[
        "placement", "shortlist_schedule",
        "baseline", "hair", "oracle",
        "hair_minus_baseline", "oracle_minus_hair", "oracle_minus_baseline",
    ]].to_string(index=False)
)

print("\n=== Gap vs flat_key_nn and oracle (adaptive pool, balanced schedule only) ===")
print(
    main_gap_adapt[[
        "placement", "shortlist_schedule",
        "baseline", "hair", "oracle",
        "hair_minus_baseline", "oracle_minus_hair", "oracle_minus_baseline",
    ]].to_string(index=False)
)

# ============================================================
# Sweeps using the best schedule per placement
# ============================================================
def run_sweep_root_dim(best_schedule_by_placement):
    rows = []
    for placement in PLACEMENTS:
        sch = best_schedule_by_placement[placement]
        for seed in SEEDS:
            for rd in ROOT_DIMS:
                rows.extend(
                    evaluate_case(
                        placement=placement,
                        seed=seed,
                        root_dim=rd,
                        base_topk=BASE_TOPK,
                        num_projections=NUM_PROJECTIONS,
                        query_noise=QUERY_NOISE,
                        local_radius=LOCAL_RADIUS,
                        shortlist_schedule_name=sch,
                        trials_per_item=3,
                        n_groups=N_GROUPS,
                        group_size=GROUP_SIZE,
                    )
                )
    return pd.DataFrame(rows)

