# ============================================================
# MEMORY HAIR — PART 12
# Separate Idea Tests on the Same Adaptive Pool
# ------------------------------------------------------------
# What this script answers:
#   1) Does iterative refinement help on the shortlist?
#   2) Does applying Loose-Screw directly to vectors help?
#   3) Does a stronger learned judge help if trained on the same pool?
#   4) Does guarding the judge improve robustness?
#   5) Which shortlist settings matter most?
#
# Main principle:
#   Keep the candidate pool fixed and test each idea separately.
#   That way every gain/loss is attributable to one change.
#
# Tested ideas (separate modes):
#   - flat_key_nn
#   - passive_root_top1
#   - fixed_multi_root_rerank
#   - adaptive_shortlist_rerank
#   - loose_screw_vector_rerank
#   - iterative_refine_1step
#   - iterative_refine_2step
#   - learned_linear_judge
#   - learned_mlp_judge
#   - pairwise_mlp_judge
#   - guarded_linear_judge
#   - guarded_mlp_judge
#   - guarded_pairwise_judge
#   - oracle_fixed_union
#   - oracle_adaptive_union
#
# Notes:
#   - Uses 3 seeds.
#   - Prints only the important summaries.
#   - Saves CSVs so you can inspect later.
# ============================================================

import os
import random
from collections import defaultdict
from dataclasses import dataclass

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import torch
import torch.nn as nn
from torch.utils.data import DataLoader, TensorDataset

# ============================================================
# Config
# ============================================================
SEEDS = [11, 22, 33]
PLACEMENTS = ["spiral", "random"]
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")

# Memory size
N_GROUPS = 64
GROUP_SIZE = 4
KEY_DIM = 64
VALUE_DIM = 64

# Candidate discovery default (main op)
ROOT_DIM = 32
TOPK_ROOT = 5
NUM_PROJECTIONS = 4
LOCAL_RADIUS = 0.12
QUERY_NOISE = 0.25
KEY_JITTER = 0.12
VALUE_JITTER = 0.12

# Adaptive shortlist schedules to test
SHORTLIST_SCHEDULES = {
    "aggressive": {"thresholds": (-1.0, 0.02, 0.05), "ks": (1, 3, 5, 8)},
    "balanced": {"thresholds": (0.03, 0.06, 0.10), "ks": (1, 3, 5, 8)},
    "conservative": {"thresholds": (0.05, 0.09, 0.14), "ks": (1, 3, 5, 10)},
}

# Guard / refinement
GUARD_MARGIN = 0.08
REFINE_ALPHA = 0.18
REFINE_STEPS = [1, 2]

# Sweep values
ROOT_DIMS = [8, 16, 32, 64]
TOPK_ROOTS = [1, 3, 5, 10]
NUM_PROJECTIONS_LIST = [1, 2, 4, 8]
QUERY_NOISES = [0.10, 0.20, 0.30, 0.40]
LOCAL_RADII = [0.08, 0.10, 0.12, 0.14]
GUARD_MARGINS = [0.02, 0.05, 0.08, 0.12]
REFINE_ALPHAS = [0.06, 0.10, 0.14, 0.18, 0.24]
SCALE_GROUPS = [32, 64, 128]

# Training settings
TRAIN_PER_GROUP = 3
NEG_PER_POS = 6
BATCH_SIZE = 256
EPOCHS = 14
LR = 1e-3

OUTDIR = "memory_hair_part12_separate_ideas"
os.makedirs(OUTDIR, exist_ok=True)

pd.set_option("display.max_columns", 300)
pd.set_option("display.width", 240)
print("Device:", DEVICE)
print("Artifacts:", OUTDIR)

# ============================================================
# Repro
# ============================================================
def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

# ============================================================
# Math helpers
# ============================================================
def normalize(x, axis=-1, eps=1e-9):
    x = np.asarray(x, dtype=np.float64)
    n = np.linalg.norm(x, axis=axis, keepdims=True)
    return x / (n + eps)


def topk_idx(scores, k):
    k = min(int(k), len(scores))
    if k <= 0:
        return np.array([], dtype=int)
    idx = np.argpartition(scores, -k)[-k:]
    return idx[np.argsort(scores[idx])[::-1]]


def sigmoid_np(x):
    x = np.asarray(x, dtype=np.float64)
    return 1.0 / (1.0 + np.exp(-x))

# ============================================================
# Geometry / placement
# ============================================================
def fermat_spiral_positions(n, radius=1.0):
    golden_angle = np.pi * (3.0 - np.sqrt(5.0))
    i = np.arange(n)
    r = radius * np.sqrt((i + 0.5) / n)
    theta = i * golden_angle
    x = r * np.cos(theta)
    y = r * np.sin(theta)
    return np.stack([x, y], axis=1)


def random_disk_positions(n, seed=0, radius=1.0):
    rng = np.random.default_rng(seed)
    r = radius * np.sqrt(rng.random(n))
    theta = 2.0 * np.pi * rng.random(n)
    x = r * np.cos(theta)
    y = r * np.sin(theta)
    return np.stack([x, y], axis=1)


def mean_nearest_neighbor_distance(pos):
    d = pos[:, None, :] - pos[None, :, :]
    dist = np.sqrt((d ** 2).sum(-1))
    np.fill_diagonal(dist, np.inf)
    return float(dist.min(axis=1).mean())


def mean_interference_kernel(pos, sigma=0.18):
    d = pos[:, None, :] - pos[None, :, :]
    dist2 = (d ** 2).sum(-1)
    W = np.exp(-dist2 / (2.0 * sigma ** 2))
    np.fill_diagonal(W, 0.0)
    return float(W.mean())


def union_radius_neighbors(positions, centers, radius):
    centers = np.asarray(centers, dtype=int)
    if len(centers) == 0:
        return np.array([], dtype=int)
    diff = positions[:, None, :] - positions[centers][None, :, :]
    d2 = np.sum(diff ** 2, axis=2)
    mask = np.any(d2 <= radius ** 2, axis=1)
    idx = np.where(mask)[0]
    if len(idx) == 0:
        idx = np.array([int(centers[0])], dtype=int)
    return idx

# ============================================================
# Synthetic clustered memory
# ============================================================
def make_clustered_memory(n_groups, group_size, key_dim, value_dim, seed=0, key_jitter=0.12, value_jitter=0.12):
    rng = np.random.default_rng(seed)
    keys = []
    values = []
    group_ids = []

    key_centers = normalize(rng.normal(size=(n_groups, key_dim)))
    value_centers = normalize(rng.normal(size=(n_groups, value_dim)))

    for g in range(n_groups):
        for _ in range(group_size):
            k = normalize(key_centers[g] + key_jitter * rng.normal(size=key_dim))
            v = normalize(value_centers[g] + value_jitter * rng.normal(size=value_dim))
            keys.append(k)
            values.append(v)
            group_ids.append(g)

    return np.stack(keys), np.stack(values), np.array(group_ids, dtype=int)


def split_by_group(group_ids, test_per_group=1, seed=0):
    rng = np.random.default_rng(seed)
    train_ids = []
    test_ids = []

    for g in np.unique(group_ids):
        idx = np.where(group_ids == g)[0]
        if len(idx) <= test_per_group:
            raise ValueError(f"Group {g} too small for split.")
        test_sel = rng.choice(idx, size=test_per_group, replace=False)
        test_set = set(test_sel.tolist())
        train_sel = np.array([i for i in idx if i not in test_set], dtype=int)
        train_ids.extend(train_sel.tolist())
        test_ids.extend(test_sel.tolist())

    return np.array(train_ids, dtype=int), np.array(test_ids, dtype=int)

# ============================================================
# Projections / roots
# ============================================================
def build_projections(key_dim, root_dim, num_projections, seed=0):
    rng = np.random.default_rng(seed + 999)
    Ps = []
    for _ in range(num_projections):
        P = rng.normal(size=(root_dim, key_dim)) / np.sqrt(key_dim)
        Ps.append(P)
    return Ps


def build_roots(keys, Ps):
    roots = []
    for P in Ps:
        roots.append(normalize(keys @ P.T))
    return roots


def root_scores_for_query(query, Ps, roots_bank):
    qroots = []
    scores_bank = []
    for P, roots in zip(Ps, roots_bank):
        qroot = normalize(query @ P.T)
        scores = roots @ qroot
        qroots.append(qroot)
        scores_bank.append(scores)
    return qroots, scores_bank

# ============================================================
# Candidate pools
# ============================================================
def candidate_pool_from_anchors(positions, anchor_idx, radius):
    return union_radius_neighbors(positions, anchor_idx, radius)


def union_of_candidates(positions, anchor_sets, radius):
    if len(anchor_sets) == 0:
        return np.array([], dtype=int), np.array([], dtype=int)
    all_anchors = np.unique(np.concatenate(anchor_sets))
    cand = candidate_pool_from_anchors(positions, all_anchors, radius)
    return cand, all_anchors


def adaptive_shortlist_size(root_scores, schedule_name="conservative"):
    """
    Choose shortlist k from the root margin.
    margin = top1 - top2.
    """
    thresholds = SHORTLIST_SCHEDULES[schedule_name]["thresholds"]
    ks = SHORTLIST_SCHEDULES[schedule_name]["ks"]
    if len(root_scores) <= 1:
        return ks[0]
    s = np.sort(root_scores)[::-1]
    margin = float(s[0] - s[1])
    if margin < thresholds[0]:
        return ks[-1]
    if margin < thresholds[1]:
        return ks[-2]
    if margin < thresholds[2]:
        return ks[1]
    return ks[0]

# ============================================================
# Candidate features and vector transforms
# ============================================================
def candidate_features(query, keys, candidate_idx, scores_bank, positions=None, candidate_center_idx=None, local_radius=0.12):
    q = normalize(query)
    cand = keys[candidate_idx]
    flat = float(cand @ q)

    root_supports = np.array([sb[candidate_idx] for sb in scores_bank], dtype=np.float64)
    root_mean = float(root_supports.mean())
    root_max = float(root_supports.max())
    root_std = float(root_supports.std())
    support_gap = float(root_max - root_mean)

    if positions is not None and candidate_center_idx is not None:
        d2 = np.sum((positions - positions[candidate_center_idx]) ** 2, axis=1)
        d2_sorted = np.sort(d2)
        nn_dist = float(np.sqrt(d2_sorted[1])) if len(d2_sorted) > 1 else 0.0
        local_density = float(np.mean(d2 <= local_radius ** 2))
    else:
        nn_dist = 0.0
        local_density = 0.0

    return np.array([flat, root_mean, root_max, root_std, support_gap, local_density, nn_dist], dtype=np.float32)


def loose_screw_vector(x, alpha=0.18, gate_bias=0.35, gate_scale=1.25):
    """
    Deterministic Loose-Screw style vector refinement.
    Keeps a clean path while preserving weak but potentially useful signal.
    """
    x = np.asarray(x, dtype=np.float64)
    clean = np.tanh(x)
    gate = sigmoid_np(gate_scale * (np.abs(x) - gate_bias))
    leak = gate * np.tanh(1.5 * x)
    out = (1.0 - alpha) * clean + alpha * leak
    return normalize(out)


def refine_query_iterative(query, candidate_vec, steps=1, alpha=0.18):
    q = normalize(query)
    v = normalize(candidate_vec)
    for _ in range(int(steps)):
        q = normalize(q + alpha * v)
    return q

# ============================================================
# Judges
# ============================================================
class LinearJudge(nn.Module):
    def __init__(self, in_dim):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, 32),
            nn.ReLU(),
            nn.Linear(32, 1),
        )

    def forward(self, x):
        return self.net(x).squeeze(-1)


class MLPJudge(nn.Module):
    def __init__(self, in_dim, hidden=64):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.ReLU(),
            nn.Linear(hidden, hidden),
            nn.ReLU(),
            nn.Linear(hidden, 1),
        )

    def forward(self, x):
        return self.net(x).squeeze(-1)


class PairwiseJudge(nn.Module):
    def __init__(self, in_dim, hidden=64):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.ReLU(),
            nn.Linear(hidden, hidden),
            nn.ReLU(),
            nn.Linear(hidden, 1),
        )

    def forward(self, x):
        return self.net(x).squeeze(-1)


def train_binary_judge(model, X, y, epochs=14, lr=1e-3, batch_size=256):
    model = model.to(DEVICE)
    opt = torch.optim.Adam(model.parameters(), lr=lr)
    loss_fn = nn.BCEWithLogitsLoss()

    ds = TensorDataset(torch.tensor(X, dtype=torch.float32), torch.tensor(y, dtype=torch.float32))
    dl = DataLoader(ds, batch_size=batch_size, shuffle=True, drop_last=False)

    model.train()
    for _ in range(epochs):
        for xb, yb in dl:
            xb = xb.to(DEVICE)
            yb = yb.to(DEVICE)
            opt.zero_grad()
            logits = model(xb)
            loss = loss_fn(logits, yb)
            loss.backward()
            opt.step()
    model.eval()
    return model


def train_pairwise_judge(model, pair_X, pair_y, epochs=14, lr=1e-3, batch_size=256):
    """
    pair_X: concatenated positive and negative features? Here we use one row per pair.
    pair_y: 1 if first item should rank above second, else 0.
    This trains a score model using a simple pairwise hinge / logistic-like setup.
    """
    model = model.to(DEVICE)
    opt = torch.optim.Adam(model.parameters(), lr=lr)
    loss_fn = nn.BCEWithLogitsLoss()

    ds = TensorDataset(torch.tensor(pair_X, dtype=torch.float32), torch.tensor(pair_y, dtype=torch.float32))
    dl = DataLoader(ds, batch_size=batch_size, shuffle=True, drop_last=False)

    model.train()
    for _ in range(epochs):
        for xb, yb in dl:
            xb = xb.to(DEVICE)
            yb = yb.to(DEVICE)
            opt.zero_grad()
            logits = model(xb)
            loss = loss_fn(logits, yb)
            loss.backward()
            opt.step()
    model.eval()
    return model


def score_model(model, feats):
    if model is None or len(feats) == 0:
        return None
    with torch.no_grad():
        xb = torch.tensor(feats, dtype=torch.float32, device=DEVICE)
        logits = model(xb)
        probs = torch.sigmoid(logits).detach().cpu().numpy()
    return probs


def selective_guard_decision(scores, margin_threshold=0.08):
    if len(scores) <= 1:
        return True
    sorted_scores = np.sort(scores)[::-1]
    margin = float(sorted_scores[0] - sorted_scores[1])
    return margin >= margin_threshold

# ============================================================
# Training data
# ============================================================
def build_binary_training_data(
    train_ids,
    keys,
    roots_bank,
    Ps,
    positions,
    query_noise,
    local_radius,
    topk_root,
    num_projections,
    samples_per_item,
    seed,
    schedule_name="conservative",
):
    rng = np.random.default_rng(seed + 4242)
    X = []
    y = []

    for i in train_ids:
        for _ in range(samples_per_item):
            q = normalize(keys[i] + query_noise * rng.normal(size=KEY_DIM))
            _, scores_bank = root_scores_for_query(q, Ps, roots_bank)

            anchor_sets = []
            for p in range(num_projections):
                root_scores = scores_bank[p]
                if schedule_name is None:
                    tk = topk_root
                else:
                    tk = adaptive_shortlist_size(root_scores, schedule_name=schedule_name)
                anchor_sets.append(topk_idx(root_scores, tk))

            cand_multi, _ = union_of_candidates(positions, anchor_sets, local_radius)
            if len(cand_multi) == 0:
                continue

            cand_list = cand_multi.tolist()
            if i not in cand_list:
                cand_list.append(int(i))
            cand_list = list(dict.fromkeys(cand_list))

            X.append(candidate_features(q, keys, i, scores_bank, positions=positions, candidate_center_idx=i, local_radius=local_radius))
            y.append(1.0)

            negatives = [c for c in cand_list if c != i]
            if len(negatives) > 0:
                pick_n = min(NEG_PER_POS, len(negatives))
                neg_pick = rng.choice(negatives, size=pick_n, replace=False)
                for c in neg_pick:
                    X.append(candidate_features(q, keys, c, scores_bank, positions=positions, candidate_center_idx=c, local_radius=local_radius))
                    y.append(0.0)

    if len(X) == 0:
        return np.zeros((0, 7), dtype=np.float32), np.zeros((0,), dtype=np.float32)

    return np.asarray(X, dtype=np.float32), np.asarray(y, dtype=np.float32)


def build_pairwise_training_data(
    train_ids,
    keys,
    roots_bank,
    Ps,
    positions,
    query_noise,
    local_radius,
    topk_root,
    num_projections,
    samples_per_item,
    seed,
    schedule_name="conservative",
):
    rng = np.random.default_rng(seed + 7777)
    X = []
    y = []

    for i in train_ids:
        for _ in range(samples_per_item):
            q = normalize(keys[i] + query_noise * rng.normal(size=KEY_DIM))
            _, scores_bank = root_scores_for_query(q, Ps, roots_bank)
            anchor_sets = []
            for p in range(num_projections):
                root_scores = scores_bank[p]
                if schedule_name is None:
                    tk = topk_root
                else:
                    tk = adaptive_shortlist_size(root_scores, schedule_name=schedule_name)
                anchor_sets.append(topk_idx(root_scores, tk))
            cand_multi, _ = union_of_candidates(positions, anchor_sets, local_radius)
            if len(cand_multi) < 2:
                continue

            # pairwise samples: positive should outrank a few negatives
            negs = [c for c in cand_multi.tolist() if c != i]
            if len(negs) == 0:
                continue
            pair_n = min(NEG_PER_POS, len(negs))
            neg_pick = rng.choice(negs, size=pair_n, replace=False)
            pos_feat = candidate_features(q, keys, i, scores_bank, positions=positions, candidate_center_idx=i, local_radius=local_radius)
            for c in neg_pick:
                neg_feat = candidate_features(q, keys, c, scores_bank, positions=positions, candidate_center_idx=c, local_radius=local_radius)
                # We concatenate [pos, neg, diff, abs diff]
                feat = np.concatenate([pos_feat, neg_feat, pos_feat - neg_feat, np.abs(pos_feat - neg_feat)]).astype(np.float32)
                X.append(feat)
                y.append(1.0)
                # reverse pair as negative example
                feat2 = np.concatenate([neg_feat, pos_feat, neg_feat - pos_feat, np.abs(pos_feat - neg_feat)]).astype(np.float32)
                X.append(feat2)
                y.append(0.0)

    if len(X) == 0:
        return np.zeros((0, 28), dtype=np.float32), np.zeros((0,), dtype=np.float32)

    return np.asarray(X, dtype=np.float32), np.asarray(y, dtype=np.float32)

# ============================================================
# Scoring functions
# ============================================================
def score_heuristic(feats):
    flat = feats[:, 0]
    root_mean = feats[:, 1]
    root_max = feats[:, 2]
    root_std = feats[:, 3]
    return flat + 0.25 * root_mean + 0.10 * root_max - 0.05 * root_std


def score_mix(feats):
    flat = feats[:, 0]
    root_mean = feats[:, 1]
    root_max = feats[:, 2]
    root_std = feats[:, 3]
    support_gap = feats[:, 4]
    local_density = feats[:, 5]
    return flat + 0.18 * root_mean + 0.12 * root_max - 0.05 * root_std + 0.03 * support_gap + 0.02 * local_density


def score_loose_screw_vectors(query, candidate_keys, alpha=0.18):
    qf = loose_screw_vector(query, alpha=alpha)
    cf = loose_screw_vector(candidate_keys, alpha=alpha)
    return cf @ qf

# ============================================================
# Evaluation case
# ============================================================
def evaluate_case(
    n_groups=64,
    group_size=4,
    placement="spiral",
    seed=0,
    root_dim=32,
    topk_root=5,
    num_projections=4,
    query_noise=0.25,
    local_radius=0.12,
    shortlist_schedule="conservative",
    guard_margin=0.08,
    refine_alpha=0.18,
    trials_per_item=3,
    train_per_group=3,
    train_judges=True,
):
    set_seed(seed)
    n_items = n_groups * group_size

    keys, values, group_ids = make_clustered_memory(
        n_groups=n_groups,
        group_size=group_size,
        key_dim=KEY_DIM,
        value_dim=VALUE_DIM,
        seed=seed,
        key_jitter=KEY_JITTER,
        value_jitter=VALUE_JITTER,
    )

    if placement == "spiral":
        positions = fermat_spiral_positions(n_items, radius=1.0)
    elif placement == "random":
        positions = random_disk_positions(n_items, seed=seed + 12345, radius=1.0)
    else:
        raise ValueError("placement must be 'spiral' or 'random'")

    Ps = build_projections(KEY_DIM, root_dim, num_projections, seed=seed)
    roots_bank = build_roots(keys, Ps)
    keys_norm = normalize(keys)
    rng = np.random.default_rng(seed + 4242)

    train_ids, test_ids = split_by_group(group_ids, test_per_group=1, seed=seed)

    X_bin, y_bin = build_binary_training_data(
        train_ids=train_ids,
        keys=keys,
        roots_bank=roots_bank,
        Ps=Ps,
        positions=positions,
        query_noise=query_noise,
        local_radius=local_radius,
        topk_root=topk_root,
        num_projections=num_projections,
        samples_per_item=train_per_group,
        seed=seed,
        schedule_name=shortlist_schedule,
    )

    X_pair, y_pair = build_pairwise_training_data(
        train_ids=train_ids,
        keys=keys,
        roots_bank=roots_bank,
        Ps=Ps,
        positions=positions,
        query_noise=query_noise,
        local_radius=local_radius,
        topk_root=topk_root,
        num_projections=num_projections,
        samples_per_item=train_per_group,
        seed=seed,
        schedule_name=shortlist_schedule,
    )

    linear_judge = None
    mlp_judge = None
    pairwise_judge = None
    if train_judges and len(X_bin) > 0:
        linear_judge = train_binary_judge(LinearJudge(X_bin.shape[1]), X_bin, y_bin, epochs=EPOCHS, lr=LR, batch_size=BATCH_SIZE)
        mlp_judge = train_binary_judge(MLPJudge(X_bin.shape[1], hidden=64), X_bin, y_bin, epochs=EPOCHS, lr=LR, batch_size=BATCH_SIZE)
    if train_judges and len(X_pair) > 0:
        pairwise_judge = train_pairwise_judge(PairwiseJudge(X_pair.shape[1], hidden=64), X_pair, y_pair, epochs=EPOCHS, lr=LR, batch_size=BATCH_SIZE)

    modes = [
        "flat_key_nn",
        "passive_root_top1",
        "fixed_multi_root_rerank",
        "adaptive_shortlist_rerank",
        "adaptive_shortlist_mix",
        "loose_screw_vector_rerank",
        "iterative_refine_1step",
        "iterative_refine_2step",
        "learned_linear_judge",
        "learned_mlp_judge",
        "pairwise_mlp_judge",
        "guarded_linear_judge",
        "guarded_mlp_judge",
        "guarded_pairwise_judge",
        "oracle_fixed_union",
        "oracle_adaptive_union",
    ]

    stats = {m: defaultdict(float) for m in modes}
    total = 0

    with torch.no_grad():
        for i in test_ids:
            true_group = int(group_ids[i])
            for _ in range(trials_per_item):
                q = normalize(keys[i] + query_noise * rng.normal(size=KEY_DIM))
                flat_scores = keys_norm @ q
                flat_pred = int(np.argmax(flat_scores))

                _, scores_bank = root_scores_for_query(q, Ps, roots_bank)
                root_margin = float(np.sort(scores_bank[0])[::-1][0] - np.sort(scores_bank[0])[::-1][1]) if len(scores_bank[0]) > 1 else 1.0

                # fixed shortlist
                fixed_anchor_sets = [topk_idx(scores_bank[p], topk_root) for p in range(num_projections)]
                fixed_single_anchors = fixed_anchor_sets[0]
                fixed_multi_anchors = np.unique(np.concatenate(fixed_anchor_sets))
                cand_single = candidate_pool_from_anchors(positions, fixed_single_anchors, local_radius)
                cand_fixed = candidate_pool_from_anchors(positions, fixed_multi_anchors, local_radius)

                # adaptive shortlist
                adaptive_anchor_sets = []
                adaptive_ks = []
                for p in range(num_projections):
                    tk = adaptive_shortlist_size(scores_bank[p], schedule_name=shortlist_schedule)
                    adaptive_ks.append(int(tk))
                    adaptive_anchor_sets.append(topk_idx(scores_bank[p], tk))
                cand_adaptive, adaptive_anchors = union_of_candidates(positions, adaptive_anchor_sets, local_radius)
                adaptive_k_mean = float(np.mean(adaptive_ks)) if len(adaptive_ks) else 0.0

                # diagnostics
                root_top1 = int(np.argmax(scores_bank[0]))
                root_hit_top1 = int(root_top1 == i)
                root_hit_topk = int(i in set(fixed_multi_anchors.tolist()))
                cov_fixed = int(i in set(cand_fixed.tolist()))
                cov_adaptive = int(i in set(cand_adaptive.tolist()))

                # baseline: passive top1 inside single-root pool
                if len(cand_single) > 0:
                    pred_passive = int(cand_single[np.argmax(flat_scores[cand_single])])
                else:
                    pred_passive = flat_pred

                # fixed multi-root rerank
                if len(cand_fixed) > 0:
                    feats_fixed = np.stack([
                        candidate_features(q, keys, c, scores_bank, positions=positions, candidate_center_idx=c, local_radius=local_radius)
                        for c in cand_fixed
                    ], axis=0)
                    s_fixed = score_heuristic(feats_fixed)
                    pred_fixed = int(cand_fixed[int(np.argmax(s_fixed))])
                    s_mix = score_mix(feats_fixed)
                    pred_mix = int(cand_fixed[int(np.argmax(s_mix))])
                else:
                    pred_fixed = flat_pred
                    pred_mix = flat_pred

                # adaptive rerank on the adaptive pool
                if len(cand_adaptive) > 0:
                    feats_ad = np.stack([
                        candidate_features(q, keys, c, scores_bank, positions=positions, candidate_center_idx=c, local_radius=local_radius)
                        for c in cand_adaptive
                    ], axis=0)
                    s_ad = score_heuristic(feats_ad)
                    pred_adaptive = int(cand_adaptive[int(np.argmax(s_ad))])
                    s_ad_mix = score_mix(feats_ad)
                    pred_adaptive_mix = int(cand_adaptive[int(np.argmax(s_ad_mix))])
                else:
                    pred_adaptive = flat_pred
                    pred_adaptive_mix = flat_pred

                # Loose-screw directly on vectors
                if len(cand_adaptive) > 0:
                    q_ls = loose_screw_vector(q, alpha=refine_alpha)
                    cand_vecs_ls = loose_screw_vector(keys[cand_adaptive], alpha=refine_alpha)
                    s_ls_vec = cand_vecs_ls @ q_ls
                    pred_ls_vec = int(cand_adaptive[int(np.argmax(s_ls_vec))])
                else:
                    pred_ls_vec = flat_pred

                # Iterative query refinement on adaptive pool
                if len(cand_adaptive) > 0:
                    # step 1: use the strongest heuristic candidate as the refinement anchor
                    best_anchor = int(cand_adaptive[int(np.argmax(s_ad_mix))])
                    q1 = refine_query_iterative(q, keys[best_anchor], steps=1, alpha=refine_alpha)
                    s1 = keys[cand_adaptive] @ q1
                    pred_refine1 = int(cand_adaptive[int(np.argmax(s1))])

                    q2 = refine_query_iterative(q, keys[best_anchor], steps=2, alpha=refine_alpha)
                    s2 = keys[cand_adaptive] @ q2
                    pred_refine2 = int(cand_adaptive[int(np.argmax(s2))])
                else:
                    pred_refine1 = flat_pred
                    pred_refine2 = flat_pred

                # Learned judges on the same adaptive pool
                if linear_judge is not None and len(cand_adaptive) > 0:
                    feats = np.stack([
                        candidate_features(q, keys, c, scores_bank, positions=positions, candidate_center_idx=c, local_radius=local_radius)
                        for c in cand_adaptive
                    ], axis=0)
                    logits = score_model(linear_judge, feats)
                    pred_linear = int(cand_adaptive[int(np.argmax(logits))])
                    linear_margin = float(np.sort(logits)[::-1][0] - np.sort(logits)[::-1][1]) if len(logits) > 1 else 1.0
                else:
                    pred_linear = pred_adaptive_mix
                    linear_margin = 1.0

                if mlp_judge is not None and len(cand_adaptive) > 0:
                    feats = np.stack([
                        candidate_features(q, keys, c, scores_bank, positions=positions, candidate_center_idx=c, local_radius=local_radius)
                        for c in cand_adaptive
                    ], axis=0)
                    logits = score_model(mlp_judge, feats)
                    pred_mlp = int(cand_adaptive[int(np.argmax(logits))])
                    mlp_margin = float(np.sort(logits)[::-1][0] - np.sort(logits)[::-1][1]) if len(logits) > 1 else 1.0
                else:
                    pred_mlp = pred_adaptive_mix
                    mlp_margin = 1.0

                if pairwise_judge is not None and len(cand_adaptive) > 0:
                    feats = np.stack([
                        candidate_features(q, keys, c, scores_bank, positions=positions, candidate_center_idx=c, local_radius=local_radius)
                        for c in cand_adaptive
                    ], axis=0)
                    # pairwise model is trained on concatenated pairs; here we score by padding the candidate features with itself
                    # and using the learned scorer as a preference predictor for each candidate independently.
                    # We approximate independent scoring by using the candidate feature vector repeated.
                    pair_feats = np.concatenate([feats, feats, np.zeros_like(feats), np.abs(feats)], axis=1)
                    logits = score_model(pairwise_judge, pair_feats)
                    pred_pairwise = int(cand_adaptive[int(np.argmax(logits))])
                    pairwise_margin = float(np.sort(logits)[::-1][0] - np.sort(logits)[::-1][1]) if len(logits) > 1 else 1.0
                else:
                    pred_pairwise = pred_adaptive_mix
                    pairwise_margin = 1.0

                # Guarded versions: trust the learned judge only if its margin is strong enough.
                # Otherwise fall back to the stronger heuristic mix on the same pool.
                pred_guard_linear = pred_linear if selective_guard_decision(np.array([linear_margin, 0.0]), guard_margin) else pred_adaptive_mix
                pred_guard_mlp = pred_mlp if selective_guard_decision(np.array([mlp_margin, 0.0]), guard_margin) else pred_adaptive_mix
                pred_guard_pairwise = pred_pairwise if selective_guard_decision(np.array([pairwise_margin, 0.0]), guard_margin) else pred_adaptive_mix

                pred_oracle_fixed = i if i in set(cand_fixed.tolist()) else pred_fixed
                pred_oracle_adaptive = i if i in set(cand_adaptive.tolist()) else pred_adaptive_mix

                # Metrics
                for mode, pred, cand, cov in [
                    ("flat_key_nn", flat_pred, np.arange(n_items), 1),
                    ("passive_root_top1", pred_passive, cand_single, int(i in set(cand_single.tolist())) if len(cand_single) else 0),
                    ("fixed_multi_root_rerank", pred_fixed, cand_fixed, cov_fixed),
                    ("adaptive_shortlist_rerank", pred_adaptive, cand_adaptive, cov_adaptive),
                    ("adaptive_shortlist_mix", pred_adaptive_mix, cand_adaptive, cov_adaptive),
                    ("loose_screw_vector_rerank", pred_ls_vec, cand_adaptive, cov_adaptive),
                    ("iterative_refine_1step", pred_refine1, cand_adaptive, cov_adaptive),
                    ("iterative_refine_2step", pred_refine2, cand_adaptive, cov_adaptive),
                    ("learned_linear_judge", pred_linear, cand_adaptive, cov_adaptive),
                    ("learned_mlp_judge", pred_mlp, cand_adaptive, cov_adaptive),
                    ("pairwise_mlp_judge", pred_pairwise, cand_adaptive, cov_adaptive),
                    ("guarded_linear_judge", pred_guard_linear, cand_adaptive, cov_adaptive),
                    ("guarded_mlp_judge", pred_guard_mlp, cand_adaptive, cov_adaptive),
                    ("guarded_pairwise_judge", pred_guard_pairwise, cand_adaptive, cov_adaptive),
                    ("oracle_fixed_union", pred_oracle_fixed, cand_fixed, cov_fixed),
                    ("oracle_adaptive_union", pred_oracle_adaptive, cand_adaptive, cov_adaptive),
                ]:
                    stats[mode]["item_hits"] += int(pred == i)
                    stats[mode]["group_hits"] += int(group_ids[pred] == true_group)
                    stats[mode]["root_hit_top1"] += root_hit_top1
                    stats[mode]["root_hit_topk"] += root_hit_topk
                    stats[mode]["candidate_coverage"] += cov
                    stats[mode]["candidate_size"] += len(cand)
                    stats[mode]["shortlist_k"] += adaptive_k_mean
                    stats[mode]["root_margin"] += root_margin

                total += 1

    rows = []
    for mode in modes:
        rows.append({
            "placement": placement,
            "seed": seed,
            "n_groups": n_groups,
            "group_size": group_size,
            "root_dim": root_dim,
            "topk_root": topk_root,
            "num_projections": num_projections,
            "query_noise": query_noise,
            "local_radius": local_radius,
            "shortlist_schedule": shortlist_schedule,
            "guard_margin": guard_margin,
            "refine_alpha": refine_alpha,
            "mode": mode,
            "item_acc": stats[mode]["item_hits"] / total,
            "group_acc": stats[mode]["group_hits"] / total,
            "root_hit_top1": stats[mode]["root_hit_top1"] / total,
            "root_hit_topk": stats[mode]["root_hit_topk"] / total,
            "candidate_coverage": stats[mode]["candidate_coverage"] / total,
            "avg_candidate_size": stats[mode]["candidate_size"] / total,
            "avg_shortlist_k": stats[mode]["shortlist_k"] / total,
            "avg_root_margin": stats[mode]["root_margin"] / total,
            "nn_dist": mean_nearest_neighbor_distance(positions),
            "interference": mean_interference_kernel(positions),
            "trained_linear": int(linear_judge is not None),
            "trained_mlp": int(mlp_judge is not None),
            "trained_pairwise": int(pairwise_judge is not None),
        })
    return rows

# ============================================================
# Summary helpers
# ============================================================
def summarize(df, group_cols, value_cols):
    agg = {}
    for c in value_cols:
        agg[f"{c}_mean"] = (c, "mean")
        agg[f"{c}_std"] = (c, "std")
    return df.groupby(group_cols, as_index=False).agg(**agg)


def gap_table(summary_df, group_cols, baseline_mode="flat_key_nn", hair_mode="adaptive_shortlist_rerank", oracle_mode="oracle_adaptive_union"):
    base = summary_df[summary_df["mode"] == baseline_mode][group_cols + ["item_acc_mean"]].rename(columns={"item_acc_mean": "baseline"})
    hair = summary_df[summary_df["mode"] == hair_mode][group_cols + ["item_acc_mean"]].rename(columns={"item_acc_mean": "hair"})
    oracle = summary_df[summary_df["mode"] == oracle_mode][group_cols + ["item_acc_mean"]].rename(columns={"item_acc_mean": "oracle"})
    out = base.merge(hair, on=group_cols).merge(oracle, on=group_cols)
    out["hair_minus_baseline"] = out["hair"] - out["baseline"]
    out["oracle_minus_hair"] = out["oracle"] - out["hair"]
    out["oracle_minus_baseline"] = out["oracle"] - out["baseline"]
    return out

# ============================================================
# Runs
# ============================================================
def run_sweep_main():
    rows = []
    print("\nRunning main benchmark across separate idea tests...\n")
    for placement in PLACEMENTS:
        for seed in SEEDS:
            for schedule_name in SHORTLIST_SCHEDULES.keys():
                rows.extend(evaluate_case(
                    placement=placement,
                    seed=seed,
                    root_dim=ROOT_DIM,
                    topk_root=TOPK_ROOT,
                    num_projections=NUM_PROJECTIONS,
                    query_noise=QUERY_NOISE,
                    local_radius=LOCAL_RADIUS,
                    shortlist_schedule=schedule_name,
                    guard_margin=GUARD_MARGIN,
                    refine_alpha=REFINE_ALPHA,
                    trials_per_item=3,
                    train_per_group=TRAIN_PER_GROUP,
                    train_judges=True,
                ))
    return pd.DataFrame(rows)


