"""
Part 13 — M-CLTR Controller Above Hair-Memory Judge
====================================================
Goal:
- Test whether a small controller (continue / overwrite / restart) can improve the
  last-mile selection stage of the hair-memory system.
- Keep printed output compact.
- Separate the controller from retrieval so we can see whether it helps the judge,
  not candidate discovery.

What this script tests:
1) Flat baseline over all items.
2) Fixed shortlist rerank.
3) Learned judge on a shortlist.
4) Guarded learned judge.
5) M-CLTR controller variants:
   - continue
   - overwrite
   - restart
   - adaptive controller (learned or heuristic)
6) Oracle controller upper bound.

Output:
- One compact main summary table.
- Small sweeps over controller threshold and overwrite strength.
- CSVs saved to disk.

Dependencies:
- numpy, pandas, torch, matplotlib (optional)

Run:
- python part13_mcltr_hair_memory_controller_experiment.py
"""

from __future__ import annotations

import os
import random
from dataclasses import dataclass
from collections import defaultdict
from typing import Dict, List, Tuple

import numpy as np
import pandas as pd
import torch
import torch.nn as nn
from torch.utils.data import DataLoader, TensorDataset

# ============================================================
# Config
# ============================================================
SEEDS = [11, 22, 33]
PLACEMENTS = ["spiral", "random"]
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
OUTDIR = "memory_hair_part13_mcltr_controller"
os.makedirs(OUTDIR, exist_ok=True)

# memory size
N_GROUPS = 64
GROUP_SIZE = 4
KEY_DIM = 64
VALUE_DIM = 64

# retrieval
ROOT_DIM = 32
NUM_PROJECTIONS = 4
BASE_TOPK_ROOT = 5
LOCAL_RADIUS = 0.12

# query noise
QUERY_NOISE = 0.25
KEY_JITTER = 0.12
VALUE_JITTER = 0.12

# training
TRAIN_PER_GROUP = 4
NEG_PER_POS = 6
BATCH_SIZE = 256
EPOCHS = 14
LR = 1e-3

# controller
DEFAULT_GUARD_MARGIN = 0.08
DEFAULT_OVERWRITE_ALPHA = 0.35
DEFAULT_RESTART_BONUS_K = 3

# sweeps
GUARD_MARGINS = [0.02, 0.05, 0.08, 0.12]
OVERWRITE_ALPHAS = [0.10, 0.20, 0.35, 0.50]
TOPK_ROOTS = [1, 3, 5, 10]

pd.set_option("display.max_columns", 200)
pd.set_option("display.width", 180)

print("Device:", DEVICE)
print("Artifacts:", OUTDIR)

# ============================================================
# Repro
# ============================================================
def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

# ============================================================
# Helpers
# ============================================================
def normalize(x, axis=-1, eps=1e-9):
    x = np.asarray(x, dtype=np.float64)
    n = np.linalg.norm(x, axis=axis, keepdims=True)
    return x / (n + eps)


def topk_idx(scores, k):
    k = min(int(k), len(scores))
    if k <= 0:
        return np.array([], dtype=int)
    idx = np.argpartition(scores, -k)[-k:]
    return idx[np.argsort(scores[idx])[::-1]]


def softmax_np(x, axis=-1, temperature=1.0):
    x = np.asarray(x, dtype=np.float64)
    x = x / max(float(temperature), 1e-9)
    x = x - np.max(x, axis=axis, keepdims=True)
    ex = np.exp(x)
    return ex / (np.sum(ex, axis=axis, keepdims=True) + 1e-9)

# ============================================================
# Geometry
# ============================================================
def fermat_spiral_positions(n, radius=1.0):
    golden_angle = np.pi * (3.0 - np.sqrt(5.0))
    i = np.arange(n)
    r = radius * np.sqrt((i + 0.5) / n)
    theta = i * golden_angle
    x = r * np.cos(theta)
    y = r * np.sin(theta)
    return np.stack([x, y], axis=1)


def random_disk_positions(n, seed=0, radius=1.0):
    rng = np.random.default_rng(seed)
    r = radius * np.sqrt(rng.random(n))
    theta = 2.0 * np.pi * rng.random(n)
    x = r * np.cos(theta)
    y = r * np.sin(theta)
    return np.stack([x, y], axis=1)


def union_radius_neighbors(positions, centers, radius):
    centers = np.asarray(centers, dtype=int)
    if len(centers) == 0:
        return np.array([], dtype=int)
    diff = positions[:, None, :] - positions[centers][None, :, :]
    d2 = np.sum(diff ** 2, axis=2)
    mask = np.any(d2 <= radius ** 2, axis=1)
    idx = np.where(mask)[0]
    if len(idx) == 0:
        idx = np.array([int(centers[0])], dtype=int)
    return idx

# ============================================================
# Synthetic memory
# ============================================================
def make_clustered_memory(n_groups, group_size, key_dim, value_dim, seed=0, key_jitter=0.12, value_jitter=0.12):
    rng = np.random.default_rng(seed)
    keys, values, group_ids = [], [], []
    key_centers = normalize(rng.normal(size=(n_groups, key_dim)))
    value_centers = normalize(rng.normal(size=(n_groups, value_dim)))

    for g in range(n_groups):
        for _ in range(group_size):
            k = normalize(key_centers[g] + key_jitter * rng.normal(size=key_dim))
            v = normalize(value_centers[g] + value_jitter * rng.normal(size=value_dim))
            keys.append(k)
            values.append(v)
            group_ids.append(g)

    return np.stack(keys), np.stack(values), np.array(group_ids, dtype=int)


def split_by_group(group_ids, test_per_group=1, seed=0):
    rng = np.random.default_rng(seed)
    train_ids, test_ids = [], []
    for g in np.unique(group_ids):
        idx = np.where(group_ids == g)[0]
        test_sel = rng.choice(idx, size=test_per_group, replace=False)
        test_set = set(test_sel.tolist())
        train_sel = np.array([i for i in idx if i not in test_set], dtype=int)
        train_ids.extend(train_sel.tolist())
        test_ids.extend(test_sel.tolist())
    return np.array(train_ids, dtype=int), np.array(test_ids, dtype=int)

# ============================================================
# Projections / roots
# ============================================================
def build_projections(key_dim, root_dim, num_projections, seed=0):
    rng = np.random.default_rng(seed + 999)
    Ps = []
    for _ in range(num_projections):
        P = rng.normal(size=(root_dim, key_dim)) / np.sqrt(key_dim)
        Ps.append(P)
    return Ps


def build_roots(keys, Ps):
    return [normalize(keys @ P.T) for P in Ps]


def root_scores_for_query(query, Ps, roots_bank):
    scores_bank = []
    for P, roots in zip(Ps, roots_bank):
        qroot = normalize(query @ P.T)
        scores_bank.append(roots @ qroot)
    return scores_bank

# ============================================================
# Features
# ============================================================
def candidate_features(query, keys, candidate_idx, scores_bank, positions=None, candidate_center_idx=None, local_radius=0.12):
    q = normalize(query)
    cand = keys[candidate_idx]
    flat = float(cand @ q)

    root_supports = np.array([sb[candidate_idx] for sb in scores_bank], dtype=np.float64)
    root_mean = float(root_supports.mean())
    root_max = float(root_supports.max())
    root_std = float(root_supports.std())
    support_gap = float(root_max - root_mean)

    if positions is not None and candidate_center_idx is not None:
        d2 = np.sum((positions - positions[candidate_center_idx]) ** 2, axis=1)
        d2_sorted = np.sort(d2)
        nn_dist = float(np.sqrt(d2_sorted[1])) if len(d2_sorted) > 1 else 0.0
        local_density = float(np.mean(d2 <= local_radius ** 2))
    else:
        nn_dist = 0.0
        local_density = 0.0

    return np.array([flat, root_mean, root_max, root_std, support_gap, local_density, nn_dist], dtype=np.float32)


def candidate_pool_from_anchors(positions, anchor_idx, radius):
    return union_radius_neighbors(positions, anchor_idx, radius)


def union_of_candidates(positions, anchor_sets, radius):
    if len(anchor_sets) == 0:
        return np.array([], dtype=int), np.array([], dtype=int)
    all_anchors = np.unique(np.concatenate(anchor_sets))
    cand = candidate_pool_from_anchors(positions, all_anchors, radius)
    return cand, all_anchors

# ============================================================
# Models
# ============================================================
class LinearJudge(nn.Module):
    def __init__(self, in_dim):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, 64),
            nn.ReLU(),
            nn.Linear(64, 1),
        )

    def forward(self, x):
        return self.net(x).squeeze(-1)


class MLPJudge(nn.Module):
    def __init__(self, in_dim):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, 64),
            nn.ReLU(),
            nn.Linear(64, 32),
            nn.ReLU(),
            nn.Linear(32, 1),
        )

    def forward(self, x):
        return self.net(x).squeeze(-1)


class OverwriteRefiner(nn.Module):
    def __init__(self, dim, alpha=0.35):
        super().__init__()
        self.linear = nn.utils.spectral_norm(nn.Linear(dim, dim))
        self.gate = nn.Linear(dim, dim)
        self.alpha = alpha

    def forward(self, x):
        g = torch.sigmoid(self.gate(x))
        delta = torch.tanh(self.linear(x))
        return x + self.alpha * g * delta


class MCLTRController(nn.Module):
    """Small controller predicting continue / overwrite / restart logits."""
    def __init__(self, in_dim, hidden=32):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.ReLU(),
            nn.Linear(hidden, 3),
        )

    def forward(self, x):
        return self.net(x)

# ============================================================
# Training
# ============================================================
def train_binary_judge(model, X, y, epochs=EPOCHS, lr=LR, batch_size=BATCH_SIZE):
    model = model.to(DEVICE)
    opt = torch.optim.Adam(model.parameters(), lr=lr)
    loss_fn = nn.BCEWithLogitsLoss()
    ds = TensorDataset(torch.tensor(X, dtype=torch.float32), torch.tensor(y, dtype=torch.float32))
    dl = DataLoader(ds, batch_size=batch_size, shuffle=True, drop_last=False)

    model.train()
    for _ in range(epochs):
        for xb, yb in dl:
            xb, yb = xb.to(DEVICE), yb.to(DEVICE)
            opt.zero_grad()
            logits = model(xb)
            loss = loss_fn(logits, yb)
            loss.backward()
            opt.step()
    model.eval()
    return model


def train_mcltr_controller(controller, X, y, epochs=EPOCHS, lr=LR, batch_size=BATCH_SIZE):
    controller = controller.to(DEVICE)
    opt = torch.optim.Adam(controller.parameters(), lr=lr)
    loss_fn = nn.CrossEntropyLoss()
    ds = TensorDataset(torch.tensor(X, dtype=torch.float32), torch.tensor(y, dtype=torch.long))
    dl = DataLoader(ds, batch_size=batch_size, shuffle=True, drop_last=False)

    controller.train()
    for _ in range(epochs):
        for xb, yb in dl:
            xb, yb = xb.to(DEVICE), yb.to(DEVICE)
            opt.zero_grad()
            logits = controller(xb)
            loss = loss_fn(logits, yb)
            loss.backward()
            opt.step()
    controller.eval()
    return controller


@torch.no_grad()
def score_model(model, feats):
    if model is None or len(feats) == 0:
        return None
    xb = torch.tensor(feats, dtype=torch.float32, device=DEVICE)
    logits = model(xb)
    if logits.ndim == 1:
        return torch.sigmoid(logits).detach().cpu().numpy()
    return logits.detach().cpu().numpy()

# ============================================================
# M-CLTR policy helpers
# ============================================================
def build_mcltr_features(q, keys, cand_idx, scores_bank, base_scores, positions, local_radius, controller_state_scale=1.0):
    """Features for controller deciding among continue / overwrite / restart."""
    feats = []
    for c in cand_idx:
        f = candidate_features(q, keys, c, scores_bank, positions=positions, candidate_center_idx=c, local_radius=local_radius)
        # add judge-relative signals
        f = np.concatenate([
            f,
            np.array([
                float(base_scores[c]),
                float(np.max(base_scores[cand_idx]) - base_scores[c]),
                float(np.mean(base_scores[cand_idx])),
                float(np.std(base_scores[cand_idx])),
            ], dtype=np.float32),
        ])
        feats.append(f * controller_state_scale)
    return np.asarray(feats, dtype=np.float32)


def controller_policy_from_logits(logits, mode="adaptive", margin_threshold=0.08):
    """
    logits: shape (n,3) where classes are [continue, overwrite, restart]
    If mode=heuristic, use simple rules instead of learned controller.
    """
    if mode == "heuristic":
        # choose restart if uncertain, overwrite if close, else continue
        if len(logits) <= 1:
            return 0
        s = np.sort(logits)[::-1]
        margin = float(s[0] - s[1])
        if margin >= margin_threshold:
            return 0
        elif margin >= margin_threshold / 2:
            return 1
        return 2
    return int(np.argmax(logits))


def apply_mcltr_action(action, scores, cand_idx, overwrite_alpha=0.35, restart_bonus_k=3):
    """
    action: 0 continue, 1 overwrite, 2 restart
    scores: numpy scores over candidate pool
    cand_idx: candidate indices
    overwrite: mix scores with smoother softmax score
    restart: widen to a larger pool later (handled by caller)
    """
    scores = np.asarray(scores, dtype=np.float64)
    if action == 0:
        return int(cand_idx[int(np.argmax(scores))]), cand_idx
    if action == 1:
        sm = softmax_np(scores, temperature=1.25)
        mix = (1.0 - overwrite_alpha) * scores + overwrite_alpha * sm
        return int(cand_idx[int(np.argmax(mix))]), cand_idx
    return -1, cand_idx

# ============================================================
# Training data for judges / controller
# ============================================================
def build_training_data(train_ids, keys, roots_bank, Ps, positions, query_noise, local_radius, topk_root, num_projections, samples_per_item, seed):
    rng = np.random.default_rng(seed + 4242)
    Xj, yj = [], []
    Xc, yc = [], []

    for i in train_ids:
        for _ in range(samples_per_item):
            q = normalize(keys[i] + query_noise * rng.normal(size=KEY_DIM))
            scores_bank = root_scores_for_query(q, Ps, roots_bank)
            anchor_sets = [topk_idx(scores_bank[p], topk_root) for p in range(num_projections)]
            cand_multi, _ = union_of_candidates(positions, anchor_sets, local_radius)
            if len(cand_multi) == 0:
                continue

            cand_list = cand_multi.tolist()
            if i not in cand_list:
                cand_list.append(int(i))
            cand_list = list(dict.fromkeys(cand_list))

            pos_feat = candidate_features(q, keys, i, scores_bank, positions=positions, candidate_center_idx=i, local_radius=local_radius)
            Xj.append(pos_feat)
            yj.append(1.0)

            negatives = [c for c in cand_list if c != i]
            if len(negatives) > 0:
                pick_n = min(NEG_PER_POS, len(negatives))
                neg_pick = rng.choice(negatives, size=pick_n, replace=False)
                for c in neg_pick:
                    feat = candidate_features(q, keys, c, scores_bank, positions=positions, candidate_center_idx=c, local_radius=local_radius)
                    Xj.append(feat)
                    yj.append(0.0)

            # controller labels are synthetic: choose action based on oracle gap and margin
            # 0 continue, 1 overwrite, 2 restart
            base_scores = np.array([candidate_features(q, keys, c, scores_bank, positions=positions, candidate_center_idx=c, local_radius=local_radius)[0] for c in cand_list])
            top2 = np.sort(base_scores)[::-1][:2]
            margin = float(top2[0] - top2[1]) if len(top2) > 1 else 1.0
            oracle_is_top = int(np.argmax(base_scores) == cand_list.index(i)) if i in cand_list else 0
            if oracle_is_top and margin >= 0.10:
                action = 0
            elif oracle_is_top:
                action = 1
            else:
                action = 2

            # use one feature vector per training example for controller
            ctrl_feat = np.concatenate([
                candidate_features(q, keys, i, scores_bank, positions=positions, candidate_center_idx=i, local_radius=local_radius),
                np.array([base_scores.max(), base_scores.mean(), base_scores.std(), margin], dtype=np.float32),
            ])
            Xc.append(ctrl_feat)
            yc.append(action)

    return np.asarray(Xj, dtype=np.float32), np.asarray(yj, dtype=np.float32), np.asarray(Xc, dtype=np.float32), np.asarray(yc, dtype=np.int64)

# ============================================================
# Evaluation
# ============================================================
def eval_case(
    n_groups=64,
    group_size=4,
    placement="spiral",
    seed=0,
    root_dim=32,
    topk_root=5,
    num_projections=4,
    query_noise=0.25,
    local_radius=0.12,
    trials_per_item=3,
    train_per_group=4,
    train_judges=True,
    guard_margin=DEFAULT_GUARD_MARGIN,
    overwrite_alpha=DEFAULT_OVERWRITE_ALPHA,
    restart_bonus_k=DEFAULT_RESTART_BONUS_K,
):
    set_seed(seed)
    n_items = n_groups * group_size

    keys, values, group_ids = make_clustered_memory(
        n_groups=n_groups,
        group_size=group_size,
        key_dim=KEY_DIM,
        value_dim=VALUE_DIM,
        seed=seed,
        key_jitter=KEY_JITTER,
        value_jitter=VALUE_JITTER,
    )

    if placement == "spiral":
        positions = fermat_spiral_positions(n_items, radius=1.0)
    elif placement == "random":
        positions = random_disk_positions(n_items, seed=seed + 12345, radius=1.0)
    else:
        raise ValueError("placement must be 'spiral' or 'random'")

    Ps = build_projections(KEY_DIM, root_dim, num_projections, seed=seed)
    roots_bank = build_roots(keys, Ps)
    keys_norm = normalize(keys)

    train_ids, test_ids = split_by_group(group_ids, test_per_group=1, seed=seed)
    rng = np.random.default_rng(seed + 4242)

    Xj, yj, Xc, yc = build_training_data(
        train_ids=train_ids,
        keys=keys,
        roots_bank=roots_bank,
        Ps=Ps,
        positions=positions,
        query_noise=query_noise,
        local_radius=local_radius,
        topk_root=topk_root,
        num_projections=num_projections,
        samples_per_item=train_per_group,
        seed=seed,
    )

    linear_judge = None
    mlp_judge = None
    controller = None
    overwrite_refiner = None

    if train_judges and len(Xj) > 0:
        linear_judge = train_binary_judge(LinearJudge(Xj.shape[1]), Xj, yj)
        mlp_judge = train_binary_judge(MLPJudge(Xj.shape[1]), Xj, yj)
        overwrite_refiner = OverwriteRefiner(dim=Xj.shape[1], alpha=overwrite_alpha).to(DEVICE)
        controller = train_mcltr_controller(MCLTRController(Xc.shape[1]), Xc, yc)

    modes = [
        "flat_key_nn",
        "fixed_multi_root_rerank",
        "adaptive_shortlist_rerank",
        "learned_linear_judge",
        "learned_mlp_judge",
        "guarded_linear_judge",
        "guarded_mlp_judge",
        "mcltr_continue",
        "mcltr_overwrite",
        "mcltr_restart",
        "mcltr_adaptive",
        "oracle_pool",
        "oracle_controller",
    ]

    stats = {m: defaultdict(float) for m in modes}
    total = 0

    with torch.no_grad():
        for i in test_ids:
            true_group = int(group_ids[i])
            for _ in range(trials_per_item):
                q = normalize(keys[i] + query_noise * rng.normal(size=KEY_DIM))
                flat_scores = keys_norm @ q
                flat_pred = int(np.argmax(flat_scores))

                scores_bank = root_scores_for_query(q, Ps, roots_bank)
                anchor_sets = [topk_idx(scores_bank[p], topk_root) for p in range(num_projections)]
                single_anchors = anchor_sets[0]
                cand_single = candidate_pool_from_anchors(positions, single_anchors, local_radius)
                cand_multi, _ = union_of_candidates(positions, anchor_sets, local_radius)

                root_top1 = int(np.argmax(scores_bank[0]))
                root_hit_top1 = int(root_top1 == i)
                root_hit_topk = int(i in set(np.unique(np.concatenate(anchor_sets)).tolist()))

                # baselines
                if len(cand_single) > 0:
                    pred_passive = int(cand_single[np.argmax(flat_scores[cand_single])])
                else:
                    pred_passive = flat_pred

                if len(cand_single) > 0:
                    feats_single = np.stack([
                        candidate_features(q, keys, c, scores_bank, positions=positions, candidate_center_idx=c, local_radius=local_radius)
                        for c in cand_single
                    ], axis=0)
                    s_single = feats_single[:, 0] + 0.25 * feats_single[:, 1] + 0.10 * feats_single[:, 2] - 0.05 * feats_single[:, 3]
                    pred_fixed = int(cand_single[int(np.argmax(s_single))])
                else:
                    pred_fixed = flat_pred

                # adaptive shortlist + learned judges on multi-root pool
                if len(cand_multi) > 0:
                    feats_multi = np.stack([
                        candidate_features(q, keys, c, scores_bank, positions=positions, candidate_center_idx=c, local_radius=local_radius)
                        for c in cand_multi
                    ], axis=0)
                    base_judge = feats_multi[:, 0] + 0.25 * feats_multi[:, 1] + 0.10 * feats_multi[:, 2] - 0.05 * feats_multi[:, 3]
                    pred_adaptive = int(cand_multi[int(np.argmax(base_judge))])
                    lin_probs = score_model(linear_judge, feats_multi)
                    mlp_probs = score_model(mlp_judge, feats_multi)
                    pred_lin = int(cand_multi[int(np.argmax(lin_probs))]) if lin_probs is not None else pred_adaptive
                    pred_mlp = int(cand_multi[int(np.argmax(mlp_probs))]) if mlp_probs is not None else pred_adaptive
                    lin_margin = float(np.sort(lin_probs)[::-1][0] - np.sort(lin_probs)[::-1][1]) if lin_probs is not None and len(lin_probs) > 1 else 1.0
                    mlp_margin = float(np.sort(mlp_probs)[::-1][0] - np.sort(mlp_probs)[::-1][1]) if mlp_probs is not None and len(mlp_probs) > 1 else 1.0
                else:
                    pred_adaptive = flat_pred
                    pred_lin = flat_pred
                    pred_mlp = flat_pred
                    lin_margin = 1.0
                    mlp_margin = 1.0
                    base_judge = np.array([], dtype=np.float64)

                # guarded versions
                pred_guard_lin = pred_lin if lin_margin >= guard_margin else pred_adaptive
                pred_guard_mlp = pred_mlp if mlp_margin >= guard_margin else pred_adaptive

                # M-CLTR controller inputs
                if len(cand_multi) > 0:
                    ctrl_feats = np.stack([
                        np.concatenate([
                            candidate_features(q, keys, c, scores_bank, positions=positions, candidate_center_idx=c, local_radius=local_radius),
                            np.array([base_judge.max(), base_judge.mean(), base_judge.std(), lin_margin], dtype=np.float32),
                        ])
                        for c in cand_multi
                    ], axis=0)
                    ctrl_logits = score_model(controller, ctrl_feats)
                    # one controller decision for the current shortlist
                    if ctrl_logits is not None:
                        ctrl_action = controller_policy_from_logits(ctrl_logits.mean(axis=0), mode="adaptive", margin_threshold=guard_margin)
                    else:
                        ctrl_action = 0
                else:
                    ctrl_action = 0

                # M-CLTR execute action on the judged shortlist
                if len(cand_multi) > 0:
                    if overwrite_refiner is not None:
                        refined_feats = overwrite_refiner(torch.tensor(feats_multi, dtype=torch.float32, device=DEVICE)).cpu().numpy()
                        refined_scores = refined_feats[:, 0] + 0.25 * refined_feats[:, 1] + 0.10 * refined_feats[:, 2] - 0.05 * refined_feats[:, 3]
                    else:
                        refined_scores = base_judge

                    pred_continue, _ = apply_mcltr_action(0, base_judge, cand_multi, overwrite_alpha, restart_bonus_k)
                    pred_overwrite, _ = apply_mcltr_action(1, refined_scores, cand_multi, overwrite_alpha, restart_bonus_k)
                    pred_restart, _ = apply_mcltr_action(2, base_judge, cand_multi, overwrite_alpha, restart_bonus_k)

                    # restart means enlarge the pool and then rerank heuristically
                    if ctrl_action == 2:
                        k_restart = min(max(len(anchor_sets[0]), topk_root + restart_bonus_k), n_items)
                        wider_anchors = [topk_idx(scores_bank[p], k_restart) for p in range(num_projections)]
                        cand_restart, _ = union_of_candidates(positions, wider_anchors, local_radius)
                        if len(cand_restart) > 0:
                            feats_restart = np.stack([
                                candidate_features(q, keys, c, scores_bank, positions=positions, candidate_center_idx=c, local_radius=local_radius)
                                for c in cand_restart
                            ], axis=0)
                            scores_restart = feats_restart[:, 0] + 0.25 * feats_restart[:, 1] + 0.10 * feats_restart[:, 2] - 0.05 * feats_restart[:, 3]
                            pred_mcltr_adaptive = int(cand_restart[int(np.argmax(scores_restart))])
                        else:
                            pred_mcltr_adaptive = pred_adaptive
                    elif ctrl_action == 1:
                        pred_mcltr_adaptive = pred_overwrite
                    else:
                        pred_mcltr_adaptive = pred_continue
                else:
                    pred_continue = flat_pred
                    pred_overwrite = flat_pred
                    pred_restart = flat_pred
                    pred_mcltr_adaptive = flat_pred

                pred_oracle_pool = i if i in set(cand_multi.tolist()) else pred_adaptive
                pred_oracle_ctrl = i if ctrl_action in [0, 1, 2] and i in set(cand_multi.tolist()) else pred_mcltr_adaptive

                cov_single = int(i in set(cand_single.tolist())) if len(cand_single) > 0 else 0
                cov_multi = int(i in set(cand_multi.tolist())) if len(cand_multi) > 0 else 0

                entries = [
                    ("flat_key_nn", flat_pred, np.arange(n_items), 1),
                    ("fixed_multi_root_rerank", pred_fixed, cand_single, cov_single),
                    ("adaptive_shortlist_rerank", pred_adaptive, cand_multi, cov_multi),
                    ("learned_linear_judge", pred_lin, cand_multi, cov_multi),
                    ("learned_mlp_judge", pred_mlp, cand_multi, cov_multi),
                    ("guarded_linear_judge", pred_guard_lin, cand_multi, cov_multi),
                    ("guarded_mlp_judge", pred_guard_mlp, cand_multi, cov_multi),
                    ("mcltr_continue", pred_continue, cand_multi, cov_multi),
                    ("mcltr_overwrite", pred_overwrite, cand_multi, cov_multi),
                    ("mcltr_restart", pred_restart, cand_multi, cov_multi),
                    ("mcltr_adaptive", pred_mcltr_adaptive, cand_multi, cov_multi),
                    ("oracle_pool", pred_oracle_pool, cand_multi, cov_multi),
                    ("oracle_controller", pred_oracle_ctrl, cand_multi, cov_multi),
                ]

                for mode, pred, cand, cov in entries:
                    stats[mode]["item_hits"] += int(pred == i)
                    stats[mode]["group_hits"] += int(group_ids[pred] == true_group)
                    stats[mode]["root_hit_top1"] += root_hit_top1
                    stats[mode]["root_hit_topk"] += root_hit_topk
                    stats[mode]["candidate_coverage"] += cov
                    stats[mode]["candidate_size"] += len(cand)

                total += 1

    rows = []
    for mode in modes:
        rows.append({
            "placement": placement,
            "seed": seed,
            "n_groups": n_groups,
            "group_size": group_size,
            "root_dim": root_dim,
            "topk_root": topk_root,
            "num_projections": num_projections,
            "query_noise": query_noise,
            "local_radius": local_radius,
            "guard_margin": guard_margin,
            "overwrite_alpha": overwrite_alpha,
            "mode": mode,
            "item_acc": stats[mode]["item_hits"] / total,
            "group_acc": stats[mode]["group_hits"] / total,
            "root_hit_top1": stats[mode]["root_hit_top1"] / total,
            "root_hit_topk": stats[mode]["root_hit_topk"] / total,
            "candidate_coverage": stats[mode]["candidate_coverage"] / total,
            "avg_candidate_size": stats[mode]["candidate_size"] / total,
        })
    return rows

# ============================================================
# Summaries
# ============================================================
def summarize(df, group_cols, value_cols):
    agg = {}
    for c in value_cols:
        agg[f"{c}_mean"] = (c, "mean")
        agg[f"{c}_std"] = (c, "std")
    return df.groupby(group_cols, as_index=False).agg(**agg)


def gap_table(summary_df, group_cols, baseline_mode="flat_key_nn", hair_mode="mcltr_adaptive", oracle_mode="oracle_pool"):
    base = summary_df[summary_df["mode"] == baseline_mode][group_cols + ["item_acc_mean"]].rename(columns={"item_acc_mean": "baseline"})
    hair = summary_df[summary_df["mode"] == hair_mode][group_cols + ["item_acc_mean"]].rename(columns={"item_acc_mean": "hair"})
    oracle = summary_df[summary_df["mode"] == oracle_mode][group_cols + ["item_acc_mean"]].rename(columns={"item_acc_mean": "oracle"})
    out = base.merge(hair, on=group_cols).merge(oracle, on=group_cols)
    out["hair_minus_baseline"] = out["hair"] - out["baseline"]
    out["oracle_minus_hair"] = out["oracle"] - out["hair"]
    out["oracle_minus_baseline"] = out["oracle"] - out["baseline"]
    return out

# ============================================================
# Main runs
# ============================================================
print("\nRunning main benchmark...\n")
main_rows = []
for placement in PLACEMENTS:
    for seed in SEEDS:
        main_rows.extend(
            eval_case(
                placement=placement,
                seed=seed,
                topk_root=BASE_TOPK_ROOT,
                guard_margin=DEFAULT_GUARD_MARGIN,
                overwrite_alpha=DEFAULT_OVERWRITE_ALPHA,
                trials_per_item=3,
                train_per_group=TRAIN_PER_GROUP,
                train_judges=True,
            )
        )

print("Running guard margin sweep...")
guard_rows = []
for placement in PLACEMENTS:
    for seed in SEEDS:
        for gm in GUARD_MARGINS:
            guard_rows.extend(
                eval_case(
                    placement=placement,
                    seed=seed,
                    topk_root=BASE_TOPK_ROOT,
                    guard_margin=gm,
                    overwrite_alpha=DEFAULT_OVERWRITE_ALPHA,
                    trials_per_item=3,
                    train_per_group=TRAIN_PER_GROUP,
                    train_judges=True,
                )
            )

print("Running overwrite alpha sweep...")
overwrite_rows = []
for placement in PLACEMENTS:
    for seed in SEEDS:
        for oa in OVERWRITE_ALPHAS:
            overwrite_rows.extend(
                eval_case(
                    placement=placement,
                    seed=seed,
                    topk_root=BASE_TOPK_ROOT,
                    guard_margin=DEFAULT_GUARD_MARGIN,
                    overwrite_alpha=oa,
                    trials_per_item=3,
                    train_per_group=TRAIN_PER_GROUP,
                    train_judges=True,
                )
            )

print("Running top-k root sweep...")
topk_rows = []
for placement in PLACEMENTS:
    for seed in SEEDS:
        for tk in TOPK_ROOTS:
            topk_rows.extend(
                eval_case(
                    placement=placement,
                    seed=seed,
                    topk_root=tk,
                    guard_margin=DEFAULT_GUARD_MARGIN,
                    overwrite_alpha=DEFAULT_OVERWRITE_ALPHA,
                    trials_per_item=3,
                    train_per_group=TRAIN_PER_GROUP,
                    train_judges=True,
                )
            )

# ============================================================
# DataFrames
# ============================================================
main_df = pd.DataFrame(main_rows)
guard_df = pd.DataFrame(guard_rows)
overwrite_df = pd.DataFrame(overwrite_rows)
topk_df = pd.DataFrame(topk_rows)

value_cols = ["item_acc", "group_acc", "candidate_coverage", "avg_candidate_size", "root_hit_top1", "root_hit_topk"]
main_agg = summarize(main_df, ["placement", "mode"], value_cols)
guard_agg = summarize(guard_df, ["placement", "guard_margin", "mode"], value_cols)
overwrite_agg = summarize(overwrite_df, ["placement", "overwrite_alpha", "mode"], value_cols)
topk_agg = summarize(topk_df, ["placement", "topk_root", "mode"], value_cols)

main_gap = gap_table(main_agg, ["placement"], baseline_mode="flat_key_nn", hair_mode="mcltr_adaptive", oracle_mode="oracle_pool")

# ============================================================
# Compact output
# ============================================================
print("\n=== Main comparison ===")
print(
    main_agg[[
        "placement", "mode", "item_acc_mean", "group_acc_mean",
        "candidate_coverage_mean", "avg_candidate_size_mean"
    ]]
    .sort_values(["placement", "item_acc_mean"], ascending=[True, False])
    .to_string(index=False)
)

print("\n=== Gap vs flat baseline and oracle (main setting) ===")
print(
    main_gap[["placement", "baseline", "hair", "oracle", "hair_minus_baseline", "oracle_minus_hair", "oracle_minus_baseline"]]
    .to_string(index=False)
)

print("\n=== Best guard margins ===")
for placement in PLACEMENTS:
    sub = guard_agg[(guard_agg["placement"] == placement) & (guard_agg["mode"] == "mcltr_adaptive")].copy()
    best = sub.sort_values("item_acc_mean", ascending=False).iloc[0]
    print(f"{placement}: guard_margin={best['guard_margin']:.2f} | item_acc={best['item_acc_mean']:.4f} | coverage={best['candidate_coverage_mean']:.4f}")

print("\n=== Best overwrite alpha ===")
for placement in PLACEMENTS:
    sub = overwrite_agg[(overwrite_agg["placement"] == placement) & (overwrite_agg["mode"] == "mcltr_adaptive")].copy()
    best = sub.sort_values("item_acc_mean", ascending=False).iloc[0]
    print(f"{placement}: overwrite_alpha={best['overwrite_alpha']:.2f} | item_acc={best['item_acc_mean']:.4f} | coverage={best['candidate_coverage_mean']:.4f}")

print("\n=== Top-k root sweep (adaptive M-CLTR only) ===")
print(
    topk_agg[topk_agg["mode"].isin(["mcltr_adaptive", "oracle_pool", "guarded_mlp_judge", "flat_key_nn"])][[
        "placement", "topk_root", "mode", "item_acc_mean", "candidate_coverage_mean", "avg_candidate_size_mean"
    ]]
    .sort_values(["placement", "topk_root", "mode"])
    .to_string(index=False)
)

# ============================================================
