# ----------------------------
# Case 4: controller sweep
# ----------------------------
def case_controller_sweep() -> pd.DataFrame:
    rows = []
    hard_noise = max(TEST_NOISES)
    for placement in ["random", "spiral_ortho"]:
        for guard_margin in GUARD_MARGINS:
            for overwrite_alpha in OVERWRITE_ALPHAS:
                for refine_alpha in REFINE_ALPHAS:
                    df, _, _, _, _ = run_world(
                        placement=placement,
                        overlap_k=MAIN_OVERLAP_K,
                        topk_root=MAIN_TOPK_ROOT,
                        ambiguity=0.35,
                        train_noise_levels=TRAIN_NOISES,
                        test_noise_levels=[hard_noise],
                        train_queries_per_item=TRAIN_QUERIES_PER_ITEM,
                        test_queries_per_item=TEST_QUERIES_PER_ITEM,
                        guard_margin=guard_margin,
                        overwrite_alpha=overwrite_alpha,
                        refine_alpha=refine_alpha,
                    )
                    keep = df[df["method"].isin([
                        "flat_key_nn",
                        "learned_linear_judge",
                        "learned_mlp_judge",
                        "pairwise_judge",
                        "guarded_linear_judge",
                        "guarded_pairwise_judge",
                        "mcltr_continue",
                        "mcltr_overwrite",
                        "mcltr_restart",
                        "mcltr_adaptive",
                        "qdmn_refine1",
                        "qdmn_refine2",
                        "oracle_pool",
                    ])].copy()
                    keep["case"] = "controller_sweep"
                    rows.append(keep)
    out = pd.concat(rows, ignore_index=True)
    out.to_csv(OUTDIR / "case4_controller_sweep.csv", index=False)
    return out

# ----------------------------
# Reporting
# ----------------------------
def print_block(title: str, df: pd.DataFrame, cols: List[str], sort_cols: List[str]) -> None:
    print(f"\n=== {title} ===")
    print(
        df.sort_values(sort_cols, ascending=[True] * len(sort_cols))
          .loc[:, cols]
          .round(4)
          .to_string(index=False)
    )

def make_summary_figure(
    placement_df: pd.DataFrame,
    ambiguity_df: pd.DataFrame,
    sweep_df: pd.DataFrame,
    controller_df: pd.DataFrame,
) -> None:
    fig, axes = plt.subplots(2, 2, figsize=(16, 11), constrained_layout=True)

    display_methods = [
        "flat_key_nn",
        "pairwise_judge",
        "guarded_linear_judge",
        "mcltr_adaptive",
        "qdmn_refine2",
        "oracle_pool",
    ]

    # A: placement debug
    ax = axes[0, 0]
    sub = placement_df[placement_df["method"].isin(display_methods)]
    for placement in ["random", "spiral_bad", "spiral_ortho"]:
        d = sub[sub["placement"] == placement]
        if len(d) == 0:
            continue
        for method in ["flat_key_nn", "pairwise_judge", "mcltr_adaptive", "qdmn_refine2", "oracle_pool"]:
            dd = d[d["method"] == method].sort_values("noise")
            if len(dd) == 0:
                continue
            label = f"{placement}:{method}"
            ax.plot(dd["noise"], dd["item_acc"], marker="o", linewidth=1.8, label=label)
    ax.set_title("A. Placement debug: accuracy vs noise")
    ax.set_xlabel("Noise")
    ax.set_ylabel("Item accuracy")
    ax.grid(True, alpha=0.25)
    ax.legend(fontsize=7, ncol=2, loc="best")

    # B: ambiguity sweep
    ax = axes[0, 1]
    sub = ambiguity_df[ambiguity_df["method"].isin(display_methods)]
    for placement in ["random", "spiral_ortho"]:
        for method in ["flat_key_nn", "pairwise_judge", "guarded_linear_judge", "mcltr_adaptive", "qdmn_refine2", "oracle_pool"]:
            dd = sub[(sub["placement"] == placement) & (sub["method"] == method)]
            if len(dd) == 0:
                continue
            dd = dd.sort_values("ambiguity")
            ax.plot(dd["ambiguity"], dd["item_acc"], marker="o", linewidth=1.8, label=f"{placement}:{method}")
    ax.set_title("B. Ambiguity sweep at fixed hard noise")
    ax.set_xlabel("Ambiguity")
    ax.set_ylabel("Item accuracy")
    ax.grid(True, alpha=0.25)
    ax.legend(fontsize=7, ncol=2, loc="best")

    # C: overlap/topk sweep
    ax = axes[1, 0]
    sub = sweep_df[sweep_df["method"].isin(["flat_key_nn", "pairwise_judge", "mcltr_adaptive", "oracle_pool"])]
    for placement in ["random", "spiral_ortho"]:
        dd0 = sub[sub["placement"] == placement]
        for method in ["flat_key_nn", "pairwise_judge", "mcltr_adaptive", "oracle_pool"]:
            ddm = dd0[dd0["method"] == method]
            if len(ddm) == 0:
                continue
            # plot best per overlap_k by topk_root
            for tk in SWEEP_TOPK_ROOT:
                dtk = ddm[ddm["topk_root"] == tk].sort_values("overlap_k")
                if len(dtk) == 0:
                    continue
                ax.plot(
                    dtk["overlap_k"],
                    dtk["item_acc"],
                    marker="o",
                    linewidth=1.4,
                    label=f"{placement}:{method}, topk={tk}",
                )
    ax.set_title("C. Overlap sweep at hard noise")
    ax.set_xlabel("Overlap k")
    ax.set_ylabel("Item accuracy")
    ax.grid(True, alpha=0.25)
    ax.legend(fontsize=6, ncol=2, loc="best")

    # D: controller sweep
    ax = axes[1, 1]
    show = controller_df[controller_df["method"].isin(["guarded_linear_judge", "guarded_pairwise_judge", "mcltr_adaptive", "qdmn_refine2"])]
    # show best settings per placement/method
    best = (
        show.sort_values(["placement", "method", "item_acc"], ascending=[True, True, False])
            .groupby(["placement", "method"], as_index=False)
            .head(1)
    )
    x = np.arange(len(best))
    ax.bar(x, best["item_acc"].values)
    ax.set_xticks(x)
    ax.set_xticklabels([f"{p}\n{m}" for p, m in zip(best["placement"], best["method"])], rotation=0, fontsize=7)
    ax.set_title("D. Best controller settings")
    ax.set_ylabel("Item accuracy")
    ax.grid(True, axis="y", alpha=0.25)

    fig.suptitle("Part 16B — Spiral debug, ambiguity, overlap, and controller cases", fontsize=14)
    fig.savefig(OUTDIR / "part16b_summary_figure.png", dpi=220, bbox_inches="tight")
    plt.show()

# ----------------------------
# Main
# ----------------------------
def main() -> pd.DataFrame:
    print("Running case 1: placement debug...")
    placement_df = case_placement_debug()

    print("Running case 2: ambiguity sweep...")
    ambiguity_df = case_ambiguity_sweep()

    print("Running case 3: overlap/topk sweep...")
    sweep_df = case_overlap_topk_sweep()

    print("Running case 4: controller sweep...")
    controller_df = case_controller_sweep()

    all_df = pd.concat([placement_df, ambiguity_df, sweep_df, controller_df], ignore_index=True)
    all_df.to_csv(OUTDIR / "all_results.csv", index=False)

    # A compact paper-ready summary
    paper_summary = (
        all_df.groupby(["case", "placement", "method"])[["item_acc", "group_acc", "coverage", "avg_pool"]]
        .mean()
        .reset_index()
        .sort_values(["case", "placement", "item_acc"], ascending=[True, True, False])
    )
    paper_summary.to_csv(OUTDIR / "paper_summary.csv", index=False)

    print_block(
        "Placement debug summary",
        placement_df,
        ["placement", "noise", "method", "item_acc", "group_acc", "coverage", "avg_pool"],
        ["placement", "noise", "item_acc"],
    )

    print_block(
        "Ambiguity sweep summary",
        ambiguity_df,
        ["placement", "ambiguity", "noise", "method", "item_acc", "group_acc", "coverage", "avg_pool"],
        ["placement", "ambiguity", "item_acc"],
    )

    print_block(
        "Overlap/topk sweep summary",
        sweep_df,
        ["placement", "overlap_k", "topk_root", "noise", "method", "item_acc", "coverage", "avg_pool"],
        ["placement", "overlap_k", "topk_root", "item_acc"],
    )

    print_block(
        "Controller sweep summary",
        controller_df,
        ["placement", "guard_margin", "overwrite_alpha", "refine_alpha", "method", "item_acc", "coverage", "avg_pool", "overwrite_rate", "restart_rate", "refine_rate"],
        ["placement", "method", "item_acc"],
    )

    print("\n=== Best non-oracle rows by case ===")
    non_oracle = all_df[all_df["method"] != "oracle_pool"].copy()
    best_by_case = (
        non_oracle.sort_values(["case", "item_acc"], ascending=[True, False])
        .groupby("case", as_index=False)
        .head(1)
        .loc[:, ["case", "placement", "method", "item_acc", "group_acc", "coverage", "avg_pool", "noise", "ambiguity", "overlap_k", "topk_root"]]
        .reset_index(drop=True)
    )
    print(best_by_case.round(4).to_string(index=False))

    make_summary_figure(placement_df, ambiguity_df, sweep_df, controller_df)

    print(f"\nSaved CSVs and figure to: {OUTDIR}")
    print("\n=== Paper summary preview ===")
    print(paper_summary.head(30).round(4).to_string(index=False))

    return all_df

if __name__ == "__main__":
    df = main()
    print("\nDone.")

# ============================================================
# PART 17 — Ambiguity / Margin-Binned Judge Test
# Fixed retrieval, same query bank, QDMN vs judge under ambiguity
# Colab-friendly, paper-style summary figure + CSVs
# ============================================================

from __future__ import annotations

import math
import random
import warnings
from dataclasses import dataclass
from collections import defaultdict
from pathlib import Path
from typing import Dict, List, Tuple, Optional

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt

from sklearn.linear_model import LogisticRegression
from sklearn.neural_network import MLPClassifier
from sklearn.pipeline import make_pipeline
from sklearn.preprocessing import StandardScaler
from sklearn.exceptions import ConvergenceWarning

warnings.filterwarnings("ignore", category=ConvergenceWarning)

# ----------------------------
# Reproducibility
# ----------------------------
SEED = 42
random.seed(SEED)
np.random.seed(SEED)
rng = np.random.default_rng(SEED)

# ----------------------------
# Global config
# ----------------------------
OUTDIR = Path("part17_ambiguity_margin_test_artifacts")
OUTDIR.mkdir(parents=True, exist_ok=True)

# memory / geometry
N_ROOTS = 256
N_GROUPS = 64
ITEMS_PER_GROUP = 4
DIM = 32
N_CLUSTERS = 16

# ambiguity sweep: higher = more overlap / more confusing items
AMBIGUITIES = [0.10, 0.20, 0.30, 0.40]

# noise schedule
TRAIN_NOISES = [0.18, 0.28, 0.38]
TEST_NOISES = [0.18, 0.28, 0.38, 0.48]
TRAIN_QUERIES_PER_ITEM = 3
TEST_QUERIES_PER_ITEM = 2

# fixed best retrieval recipe from earlier runs
MAIN_OVERLAP_K = 3
MAIN_TOPK_ROOT = 10

# controller knobs
GUARD_MARGIN = 0.06
OVERWRITE_ALPHA = 0.10
REFINE_ALPHA = 0.12

# methods to compare
METHODS = [
    "flat_key_nn",
    "learned_linear_judge",
    "guarded_linear_judge",
    "mcltr_adaptive",
    "qdmn_refine1",
    "qdmn_refine2",
    "oracle_pool",
]

DISPLAY_METHODS = [
    "flat_key_nn",
    "learned_linear_judge",
    "guarded_linear_judge",
    "mcltr_adaptive",
    "qdmn_refine2",
    "oracle_pool",
]

# ----------------------------
# Helpers
# ----------------------------
def unit_rows(x: np.ndarray) -> np.ndarray:
    x = np.asarray(x, dtype=np.float64)
    if x.ndim == 1:
        x = x[None, :]
    n = np.linalg.norm(x, axis=-1, keepdims=True)
    return x / (n + 1e-12)

def normalize01(x: np.ndarray) -> np.ndarray:
    x = np.asarray(x, dtype=np.float64)
    mn, mx = float(np.min(x)), float(np.max(x))
    if abs(mx - mn) < 1e-12:
        return np.zeros_like(x, dtype=np.float64)
    return (x - mn) / (mx - mn)

def softmax(x: np.ndarray) -> np.ndarray:
    x = np.asarray(x, dtype=np.float64)
    x = x - np.max(x)
    e = np.exp(x)
    return e / (e.sum() + 1e-12)

def top2_margin(scores: np.ndarray) -> float:
    if len(scores) == 0:
        return -np.inf
    if len(scores) == 1:
        return np.inf
    order = np.argsort(-scores)
    return float(scores[order[0]] - scores[order[1]])

def make_random_roots(n_roots: int, dim: int) -> np.ndarray:
    return unit_rows(rng.normal(size=(n_roots, dim)))

def make_spiral_ortho_roots(n_roots: int, dim: int) -> np.ndarray:
    """
    Spiral lifted into a 2D subspace of the ambient space.
    This is the cleaner spiral variant to test against random.
    """
    t = np.arange(n_roots, dtype=np.float64)
    golden_angle = math.pi * (3 - math.sqrt(5))
    theta = t * golden_angle
    radius = np.sqrt((t + 0.5) / n_roots)
    base2 = np.stack([radius * np.cos(theta), radius * np.sin(theta)], axis=1)

    q, _ = np.linalg.qr(rng.normal(size=(dim, dim)))
    w = q[:2, :]  # 2 x dim
    roots = base2 @ w
    roots += 0.03 * rng.normal(size=roots.shape)
    return unit_rows(roots)

@dataclass
class Item:
    idx: int
    group: int
    cluster: int
    vec: np.ndarray
    assigned_roots: Optional[np.ndarray] = None

def make_items(
    n_groups: int,
    items_per_group: int,
    dim: int,
    n_clusters: int,
    ambiguity: float,
) -> List[Item]:
    """
    Higher ambiguity => groups are more cluster-like and more similar to each other.
    """
    cluster_proto = unit_rows(rng.normal(size=(n_clusters, dim)))
    group_proto = np.zeros((n_groups, dim), dtype=np.float64)

    # how much the group still keeps its own identity
    group_keep = 0.70 - 0.10 * ambiguity
    cluster_pull = 0.30 + 0.10 * ambiguity

    for g in range(n_groups):
        c = g % n_clusters
        group_proto[g] = unit_rows(
            (group_keep * rng.normal(size=dim) + cluster_pull * cluster_proto[c])[None, :]
        )[0]

    items: List[Item] = []
    idx = 0

    # higher ambiguity pushes items closer to the shared cluster prototype
    mix_to_cluster = 0.25 + 0.45 * ambiguity
    noise_scale = 0.08 + 0.12 * ambiguity

    for g in range(n_groups):
        c = g % n_clusters
        for _ in range(items_per_group):
            vec = (
                (1.0 - mix_to_cluster) * group_proto[g]
                + mix_to_cluster * cluster_proto[c]
                + noise_scale * rng.normal(size=dim)
            )
            vec = unit_rows(vec)[0]
            items.append(Item(idx=idx, group=g, cluster=c, vec=vec))
            idx += 1

    return items

def make_query(item: Item, noise: float) -> np.ndarray:
    q = item.vec + rng.normal(scale=noise, size=item.vec.shape)
    return unit_rows(q)[0]

# ----------------------------
# Index
# ----------------------------
class MemoryIndex:
    def __init__(self, roots: np.ndarray, overlap_k: int, topk_root: int):
        self.roots = unit_rows(roots)
        self.overlap_k = int(overlap_k)
        self.topk_root = int(topk_root)
        self.items: List[Item] = []
        self.item_mat: Optional[np.ndarray] = None
        self.root_to_items: Dict[int, List[int]] = defaultdict(list)

    def write(self, items: List[Item]) -> None:
        self.items = items
        self.item_mat = np.stack([it.vec for it in items], axis=0)
        sim = self.item_mat @ self.roots.T
        for i, it in enumerate(items):
            best_roots = np.argsort(-sim[i])[: self.overlap_k]
            it.assigned_roots = best_roots
            for r in best_roots:
                self.root_to_items[int(r)].append(i)

    def candidate_pool(
        self, q: np.ndarray, topk_root: Optional[int] = None
    ) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
        if topk_root is None:
            topk_root = self.topk_root
        q = unit_rows(q)[0]
        root_sim = self.roots @ q
        selected_roots = np.argsort(-root_sim)[: int(topk_root)]

        cand: List[int] = []
        for r in selected_roots:
            cand.extend(self.root_to_items.get(int(r), []))

        if len(cand) == 0:
            return np.array([], dtype=int), selected_roots, root_sim

        return np.unique(np.asarray(cand, dtype=int)), selected_roots, root_sim

# ----------------------------
# Query bank
# ----------------------------
def make_query_bank(
    index: MemoryIndex,
    item_ids: List[int],
    noises: List[float],
    queries_per_item: int,
) -> List[dict]:
    bank = []
    for item_id in item_ids:
        item = index.items[item_id]
        for noise in noises:
            for _ in range(queries_per_item):
                bank.append(
                    {
                        "item_idx": item.idx,
                        "group": item.group,
                        "cluster": item.cluster,
                        "noise": float(noise),
                        "q": make_query(item, noise=noise),
                        "clean_vec": item.vec.copy(),
                    }
                )
    rng.shuffle(bank)
    return bank

# ----------------------------
# Candidate features
# ----------------------------
def pool_features(
    index: MemoryIndex,
    q: np.ndarray,
    cand_idx: np.ndarray,
    selected_roots: np.ndarray,
) -> Tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray]:
    if len(cand_idx) == 0:
        empty = np.array([], dtype=np.float64)
        return np.zeros((0, 4), dtype=np.float64), empty, empty, empty, empty

    q = unit_rows(q)[0]
    cand_mat = index.item_mat[cand_idx]
    cosine = cand_mat @ q

    selected_roots_set = set(int(r) for r in selected_roots.tolist())
    root_support = []
    group_support = []
    local_density = []

    group_counts = defaultdict(int)
    for i in cand_idx.tolist():
        group_counts[index.items[i].group] += 1

    sim_mat = cand_mat @ cand_mat.T
    np.fill_diagonal(sim_mat, -1.0)

    for pos, i in enumerate(cand_idx.tolist()):
        item = index.items[i]
        assigned = set(int(r) for r in (item.assigned_roots.tolist() if item.assigned_roots is not None else []))
        rs = len(assigned.intersection(selected_roots_set)) / max(1, len(selected_roots_set))
        gs = group_counts[item.group] / max(1, len(cand_idx))

        row = sim_mat[pos]
        if len(row) >= 3:
            top3 = np.sort(row)[-3:]
            ld = float(np.mean(top3))
        else:
            ld = float(np.mean(row)) if len(row) else 0.0

        root_support.append(rs)
        group_support.append(gs)
        local_density.append(ld)

    root_support = np.asarray(root_support, dtype=np.float64)
    group_support = np.asarray(group_support, dtype=np.float64)
    local_density = np.asarray(local_density, dtype=np.float64)

    X = np.stack([cosine, root_support, group_support, local_density], axis=1)
    return X, cosine, root_support, group_support, local_density

def hard_negative_training_set(
    index: MemoryIndex,
    query_bank: List[dict],
    hard_negatives_per_query: int = 8,
) -> Tuple[np.ndarray, np.ndarray]:
    X_rows = []
    y_rows = []

    for rec in query_bank:
        cand_idx, selected_roots, _ = index.candidate_pool(rec["q"])
        if len(cand_idx) == 0:
            continue
        if rec["item_idx"] not in set(cand_idx.tolist()):
            continue

        X, base, _, _, _ = pool_features(index, rec["q"], cand_idx, selected_roots)
        pos_pos = int(np.where(cand_idx == rec["item_idx"])[0][0])

        neg_pos = np.where(cand_idx != rec["item_idx"])[0]
        if len(neg_pos) == 0:
            X_rows.append(X[pos_pos])
            y_rows.append(1)
            continue

        hard_order = np.argsort(-base[neg_pos])
        hard_take = neg_pos[hard_order[: min(hard_negatives_per_query, len(neg_pos))]]

        X_rows.append(X[pos_pos])
        y_rows.append(1)

        for j in hard_take:
            X_rows.append(X[j])
            y_rows.append(0)

    if len(X_rows) == 0:
        return np.zeros((0, 4), dtype=np.float64), np.zeros((0,), dtype=np.int64)

    return np.vstack(X_rows), np.asarray(y_rows, dtype=np.int64)

def train_judges(index: MemoryIndex, train_bank: List[dict]) -> Dict[str, object]:
    X, y = hard_negative_training_set(index, train_bank)
    if len(X) == 0:
        raise RuntimeError("No training data collected for judges.")

    linear = make_pipeline(
        StandardScaler(),
        LogisticRegression(
            max_iter=500,
            class_weight="balanced",
            random_state=SEED,
            solver="lbfgs",
        ),
    )
    linear.fit(X, y)

    pos = np.where(y == 1)[0]
    neg = np.where(y == 0)[0]
    n = min(len(pos), len(neg))
    pos_sel = rng.choice(pos, size=n, replace=len(pos) < n)
    neg_sel = rng.choice(neg, size=n, replace=len(neg) < n)
    idx = np.concatenate([pos_sel, neg_sel])
    rng.shuffle(idx)

    Xb = X[idx]
    yb = y[idx]

    mlp = make_pipeline(
        StandardScaler(),
        MLPClassifier(
            hidden_layer_sizes=(24, 12),
            activation="relu",
            alpha=1e-4,
            max_iter=400,
            early_stopping=True,
            n_iter_no_change=25,
            random_state=SEED,
        ),
    )
    mlp.fit(Xb, yb)

    return {"linear": linear, "mlp": mlp}

# ----------------------------
# Refinement / scoring
# ----------------------------
def blended_score(
    prob: np.ndarray,
    base: np.ndarray,
    root_support: np.ndarray,
    group_support: np.ndarray,
    local_density: np.ndarray,
) -> np.ndarray:
    b = normalize01(base)
    return (
        0.60 * prob
        + 0.18 * b
        + 0.10 * root_support
        + 0.07 * group_support
        + 0.05 * normalize01(local_density)
    )

def refine_query(
    q: np.ndarray,
    cand_mat: np.ndarray,
    guide_scores: np.ndarray,
    steps: int,
    alpha: float,
) -> np.ndarray:
    qn = unit_rows(q)[0].copy()
    if len(cand_mat) == 0:
        return qn

    k = min(3, len(cand_mat))
    guide_idx = np.argsort(-guide_scores)[:k]

    for _ in range(steps):
        weights = softmax(guide_scores[guide_idx])
        target = np.sum(cand_mat[guide_idx] * weights[:, None], axis=0)
        target = unit_rows(target)[0]
        qn = unit_rows(qn + alpha * target)[0]

    return qn

# ----------------------------
# Controller / selector
# ----------------------------
def choose_candidate(
    method: str,
    index: MemoryIndex,
    q: np.ndarray,
    clean_vec: np.ndarray,
    cand_idx: np.ndarray,
    selected_roots: np.ndarray,
    models: Dict[str, object],
    topk_root: int,
    guard_margin: float,
    overwrite_alpha: float,
    refine_alpha: float,
) -> Tuple[int, Dict[str, int]]:
    flags = {"overwrite": 0, "restart": 0, "refine": 0}

    if len(cand_idx) == 0:
        return -1, flags

    X, base, root_support, group_support, local_density = pool_features(index, q, cand_idx, selected_roots)
    linear_prob = models["linear"].predict_proba(X)[:, 1]
    mlp_prob = models["mlp"].predict_proba(X)[:, 1]

    if method == "oracle_pool":
        scores = index.item_mat[cand_idx] @ unit_rows(clean_vec)[0]
        return int(cand_idx[np.argmax(scores)]), flags

    if method == "flat_key_nn":
        return int(cand_idx[np.argmax(base)]), flags

    if method == "learned_linear_judge":
        return int(cand_idx[np.argmax(linear_prob)]), flags

    if method == "guarded_linear_judge":
        if top2_margin(linear_prob) >= guard_margin:
            return int(cand_idx[np.argmax(linear_prob)]), flags
        flags["overwrite"] = 1
        scores = blended_score(linear_prob, base, root_support, group_support, local_density)
        return int(cand_idx[np.argmax(scores)]), flags

    if method in {"mcltr_adaptive"}:
        order = np.argsort(-linear_prob)
        top1 = int(order[0])
        margin = float(linear_prob[order[0]] - linear_prob[order[1]]) if len(order) > 1 else 1.0

        if margin >= guard_margin:
            return int(cand_idx[top1]), flags
        elif margin >= guard_margin / 2.0:
            flags["overwrite"] = 1
            q2 = refine_query(q, index.item_mat[cand_idx], linear_prob, steps=1, alpha=overwrite_alpha)
            X2, base2, rs2, gs2, ld2 = pool_features(index, q2, cand_idx, selected_roots)
            lp2 = models["linear"].predict_proba(X2)[:, 1]
            scores = blended_score(lp2, base2, rs2, gs2, ld2)
            return int(cand_idx[np.argmax(scores)]), flags
        else:
            flags["restart"] = 1
            cand_idx2, selected_roots2, _ = index.candidate_pool(q, topk_root=topk_root + 3)
            if len(cand_idx2) > 0:
                X2, base2, rs2, gs2, ld2 = pool_features(index, q, cand_idx2, selected_roots2)
                lp2 = models["linear"].predict_proba(X2)[:, 1]
                scores = blended_score(lp2, base2, rs2, gs2, ld2)
                return int(cand_idx2[np.argmax(scores)]), flags
            return int(cand_idx[top1]), flags

    if method in {"qdmn_refine1", "qdmn_refine2"}:
        steps = 1 if method == "qdmn_refine1" else 2
        guide = linear_prob
        q2 = refine_query(q, index.item_mat[cand_idx], guide, steps=steps, alpha=refine_alpha)
        flags["refine"] = 1
        scores = index.item_mat[cand_idx] @ unit_rows(q2)[0]
        return int(cand_idx[np.argmax(scores)]), flags

    raise KeyError(f"Unknown method: {method}")

# ----------------------------
# Precompute same query bank for all methods
# ----------------------------
def precompute_bank(
    index: MemoryIndex,
    bank: List[dict],
    topk_root: int,
) -> List[dict]:
    out = []
    for rec in bank:
        cand_idx, selected_roots, _ = index.candidate_pool(rec["q"], topk_root=topk_root)
        X, base, root_support, group_support, local_density = pool_features(index, rec["q"], cand_idx, selected_roots)
        out.append(
            {
                **rec,
                "cand_idx": cand_idx,
                "selected_roots": selected_roots,
                "X": X,
                "base": base,
                "root_support": root_support,
                "group_support": group_support,
                "local_density": local_density,
                "base_margin": top2_margin(base),
                "pool_size": int(len(cand_idx)),
            }
        )
    return out

def assign_margin_bins(df: pd.DataFrame) -> pd.DataFrame:
    df = df.copy()
    df["margin_bin"] = "mid"

    for (placement, ambiguity), gidx in df.groupby(["placement", "ambiguity"]).groups.items():
        s = df.loc[gidx, "base_margin"].astype(float)

        # rank-first qcut avoids duplicate-edge failures
        try:
            bins = pd.qcut(s.rank(method="first"), q=3, labels=["low", "mid", "high"])
        except Exception:
            bins = pd.cut(s, bins=3, labels=["low", "mid", "high"], include_lowest=True)

        df.loc[gidx, "margin_bin"] = bins.astype(str).to_numpy()

    return df

# ----------------------------
# Evaluation
# ----------------------------
def evaluate_setting(
    placement: str,
    ambiguity: float,
    overlap_k: int,
    topk_root: int,
    train_noise_levels: List[float],
    test_noise_levels: List[float],
    train_queries_per_item: int,
    test_queries_per_item: int,
) -> Tuple[pd.DataFrame, Dict[str, object]]:
    roots = make_random_roots(N_ROOTS, DIM) if placement == "random" else make_spiral_ortho_roots(N_ROOTS, DIM)
    items = make_items(N_GROUPS, ITEMS_PER_GROUP, DIM, N_CLUSTERS, ambiguity=ambiguity)

    index = MemoryIndex(roots=roots, overlap_k=overlap_k, topk_root=topk_root)
    index.write(items)

    all_item_ids = np.arange(len(items))
    rng.shuffle(all_item_ids)
    split = int(0.70 * len(all_item_ids))
    train_ids = all_item_ids[:split].tolist()
    test_ids = all_item_ids[split:].tolist()

    train_bank = make_query_bank(index, train_ids, train_noise_levels, train_queries_per_item)
    models = train_judges(index, train_bank)

    test_rows = []
    for noise in test_noise_levels:
        test_bank = make_query_bank(index, test_ids, [noise], test_queries_per_item)
        prebank = precompute_bank(index, test_bank, topk_root=topk_root)

        for method in METHODS:
            for rec in prebank:
                chosen, flags = choose_candidate(
                    method=method,
                    index=index,
                    q=rec["q"],
                    clean_vec=rec["clean_vec"],
                    cand_idx=rec["cand_idx"],
                    selected_roots=rec["selected_roots"],
                    models=models,
                    topk_root=topk_root,
                    guard_margin=GUARD_MARGIN,
                    overwrite_alpha=OVERWRITE_ALPHA,
                    refine_alpha=REFINE_ALPHA,
                )

                correct_item = int(chosen == rec["item_idx"])
                correct_group = int(chosen >= 0 and index.items[chosen].group == rec["group"])

                test_rows.append(
                    {
                        "placement": placement,
                        "ambiguity": ambiguity,
                        "noise": noise,
                        "method": method,
                        "item_acc": correct_item,
                        "group_acc": correct_group,
                        "coverage": int(rec["item_idx"] in set(rec["cand_idx"].tolist())) if len(rec["cand_idx"]) > 0 else 0,
                        "avg_pool": rec["pool_size"],
                        "overwrite_rate": flags["overwrite"],
                        "restart_rate": flags["restart"],
                        "refine_rate": flags["refine"],
                        "base_margin": rec["base_margin"],
                        "margin_bin": None,  # filled later
                    }
                )

    df = pd.DataFrame(test_rows)
    df = assign_margin_bins(df)
    return df, {"index": index, "models": models, "train_bank": train_bank}

# ----------------------------
# Main
# ----------------------------
def main() -> pd.DataFrame:
    all_rows = []
    settings = {}

    print("Running ambiguity / margin-binned test...")

    for placement in ["random", "spiral_ortho"]:
        for ambiguity in AMBIGUITIES:
            df, pack = evaluate_setting(
                placement=placement,
                ambiguity=ambiguity,
                overlap_k=MAIN_OVERLAP_K,
                topk_root=MAIN_TOPK_ROOT,
                train_noise_levels=TRAIN_NOISES,
                test_noise_levels=TEST_NOISES,
                train_queries_per_item=TRAIN_QUERIES_PER_ITEM,
                test_queries_per_item=TEST_QUERIES_PER_ITEM,
            )
            all_rows.append(df)
            settings[(placement, ambiguity)] = pack

    main_df = pd.concat(all_rows, ignore_index=True)
    main_df.to_csv(OUTDIR / "results.csv", index=False)

    method_summary = (
        main_df.groupby(["placement", "ambiguity", "method"])[
            ["item_acc", "group_acc", "coverage", "avg_pool", "overwrite_rate", "restart_rate", "refine_rate"]
        ]
        .mean()
        .reset_index()
    )
    method_summary.to_csv(OUTDIR / "method_summary.csv", index=False)

    margin_summary = (
        main_df.groupby(["placement", "ambiguity", "margin_bin", "method"])[["item_acc", "group_acc", "coverage"]]
        .mean()
        .reset_index()
    )
    margin_summary.to_csv(OUTDIR / "margin_bin_summary.csv", index=False)

    # oracle gap table
    oracle = method_summary[method_summary["method"] == "oracle_pool"][["placement", "ambiguity", "item_acc"]].rename(
        columns={"item_acc": "oracle_acc"}
    )
    non_oracle = method_summary[method_summary["method"] != "oracle_pool"].merge(
        oracle, on=["placement", "ambiguity"], how="left"
    )
    non_oracle["oracle_gap"] = non_oracle["oracle_acc"] - non_oracle["item_acc"]
    best_non_oracle = (
        non_oracle.sort_values(["placement", "ambiguity", "item_acc"], ascending=[True, True, False])
        .groupby(["placement", "ambiguity"], as_index=False)
        .head(1)
        .reset_index(drop=True)
    )
    best_non_oracle.to_csv(OUTDIR / "best_non_oracle.csv", index=False)

    print("\n=== Overall mean by method ===")
    print(
        method_summary.groupby("method")[["item_acc", "group_acc", "coverage", "avg_pool"]]
        .mean()
        .sort_values("item_acc", ascending=False)
        .round(4)
        .to_string()
    )

    print("\n=== Mean by placement ===")
    print(
        method_summary.groupby("placement")[["item_acc", "group_acc", "coverage", "avg_pool"]]
        .mean()
        .round(4)
        .to_string()
    )

    print("\n=== Mean by ambiguity ===")
    print(
        method_summary.groupby("ambiguity")[["item_acc", "group_acc", "coverage", "avg_pool"]]
        .mean()
        .round(4)
        .to_string()
    )

    print("\n=== Best non-oracle per placement/ambiguity ===")
    print(
        best_non_oracle[
            ["placement", "ambiguity", "method", "item_acc", "oracle_acc", "oracle_gap", "coverage", "avg_pool"]
        ]
        .round(4)
        .sort_values(["placement", "ambiguity"])
        .to_string(index=False)
    )

    print("\n=== Margin-bin summary (random placement, hardest ambiguity) ===")
    hard_amb = max(AMBIGUITIES)
    show_margin = margin_summary[
        (margin_summary["placement"] == "random")
        & (margin_summary["ambiguity"] == hard_amb)
        & (margin_summary["method"].isin(DISPLAY_METHODS))
    ].copy()
    show_margin["margin_bin"] = pd.Categorical(show_margin["margin_bin"], ["low", "mid", "high"], ordered=True)
    print(
        show_margin.sort_values(["margin_bin", "item_acc"], ascending=[True, False])
        .loc[:, ["margin_bin", "method", "item_acc", "group_acc", "coverage"]]
        .round(4)
        .to_string(index=False)
    )

    # paper figure
    fig, axes = plt.subplots(2, 2, figsize=(15, 10), constrained_layout=True)

    # A: random placement
    ax = axes[0, 0]
    sub = method_summary[(method_summary["placement"] == "random") & (method_summary["method"].isin(DISPLAY_METHODS))]
    for m in DISPLAY_METHODS:
        d = sub[sub["method"] == m].sort_values("ambiguity")
        ax.plot(d["ambiguity"], d["item_acc"], marker="o", linewidth=2, label=m)
    ax.set_title("A. Random placement: accuracy vs ambiguity")
    ax.set_xlabel("Ambiguity")
    ax.set_ylabel("Item accuracy")
    ax.grid(True, alpha=0.25)
    ax.legend(fontsize=8, loc="best")

    # B: spiral_ortho
    ax = axes[0, 1]
    sub = method_summary[(method_summary["placement"] == "spiral_ortho") & (method_summary["method"].isin(DISPLAY_METHODS))]
    for m in DISPLAY_METHODS:
        d = sub[sub["method"] == m].sort_values("ambiguity")
        ax.plot(d["ambiguity"], d["item_acc"], marker="o", linewidth=2, label=m)
    ax.set_title("B. Spiral-ortho placement: accuracy vs ambiguity")
    ax.set_xlabel("Ambiguity")
    ax.set_ylabel("Item accuracy")
    ax.grid(True, alpha=0.25)
    ax.legend(fontsize=8, loc="best")

    # C: margin bins at hardest ambiguity
    ax = axes[1, 0]
    sub = margin_summary[
        (margin_summary["placement"] == "random")
        & (margin_summary["ambiguity"] == hard_amb)
        & (margin_summary["method"].isin(DISPLAY_METHODS))
    ].copy()
    for m in DISPLAY_METHODS:
        d = sub[sub["method"] == m].copy()
        if len(d) == 0:
            continue
        d["margin_bin"] = pd.Categorical(d["margin_bin"], ["low", "mid", "high"], ordered=True)
        d = d.sort_values("margin_bin")
        ax.plot(d["margin_bin"].astype(str), d["item_acc"], marker="o", linewidth=2, label=m)
    ax.set_title(f"C. Random placement: margin bins at ambiguity={hard_amb}")
    ax.set_xlabel("Base shortlist margin bin")
    ax.set_ylabel("Item accuracy")
    ax.grid(True, alpha=0.25)
    ax.legend(fontsize=8, loc="best")

    # D: oracle gap for best non-oracle
    ax = axes[1, 1]
    for placement in ["random", "spiral_ortho"]:
        d = best_non_oracle[best_non_oracle["placement"] == placement].sort_values("ambiguity")
        ax.plot(d["ambiguity"], d["oracle_gap"], marker="o", linewidth=2, label=placement)
    ax.set_title("D. Oracle gap of best non-oracle method")
    ax.set_xlabel("Ambiguity")
    ax.set_ylabel("Oracle gap")
    ax.grid(True, alpha=0.25)
    ax.legend(fontsize=8, loc="best")

    fig.suptitle("Part 17 — When does QDMN help: ambiguity, margin bins, and placement?", fontsize=14)
    fig.savefig(OUTDIR / "part17_summary_figure.png", dpi=220, bbox_inches="tight")
    plt.show()

    # compact final table for paper notes
    paper_preview = (
        best_non_oracle[
            ["placement", "ambiguity", "method", "item_acc", "oracle_acc", "oracle_gap", "coverage", "avg_pool"]
        ]
        .round(4)
        .sort_values(["placement", "ambiguity"])
    )
    paper_preview.to_csv(OUTDIR / "paper_preview.csv", index=False)

    print(f"\nSaved CSVs and figure to: {OUTDIR}")
    print("\n=== Paper preview ===")
    print(paper_preview.to_string(index=False))

    return main_df

if __name__ == "__main__":
    df = main()
    print("\nDone.")

# ============================================================
# PART 18 — Spiral vs Random Placement Sanity Sweep
# Tests whether spiral is worse because it covers a focused band,
# and whether that changes across different synthetic cases.
#
# Outputs:
# - root diagnostics table
# - per-case / per-placement / per-noise summary tables
# - best-method tables
# - one paper-style multi-panel figure
# - CSV artifacts
# ============================================================

from __future__ import annotations

import math
import random
import warnings
from dataclasses import dataclass
from collections import Counter, defaultdict
from pathlib import Path
from typing import Dict, List, Tuple, Optional

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt

from sklearn.linear_model import LogisticRegression
from sklearn.neural_network import MLPClassifier
from sklearn.pipeline import make_pipeline
from sklearn.preprocessing import StandardScaler
from sklearn.exceptions import ConvergenceWarning

warnings.filterwarnings("ignore", category=ConvergenceWarning)

# ----------------------------
# Reproducibility
# ----------------------------
SEED = 42
random.seed(SEED)
np.random.seed(SEED)
rng = np.random.default_rng(SEED)

# ----------------------------
# Output
# ----------------------------
OUTDIR = Path("part18_spiral_vs_random_sanity_artifacts")
OUTDIR.mkdir(parents=True, exist_ok=True)

# ----------------------------
# Global config
# ----------------------------
N_ROOTS = 256
N_GROUPS = 64
ITEMS_PER_GROUP = 4
DIM = 32
N_CLUSTERS = 16

TRAIN_NOISES = [0.12, 0.20, 0.28]
TEST_NOISES = [0.12, 0.20, 0.28, 0.38, 0.48]
TRAIN_QUERIES_PER_ITEM = 3
TEST_QUERIES_PER_ITEM = 2

OVERLAP_K = 3
TOPK_ROOT = 10

GUARD_MARGIN = 0.06
OVERWRITE_ALPHA = 0.10
REFINE_ALPHA = 0.12

HARD_NEGATIVES_PER_QUERY = 8

PLACEMENTS = ["random", "spiral_bad", "spiral_ortho"]
METHODS = [
    "flat_key_nn",
    "learned_linear_judge",
    "guarded_linear_judge",
    "mcltr_adaptive",
    "qdmn_refine1",
    "qdmn_refine2",
    "oracle_pool",
]

CASE_SPECS = {
    # Easy-ish, weakly clustered, moderate noise
    "separated": dict(
        group_strength=0.82,
        cluster_strength=0.10,
        shared_strength=0.00,
        item_noise=0.18,
        group_noise=0.10,
        cluster_noise=0.05,
        shared_noise=0.02,
    ),
    # Strong shared cluster structure
    "clustered": dict(
        group_strength=0.48,
        cluster_strength=0.34,
        shared_strength=0.00,
        item_noise=0.18,
        group_noise=0.12,
        cluster_noise=0.06,
        shared_noise=0.02,
    ),
    # Strong shared core -> high confusion
    "shared_core": dict(
        group_strength=0.36,
        cluster_strength=0.00,
        shared_strength=0.46,
        item_noise=0.18,
        group_noise=0.12,
        cluster_noise=0.04,
        shared_noise=0.04,
    ),
    # Low-dimensional latent manifold, where spiral might plausibly help
    "latent_manifold": dict(
        group_strength=0.00,
        cluster_strength=0.00,
        shared_strength=0.00,
        item_noise=0.14,
        group_noise=0.00,
        cluster_noise=0.00,
        shared_noise=0.00,
    ),
}

# ----------------------------
# Helpers
# ----------------------------
def unit_rows(x: np.ndarray) -> np.ndarray:
    x = np.asarray(x, dtype=np.float64)
    if x.ndim == 1:
        x = x[None, :]
    n = np.linalg.norm(x, axis=-1, keepdims=True)
    return x / (n + 1e-12)

def normalize01(x: np.ndarray) -> np.ndarray:
    x = np.asarray(x, dtype=np.float64)
    mn, mx = float(np.min(x)), float(np.max(x))
    if abs(mx - mn) < 1e-12:
        return np.zeros_like(x, dtype=np.float64)
    return (x - mn) / (mx - mn)

def softmax(x: np.ndarray) -> np.ndarray:
    x = np.asarray(x, dtype=np.float64)
    x = x - np.max(x)
    e = np.exp(x)
    return e / (e.sum() + 1e-12)

def entropy_norm(counts: np.ndarray) -> float:
    counts = np.asarray(counts, dtype=np.float64)
    p = counts[counts > 0]
    if len(p) == 0:
        return 0.0
    p = p / p.sum()
    h = -np.sum(p * np.log(p + 1e-12))
    return float(h / np.log(len(counts) + 1e-12))

def cosine_matrix(a: np.ndarray, b: np.ndarray) -> np.ndarray:
    return unit_rows(a) @ unit_rows(b).T

def make_random_roots(n_roots: int, dim: int) -> np.ndarray:
    return unit_rows(rng.normal(size=(n_roots, dim)))

def make_spiral_bad_roots(n_roots: int, dim: int) -> np.ndarray:
    """
    Spiral lifted into a random 2->D map.
    This is the most likely to be 'focused' or collapsed.
    """
    t = np.arange(n_roots, dtype=np.float64)
    golden_angle = math.pi * (3 - math.sqrt(5))
    theta = t * golden_angle
    radius = np.sqrt((t + 0.5) / n_roots)
    base2 = np.stack([radius * np.cos(theta), radius * np.sin(theta)], axis=1)
    W = rng.normal(size=(2, dim))
    roots = base2 @ W
    roots += 0.12 * rng.normal(size=roots.shape)
    return unit_rows(roots)

def make_spiral_ortho_roots(n_roots: int, dim: int) -> np.ndarray:
    """
    Spiral lifted into an orthonormal 2D subspace of R^D.
    Usually better spread than spiral_bad.
    """
    t = np.arange(n_roots, dtype=np.float64)
    golden_angle = math.pi * (3 - math.sqrt(5))
    theta = t * golden_angle
    radius = np.sqrt((t + 0.5) / n_roots)
    base2 = np.stack([radius * np.cos(theta), radius * np.sin(theta)], axis=1)

    q, _ = np.linalg.qr(rng.normal(size=(dim, 2)))   # q: (dim, 2)
    roots = base2 @ q.T                              # (n_roots, dim)
    roots += 0.03 * rng.normal(size=roots.shape)
    return unit_rows(roots)

def root_diagnostics(roots: np.ndarray) -> Dict[str, float]:
    roots = unit_rows(roots)
    sim = roots @ roots.T
    n = sim.shape[0]
    tri = sim[np.triu_indices(n, k=1)]
    nn = []
    for i in range(n):
        row = sim[i].copy()
        row[i] = -np.inf
        nn.append(np.max(row))
    return {
        "mean_pairwise_cos": float(np.mean(tri)),
        "std_pairwise_cos": float(np.std(tri)),
        "mean_nn_cos": float(np.mean(nn)),
        "std_nn_cos": float(np.std(nn)),
    }

@dataclass
class Item:
    idx: int
    group: int
    cluster: int
    vec: np.ndarray
    assigned_roots: Optional[np.ndarray] = None

def make_items(case_name: str, n_groups: int, items_per_group: int, dim: int, n_clusters: int) -> List[Item]:
    spec = CASE_SPECS[case_name]

    if case_name == "latent_manifold":
        # 2D latent manifold mapped into D
        latent = rng.uniform(-1.0, 1.0, size=(n_groups, 2))
        q, _ = np.linalg.qr(rng.normal(size=(dim, 2)))  # dim x 2
        group_proto = unit_rows(latent @ q.T)
        cluster_proto = unit_rows(rng.normal(size=(max(1, n_clusters), dim)))
        shared_proto = unit_rows(rng.normal(size=(dim,)))[0]
    else:
        cluster_proto = unit_rows(rng.normal(size=(n_clusters, dim)))
        shared_proto = unit_rows(rng.normal(size=(dim,)))[0]
        group_proto = np.zeros((n_groups, dim), dtype=np.float64)
        for g in range(n_groups):
            c = g % n_clusters
            vec = (
                spec["group_strength"] * rng.normal(size=dim)
                + spec["cluster_strength"] * cluster_proto[c]
                + spec["shared_strength"] * shared_proto
                + spec["group_noise"] * rng.normal(size=dim)
            )
            group_proto[g] = unit_rows(vec)[0]

    items: List[Item] = []
    idx = 0
    for g in range(n_groups):
        c = g % n_clusters
        for _ in range(items_per_group):
            if case_name == "latent_manifold":
                base = group_proto[g]
                vec = base + spec["item_noise"] * rng.normal(size=dim)
            else:
                vec = (
                    spec["group_strength"] * group_proto[g]
                    + spec["cluster_strength"] * cluster_proto[c]
                    + spec["shared_strength"] * shared_proto
                    + spec["item_noise"] * rng.normal(size=dim)
                )
            vec = unit_rows(vec)[0]
            items.append(Item(idx=idx, group=g, cluster=c, vec=vec))
            idx += 1

    return items

def make_query(item: Item, noise: float) -> np.ndarray:
    q = item.vec + rng.normal(scale=noise, size=item.vec.shape)
    return unit_rows(q)[0]

# ----------------------------
# Index
# ----------------------------
class MemoryIndex:
    def __init__(self, roots: np.ndarray, overlap_k: int, topk_root: int):
        self.roots = unit_rows(roots)
        self.overlap_k = int(overlap_k)
        self.topk_root = int(topk_root)
        self.items: List[Item] = []
        self.item_mat: Optional[np.ndarray] = None
        self.root_to_items: Dict[int, List[int]] = defaultdict(list)

    def write(self, items: List[Item]) -> None:
        self.items = items
        self.item_mat = np.stack([it.vec for it in items], axis=0)
        sim = self.item_mat @ self.roots.T
        for i, it in enumerate(items):
            best_roots = np.argsort(-sim[i])[: self.overlap_k]
            it.assigned_roots = best_roots
            for r in best_roots:
                self.root_to_items[int(r)].append(i)

    def candidate_pool(self, q: np.ndarray, topk_root: Optional[int] = None) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
        if topk_root is None:
            topk_root = self.topk_root
        q = unit_rows(q)[0]
        root_sim = self.roots @ q
        selected_roots = np.argsort(-root_sim)[: int(topk_root)]

        cand: List[int] = []
        for r in selected_roots:
            cand.extend(self.root_to_items.get(int(r), []))

        if len(cand) == 0:
            return np.array([], dtype=int), selected_roots, root_sim
        return np.unique(np.asarray(cand, dtype=int)), selected_roots, root_sim

    def assignment_diagnostics(self) -> Dict[str, float]:
        counts = np.zeros(len(self.roots), dtype=np.int64)
        for ridx, lst in self.root_to_items.items():
            counts[ridx] = len(lst)
        return {
            "assigned_total": int(counts.sum()),
            "assigned_nonzero": int(np.sum(counts > 0)),
            "assignment_entropy": entropy_norm(counts),
            "assignment_cv": float(np.std(counts) / (np.mean(counts) + 1e-12)),
        }

# ----------------------------
# Query banks
# ----------------------------
def make_query_bank(
    index: MemoryIndex,
    item_ids: List[int],
    noises: List[float],
    queries_per_item: int,
) -> List[dict]:
    bank = []
    for item_id in item_ids:
        item = index.items[item_id]
        for noise in noises:
            for _ in range(queries_per_item):
                bank.append(
                    {
                        "item_idx": item.idx,
                        "group": item.group,
                        "cluster": item.cluster,
                        "noise": float(noise),
                        "q": make_query(item, noise=noise),
                        "clean_vec": item.vec.copy(),
                    }
                )
    rng.shuffle(bank)
    return bank

# ----------------------------
# Features / training
# ----------------------------
def pool_features(
    index: MemoryIndex,
    q: np.ndarray,
    cand_idx: np.ndarray,
    selected_roots: np.ndarray,
) -> Tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray]:
    if len(cand_idx) == 0:
        empty = np.array([], dtype=np.float64)
        return np.zeros((0, 4), dtype=np.float64), empty, empty, empty, empty

    q = unit_rows(q)[0]
    cand_mat = index.item_mat[cand_idx]
    cosine = cand_mat @ q

    selected_roots_set = set(int(r) for r in selected_roots.tolist())
    root_support = []
    group_support = []
    local_density = []

    group_counts = Counter(index.items[i].group for i in cand_idx.tolist())
    sim_mat = cand_mat @ cand_mat.T
    np.fill_diagonal(sim_mat, -1.0)

    for pos, i in enumerate(cand_idx.tolist()):
        item = index.items[i]
        assigned = set(int(r) for r in (item.assigned_roots.tolist() if item.assigned_roots is not None else []))
        rs = len(assigned.intersection(selected_roots_set)) / max(1, len(selected_roots_set))
        gs = group_counts[item.group] / max(1, len(cand_idx))
        row = sim_mat[pos]
        if len(row) >= 3:
            top3 = np.sort(row)[-3:]
            ld = float(np.mean(top3))
        else:
            ld = float(np.mean(row)) if len(row) else 0.0
        root_support.append(rs)
        group_support.append(gs)
        local_density.append(ld)

    root_support = np.asarray(root_support, dtype=np.float64)
    group_support = np.asarray(group_support, dtype=np.float64)
    local_density = np.asarray(local_density, dtype=np.float64)

    X = np.stack([cosine, root_support, group_support, local_density], axis=1)
    return X, cosine, root_support, group_support, local_density

def hard_negative_training_set(
    index: MemoryIndex,
    query_bank: List[dict],
    hard_negatives_per_query: int = HARD_NEGATIVES_PER_QUERY,
    max_queries: Optional[int] = None,
) -> Tuple[np.ndarray, np.ndarray]:
    X_rows = []
    y_rows = []

    if max_queries is not None and len(query_bank) > max_queries:
        query_bank = query_bank[:max_queries]

    for rec in query_bank:
        cand_idx, selected_roots, _ = index.candidate_pool(rec["q"])
        if len(cand_idx) == 0:
            continue
        if rec["item_idx"] not in set(cand_idx.tolist()):
            continue

        X, cosine, _, _, _ = pool_features(index, rec["q"], cand_idx, selected_roots)
        pos_pos = int(np.where(cand_idx == rec["item_idx"])[0][0])
        neg_pos = np.where(cand_idx != rec["item_idx"])[0]

        X_rows.append(X[pos_pos])
        y_rows.append(1)

        if len(neg_pos) == 0:
            continue

        neg_scores = cosine[neg_pos]
        hard_order = np.argsort(-neg_scores)
        hard_take = neg_pos[hard_order[: min(hard_negatives_per_query, len(neg_pos))]]

        for j in hard_take:
            X_rows.append(X[j])
            y_rows.append(0)

    if len(X_rows) == 0:
        return np.zeros((0, 4), dtype=np.float64), np.zeros((0,), dtype=np.int64)

    return np.vstack(X_rows), np.asarray(y_rows, dtype=np.int64)

def train_judges(index: MemoryIndex, train_bank: List[dict]) -> Dict[str, object]:
    X, y = hard_negative_training_set(index, train_bank)
    if len(X) == 0:
        raise RuntimeError("No training data collected.")

    linear = make_pipeline(
        StandardScaler(),
        LogisticRegression(
            max_iter=500,
            class_weight="balanced",
            random_state=SEED,
            solver="lbfgs",
        ),
    )
    linear.fit(X, y)

    # balanced MLP
    pos = np.where(y == 1)[0]
    neg = np.where(y == 0)[0]
    n = min(len(pos), len(neg))
    pos_sel = rng.choice(pos, size=n, replace=len(pos) < n)
    neg_sel = rng.choice(neg, size=n, replace=len(neg) < n)
    idx = np.concatenate([pos_sel, neg_sel])
    rng.shuffle(idx)

    Xb = X[idx]
    yb = y[idx]

    mlp = make_pipeline(
        StandardScaler(),
        MLPClassifier(
            hidden_layer_sizes=(24, 12),
            activation="relu",
            alpha=1e-4,
            max_iter=500,
            early_stopping=True,
            n_iter_no_change=25,
            random_state=SEED,
        ),
    )
    mlp.fit(Xb, yb)

    return {"linear": linear, "mlp": mlp}

# ----------------------------
# Controllers
# ----------------------------
def top2_margin(scores: np.ndarray) -> float:
    if len(scores) == 0:
        return -np.inf
    if len(scores) == 1:
        return np.inf
    order = np.argsort(-scores)
    return float(scores[order[0]] - scores[order[1]])

def blended_score(
    prob: np.ndarray,
    base: np.ndarray,
    root_support: np.ndarray,
    group_support: np.ndarray,
    local_density: np.ndarray,
) -> np.ndarray:
    b = normalize01(base)
    return (
        0.60 * prob
        + 0.18 * b
        + 0.10 * root_support
        + 0.07 * group_support
        + 0.05 * normalize01(local_density)
    )

def refine_query(
    q: np.ndarray,
    cand_mat: np.ndarray,
    guide_scores: np.ndarray,
    steps: int,
    alpha: float,
) -> np.ndarray:
    qn = unit_rows(q)[0].copy()
    if len(cand_mat) == 0:
        return qn

    k = min(3, len(cand_mat))
    guide_idx = np.argsort(-guide_scores)[:k]
    for _ in range(steps):
        weights = softmax(guide_scores[guide_idx])
        target = np.sum(cand_mat[guide_idx] * weights[:, None], axis=0)
        target = unit_rows(target)[0]
        qn = unit_rows(qn + alpha * target)[0]
    return qn

def choose_candidate(
    method: str,
    index: MemoryIndex,
    q: np.ndarray,
    clean_vec: np.ndarray,
    cand_idx: np.ndarray,
    selected_roots: np.ndarray,
    models: Dict[str, object],
    topk_root: int,
    guard_margin: float,
    overwrite_alpha: float,
    refine_alpha: float,
) -> Tuple[int, Dict[str, int]]:
    flags = {"overwrite": 0, "restart": 0, "refine": 0}

    if len(cand_idx) == 0:
        return -1, flags

    X, base, root_support, group_support, local_density = pool_features(index, q, cand_idx, selected_roots)
    linear_prob = models["linear"].predict_proba(X)[:, 1]
    mlp_prob = models["mlp"].predict_proba(X)[:, 1]

    if method == "oracle_pool":
        scores = index.item_mat[cand_idx] @ unit_rows(clean_vec)[0]
        return int(cand_idx[np.argmax(scores)]), flags

    if method == "flat_key_nn":
        return int(cand_idx[np.argmax(base)]), flags

    if method == "learned_linear_judge":
        return int(cand_idx[np.argmax(linear_prob)]), flags

    if method == "guarded_linear_judge":
        if top2_margin(linear_prob) >= guard_margin:
            return int(cand_idx[np.argmax(linear_prob)]), flags
        flags["overwrite"] = 1
        scores = blended_score(linear_prob, base, root_support, group_support, local_density)
        return int(cand_idx[np.argmax(scores)]), flags

    if method == "mcltr_adaptive":
        order = np.argsort(-linear_prob)
        top1 = int(order[0])
        margin = float(linear_prob[order[0]] - linear_prob[order[1]]) if len(order) > 1 else 1.0

        if margin >= guard_margin:
            return int(cand_idx[top1]), flags
        elif margin >= guard_margin / 2.0:
            flags["overwrite"] = 1
            q2 = refine_query(q, index.item_mat[cand_idx], linear_prob, steps=1, alpha=overwrite_alpha)
            X2, base2, rs2, gs2, ld2 = pool_features(index, q2, cand_idx, selected_roots)
            lp2 = models["linear"].predict_proba(X2)[:, 1]
            scores = blended_score(lp2, base2, rs2, gs2, ld2)
            return int(cand_idx[np.argmax(scores)]), flags
        else:
            flags["restart"] = 1
            cand_idx2, selected_roots2, _ = index.candidate_pool(q, topk_root=topk_root + 3)
            if len(cand_idx2) > 0:
                X2, base2, rs2, gs2, ld2 = pool_features(index, q, cand_idx2, selected_roots2)
                lp2 = models["linear"].predict_proba(X2)[:, 1]
                scores = blended_score(lp2, base2, rs2, gs2, ld2)
                return int(cand_idx2[np.argmax(scores)]), flags
            return int(cand_idx[top1]), flags

    if method in {"qdmn_refine1", "qdmn_refine2"}:
        steps = 1 if method == "qdmn_refine1" else 2
        X0, _, _, _, _ = pool_features(index, q, cand_idx, selected_roots)
        guide = models["linear"].predict_proba(X0)[:, 1]
        q2 = refine_query(q, index.item_mat[cand_idx], guide, steps=steps, alpha=refine_alpha)
        flags["refine"] = 1
        scores = index.item_mat[cand_idx] @ unit_rows(q2)[0]
        return int(cand_idx[np.argmax(scores)]), flags

    raise KeyError(f"Unknown method: {method}")

# ----------------------------
# Evaluation
# ----------------------------
def evaluate_methods(
    index: MemoryIndex,
    models: Dict[str, object],
    query_bank: List[dict],
    methods: List[str],
    topk_root: int,
    guard_margin: float,
    overwrite_alpha: float,
    refine_alpha: float,
) -> pd.DataFrame:
    rows = []
    for method in methods:
        item_hits = 0
        group_hits = 0
        coverage_hits = 0
        avg_pool = 0.0
        overwrite_count = 0
        restart_count = 0
        refine_count = 0

        for rec in query_bank:
            q = rec["q"]
            item_idx = rec["item_idx"]
            clean_vec = rec["clean_vec"]

            cand_idx, selected_roots, _ = index.candidate_pool(q, topk_root=topk_root)
            avg_pool += len(cand_idx)
            if len(cand_idx) > 0:
                coverage_hits += int(item_idx in set(cand_idx.tolist()))

            chosen, flags = choose_candidate(
                method=method,
                index=index,
                q=q,
                clean_vec=clean_vec,
                cand_idx=cand_idx,
                selected_roots=selected_roots,
                models=models,
                topk_root=topk_root,
                guard_margin=guard_margin,
                overwrite_alpha=overwrite_alpha,
                refine_alpha=refine_alpha,
            )

            overwrite_count += flags["overwrite"]
            restart_count += flags["restart"]
            refine_count += flags["refine"]

            if chosen == item_idx:
                item_hits += 1
            if chosen >= 0 and index.items[chosen].group == rec["group"]:
                group_hits += 1

        n = len(query_bank)
        rows.append(
            {
                "method": method,
                "item_acc": item_hits / n,
                "group_acc": group_hits / n,
                "coverage": coverage_hits / n,
                "avg_pool": avg_pool / n,
                "overwrite_rate": overwrite_count / n,
                "restart_rate": restart_count / n,
                "refine_rate": refine_count / n,
            }
        )
    return pd.DataFrame(rows)

def run_case(
    case_name: str,
    placement: str,
    overlap_k: int,
    topk_root: int,
    train_noise_levels: List[float],
    test_noise_levels: List[float],
    train_queries_per_item: int,
    test_queries_per_item: int,
    guard_margin: float = GUARD_MARGIN,
    overwrite_alpha: float = OVERWRITE_ALPHA,
    refine_alpha: float = REFINE_ALPHA,
) -> Tuple[pd.DataFrame, Dict[str, object], MemoryIndex]:
    if placement == "random":
        roots = make_random_roots(N_ROOTS, DIM)
    elif placement == "spiral_bad":
        roots = make_spiral_bad_roots(N_ROOTS, DIM)
    elif placement == "spiral_ortho":
        roots = make_spiral_ortho_roots(N_ROOTS, DIM)
    else:
        raise KeyError(placement)

    items = make_items(case_name, N_GROUPS, ITEMS_PER_GROUP, DIM, N_CLUSTERS)
    index = MemoryIndex(roots=roots, overlap_k=overlap_k, topk_root=topk_root)
    index.write(items)

    all_ids = np.arange(len(items))
    rng.shuffle(all_ids)
    split = int(0.70 * len(all_ids))
    train_ids = all_ids[:split].tolist()
    test_ids = all_ids[split:].tolist()

    train_bank = make_query_bank(index, train_ids, train_noise_levels, train_queries_per_item)
    models = train_judges(index, train_bank)

    all_rows = []
    for noise in test_noise_levels:
        test_bank = make_query_bank(index, test_ids, [noise], test_queries_per_item)
        df_noise = evaluate_methods(
            index=index,
            models=models,
            query_bank=test_bank,
            methods=METHODS,
            topk_root=topk_root,
            guard_margin=guard_margin,
            overwrite_alpha=overwrite_alpha,
            refine_alpha=refine_alpha,
        )
        df_noise["case"] = case_name
        df_noise["placement"] = placement
        df_noise["noise"] = float(noise)
        df_noise["overlap_k"] = overlap_k
        df_noise["topk_root"] = topk_root
        all_rows.append(df_noise)

    return pd.concat(all_rows, ignore_index=True), models, index

# ----------------------------
# Main sweep
# ----------------------------
def main() -> pd.DataFrame:
    rows = []
    root_rows = []

    print("Running placement / case sweep...")

    for case_name in CASE_SPECS.keys():
        for placement in PLACEMENTS:
            df, models, index = run_case(
                case_name=case_name,
                placement=placement,
                overlap_k=OVERLAP_K,
                topk_root=TOPK_ROOT,
                train_noise_levels=TRAIN_NOISES,
                test_noise_levels=TEST_NOISES,
                train_queries_per_item=TRAIN_QUERIES_PER_ITEM,
                test_queries_per_item=TEST_QUERIES_PER_ITEM,
            )
            rows.append(df)

            rd = root_diagnostics(index.roots)
            ad = index.assignment_diagnostics()
            root_rows.append(
                {
                    "case": case_name,
                    "placement": placement,
                    **rd,
                    **ad,
                }
            )

    df = pd.concat(rows, ignore_index=True)
    root_df = pd.DataFrame(root_rows)

    df.to_csv(OUTDIR / "main_results.csv", index=False)
    root_df.to_csv(OUTDIR / "root_diagnostics.csv", index=False)

    # ------------------------
    # Summary tables
    # ------------------------
    print("\n=== Root diagnostics ===")
    print(
        root_df.round(4)
        .sort_values(["case", "placement"])
        .to_string(index=False)
    )

    print("\n=== Overall mean by method ===")
    print(
        df.groupby("method")[["item_acc", "group_acc", "coverage", "avg_pool"]]
        .mean()
        .sort_values("item_acc", ascending=False)
        .round(4)
        .to_string()
    )

    print("\n=== Mean by case ===")
    print(
        df.groupby("case")[["item_acc", "group_acc", "coverage", "avg_pool"]]
        .mean()
        .round(4)
        .to_string()
    )

    print("\n=== Mean by placement ===")
    print(
        df.groupby("placement")[["item_acc", "group_acc", "coverage", "avg_pool"]]
        .mean()
        .round(4)
        .to_string()
    )

    print("\n=== Mean by case x placement ===")
    case_place = (
        df.groupby(["case", "placement"])[["item_acc", "group_acc", "coverage", "avg_pool"]]
        .mean()
        .reset_index()
        .sort_values(["case", "item_acc"], ascending=[True, False])
    )
    print(case_place.round(4).to_string(index=False))

    # best non-oracle per case / placement / noise
    non_oracle = df[df["method"] != "oracle_pool"].copy()
    best = (
        non_oracle.sort_values(["case", "placement", "noise", "item_acc"], ascending=[True, True, True, False])
        .groupby(["case", "placement", "noise"], as_index=False)
        .head(1)
        .loc[:, ["case", "placement", "noise", "method", "item_acc", "coverage", "avg_pool", "overwrite_rate", "restart_rate", "refine_rate"]]
        .reset_index(drop=True)
    )
    best.to_csv(OUTDIR / "best_by_case_placement_noise.csv", index=False)

    print("\n=== Best non-oracle per case / placement / noise ===")
    print(best.round(4).to_string(index=False))

    # margin bins for the hardest noise, to isolate ambiguity
    hard_noise = max(TEST_NOISES)
    print(f"\nRunning margin-bin summary at hard noise={hard_noise}...")

    # Build one representative run for random and spiral_ortho on the hardest noise
    margin_rows = []
    for placement in ["random", "spiral_ortho"]:
        case_name = "shared_core"
        df_case, models, index = run_case(
            case_name=case_name,
            placement=placement,
            overlap_k=OVERLAP_K,
            topk_root=TOPK_ROOT,
            train_noise_levels=TRAIN_NOISES,
            test_noise_levels=[hard_noise],
            train_queries_per_item=TRAIN_QUERIES_PER_ITEM,
            test_queries_per_item=TEST_QUERIES_PER_ITEM,
        )

        # rebuild the same test bank to score margins
        all_ids = np.arange(len(index.items))
        rng.shuffle(all_ids)
        split = int(0.70 * len(all_ids))
        test_ids = all_ids[split:].tolist()
        test_bank = make_query_bank(index, test_ids, [hard_noise], TEST_QUERIES_PER_ITEM)

        # margin bins using linear judge scores
        per_query = []
        for rec in test_bank:
            cand_idx, selected_roots, _ = index.candidate_pool(rec["q"], topk_root=TOPK_ROOT)
            if len(cand_idx) == 0:
                continue
            X, base, _, _, _ = pool_features(index, rec["q"], cand_idx, selected_roots)
            lp = models["linear"].predict_proba(X)[:, 1]
            margin = top2_margin(lp)
            oracle_scores = index.item_mat[cand_idx] @ unit_rows(rec["clean_vec"])[0]
            oracle_choice = int(cand_idx[np.argmax(oracle_scores)])
            per_query.append(
                {
                    "margin": margin,
                    "item_idx": rec["item_idx"],
                    "group": rec["group"],
                    "cand_idx": cand_idx,
                    "selected_roots": selected_roots,
                    "q": rec["q"],
                    "clean_vec": rec["clean_vec"],
                    "oracle_choice": oracle_choice,
                    "lp": lp,
                    "base": base,
                }
            )

        if len(per_query) == 0:
            continue

        margins = np.array([r["margin"] for r in per_query])
        bins = np.quantile(margins, [0.0, 0.33, 0.66, 1.0])
        labels = ["low", "mid", "high"]

        for i, label in enumerate(labels):
            lo, hi = bins[i], bins[i + 1]
            if i < 2:
                subset = [r for r in per_query if (r["margin"] >= lo and r["margin"] < hi)]
            else:
                subset = [r for r in per_query if (r["margin"] >= lo and r["margin"] <= hi)]
            if len(subset) == 0:
                continue

            for method in ["flat_key_nn", "learned_linear_judge", "guarded_linear_judge", "mcltr_adaptive", "qdmn_refine2", "oracle_pool"]:
                hits = 0
                group_hits = 0
                cov = 0
                for r in subset:
                    cand_idx = r["cand_idx"]
                    selected_roots = r["selected_roots"]
                    q = r["q"]
                    clean_vec = r["clean_vec"]
                    item_idx = r["item_idx"]
                    cov += int(item_idx in set(cand_idx.tolist()))
                    chosen, _ = choose_candidate(
                        method=method,
                        index=index,
                        q=q,
                        clean_vec=clean_vec,
                        cand_idx=cand_idx,
                        selected_roots=selected_roots,
                        models=models,
                        topk_root=TOPK_ROOT,
                        guard_margin=GUARD_MARGIN,
                        overwrite_alpha=OVERWRITE_ALPHA,
                        refine_alpha=REFINE_ALPHA,
                    )
                    if chosen == item_idx:
                        hits += 1
                    if chosen >= 0 and index.items[chosen].group == r["group"]:
                        group_hits += 1

                margin_rows.append(
                    {
                        "placement": placement,
                        "case": case_name,
                        "margin_bin": label,
                        "method": method,
                        "item_acc": hits / len(subset),
                        "group_acc": group_hits / len(subset),
                        "coverage": cov / len(subset),
                    }
                )

    margin_df = pd.DataFrame(margin_rows)
    margin_df.to_csv(OUTDIR / "margin_bin_summary.csv", index=False)

    print("\n=== Margin-bin summary (hard ambiguity) ===")
    print(
        margin_df.sort_values(["placement", "margin_bin", "item_acc"], ascending=[True, True, False])
        .round(4)
        .to_string(index=False)
    )

    # ------------------------
    # Paper preview
    # ------------------------
    paper_preview = (
        df.groupby(["case", "placement", "method"])[["item_acc", "group_acc", "coverage", "avg_pool"]]
        .mean()
        .reset_index()
        .sort_values(["case", "item_acc"], ascending=[True, False])
    )
    paper_preview.to_csv(OUTDIR / "paper_preview.csv", index=False)

    print("\n=== Paper preview ===")
    print(paper_preview.round(4).to_string(index=False))

    # ------------------------
    # Figure: 2x2 summary
    # ------------------------
    fig, axes = plt.subplots(2, 2, figsize=(16, 11), constrained_layout=True)

    # A: root spread diagnostics
    ax = axes[0, 0]
    diag = root_df.copy()
    xlabels = [f"{c}\n{p}" for c, p in zip(diag["case"], diag["placement"])]
    ax.bar(range(len(diag)), diag["mean_pairwise_cos"].values)
    ax.set_xticks(range(len(diag)))
    ax.set_xticklabels(xlabels, rotation=25, ha="right")
    ax.set_title("A. Root spread: mean pairwise cosine")
    ax.set_ylabel("Higher = more concentrated")
    ax.grid(True, axis="y", alpha=0.2)

    # B: assignment entropy
    ax = axes[0, 1]
    ax.bar(range(len(diag)), diag["assignment_entropy"].values)
    ax.set_xticks(range(len(diag)))
    ax.set_xticklabels(xlabels, rotation=25, ha="right")
    ax.set_title("B. Root usage entropy")
    ax.set_ylabel("1.0 = uniform usage")
    ax.grid(True, axis="y", alpha=0.2)

    # C: accuracy vs noise on shared_core
    ax = axes[1, 0]
    sub = df[(df["case"] == "shared_core") & (df["method"].isin(["flat_key_nn", "learned_linear_judge", "guarded_linear_judge", "mcltr_adaptive", "qdmn_refine2", "oracle_pool"]))]
    for m in ["flat_key_nn", "learned_linear_judge", "guarded_linear_judge", "mcltr_adaptive", "qdmn_refine2", "oracle_pool"]:
        d = sub[sub["method"] == m].sort_values("noise")
        ax.plot(d["noise"], d["item_acc"], marker="o", linewidth=2, label=m)
    ax.set_title("C. Shared-core case: accuracy vs noise")
    ax.set_xlabel("Noise")
    ax.set_ylabel("Item accuracy")
    ax.grid(True, alpha=0.25)
    ax.legend(fontsize=7, loc="best")

    # D: accuracy vs noise on latent_manifold
    ax = axes[1, 1]
    sub = df[(df["case"] == "latent_manifold") & (df["method"].isin(["flat_key_nn", "learned_linear_judge", "guarded_linear_judge", "mcltr_adaptive", "qdmn_refine2", "oracle_pool"]))]
    for m in ["flat_key_nn", "learned_linear_judge", "guarded_linear_judge", "mcltr_adaptive", "qdmn_refine2", "oracle_pool"]:
        d = sub[sub["method"] == m].sort_values("noise")
        ax.plot(d["noise"], d["item_acc"], marker="o", linewidth=2, label=m)
    ax.set_title("D. Latent-manifold case: accuracy vs noise")
    ax.set_xlabel("Noise")
    ax.set_ylabel("Item accuracy")
    ax.grid(True, alpha=0.25)
    ax.legend(fontsize=7, loc="best")

    fig.suptitle("Part 18 — Random vs spiral placements across multiple data regimes", fontsize=14)
    fig.savefig(OUTDIR / "part18_summary_figure.png", dpi=220, bbox_inches="tight")
    plt.show()

    print(f"\nSaved artifacts to: {OUTDIR}")
    return df

if __name__ == "__main__":
    df = main()
    print("\nDone.")

# ============================================================
# PART 19 — Spiral Geometry + QDMN Last-Mile Test
# Tests:
# 1) random vs spiral_bad vs spiral_ortho vs spiral_pca
# 2) multiple synthetic cases
# 3) whether QDMN helps mainly in low-margin ambiguity
# Outputs:
# - root diagnostics
# - case/placement/noise summaries
# - best non-oracle tables
# - margin-bin summary for QDMN gain
# - one paper-style 2x2 figure
# - CSV artifacts
# ============================================================

from __future__ import annotations

import math
import random
import warnings
from dataclasses import dataclass
from collections import Counter, defaultdict
from pathlib import Path
from typing import Dict, List, Tuple, Optional

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt

from sklearn.linear_model import LogisticRegression
from sklearn.pipeline import make_pipeline
from sklearn.preprocessing import StandardScaler
from sklearn.exceptions import ConvergenceWarning

warnings.filterwarnings("ignore", category=ConvergenceWarning)

# ----------------------------
# Reproducibility
# ----------------------------
SEED = 42
random.seed(SEED)
np.random.seed(SEED)
rng = np.random.default_rng(SEED)

# ----------------------------
# Output
# ----------------------------
OUTDIR = Path("part19_spiral_qdmn_final_artifacts")
OUTDIR.mkdir(parents=True, exist_ok=True)

# ----------------------------
# Global config
# ----------------------------
N_ROOTS = 256
N_GROUPS = 64
ITEMS_PER_GROUP = 4
DIM = 32
N_CLUSTERS = 16

TRAIN_NOISES = [0.12, 0.20, 0.28]
TEST_NOISES = [0.12, 0.20, 0.28, 0.38, 0.48]
TRAIN_QUERIES_PER_ITEM = 3
TEST_QUERIES_PER_ITEM = 2

OVERLAP_K = 3
TOPK_ROOT = 10

GUARD_MARGIN = 0.06
OVERWRITE_ALPHA = 0.10
REFINE_ALPHA = 0.12

HARD_NEGATIVES_PER_QUERY = 8

PLACEMENTS = ["random", "spiral_bad", "spiral_ortho", "spiral_pca"]
METHODS = [
    "flat_key_nn",
    "learned_linear_judge",
    "guarded_linear_judge",
    "mcltr_adaptive",
    "qdmn_refine1",
    "qdmn_refine2",
    "oracle_pool",
]

CASE_SPECS = {
    "separated": dict(
        group_mix=0.78,
        cluster_mix=0.05,
        shared_mix=0.00,
        item_noise=0.14,
        group_noise=0.05,
        cluster_noise=0.03,
        shared_noise=0.01,
        latent=False,
    ),
    "clustered": dict(
        group_mix=0.48,
        cluster_mix=0.32,
        shared_mix=0.00,
        item_noise=0.16,
        group_noise=0.08,
        cluster_noise=0.05,
        shared_noise=0.01,
        latent=False,
    ),
    "shared_core": dict(
        group_mix=0.26,
        cluster_mix=0.00,
        shared_mix=0.56,
        item_noise=0.16,
        group_noise=0.10,
        cluster_noise=0.00,
        shared_noise=0.04,
        latent=False,
    ),
    "latent_manifold": dict(
        group_mix=0.00,
        cluster_mix=0.00,
        shared_mix=0.00,
        item_noise=0.12,
        group_noise=0.00,
        cluster_noise=0.00,
        shared_noise=0.00,
        latent=True,
    ),
}

# ----------------------------
# Helpers
# ----------------------------
def unit_rows(x: np.ndarray) -> np.ndarray:
    x = np.asarray(x, dtype=np.float64)
    if x.ndim == 1:
        x = x[None, :]
    n = np.linalg.norm(x, axis=-1, keepdims=True)
    return x / (n + 1e-12)

def normalize01(x: np.ndarray) -> np.ndarray:
    x = np.asarray(x, dtype=np.float64)
    mn, mx = float(np.min(x)), float(np.max(x))
    if abs(mx - mn) < 1e-12:
        return np.zeros_like(x, dtype=np.float64)
    return (x - mn) / (mx - mn)

def softmax(x: np.ndarray) -> np.ndarray:
    x = np.asarray(x, dtype=np.float64)
    x = x - np.max(x)
    e = np.exp(x)
    return e / (e.sum() + 1e-12)

def entropy_norm(counts: np.ndarray) -> float:
    counts = np.asarray(counts, dtype=np.float64)
    counts = counts[counts > 0]
    if len(counts) == 0:
        return 0.0
    p = counts / counts.sum()
    h = -np.sum(p * np.log(p + 1e-12))
    return float(h / np.log(max(len(p), 2)))

def cosine_matrix(a: np.ndarray, b: np.ndarray) -> np.ndarray:
    return unit_rows(a) @ unit_rows(b).T

def top2_margin(scores: np.ndarray) -> float:
    if len(scores) == 0:
        return -np.inf
    if len(scores) == 1:
        return 1e6
    order = np.argsort(-scores)
    return float(scores[order[0]] - scores[order[1]])

def make_random_roots(n_roots: int, dim: int) -> np.ndarray:
    return unit_rows(rng.normal(size=(n_roots, dim)))

def random_basis_2xd(dim: int) -> np.ndarray:
    return rng.normal(size=(2, dim))

def ortho_basis_2xd(dim: int) -> np.ndarray:
    q, _ = np.linalg.qr(rng.normal(size=(dim, 2)))
    return q.T  # (2, dim)

def pca_basis_2xd(items: List["Item"], dim: int) -> np.ndarray:
    item_mat = np.stack([it.vec for it in items], axis=0)
    centered = item_mat - item_mat.mean(axis=0, keepdims=True)
    _, _, vt = np.linalg.svd(centered, full_matrices=False)
    return vt[:2]  # (2, dim)

def make_spiral_roots(
    n_roots: int,
    dim: int,
    basis_2xd: np.ndarray,
    noise_scale: float = 0.04,
) -> np.ndarray:
    t = np.arange(n_roots, dtype=np.float64)
    golden_angle = math.pi * (3 - math.sqrt(5))
    theta = t * golden_angle
    radius = np.sqrt((t + 0.5) / n_roots)
    coords = np.stack([radius * np.cos(theta), radius * np.sin(theta)], axis=1)
    roots = coords @ basis_2xd
    roots += noise_scale * rng.normal(size=roots.shape)
    return unit_rows(roots)

@dataclass
class Item:
    idx: int
    group: int
    cluster: int
    vec: np.ndarray
    assigned_roots: Optional[np.ndarray] = None

def make_items(case_name: str, n_groups: int, items_per_group: int, dim: int, n_clusters: int) -> List[Item]:
    spec = CASE_SPECS[case_name]
    items: List[Item] = []

    if spec["latent"]:
        latent_pts = rng.uniform(-1.0, 1.0, size=(n_groups, 2))
        basis = ortho_basis_2xd(dim)
        group_proto = unit_rows(latent_pts @ basis)
        cluster_proto = unit_rows(rng.normal(size=(max(1, n_clusters), dim)))
        shared_proto = unit_rows(rng.normal(size=(dim,)))[0]
    else:
        cluster_proto = unit_rows(rng.normal(size=(n_clusters, dim)))
        shared_proto = unit_rows(rng.normal(size=(dim,)))[0]
        group_proto = np.zeros((n_groups, dim), dtype=np.float64)

        for g in range(n_groups):
            c = g % n_clusters
            vec = (
                spec["group_mix"] * rng.normal(size=dim)
                + spec["cluster_mix"] * cluster_proto[c]
                + spec["shared_mix"] * shared_proto
                + spec["group_noise"] * rng.normal(size=dim)
            )
            group_proto[g] = unit_rows(vec)[0]

    idx = 0
    for g in range(n_groups):
        c = g % n_clusters
        for _ in range(items_per_group):
            if spec["latent"]:
                vec = group_proto[g] + spec["item_noise"] * rng.normal(size=dim)
            else:
                vec = (
                    group_proto[g]
                    + spec["cluster_mix"] * cluster_proto[c]
                    + spec["shared_mix"] * shared_proto
                    + spec["item_noise"] * rng.normal(size=dim)
                )
            vec = unit_rows(vec)[0]
            items.append(Item(idx=idx, group=g, cluster=c, vec=vec))
            idx += 1

    return items

def make_query(item: Item, noise: float) -> np.ndarray:
    q = item.vec + rng.normal(scale=noise, size=item.vec.shape)
    return unit_rows(q)[0]

# ----------------------------
# Index
# ----------------------------
class MemoryIndex:
    def __init__(self, roots: np.ndarray, overlap_k: int, topk_root: int):
        self.roots = unit_rows(roots)
        self.overlap_k = int(overlap_k)
        self.topk_root = int(topk_root)
        self.items: List[Item] = []
        self.item_mat: Optional[np.ndarray] = None
        self.root_to_items: Dict[int, List[int]] = defaultdict(list)

    def write(self, items: List[Item]) -> None:
        self.items = items
        self.item_mat = np.stack([it.vec for it in items], axis=0)
        sim = self.item_mat @ self.roots.T
        for i, it in enumerate(items):
            best_roots = np.argsort(-sim[i])[: self.overlap_k]
            it.assigned_roots = best_roots
            for r in best_roots:
                self.root_to_items[int(r)].append(i)

    def candidate_pool(self, q: np.ndarray, topk_root: Optional[int] = None) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
        if topk_root is None:
            topk_root = self.topk_root
        q = unit_rows(q)[0]
        root_sim = self.roots @ q
        selected_roots = np.argsort(-root_sim)[: int(topk_root)]

        cand: List[int] = []
        for r in selected_roots:
            cand.extend(self.root_to_items.get(int(r), []))

        if len(cand) == 0:
            return np.array([], dtype=int), selected_roots, root_sim
        return np.unique(np.asarray(cand, dtype=int)), selected_roots, root_sim

    def assignment_diagnostics(self) -> Dict[str, float]:
        counts = np.zeros(len(self.roots), dtype=np.int64)
        for ridx, lst in self.root_to_items.items():
            counts[ridx] = len(lst)
        return {
            "assigned_total": int(counts.sum()),
            "assigned_nonzero": int(np.sum(counts > 0)),
            "assignment_entropy": entropy_norm(counts),
            "assignment_cv": float(np.std(counts) / (np.mean(counts) + 1e-12)),
        }

# ----------------------------
# Root diagnostics
# ----------------------------
def root_diagnostics(roots: np.ndarray) -> Dict[str, float]:
    roots = unit_rows(roots)
    sim = roots @ roots.T
    n = sim.shape[0]
    tri = sim[np.triu_indices(n, k=1)]
    nn = []
    for i in range(n):
        row = sim[i].copy()
        row[i] = -np.inf
        nn.append(np.max(row))
    return {
        "mean_pairwise_cos": float(np.mean(tri)),
        "std_pairwise_cos": float(np.std(tri)),
        "mean_nn_cos": float(np.mean(nn)),
        "std_nn_cos": float(np.std(nn)),
    }

# ----------------------------
# Query banks
# ----------------------------
def make_query_bank(
    index: MemoryIndex,
    item_ids: List[int],
    noises: List[float],
    queries_per_item: int,
) -> List[dict]:
    bank = []
    for item_id in item_ids:
        item = index.items[item_id]
        for noise in noises:
            for _ in range(queries_per_item):
                bank.append(
                    {
                        "item_idx": item.idx,
                        "group": item.group,
                        "cluster": item.cluster,
                        "noise": float(noise),
                        "q": make_query(item, noise=noise),
                        "clean_vec": item.vec.copy(),
                    }
                )
    rng.shuffle(bank)
    return bank

# ----------------------------
# Features / training
# ----------------------------
def pool_features(
    index: MemoryIndex,
    q: np.ndarray,
    cand_idx: np.ndarray,
    selected_roots: np.ndarray,
) -> Tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray]:
    if len(cand_idx) == 0:
        empty = np.array([], dtype=np.float64)
        return np.zeros((0, 4), dtype=np.float64), empty, empty, empty, empty

    q = unit_rows(q)[0]
    cand_mat = index.item_mat[cand_idx]
    cosine = cand_mat @ q

    selected_roots_set = set(int(r) for r in selected_roots.tolist())
    root_support = []
    group_support = []
    local_density = []

    group_counts = Counter(index.items[i].group for i in cand_idx.tolist())
    sim_mat = cand_mat @ cand_mat.T
    np.fill_diagonal(sim_mat, -1.0)

    for pos, i in enumerate(cand_idx.tolist()):
        item = index.items[i]
        assigned = set(int(r) for r in (item.assigned_roots.tolist() if item.assigned_roots is not None else []))
        rs = len(assigned.intersection(selected_roots_set)) / max(1, len(selected_roots_set))
        gs = group_counts[item.group] / max(1, len(cand_idx))
        row = sim_mat[pos]
        if len(row) >= 3:
            top3 = np.sort(row)[-3:]
            ld = float(np.mean(top3))
        else:
            ld = float(np.mean(row)) if len(row) else 0.0
        root_support.append(rs)
        group_support.append(gs)
        local_density.append(ld)

    root_support = np.asarray(root_support, dtype=np.float64)
    group_support = np.asarray(group_support, dtype=np.float64)
    local_density = np.asarray(local_density, dtype=np.float64)

    X = np.stack([cosine, root_support, group_support, local_density], axis=1)
    return X, cosine, root_support, group_support, local_density

def hard_negative_training_set(
    index: MemoryIndex,
    query_bank: List[dict],
    hard_negatives_per_query: int = HARD_NEGATIVES_PER_QUERY,
    max_queries: Optional[int] = None,
) -> Tuple[np.ndarray, np.ndarray]:
    X_rows = []
    y_rows = []

    if max_queries is not None and len(query_bank) > max_queries:
        query_bank = query_bank[:max_queries]

    for rec in query_bank:
        cand_idx, selected_roots, _ = index.candidate_pool(rec["q"])
        if len(cand_idx) == 0:
            continue
        if rec["item_idx"] not in set(cand_idx.tolist()):
            continue

        X, cosine, _, _, _ = pool_features(index, rec["q"], cand_idx, selected_roots)
        pos_pos = int(np.where(cand_idx == rec["item_idx"])[0][0])
        neg_pos = np.where(cand_idx != rec["item_idx"])[0]

        X_rows.append(X[pos_pos])
        y_rows.append(1)

        if len(neg_pos) == 0:
            continue

        neg_scores = cosine[neg_pos]
        hard_order = np.argsort(-neg_scores)
        hard_take = neg_pos[hard_order[: min(hard_negatives_per_query, len(neg_pos))]]

        for j in hard_take:
            X_rows.append(X[j])
            y_rows.append(0)

    if len(X_rows) == 0:
        return np.zeros((0, 4), dtype=np.float64), np.zeros((0,), dtype=np.int64)

    return np.vstack(X_rows), np.asarray(y_rows, dtype=np.int64)

def train_linear_judge(index: MemoryIndex, train_bank: List[dict]) -> object:
    X, y = hard_negative_training_set(index, train_bank)
    if len(X) == 0:
        raise RuntimeError("No training data collected.")

    if len(np.unique(y)) < 2:
        raise RuntimeError("Judge training set needs both classes.")

    linear = make_pipeline(
        StandardScaler(),
        LogisticRegression(
            max_iter=600,
            class_weight="balanced",
            random_state=SEED,
            solver="lbfgs",
        ),
    )
    linear.fit(X, y)
    return linear

# ----------------------------
# Controllers
# ----------------------------
def blended_score(
    prob: np.ndarray,
    base: np.ndarray,
    root_support: np.ndarray,
    group_support: np.ndarray,
    local_density: np.ndarray,
) -> np.ndarray:
    b = normalize01(base)
    return (
        0.60 * prob
        + 0.18 * b
        + 0.10 * root_support
        + 0.07 * group_support
        + 0.05 * normalize01(local_density)
    )

def refine_query(
    q: np.ndarray,
    cand_mat: np.ndarray,
    guide_scores: np.ndarray,
    steps: int,
    alpha: float,
) -> np.ndarray:
    qn = unit_rows(q)[0].copy()
    if len(cand_mat) == 0:
        return qn

    k = min(3, len(cand_mat))
    guide_idx = np.argsort(-guide_scores)[:k]
    for _ in range(steps):
        weights = softmax(guide_scores[guide_idx])
        target = np.sum(cand_mat[guide_idx] * weights[:, None], axis=0)
        target = unit_rows(target)[0]
        qn = unit_rows(qn + alpha * target)[0]
    return qn

def choose_candidate(
    method: str,
    index: MemoryIndex,
    q: np.ndarray,
    clean_vec: np.ndarray,
    cand_idx: np.ndarray,
    selected_roots: np.ndarray,
    linear_model: object,
    topk_root: int,
    guard_margin: float,
    overwrite_alpha: float,
    refine_alpha: float,
) -> Tuple[int, Dict[str, int]]:
    flags = {"overwrite": 0, "restart": 0, "refine": 0}

    if len(cand_idx) == 0:
        return -1, flags

    X, base, root_support, group_support, local_density = pool_features(index, q, cand_idx, selected_roots)
    linear_prob = linear_model.predict_proba(X)[:, 1]

    if method == "oracle_pool":
        scores = index.item_mat[cand_idx] @ unit_rows(clean_vec)[0]
        return int(cand_idx[np.argmax(scores)]), flags

    if method == "flat_key_nn":
        return int(cand_idx[np.argmax(base)]), flags

    if method == "learned_linear_judge":
        return int(cand_idx[np.argmax(linear_prob)]), flags

    if method == "guarded_linear_judge":
        if top2_margin(linear_prob) >= guard_margin:
            return int(cand_idx[np.argmax(linear_prob)]), flags
        flags["overwrite"] = 1
        scores = blended_score(linear_prob, base, root_support, group_support, local_density)
        return int(cand_idx[np.argmax(scores)]), flags

    if method == "mcltr_adaptive":
        order = np.argsort(-linear_prob)
        top1 = int(order[0])
        margin = float(linear_prob[order[0]] - linear_prob[order[1]]) if len(order) > 1 else 1.0

        if margin >= guard_margin:
            return int(cand_idx[top1]), flags
        elif margin >= guard_margin / 2.0:
            flags["overwrite"] = 1
            q2 = refine_query(q, index.item_mat[cand_idx], linear_prob, steps=1, alpha=overwrite_alpha)
            X2, base2, rs2, gs2, ld2 = pool_features(index, q2, cand_idx, selected_roots)
            lp2 = linear_model.predict_proba(X2)[:, 1]
            scores = blended_score(lp2, base2, rs2, gs2, ld2)
            return int(cand_idx[np.argmax(scores)]), flags
        else:
            flags["restart"] = 1
            cand_idx2, selected_roots2, _ = index.candidate_pool(q, topk_root=topk_root + 3)
            if len(cand_idx2) > 0:
                X2, base2, rs2, gs2, ld2 = pool_features(index, q, cand_idx2, selected_roots2)
                lp2 = linear_model.predict_proba(X2)[:, 1]
                scores = blended_score(lp2, base2, rs2, gs2, ld2)
                return int(cand_idx2[np.argmax(scores)]), flags
            return int(cand_idx[top1]), flags

    if method in {"qdmn_refine1", "qdmn_refine2"}:
        steps = 1 if method == "qdmn_refine1" else 2
        X0, _, _, _, _ = pool_features(index, q, cand_idx, selected_roots)
        guide = linear_model.predict_proba(X0)[:, 1]
        q2 = refine_query(q, index.item_mat[cand_idx], guide, steps=steps, alpha=refine_alpha)
        flags["refine"] = 1
        scores = index.item_mat[cand_idx] @ unit_rows(q2)[0]
        return int(cand_idx[np.argmax(scores)]), flags

    raise KeyError(f"Unknown method: {method}")

# ----------------------------
# Evaluation
# ----------------------------
def evaluate_methods(
    index: MemoryIndex,
    linear_model: object,
    query_bank: List[dict],
    methods: List[str],
    topk_root: int,
    guard_margin: float,
    overwrite_alpha: float,
    refine_alpha: float,
    noise_value: float,
) -> pd.DataFrame:
    rows = []
    for method in methods:
        item_hits = 0
        group_hits = 0
        coverage_hits = 0
        avg_pool = 0.0
        overwrite_count = 0
        restart_count = 0
        refine_count = 0

        for rec in query_bank:
            q = rec["q"]
            item_idx = rec["item_idx"]
            clean_vec = rec["clean_vec"]

            cand_idx, selected_roots, _ = index.candidate_pool(q, topk_root=topk_root)
            avg_pool += len(cand_idx)
            if len(cand_idx) > 0:
                coverage_hits += int(item_idx in set(cand_idx.tolist()))

            chosen, flags = choose_candidate(
                method=method,
                index=index,
                q=q,
                clean_vec=clean_vec,
                cand_idx=cand_idx,
                selected_roots=selected_roots,
                linear_model=linear_model,
                topk_root=topk_root,
                guard_margin=guard_margin,
                overwrite_alpha=overwrite_alpha,
                refine_alpha=refine_alpha,
            )

            overwrite_count += flags["overwrite"]
            restart_count += flags["restart"]
            refine_count += flags["refine"]

            if chosen == item_idx:
                item_hits += 1
            if chosen >= 0 and index.items[chosen].group == rec["group"]:
                group_hits += 1

        n = len(query_bank)
        rows.append(
            {
                "method": method,
                "item_acc": item_hits / n,
                "group_acc": group_hits / n,
                "coverage": coverage_hits / n,
                "avg_pool": avg_pool / n,
                "oracle_gap": np.nan,
                "overwrite_rate": overwrite_count / n,
                "restart_rate": restart_count / n,
                "refine_rate": refine_count / n,
                "guard_margin": guard_margin,
                "overwrite_alpha": overwrite_alpha,
                "refine_alpha": refine_alpha,
                "topk_root": topk_root,
                "overlap_k": index.overlap_k,
                "noise": noise_value,
            }
        )
    return pd.DataFrame(rows)

# ----------------------------
# Root generators
# ----------------------------
def make_roots_for_placement(
    placement: str,
    case_items: List[Item],
    dim: int,
) -> np.ndarray:
    if placement == "random":
        return make_random_roots(N_ROOTS, dim)

    if placement == "spiral_bad":
        basis = random_basis_2xd(dim)
        return make_spiral_roots(N_ROOTS, dim, basis_2xd=basis, noise_scale=0.10)

    if placement == "spiral_ortho":
        basis = ortho_basis_2xd(dim)
        return make_spiral_roots(N_ROOTS, dim, basis_2xd=basis, noise_scale=0.03)

    if placement == "spiral_pca":
        basis = pca_basis_2xd(case_items, dim)
        return make_spiral_roots(N_ROOTS, dim, basis_2xd=basis, noise_scale=0.03)

    raise KeyError(placement)

# ----------------------------
# Run a single case
# ----------------------------
def run_case(
    case_name: str,
    placement: str,
    overlap_k: int,
    topk_root: int,
    train_noise_levels: List[float],
    test_noise_levels: List[float],
    train_queries_per_item: int,
    test_queries_per_item: int,
    guard_margin: float = GUARD_MARGIN,
    overwrite_alpha: float = OVERWRITE_ALPHA,
    refine_alpha: float = REFINE_ALPHA,
) -> Tuple[pd.DataFrame, object, MemoryIndex, List[dict], Dict[float, List[dict]]]:
    items = make_items(case_name, N_GROUPS, ITEMS_PER_GROUP, DIM, N_CLUSTERS)
    roots = make_roots_for_placement(placement, items, DIM)

    index = MemoryIndex(roots=roots, overlap_k=overlap_k, topk_root=topk_root)
    index.write(items)

    all_ids = np.arange(len(items))
    rng.shuffle(all_ids)
    split = int(0.70 * len(all_ids))
    train_ids = all_ids[:split].tolist()
    test_ids = all_ids[split:].tolist()

    train_bank = make_query_bank(index, train_ids, train_noise_levels, train_queries_per_item)
    linear_model = train_linear_judge(index, train_bank)

    all_rows = []
    test_banks: Dict[float, List[dict]] = {}

    for noise in test_noise_levels:
        test_bank = make_query_bank(index, test_ids, [noise], test_queries_per_item)
        test_banks[float(noise)] = test_bank

        df_noise = evaluate_methods(
            index=index,
            linear_model=linear_model,
            query_bank=test_bank,
            methods=METHODS,
            topk_root=topk_root,
            guard_margin=guard_margin,
            overwrite_alpha=overwrite_alpha,
            refine_alpha=refine_alpha,
            noise_value=noise,
        )
        df_noise["case"] = case_name
        df_noise["placement"] = placement
        all_rows.append(df_noise)

    return pd.concat(all_rows, ignore_index=True), linear_model, index, train_bank, test_banks

# ----------------------------
# Margin-bin analysis for QDMN
# ----------------------------
def margin_bin_analysis(
    case_name: str,
    placements: List[str],
    hard_noise: float,
    overlap_k: int,
    topk_root: int,
    train_noise_levels: List[float],
    train_queries_per_item: int,
    test_queries_per_item: int,
    guard_margin: float,
    overwrite_alpha: float,
    refine_alpha: float,
) -> Tuple[pd.DataFrame, pd.DataFrame]:
    rows = []
    gain_rows = []

    for placement in placements:
        df_case, linear_model, index, train_bank, test_banks = run_case(
            case_name=case_name,
            placement=placement,
            overlap_k=overlap_k,
            topk_root=topk_root,
            train_noise_levels=train_noise_levels,
            test_noise_levels=[hard_noise],
            train_queries_per_item=train_queries_per_item,
            test_queries_per_item=test_queries_per_item,
            guard_margin=guard_margin,
            overwrite_alpha=overwrite_alpha,
            refine_alpha=refine_alpha,
        )

        test_bank = test_banks[float(hard_noise)]

        per_query = []
        for rec in test_bank:
            cand_idx, selected_roots, _ = index.candidate_pool(rec["q"], topk_root=topk_root)
            if len(cand_idx) == 0:
                continue
            X, base, _, _, _ = pool_features(index, rec["q"], cand_idx, selected_roots)
            lp = linear_model.predict_proba(X)[:, 1]
            margin = top2_margin(lp)
            per_query.append(
                {
                    "margin": margin,
                    "item_idx": rec["item_idx"],
                    "group": rec["group"],
                    "cand_idx": cand_idx,
                    "selected_roots": selected_roots,
                    "q": rec["q"],
                    "clean_vec": rec["clean_vec"],
                }
            )

        if len(per_query) == 0:
            continue

        margins = np.array([r["margin"] for r in per_query], dtype=np.float64)
        margins = margins[np.isfinite(margins)]
        if len(margins) < 3:
            continue

        bins = np.quantile(margins, [0.0, 0.33, 0.66, 1.0])
        labels = ["low", "mid", "high"]

        for i, label in enumerate(labels):
            lo, hi = bins[i], bins[i + 1]
            if i < 2:
                subset = [r for r in per_query if np.isfinite(r["margin"]) and (r["margin"] >= lo and r["margin"] < hi)]
            else:
                subset = [r for r in per_query if np.isfinite(r["margin"]) and (r["margin"] >= lo and r["margin"] <= hi)]
            if len(subset) == 0:
                continue

            method_scores = {}
            for method in ["flat_key_nn", "guarded_linear_judge", "mcltr_adaptive", "qdmn_refine2", "oracle_pool"]:
                hits = 0
                group_hits = 0
                cov = 0
                for r in subset:
                    cand_idx = r["cand_idx"]
                    selected_roots = r["selected_roots"]
                    q = r["q"]
                    clean_vec = r["clean_vec"]
                    item_idx = r["item_idx"]

                    cov += int(item_idx in set(cand_idx.tolist()))
                    chosen, _ = choose_candidate(
                        method=method,
                        index=index,
                        q=q,
                        clean_vec=clean_vec,
                        cand_idx=cand_idx,
                        selected_roots=selected_roots,
                        linear_model=linear_model,
                        topk_root=topk_root,
                        guard_margin=guard_margin,
                        overwrite_alpha=overwrite_alpha,
                        refine_alpha=refine_alpha,
                    )
                    if chosen == item_idx:
                        hits += 1
                    if chosen >= 0 and index.items[chosen].group == r["group"]:
                        group_hits += 1

                acc = hits / len(subset)
                gacc = group_hits / len(subset)
                covr = cov / len(subset)
                method_scores[method] = acc

                rows.append(
                    {
                        "placement": placement,
                        "case": case_name,
                        "margin_bin": label,
                        "method": method,
                        "item_acc": acc,
                        "group_acc": gacc,
                        "coverage": covr,
                    }
                )

            gain_rows.append(
                {
                    "placement": placement,
                    "case": case_name,
                    "margin_bin": label,
                    "qdmn_minus_flat": method_scores.get("qdmn_refine2", np.nan) - method_scores.get("flat_key_nn", np.nan),
                    "qdmn_minus_guarded": method_scores.get("qdmn_refine2", np.nan) - method_scores.get("guarded_linear_judge", np.nan),
                }
            )

    return pd.DataFrame(rows), pd.DataFrame(gain_rows)

# ----------------------------
# Plot helper
# ----------------------------
def plot_heatmap(ax, pivot: pd.DataFrame, title: str, cmap: str = "viridis", fmt: str = ".2f"):
    data = pivot.values.astype(float)
    im = ax.imshow(data, aspect="auto", cmap=cmap)
    ax.set_xticks(range(len(pivot.columns)))
    ax.set_xticklabels(pivot.columns, rotation=20, ha="right")
    ax.set_yticks(range(len(pivot.index)))
    ax.set_yticklabels(pivot.index)
    ax.set_title(title)
    med = np.nanmedian(data)
    for i in range(data.shape[0]):
        for j in range(data.shape[1]):
            val = data[i, j]
            if np.isfinite(val):
                ax.text(
                    j, i, format(val, fmt),
                    ha="center", va="center", fontsize=8,
                    color="white" if val > med else "black"
                )
    return im

# ----------------------------
# Main
# ----------------------------
def main() -> pd.DataFrame:
    all_rows = []
    root_rows = []

    print("Running placement / case sweep...")

    for case_name in CASE_SPECS.keys():
        for placement in PLACEMENTS:
            df_case, linear_model, index, train_bank, test_banks = run_case(
                case_name=case_name,
                placement=placement,
                overlap_k=OVERLAP_K,
                topk_root=TOPK_ROOT,
                train_noise_levels=TRAIN_NOISES,
                test_noise_levels=TEST_NOISES,
                train_queries_per_item=TRAIN_QUERIES_PER_ITEM,
                test_queries_per_item=TEST_QUERIES_PER_ITEM,
                guard_margin=GUARD_MARGIN,
                overwrite_alpha=OVERWRITE_ALPHA,
                refine_alpha=REFINE_ALPHA,
            )
            all_rows.append(df_case)

            rd = root_diagnostics(index.roots)
            ad = index.assignment_diagnostics()
            root_rows.append({"case": case_name, "placement": placement, **rd, **ad})

    df = pd.concat(all_rows, ignore_index=True)
    root_df = pd.DataFrame(root_rows)

    df.to_csv(OUTDIR / "main_results.csv", index=False)
    root_df.to_csv(OUTDIR / "root_diagnostics.csv", index=False)

    # Add oracle gap
    df["oracle_gap"] = np.nan
    for (case_name, placement, noise), grp in df.groupby(["case", "placement", "noise"]):
        oracle_row = grp[grp["method"] == "oracle_pool"]
        if len(oracle_row) == 0:
            continue
        oracle_acc = float(oracle_row["item_acc"].iloc[0])
        df.loc[grp.index, "oracle_gap"] = oracle_acc - grp["item_acc"].values

    # ------------------------
    # Summary tables
    # ------------------------
    print("\n=== Root diagnostics ===")
    print(root_df.round(4).sort_values(["case", "placement"]).to_string(index=False))

    print("\n=== Overall mean by method ===")
    print(
        df.groupby("method")[["item_acc", "group_acc", "coverage", "avg_pool", "oracle_gap"]]
        .mean()
        .sort_values("item_acc", ascending=False)
        .round(4)
        .to_string()
    )

    print("\n=== Mean by case ===")
    print(
        df.groupby("case")[["item_acc", "group_acc", "coverage", "avg_pool", "oracle_gap"]]
        .mean()
        .round(4)
        .to_string()
    )

    print("\n=== Mean by placement ===")
    print(
        df.groupby("placement")[["item_acc", "group_acc", "coverage", "avg_pool", "oracle_gap"]]
        .mean()
        .round(4)
        .to_string()
    )

    print("\n=== Mean by case x placement ===")
    case_place = (
        df.groupby(["case", "placement"])[["item_acc", "group_acc", "coverage", "avg_pool", "oracle_gap"]]
        .mean()
        .reset_index()
        .sort_values(["case", "item_acc"], ascending=[True, False])
    )
    print(case_place.round(4).to_string(index=False))

    non_oracle = df[df["method"] != "oracle_pool"].copy()
    best = (
        non_oracle.sort_values(["case", "placement", "noise", "item_acc"], ascending=[True, True, True, False])
        .groupby(["case", "placement", "noise"], as_index=False)
        .head(1)
        .loc[:, ["case", "placement", "noise", "method", "item_acc", "oracle_gap", "coverage", "avg_pool", "overwrite_rate", "restart_rate", "refine_rate"]]
        .reset_index(drop=True)
    )
    best.to_csv(OUTDIR / "best_by_case_placement_noise.csv", index=False)

    print("\n=== Best non-oracle per case / placement / noise ===")
    print(best.round(4).to_string(index=False))

    # ------------------------
    # Margin-bin analysis for QDMN
    # ------------------------
    hard_noise = max(TEST_NOISES)
    print(f"\nRunning margin-bin summary at hard noise={hard_noise}...")

    margin_df, gain_df = margin_bin_analysis(
        case_name="shared_core",
        placements=["random", "spiral_ortho"],
        hard_noise=hard_noise,
        overlap_k=OVERLAP_K,
        topk_root=TOPK_ROOT,
        train_noise_levels=TRAIN_NOISES,
        train_queries_per_item=TRAIN_QUERIES_PER_ITEM,
        test_queries_per_item=TEST_QUERIES_PER_ITEM,
        guard_margin=GUARD_MARGIN,
        overwrite_alpha=OVERWRITE_ALPHA,
        refine_alpha=REFINE_ALPHA,
    )

    margin_df.to_csv(OUTDIR / "margin_bin_summary.csv", index=False)
    gain_df.to_csv(OUTDIR / "qdmn_gain_by_margin_bin.csv", index=False)

    print("\n=== Margin-bin summary (hard ambiguity) ===")
    print(
        margin_df.sort_values(["placement", "margin_bin", "item_acc"], ascending=[True, True, False])
        .round(4)
        .to_string(index=False)
    )

    print("\n=== QDMN gain over flat/guarded (hard ambiguity) ===")
    print(gain_df.round(4).sort_values(["placement", "margin_bin"]).to_string(index=False))

    # ------------------------
    # Paper preview
    # ------------------------
    paper_preview = (
        df.groupby(["case", "placement", "method"])[["item_acc", "group_acc", "coverage", "avg_pool", "oracle_gap"]]
        .mean()
        .reset_index()
        .sort_values(["case", "item_acc"], ascending=[True, False])
    )
    paper_preview.to_csv(OUTDIR / "paper_preview.csv", index=False)

    print("\n=== Paper preview ===")
    print(paper_preview.round(4).to_string(index=False))

    # ------------------------
    # Figure: 2x2 summary
    # ------------------------
    fig, axes = plt.subplots(2, 2, figsize=(16, 11), constrained_layout=True)

    ax = axes[0, 0]
    pivot_a = root_df.pivot(index="case", columns="placement", values="mean_nn_cos").reindex(index=list(CASE_SPECS.keys()), columns=PLACEMENTS)
    im = plot_heatmap(ax, pivot_a, "A. Root concentration: mean nearest-neighbor cosine", cmap="magma", fmt=".2f")
    fig.colorbar(im, ax=ax, fraction=0.046, pad=0.04)

    ax = axes[0, 1]
    pivot_b = root_df.pivot(index="case", columns="placement", values="assignment_entropy").reindex(index=list(CASE_SPECS.keys()), columns=PLACEMENTS)
    im = plot_heatmap(ax, pivot_b, "B. Root usage entropy", cmap="viridis", fmt=".2f")
    fig.colorbar(im, ax=ax, fraction=0.046, pad=0.04)

    ax = axes[1, 0]
    show_methods = ["flat_key_nn", "guarded_linear_judge", "mcltr_adaptive", "qdmn_refine2", "oracle_pool"]
    sub = df[(df["case"] == "shared_core") & (df["method"].isin(show_methods))]
    for m in show_methods:
        d = sub[sub["method"] == m].sort_values("noise")
        ax.plot(d["noise"], d["item_acc"], marker="o", linewidth=2, label=m)
    ax.set_title("C. Shared-core case: accuracy vs noise")
    ax.set_xlabel("Noise")
    ax.set_ylabel("Item accuracy")
    ax.grid(True, alpha=0.25)
    ax.legend(fontsize=7, loc="best")

    ax = axes[1, 1]
    bins_order = ["low", "mid", "high"]
    x = np.arange(len(bins_order))
    width = 0.35
    for i, placement in enumerate(["random", "spiral_ortho"]):
        subg = gain_df[gain_df["placement"] == placement].copy()
        vals = []
        for b in bins_order:
            row = subg[subg["margin_bin"] == b]
            vals.append(float(row["qdmn_minus_flat"].iloc[0]) if len(row) else np.nan)
        ax.bar(x + (i - 0.5) * width, vals, width=width, label=placement)
    ax.axhline(0.0, linestyle="--", linewidth=1)
    ax.set_xticks(x)
    ax.set_xticklabels(bins_order)
    ax.set_title("D. QDMN gain over flat judge\n(shared_core, hardest noise)")
    ax.set_xlabel("Margin bin")
    ax.set_ylabel("Item acc gain")
    ax.grid(True, axis="y", alpha=0.25)
    ax.legend(fontsize=8, loc="best")

    fig.suptitle("Part 19 — Spiral geometry, root spread, and QDMN last-mile refinement", fontsize=14)
    fig.savefig(OUTDIR / "part19_summary_figure.png", dpi=220, bbox_inches="tight")
    plt.show()

    print(f"\nSaved artifacts to: {OUTDIR}")
    return df

if __name__ == "__main__":
    df = main()
    print("\nDone.")

# ============================================================
# FINAL SCALE TEST — faster CPU version
# Matched budget, multiple seeds
# Random vs spiral_pca, flat vs judge vs QDMN, oracle upper bound
# One-cell Colab script
# ============================================================

from __future__ import annotations

import math
import random
import time
import warnings
from dataclasses import dataclass
from collections import Counter, defaultdict
from pathlib import Path
from typing import Dict, List, Tuple, Optional

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt

from sklearn.linear_model import LogisticRegression
from sklearn.pipeline import make_pipeline
from sklearn.preprocessing import StandardScaler
from sklearn.exceptions import ConvergenceWarning

warnings.filterwarnings("ignore", category=ConvergenceWarning)

# ----------------------------
# Global config
# ----------------------------
OUTDIR = Path("final_scale_test_artifacts")
OUTDIR.mkdir(parents=True, exist_ok=True)

# Fewer seeds / queries keeps this meaningful but much faster.
SEEDS = [11, 22, 33]
SCALES = [256, 1024, 2048]
ITEMS_PER_GROUP = 4
DIM = 32
N_ROOTS = 256
OVERLAP_K = 3
TOPK_ROOT = 10
TRAIN_FRAC = 0.70

TRAIN_NOISES = [0.12, 0.20, 0.28]
TEST_NOISES = [0.12, 0.20, 0.28, 0.38]
TRAIN_QUERIES_PER_ITEM = 2
TEST_QUERIES_PER_ITEM = 1

GUARD_MARGIN = 0.06
OVERWRITE_ALPHA = 0.10
REFINE_ALPHA = 0.12

PLACEMENTS = ["random", "spiral_pca"]

METHODS = [
    "flat_key_nn",
    "learned_linear_judge",
    "guarded_linear_judge",
    "mcltr_adaptive",
    "qdmn_refine2",
    "oracle_pool",
]

# ----------------------------
# Utilities
# ----------------------------
def unit_rows(x: np.ndarray) -> np.ndarray:
    x = np.asarray(x, dtype=np.float64)
    if x.ndim == 1:
        x = x[None, :]
    n = np.linalg.norm(x, axis=-1, keepdims=True)
    return x / (n + 1e-12)

def normalize01(x: np.ndarray) -> np.ndarray:
    x = np.asarray(x, dtype=np.float64)
    mn, mx = float(np.min(x)), float(np.max(x))
    if abs(mx - mn) < 1e-12:
        return np.zeros_like(x, dtype=np.float64)
    return (x - mn) / (mx - mn)

def softmax(x: np.ndarray) -> np.ndarray:
    x = np.asarray(x, dtype=np.float64)
    x = x - np.max(x)
    e = np.exp(x)
    return e / (e.sum() + 1e-12)

def top2_margin(scores: np.ndarray) -> float:
    if len(scores) == 0:
        return -np.inf
    if len(scores) == 1:
        return np.inf
    order = np.argsort(-scores)
    return float(scores[order[0]] - scores[order[1]])

def entropy_norm(counts: np.ndarray) -> float:
    counts = np.asarray(counts, dtype=np.float64)
    counts = counts[counts > 0]
    if len(counts) == 0:
        return 0.0
    p = counts / counts.sum()
    h = -np.sum(p * np.log(p + 1e-12))
    return float(h / np.log(max(len(p), 2)))

def make_rng(seed: int) -> np.random.Generator:
    return np.random.default_rng(seed)

def root_diagnostics(roots: np.ndarray) -> Dict[str, float]:
    roots = unit_rows(roots)
    sim = roots @ roots.T
    n = sim.shape[0]
    tri = sim[np.triu_indices(n, k=1)]
    nn = []
    for i in range(n):
        row = sim[i].copy()
        row[i] = -np.inf
        nn.append(np.max(row))
    return {
        "mean_pairwise_cos": float(np.mean(tri)),
        "std_pairwise_cos": float(np.std(tri)),
        "mean_nn_cos": float(np.mean(nn)),
        "std_nn_cos": float(np.std(nn)),
    }

# ----------------------------
# Data generation
# ----------------------------
@dataclass
class Item:
    idx: int
    group: int
    vec: np.ndarray
    assigned_roots: Optional[np.ndarray] = None

def make_items_shared_core(
    n_groups: int,
    items_per_group: int,
    dim: int,
    seed: int,
) -> List[Item]:
    rng = make_rng(seed)
    group_proto = unit_rows(rng.normal(size=(n_groups, dim)))
    shared_proto = unit_rows(rng.normal(size=(dim,)))[0]

    items: List[Item] = []
    idx = 0
    for g in range(n_groups):
        for _ in range(items_per_group):
            vec = (
                0.26 * group_proto[g]
                + 0.56 * shared_proto
                + 0.18 * rng.normal(size=dim)
            )
            vec = unit_rows(vec)[0]
            items.append(Item(idx=idx, group=g, vec=vec))
            idx += 1
    return items

def make_query(item: Item, noise: float, rng: np.random.Generator) -> np.ndarray:
    q = item.vec + rng.normal(scale=noise, size=item.vec.shape)
    return unit_rows(q)[0]

# ----------------------------
# Root generators
# ----------------------------
def make_random_roots(n_roots: int, dim: int, rng: np.random.Generator) -> np.ndarray:
    return unit_rows(rng.normal(size=(n_roots, dim)))

def make_spiral_pca_roots(
    item_mat: np.ndarray,
    n_roots: int,
    dim: int,
    rng: np.random.Generator,
    noise_scale: float = 0.03,
) -> np.ndarray:
    centered = item_mat - item_mat.mean(axis=0, keepdims=True)
    _, _, vt = np.linalg.svd(centered, full_matrices=False)
    basis = vt[:2]  # (2, dim)

    t = np.arange(n_roots, dtype=np.float64)
    golden_angle = math.pi * (3 - math.sqrt(5))
    theta = t * golden_angle
    radius = np.sqrt((t + 0.5) / n_roots)
    coords = np.stack([radius * np.cos(theta), radius * np.sin(theta)], axis=1)

    roots = coords @ basis
    roots += noise_scale * rng.normal(size=roots.shape)
    return unit_rows(roots)

# ----------------------------
# Memory index
# ----------------------------
class MemoryIndex:
    def __init__(self, roots: np.ndarray, overlap_k: int, topk_root: int):
        self.roots = unit_rows(roots)
        self.overlap_k = int(overlap_k)
        self.topk_root = int(topk_root)
        self.items: List[Item] = []
        self.item_mat: Optional[np.ndarray] = None
        self.root_to_items: Dict[int, List[int]] = defaultdict(list)

    def write(self, items: List[Item]) -> None:
        self.items = items
        self.item_mat = np.stack([it.vec for it in items], axis=0)
        sim = self.item_mat @ self.roots.T

        for i, it in enumerate(items):
            best_roots = np.argsort(-sim[i])[: self.overlap_k]
            it.assigned_roots = best_roots
            for r in best_roots:
                self.root_to_items[int(r)].append(i)

    def candidate_pool(
        self,
        q: np.ndarray,
        topk_root: Optional[int] = None,
    ) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
        if topk_root is None:
            topk_root = self.topk_root
        q = unit_rows(q)[0]
        root_sim = self.roots @ q
        selected_roots = np.argsort(-root_sim)[: int(topk_root)]

        cand: List[int] = []
        for r in selected_roots:
            cand.extend(self.root_to_items.get(int(r), []))

        if len(cand) == 0:
            return np.array([], dtype=int), selected_roots, root_sim

        return np.unique(np.asarray(cand, dtype=int)), selected_roots, root_sim

    def assignment_diagnostics(self) -> Dict[str, float]:
        counts = np.zeros(len(self.roots), dtype=np.int64)
        for ridx, lst in self.root_to_items.items():
            counts[ridx] = len(lst)
        return {
            "assigned_total": int(counts.sum()),
            "assigned_nonzero": int(np.sum(counts > 0)),
            "assignment_entropy": entropy_norm(counts),
            "assignment_cv": float(np.std(counts) / (np.mean(counts) + 1e-12)),
        }

# ----------------------------
# Query bank
# ----------------------------
def make_query_bank(
    index: MemoryIndex,
    item_ids: List[int],
    noises: List[float],
    queries_per_item: int,
    rng: np.random.Generator,
) -> List[dict]:
    bank = []
    for item_id in item_ids:
        item = index.items[item_id]
        for noise in noises:
            for _ in range(queries_per_item):
                bank.append(
                    {
                        "item_idx": item.idx,
                        "group": item.group,
                        "noise": float(noise),
                        "q": make_query(item, noise=noise, rng=rng),
                        "clean_vec": item.vec.copy(),
                    }
                )
    rng.shuffle(bank)
    return bank

# ----------------------------
# Features / training
# ----------------------------
def pool_features(
    index: MemoryIndex,
    q: np.ndarray,
    cand_idx: np.ndarray,
    selected_roots: np.ndarray,
) -> Tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray]:
    """
    Faster version:
    - avoids O(k^2) candidate-candidate similarity matrix
    - uses top similarities to the query as a cheap local-density proxy
    """
    if len(cand_idx) == 0:
        empty = np.array([], dtype=np.float64)
        return np.zeros((0, 4), dtype=np.float64), empty, empty, empty, empty

    q = unit_rows(q)[0]
    cand_mat = index.item_mat[cand_idx]
    cosine = cand_mat @ q

    selected_roots_set = set(int(r) for r in selected_roots.tolist())
    root_support = []
    group_support = []
    local_density = []

    group_counts = Counter(index.items[i].group for i in cand_idx.tolist())

    # cheap proxy for "local density": how strong the candidate's own query match is
    # relative to the pool. This keeps the signal useful without the pairwise cost.
    top_cosine_floor = np.sort(cosine)[-min(3, len(cosine)):]
    density_floor = float(np.mean(top_cosine_floor)) if len(top_cosine_floor) else 0.0

    for i in cand_idx.tolist():
        item = index.items[i]
        assigned = set(int(r) for r in (item.assigned_roots.tolist() if item.assigned_roots is not None else []))
        rs = len(assigned.intersection(selected_roots_set)) / max(1, len(selected_roots_set))
        gs = group_counts[item.group] / max(1, len(cand_idx))

        # per-candidate density proxy based on its similarity to the query
        # plus a small shared baseline from the pool.
        # This keeps the feature meaningful but cheap.
        local_density.append(0.5 * float(item.vec @ q) + 0.5 * density_floor)

        root_support.append(rs)
        group_support.append(gs)

    root_support = np.asarray(root_support, dtype=np.float64)
    group_support = np.asarray(group_support, dtype=np.float64)
    local_density = np.asarray(local_density, dtype=np.float64)

    X = np.stack([cosine, root_support, group_support, local_density], axis=1)
    return X, cosine, root_support, group_support, local_density

def hard_negative_training_set(
    index: MemoryIndex,
    query_bank: List[dict],
    hard_negatives_per_query: int = 8,
) -> Tuple[np.ndarray, np.ndarray]:
    X_rows = []
    y_rows = []

    for rec in query_bank:
        cand_idx, selected_roots, _ = index.candidate_pool(rec["q"])
        if len(cand_idx) == 0:
            continue
        if rec["item_idx"] not in set(cand_idx.tolist()):
            continue

        X, cosine, _, _, _ = pool_features(index, rec["q"], cand_idx, selected_roots)
        pos_pos = int(np.where(cand_idx == rec["item_idx"])[0][0])
        neg_pos = np.where(cand_idx != rec["item_idx"])[0]

        X_rows.append(X[pos_pos])
        y_rows.append(1)

        if len(neg_pos) == 0:
            continue

        neg_scores = cosine[neg_pos]
        hard_order = np.argsort(-neg_scores)
        hard_take = neg_pos[hard_order[: min(hard_negatives_per_query, len(neg_pos))]]

        for j in hard_take:
            X_rows.append(X[j])
            y_rows.append(0)

    if len(X_rows) == 0:
        return np.zeros((0, 4), dtype=np.float64), np.zeros((0,), dtype=np.int64)

    return np.vstack(X_rows), np.asarray(y_rows, dtype=np.int64)

def train_linear_judge(index: MemoryIndex, train_bank: List[dict]) -> object:
    X, y = hard_negative_training_set(index, train_bank)
    if len(X) == 0:
        raise RuntimeError("No training data collected.")

    model = make_pipeline(
        StandardScaler(),
        LogisticRegression(
            max_iter=400,
            class_weight="balanced",
            random_state=0,
            solver="lbfgs",
        ),
    )
    model.fit(X, y)
    return model

# ----------------------------
# Controllers
# ----------------------------
def blended_score(
    prob: np.ndarray,
    base: np.ndarray,
    root_support: np.ndarray,
    group_support: np.ndarray,
    local_density: np.ndarray,
) -> np.ndarray:
    b = normalize01(base)
    return (
        0.60 * prob
        + 0.18 * b
        + 0.10 * root_support
        + 0.07 * group_support
        + 0.05 * normalize01(local_density)
    )

def refine_query(
    q: np.ndarray,
    cand_mat: np.ndarray,
    guide_scores: np.ndarray,
    steps: int,
    alpha: float,
) -> np.ndarray:
    qn = unit_rows(q)[0].copy()
    if len(cand_mat) == 0:
        return qn

    k = min(3, len(cand_mat))
    guide_idx = np.argsort(-guide_scores)[:k]
    for _ in range(steps):
        weights = softmax(guide_scores[guide_idx])
        target = np.sum(cand_mat[guide_idx] * weights[:, None], axis=0)
        target = unit_rows(target)[0]
        qn = unit_rows(qn + alpha * target)[0]
    return qn

def choose_candidate(
    method: str,
    index: MemoryIndex,
    q: np.ndarray,
    clean_vec: np.ndarray,
    cand_idx: np.ndarray,
    selected_roots: np.ndarray,
    linear_model: object,
    topk_root: int,
    guard_margin: float,
    overwrite_alpha: float,
    refine_alpha: float,
) -> Tuple[int, Dict[str, int]]:
    flags = {"overwrite": 0, "restart": 0, "refine": 0}

    if len(cand_idx) == 0:
        return -1, flags

    X, base, root_support, group_support, local_density = pool_features(index, q, cand_idx, selected_roots)
    linear_prob = linear_model.predict_proba(X)[:, 1]

    if method == "oracle_pool":
        scores = index.item_mat[cand_idx] @ unit_rows(clean_vec)[0]
        return int(cand_idx[np.argmax(scores)]), flags

    if method == "flat_key_nn":
        return int(cand_idx[np.argmax(base)]), flags

    if method == "learned_linear_judge":
        return int(cand_idx[np.argmax(linear_prob)]), flags

    if method == "guarded_linear_judge":
        if top2_margin(linear_prob) >= guard_margin:
            return int(cand_idx[np.argmax(linear_prob)]), flags
        flags["overwrite"] = 1
        scores = blended_score(linear_prob, base, root_support, group_support, local_density)
        return int(cand_idx[np.argmax(scores)]), flags

    if method == "mcltr_adaptive":
        order = np.argsort(-linear_prob)
        top1 = int(order[0])
        margin = float(linear_prob[order[0]] - linear_prob[order[1]]) if len(order) > 1 else 1.0

        if margin >= guard_margin:
            return int(cand_idx[top1]), flags
        elif margin >= guard_margin / 2.0:
            flags["overwrite"] = 1
            q2 = refine_query(q, index.item_mat[cand_idx], linear_prob, steps=1, alpha=overwrite_alpha)
            X2, base2, rs2, gs2, ld2 = pool_features(index, q2, cand_idx, selected_roots)
            lp2 = linear_model.predict_proba(X2)[:, 1]
            scores = blended_score(lp2, base2, rs2, gs2, ld2)
            return int(cand_idx[np.argmax(scores)]), flags
        else:
            flags["restart"] = 1
            cand_idx2, selected_roots2, _ = index.candidate_pool(q, topk_root=topk_root + 3)
            if len(cand_idx2) > 0:
                X2, base2, rs2, gs2, ld2 = pool_features(index, q, cand_idx2, selected_roots2)
                lp2 = linear_model.predict_proba(X2)[:, 1]
                scores = blended_score(lp2, base2, rs2, gs2, ld2)
                return int(cand_idx2[np.argmax(scores)]), flags
            return int(cand_idx[top1]), flags

    if method == "qdmn_refine2":
        X0, _, _, _, _ = pool_features(index, q, cand_idx, selected_roots)
        guide = linear_model.predict_proba(X0)[:, 1]
        q2 = refine_query(q, index.item_mat[cand_idx], guide, steps=2, alpha=refine_alpha)
        flags["refine"] = 1
        scores = index.item_mat[cand_idx] @ unit_rows(q2)[0]
        return int(cand_idx[np.argmax(scores)]), flags

    raise KeyError(f"Unknown method: {method}")

# ----------------------------
# Evaluation
# ----------------------------
def evaluate_methods(
    index: MemoryIndex,
    linear_model: object,
    query_bank: List[dict],
    methods: List[str],
    topk_root: int,
    guard_margin: float,
    overwrite_alpha: float,
    refine_alpha: float,
) -> pd.DataFrame:
    rows = []
    t0_all = time.perf_counter()

    for method in methods:
        t0 = time.perf_counter()
        item_hits = 0
        group_hits = 0
        coverage_hits = 0
        avg_pool = 0.0
        overwrite_count = 0
        restart_count = 0
        refine_count = 0

        for rec in query_bank:
            q = rec["q"]
            item_idx = rec["item_idx"]
            clean_vec = rec["clean_vec"]

            cand_idx, selected_roots, _ = index.candidate_pool(q, topk_root=topk_root)
            avg_pool += len(cand_idx)
            if len(cand_idx) > 0:
                coverage_hits += int(item_idx in set(cand_idx.tolist()))

            chosen, flags = choose_candidate(
                method=method,
                index=index,
                q=q,
                clean_vec=clean_vec,
                cand_idx=cand_idx,
                selected_roots=selected_roots,
                linear_model=linear_model,
                topk_root=topk_root,
                guard_margin=guard_margin,
                overwrite_alpha=overwrite_alpha,
                refine_alpha=refine_alpha,
            )

            overwrite_count += flags["overwrite"]
            restart_count += flags["restart"]
            refine_count += flags["refine"]

            if chosen == item_idx:
                item_hits += 1
            if chosen >= 0 and index.items[chosen].group == rec["group"]:
                group_hits += 1

        elapsed_ms = (time.perf_counter() - t0) * 1000.0
        n = len(query_bank)
        rows.append(
            {
                "method": method,
                "item_acc": item_hits / n,
                "group_acc": group_hits / n,
                "coverage": coverage_hits / n,
                "avg_pool": avg_pool / n,
                "overwrite_rate": overwrite_count / n,
                "restart_rate": restart_count / n,
                "refine_rate": refine_count / n,
                "runtime_ms": elapsed_ms,
            }
        )

    total_ms = (time.perf_counter() - t0_all) * 1000.0
    out = pd.DataFrame(rows)
    out["total_runtime_ms"] = total_ms
    return out

# ----------------------------
# Run one trial
# ----------------------------
def run_trial(scale: int, placement: str, seed: int) -> Tuple[pd.DataFrame, Dict[str, float], Dict[str, float]]:
    rng = make_rng(seed)
    n_groups = scale // ITEMS_PER_GROUP
    items = make_items_shared_core(n_groups=n_groups, items_per_group=ITEMS_PER_GROUP, dim=DIM, seed=seed)
    item_mat = np.stack([it.vec for it in items], axis=0)

    if placement == "random":
        roots = make_random_roots(N_ROOTS, DIM, rng)
    elif placement == "spiral_pca":
        roots = make_spiral_pca_roots(item_mat, N_ROOTS, DIM, rng, noise_scale=0.03)
    else:
        raise KeyError(placement)

    index = MemoryIndex(roots=roots, overlap_k=OVERLAP_K, topk_root=TOPK_ROOT)
    index.write(items)

    all_ids = np.arange(len(items))
    rng.shuffle(all_ids)
    split = int(TRAIN_FRAC * len(all_ids))
    train_ids = all_ids[:split].tolist()
    test_ids = all_ids[split:].tolist()

    train_bank = make_query_bank(index, train_ids, TRAIN_NOISES, TRAIN_QUERIES_PER_ITEM, rng)
    linear_model = train_linear_judge(index, train_bank)

    test_rows = []
    for noise in TEST_NOISES:
        test_bank = make_query_bank(index, test_ids, [noise], TEST_QUERIES_PER_ITEM, rng)
        df_noise = evaluate_methods(
            index=index,
            linear_model=linear_model,
            query_bank=test_bank,
            methods=METHODS,
            topk_root=TOPK_ROOT,
            guard_margin=GUARD_MARGIN,
            overwrite_alpha=OVERWRITE_ALPHA,
            refine_alpha=REFINE_ALPHA,
        )
        df_noise["seed"] = seed
        df_noise["scale"] = scale
        df_noise["placement"] = placement
        df_noise["noise"] = noise
        test_rows.append(df_noise)

    result_df = pd.concat(test_rows, ignore_index=True)
    rd = root_diagnostics(index.roots)
    ad = index.assignment_diagnostics()
    return result_df, rd, ad

# ----------------------------
# Main
# ----------------------------
def main() -> pd.DataFrame:
    all_rows = []
    root_rows = []

    print("Running final matched-budget scale sweep...")

    for seed in SEEDS:
        for scale in SCALES:
            for placement in PLACEMENTS:
                df_trial, rd, ad = run_trial(scale=scale, placement=placement, seed=seed)
                all_rows.append(df_trial)
                root_rows.append(
                    {
                        "seed": seed,
                        "scale": scale,
                        "placement": placement,
                        **rd,
                        **ad,
                    }
                )

    df = pd.concat(all_rows, ignore_index=True)
    root_df = pd.DataFrame(root_rows)

    # oracle gap by matched seed/scale/placement/noise
    df["oracle_gap"] = np.nan
    for (seed, scale, placement, noise), grp in df.groupby(["seed", "scale", "placement", "noise"]):
        oracle_acc = grp.loc[grp["method"] == "oracle_pool", "item_acc"].iloc[0]
        df.loc[grp.index, "oracle_gap"] = oracle_acc - grp["item_acc"].values

    df.to_csv(OUTDIR / "raw_results.csv", index=False)
    root_df.to_csv(OUTDIR / "root_diagnostics.csv", index=False)

    # ----------------------------
    # Summary tables
    # ----------------------------
    print("\n=== Root diagnostics (mean over seeds) ===")
    print(
        root_df.groupby(["scale", "placement"])[
            ["mean_pairwise_cos", "mean_nn_cos", "assignment_entropy", "assignment_cv"]
        ]
        .mean()
        .round(4)
        .to_string()
    )

    print("\n=== Overall mean by method ===")
    print(
        df.groupby("method")[["item_acc", "group_acc", "coverage", "avg_pool", "oracle_gap", "runtime_ms"]]
        .mean()
        .sort_values("item_acc", ascending=False)
        .round(4)
        .to_string()
    )

    print("\n=== Mean by scale ===")
    print(
        df.groupby("scale")[["item_acc", "group_acc", "coverage", "avg_pool", "oracle_gap", "runtime_ms"]]
        .mean()
        .round(4)
        .to_string()
    )

    print("\n=== Mean by placement ===")
    print(
        df.groupby("placement")[["item_acc", "group_acc", "coverage", "avg_pool", "oracle_gap", "runtime_ms"]]
        .mean()
        .round(4)
        .to_string()
    )

    print("\n=== Mean by scale x placement ===")
    scale_place = (
        df.groupby(["scale", "placement"])[["item_acc", "group_acc", "coverage", "avg_pool", "oracle_gap", "runtime_ms"]]
        .mean()
        .reset_index()
        .sort_values(["scale", "item_acc"], ascending=[True, False])
    )
    print(scale_place.round(4).to_string(index=False))

    # best non-oracle per scale/placement/noise averaged over seeds
    non_oracle = df[df["method"] != "oracle_pool"].copy()
    best = (
        non_oracle.groupby(["scale", "placement", "noise", "method"], as_index=False)[
            ["item_acc", "group_acc", "coverage", "avg_pool", "oracle_gap", "runtime_ms"]
        ]
        .mean()
        .sort_values(["scale", "placement", "noise", "item_acc"], ascending=[True, True, True, False])
        .groupby(["scale", "placement", "noise"], as_index=False)
        .head(1)
        .reset_index(drop=True)
    )
    best.to_csv(OUTDIR / "best_by_scale_placement_noise.csv", index=False)

    print("\n=== Best non-oracle per scale / placement / noise ===")
    print(best.round(4).to_string(index=False))

    # find any 100% rows
    perfect = df[df["item_acc"] >= 0.9999].copy()
    if len(perfect) > 0:
        print("\n=== Any 100% rows found ===")
        cols = ["seed", "scale", "placement", "noise", "method", "item_acc", "coverage", "avg_pool", "runtime_ms"]
        print(perfect[cols].sort_values(cols[:4]).round(4).to_string(index=False))
    else:
        print("\nNo 100% rows found in this matched-budget scale sweep.")

    # compact paper table
    paper = (
        df.groupby(["scale", "placement", "method"])[["item_acc", "group_acc", "coverage", "avg_pool", "oracle_gap", "runtime_ms"]]
        .mean()
        .reset_index()
        .sort_values(["scale", "item_acc"], ascending=[True, False])
    )
    paper.to_csv(OUTDIR / "paper_summary.csv", index=False)

    print("\n=== Paper summary preview ===")
    print(paper.round(4).to_string(index=False))

    # ----------------------------
    # Figure: 2x2 summary
    # ----------------------------
    fig, axes = plt.subplots(2, 2, figsize=(16, 11), constrained_layout=True)

    method_order = [
        "flat_key_nn",
        "learned_linear_judge",
        "guarded_linear_judge",
        "mcltr_adaptive",
        "qdmn_refine2",
        "oracle_pool",
    ]

    # A: item accuracy vs scale
    ax = axes[0, 0]
    sub = df[df["method"].isin(method_order)].groupby(["scale", "placement", "method"], as_index=False)["item_acc"].mean()
    for placement in PLACEMENTS:
        for m in method_order:
            d = sub[(sub["placement"] == placement) & (sub["method"] == m)].sort_values("scale")
            ax.plot(d["scale"], d["item_acc"], marker="o", linewidth=1.8, label=f"{placement} / {m}")
    ax.set_title("A. Accuracy vs scale")
    ax.set_xlabel("Number of items")
    ax.set_ylabel("Item accuracy")
    ax.grid(True, alpha=0.25)
    ax.legend(fontsize=6, ncol=2, loc="best")

    # B: coverage vs scale
    ax = axes[0, 1]
    sub_cov = df.groupby(["scale", "placement"], as_index=False)["coverage"].mean()
    for placement in PLACEMENTS:
        d = sub_cov[sub_cov["placement"] == placement].sort_values("scale")
        ax.plot(d["scale"], d["coverage"], marker="o", linewidth=2, label=placement)
    ax.set_title("B. Coverage vs scale")
    ax.set_xlabel("Number of items")
    ax.set_ylabel("Coverage")
    ax.grid(True, alpha=0.25)
    ax.legend(fontsize=8, loc="best")

    # C: oracle gap vs scale
    ax = axes[1, 0]
    sub_gap = df.groupby(["scale", "placement"], as_index=False)["oracle_gap"].mean()
    for placement in PLACEMENTS:
        d = sub_gap[sub_gap["placement"] == placement].sort_values("scale")
        ax.plot(d["scale"], d["oracle_gap"], marker="o", linewidth=2, label=placement)
    ax.set_title("C. Oracle gap vs scale")
    ax.set_xlabel("Number of items")
    ax.set_ylabel("Oracle gap")
    ax.grid(True, alpha=0.25)
    ax.legend(fontsize=8, loc="best")

    # D: runtime vs scale
    ax = axes[1, 1]
    sub_rt = df.groupby(["scale", "placement", "method"], as_index=False)["runtime_ms"].mean()
    for m in ["flat_key_nn", "mcltr_adaptive", "qdmn_refine2", "oracle_pool"]:
        d = sub_rt[(sub_rt["placement"] == "random") & (sub_rt["method"] == m)].sort_values("scale")
        ax.plot(d["scale"], d["runtime_ms"], marker="o", linewidth=2, label=f"random / {m}")
    ax.set_title("D. Runtime vs scale (random placement)")
    ax.set_xlabel("Number of items")
    ax.set_ylabel("ms per test split")
    ax.grid(True, alpha=0.25)
    ax.legend(fontsize=8, loc="best")

    fig.suptitle("Final matched-budget scale test", fontsize=14)
    fig.savefig(OUTDIR / "final_scale_summary_figure.png", dpi=220, bbox_inches="tight")
    plt.show()

    print(f"\nSaved artifacts to: {OUTDIR}")
    return df

if __name__ == "__main__":
    df = main()
    print("\nDone.")
